      </div>
      <RecordSheet
        fit={{ tables: [[CELL.date, CELL.pick, CELL.pick, CELL.pick, CELL.pick, CELL.number, CELL.pick, CELL.status]] }}
        open={details}
        onOpenChange={setDetails}
        mode="edit"
        editTitle="Next 7 days"
