*/

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
const rate = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", minimumFractionDigits: 3, maximumFractionDigits: 4 });

const WHEN = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });

/*
  THE DISPUTE (Pavan, 2026-10-14) — what is disputed and why, the notes both
  sides have added (newest last, as a conversation reads), a box to add one,
  and the documents offered as proof with Add document — the Orders
  documents table, so the same data wears the same control.
*/
function DisputeSections({ invoice, dispute, total }: { invoice: Invoice; dispute: Dispute; total: number }) {
  const [draft, setDraft] = React.useState("");
  const fileInput = React.useRef<HTMLInputElement>(null);
  const diff = dispute.claimed !== null ? total - dispute.claimed : null;
  return (
    <>
      {dispute.kind ? (
        /* THE CUSTOMER'S DISPUTE (Pavan, 2026-10-15) — what is wrong, what
           they asked for, the lines in question, and the tenant's answer. */
        <SheetSection title="Invoice dispute">
          <div className="grid grid-cols-4 gap-4">
            <Fact label="Raised by">
              <span>{dispute.raisedBy}</span>
              <span className="text-xs text-muted-foreground">{WHEN.format(new Date(dispute.raisedAt))}</span>
            </Fact>
            <Fact label="What is wrong">{dispute.kind}</Fact>
            <Fact label="Asking for">{asksFor(dispute.kind)}</Fact>
            <Fact label="In question">
              <span className="font-semibold tabular-nums">{usd.format(inQuestion(invoice))}</span>
            </Fact>
          </div>
          {dispute.lines && dispute.lines.length > 0 && (
            <dl className="flex flex-col rounded-lg border border-border">
              {dispute.lines.map((l) => (
                <div key={l.key} className="flex h-10 items-center justify-between gap-4 border-b border-border px-3 text-sm last:border-b-0">
                  <dt className="truncate text-foreground">{l.label}</dt>
                  <dd className="shrink-0 tabular-nums text-muted-foreground">
                    {usd.format(l.charged)} → <span className="text-foreground">{usd.format(l.expected)}</span>
                  </dd>
                </div>
              ))}
            </dl>
          )}
          {dispute.outcome && (
            <div className="flex flex-col gap-1.5 rounded-lg bg-fp-table-header p-3 text-sm">
              <span className="flex flex-wrap items-center gap-2">
                <StatusChip
                  tone={kindTone(dispute.outcome.result === "Rejected" ? "neutral" : "success")}
                  variant="soft"
                >
                  {dispute.outcome.result}
                </StatusChip>
                <span className="text-xs text-muted-foreground">
                  {dispute.outcome.by} · {WHEN.format(new Date(dispute.outcome.at))}
                </span>
              </span>
              <span className="text-foreground">{dispute.outcome.note}</span>
              {dispute.outcome.credit !== undefined && (
                <span className="tabular-nums text-foreground">
                  Credit note {dispute.outcome.creditNoteNo} · {usd.format(dispute.outcome.credit)}
                </span>
              )}
              {dispute.closedAt ? (
                <span className="text-xs text-muted-foreground">Closed {WHEN.format(new Date(dispute.closedAt))}</span>
              ) : (
                <span className="flex justify-end pt-1">
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => {
                      closeDispute(invoice.invoiceNo);
                      toast.success(`Dispute on ${invoice.invoiceNo} closed`);
                    }}
                  >
                    Close dispute
                  </Button>
                </span>
              )}
            </div>
          )}
        </SheetSection>
      ) : (
        <SheetSection title="Payment dispute">
          <div className="grid grid-cols-4 gap-4">
            <Fact label="Raised by">
              <span>{dispute.raisedBy}</span>
              <span className="text-xs text-muted-foreground">{WHEN.format(new Date(dispute.raisedAt))}</span>
            </Fact>
            <Fact label="Invoiced">
              <span className="tabular-nums">{usd.format(total)}</span>
            </Fact>
            <Fact label="You say">
              <span className="tabular-nums">{dispute.claimed !== null ? usd.format(dispute.claimed) : "—"}</span>
            </Fact>
            <Fact label="Difference">
              <span className="font-semibold tabular-nums text-status-failed">{diff !== null ? usd.format(diff) : "—"}</span>
            </Fact>
          </div>
          <SheetField label="Reason">
            <p className="text-sm text-foreground">{dispute.reason}</p>
          </SheetField>
        </SheetSection>
      )}

      <SheetSection title="Notes">
        <ol className="flex flex-col gap-4">
          {dispute.notes.map((n) => (
            <li key={n.id} className="flex gap-3">
              <span
                aria-hidden
                className={cn(
                  "flex size-8 shrink-0 items-center justify-center rounded-full text-xs font-medium",
                  n.side === "customer" ? "bg-muted text-foreground" : "bg-brand/10 text-brand"
                )}
              >
                {n.by
                  .split(" ")
                  .map((w) => w[0])
                  .slice(0, 2)
                  .join("")}
              </span>
              <div className="flex min-w-0 flex-1 flex-col gap-1">
                <p className="flex flex-wrap items-center gap-x-2 text-sm">
                  <span className="font-medium text-foreground">{n.by}</span>
                  <Pill>{n.side === "customer" ? ACCOUNT : ISSUER}</Pill>
                  <span className="text-xs text-muted-foreground">{WHEN.format(new Date(n.at))}</span>
                </p>
                <p className="text-sm whitespace-pre-line text-foreground">{n.text}</p>
              </div>
            </li>
          ))}
        </ol>
        {/* A REJECTED DISPUTE TAKES ONE MORE REPLY; a closed one none. */}
        {canReply(dispute) && (
        <div className="flex flex-col gap-2 border-t border-border pt-4">
          <Textarea
            aria-label="Add a note"
            placeholder={`Add a note for ${ISSUER}`}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            className="min-h-20"
          />
          <div className="flex justify-end">
            <Button
              size="sm"
              disabled={!draft.trim()}
              onClick={() => {
                addDisputeNote(invoice.invoiceNo, draft.trim());
                setDraft("");
              }}
            >
              {dispute.outcome?.result === "Rejected" ? "Send reply" : "Add note"}
            </Button>
          </div>
        </div>
        )}
      </SheetSection>

      <SheetSection
        title="Documents"
        flush
        hanging={<HangingAdd label="Add document" onClick={() => fileInput.current?.click()} />}
      >
        <DocumentsTable
          rows={documentRows(dispute.documents)}
          onAdd={() => fileInput.current?.click()}
          onDownload={(d) => toast.success(`${d.name} downloaded`)}
        />
        <input
          ref={fileInput}
          type="file"
          multiple
          className="hidden"
          onChange={(e) => {
            const files = [...(e.target.files ?? [])];
            e.target.value = "";
            if (files.length === 0) return;
            addDisputeDocuments(invoice.invoiceNo, files);
            toast.success(files.length === 1 ? `${files[0].name} added` : `${files.length} documents added`);
          }}
        />
      </SheetSection>
    </>
  );
}

function Fact({ label, children }: { label: string; children: React.ReactNode }) {
  return (
    <SheetField label={label}>
      <div className="flex min-h-9 flex-col justify-center text-sm text-foreground">{children}</div>
    </SheetField>
  );
}

const settled_ = (i: Invoice) => SETTLED.includes(i.status);

export function InvoiceSheet({
  invoice,
  open,
  onOpenChange,
  onDownload,
  orderLink,
}: {
  invoice: Invoice | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onDownload: (inv: Invoice) => void;
  /** The order number as a link, when it can open (PRD FR-10). */
  orderLink?: (orderNo: string) => React.ReactNode;
}) {
  const [disputing, setDisputing] = React.useState(false);
  if (!invoice) return null;
  const c = chargesOf(invoice);
  /* ONE OPEN DISPUTE PER INVOICE; a settled invoice is not disputed here. */
  /* DISPUTES ARE HIDDEN FOR NOW (Pavan, 2026-10-20 — not in the product
     yet, per the Anirudh review). The flow stays built: DISPUTES_ON brings it
     back. */
  const canDispute = DISPUTES_ON && !settled_(invoice) && !disputeOpen(invoice) && invoice.status !== "Payment disputed";
  const d = daysFrom(invoice.due);
  const settled = SETTLED.includes(invoice.status);
  return (
    <>
    <RecordSheet
      /* WIDTH FROM ITS TABLES (Pavan, 2026-10-15): charges = item name, basis
         ("gal @ rate", text), amount; dispute documents = document name, added
         date, by (pick), menu. Charges is the widest. */
      fit={{
        tables: [
          [CELL.name, CELL.text, CELL.number],
          ...(invoice.dispute ? [[CELL.name, CELL.date, CELL.pick, CELL.bin]] : []),
        ],
      }}
      open={open}
      onOpenChange={onOpenChange}
      mode="edit"
      editTitle={invoice.invoiceNo}
      createTitle=""
      createAction=""
      showCancel={false}
      onSubmit={() => {}}
      headerAside={
        <StatusChip tone={INVOICE_STATUS_TONE[invoice.status]} variant="text">
          {invoice.status}
        </StatusChip>
      }
      headerMenu={
        canDispute ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon-sm" aria-label="More invoice actions">
                <MoreHorizontal />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-48">
              <DropdownMenuItem onSelect={() => setDisputing(true)}>
                <Flag />
                Dispute invoice
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        ) : undefined
      }
      headerActions={
        <Tooltip>
          <TooltipTrigger asChild>
            <Button variant="ghost" size="icon-sm" aria-label="Download invoice" onClick={() => onDownload(invoice)}>
              <Download />
            </Button>
          </TooltipTrigger>
          <TooltipContent>Download invoice</TooltipContent>
        </Tooltip>
      }
      footerPrimary={
        <Button onClick={() => onDownload(invoice)}>
          <Download />
          Download invoice
        </Button>
      }
    >
      <div className="flex min-w-0 flex-col gap-10">
        <SheetSection title="Summary">
          <div className="grid grid-cols-3 gap-4">
            <Fact label="Order">{orderLink ? orderLink(invoice.orderNo) : invoice.orderNo}</Fact>
            <Fact label="Bill to">{invoice.billTo}</Fact>
            <Fact label="Ship-to">{invoice.shipTo}</Fact>
            <Fact label="Issued">
              <span>{printKey(invoice.issued)}</span>
              <span className="text-xs text-muted-foreground">by {ISSUER}</span>
            </Fact>
            <Fact label="Due">
              <span>{printKey(invoice.due)}</span>
              {invoice.status === "Invoice disputed" ? (
                <span className="text-xs text-muted-foreground">Paused · disputed</span>
              ) : !settled && (
                <span className={cn("text-xs", d < 0 ? "text-status-failed" : "text-muted-foreground")}>
                  {d < 0 ? `${-d} ${d === -1 ? "day" : "days"} overdue` : d === 0 ? "Due today" : `In ${d} ${d === 1 ? "day" : "days"}`}
                </span>
              )}
            </Fact>
            {/* THE STATUS IS IN THE HEADER — this slot says what it means. */}
            {settled ? (
              <Fact label="Paid on">{invoice.paidOn ? printKey(invoice.paidOn) : "—"}</Fact>
            ) : (
              <Fact label="Amount due">
                <span className="font-semibold tabular-nums">{usd.format(amountDue(invoice))}</span>
                {invoice.dispute?.outcome?.credit !== undefined && (
                  <span className="text-xs text-muted-foreground">
                    after credit note {invoice.dispute.outcome.creditNoteNo}
                  </span>
                )}
              </Fact>
            )}
          </div>
        </SheetSection>

        {invoice.dispute && <DisputeSections invoice={invoice} dispute={invoice.dispute} total={c.total} />}

        <SheetSection title="Charges" flush>
          <table className="w-full table-fixed border-collapse text-sm">
            <colgroup>
              <col />
              <col className="w-[40%]" />
              <col className="w-[140px]" />
            </colgroup>
            <thead>
              <tr className="border-b border-border bg-fp-table-header text-left text-xs font-medium text-muted-foreground">
                <th className="px-4 py-2.5 font-medium">Item</th>
                <th className="px-3 py-2.5 font-medium">Basis</th>
                <th className="px-4 py-2.5 font-medium">Amount</th>
              </tr>
            </thead>
            <tbody>
              {c.fuel.map((l) => (
                <tr key={l.product} className="h-11 border-b border-border">
                  <td className="px-4 text-foreground">Fuel · {l.product}</td>
                  <td className="px-3 tabular-nums text-muted-foreground">
                    {l.gal.toLocaleString()} gal @ {rate.format(l.rate)}
                  </td>
                  <td className="px-4 tabular-nums text-foreground">{usd.format(l.amount)}</td>
                </tr>
              ))}
              <tr className="h-11 border-b border-border">
                <td className="px-4 text-foreground">Fees (delivery, environmental)</td>
                <td className="px-3 tabular-nums text-muted-foreground">
                  {c.gal.toLocaleString()} gal @ {rate.format(FEES_PER_GAL)}
                </td>
                <td className="px-4 tabular-nums text-foreground">{usd.format(c.fees)}</td>
              </tr>
              <tr className="h-11 border-b border-border">
                <td className="px-4 text-foreground">Tax (federal + state excise)</td>
                <td className="px-3 tabular-nums text-muted-foreground">{Math.round(TAX_RATE * 100)}%</td>
                <td className="px-4 tabular-nums text-foreground">{usd.format(c.tax)}</td>
              </tr>
              <tr className="h-12">
                <td className="px-4 font-semibold text-foreground" colSpan={2}>
                  {settled ? "Total paid" : "Total due"}
                </td>
                <td className="px-4 font-semibold tabular-nums text-foreground">{usd.format(c.total)}</td>
              </tr>
            </tbody>
          </table>
        </SheetSection>
      </div>
      {/* INSIDE THE SHEET, so it knows the width beneath it (a strip shows). */}
      <DisputeSheet invoice={invoice} open={disputing} onOpenChange={setDisputing} />
    </RecordSheet>
    </>
  );
}

import * as React from "react";
import { toast } from "sonner";
import { Download, ReceiptText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { StatusChip } from "@/components/ui/status-chip";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { AlertBanner, type BannerAlert } from "@/components/ui/alert-banner";
import { cn } from "@/lib/utils";
import { TwoLineCell, type ListColumn } from "../unified-view/ListTable";
import { printKey, useRequests } from "./orders";
import { RecordLink, usePortalNav } from "./nav";
import { CREDIT } from "./dashboard";
import { PortalList } from "./PortalList";
import { InvoiceSheet } from "./InvoiceSheet";
import { StatementView } from "./StatementView";
import {
  INVOICE_STATUSES,
  INVOICE_STATUS_TONE,
  SETTLED,
  TERMS,
  daysFrom,
  amountDue,
  inQuestion,
  invoiceSummary,
  totalOf,
  useInvoices,
  type Invoice,
} from "./invoices";

/*
  INVOICES (Pavan, 2026-10-14) — the Lovable reference's invoice page and
  flow, in our DS:

    overview   Outstanding · Overdue · Paid (last 90 days) · Terms (and the
               credit limit, where the tenant gives credit) — ONE read-only
               card, tiles ruled apart, as on Orders
    alerts     the DS banner with interaction, under the toolbar (the
               portal's place): overdue · payment disputed · due this week;
               each title filters the list to its status
    list       Invoice · Issued · Due · Order · Ship-to · Amount · Status ·
               Download — the portal list (the Unified View list as one piece)
    sheet      a row opens the invoice: summary and charges to the total

  NO "PAY" COLUMN. The portal does not take payments yet, so the status says
  where an invoice stands, and the last column is DOWNLOAD INVOICE — one
  icon, highlighted only when the pointer is on it.
*/

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
const usd0 = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });
const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`;

type IK = "invoice" | "issued" | "due" | "order" | "shipTo" | "amount" | "status" | "download" | "actions";
const COLUMNS: ListColumn<IK>[] = [
  { key: "invoice", label: "Invoice", width: 90, sortable: true },
  { key: "issued", label: "Issued", width: 120, sortable: true },
  { key: "due", label: "Due", width: 130, sortable: true },
  { key: "order", label: "Order", width: 100, sortable: true },
  { key: "shipTo", label: "Ship-to", width: 170, sortable: true },
  { key: "amount", label: "Amount", width: 100, sortable: true },
  { key: "status", label: "Status", width: 160, sortable: true },
  { key: "download", label: "Download", width: 90 },
  { key: "actions", label: "", width: 44 },
];

const dueNote = (i: Invoice) => {
  if (SETTLED.includes(i.status)) return "";
  /* AN OPEN DISPUTE PAUSES THE DUE DATE — never "overdue" while it lasts. */
  if (i.status === "Invoice disputed") return "Paused · disputed";
  const d = daysFrom(i.due);
  return d < 0 ? `${-d} ${d === -1 ? "day" : "days"} overdue` : d === 0 ? "Due today" : `In ${d} ${d === 1 ? "day" : "days"}`;
};

const text = (i: Invoice, k: IK): string => {
  switch (k) {
    case "invoice":
      return i.invoiceNo;
    case "issued":
      return printKey(i.issued);
    case "due":
      return `${printKey(i.due)} ${dueNote(i)}`;
    case "order":
      return i.orderNo;
    case "shipTo":
      return i.shipTo;
    case "amount":
      return usd.format(totalOf(i));
    case "status":
      return i.status;
    default:
      return "";
  }
};

/** The overview — four read-only tiles in one card. */
function Overview() {
  const s = invoiceSummary();
  const tiles = [
    { title: "Outstanding", value: usd0.format(s.outstanding), note: plural(s.openCount, "open invoice", "open invoices") },
    {
      title: "Overdue",
      value: usd0.format(s.overdue),
      note: plural(s.overdueCount, "invoice", "invoices"),
      tone: s.overdue > 0 ? "text-status-failed" : undefined,
    },
    { title: "Paid · last 90 days", value: usd0.format(s.paid90), note: plural(s.paid90Count, "invoice", "invoices") },
    {
      title: "Terms",
      value: TERMS,
      note: CREDIT.enabled ? `Credit limit ${usd0.format(CREDIT.limit)} a ${CREDIT.period}` : "Pay on invoice",
    },
  ];
  return (
    <div className="grid grid-cols-1 divide-y divide-border rounded-xl border border-border bg-fp-surface-1b sm:grid-cols-2 sm:divide-y-0 xl:grid-cols-4 xl:divide-x">
      {tiles.map((t) => (
        <section key={t.title} className="flex min-w-0 flex-col gap-1 px-4 py-3">
          <h3 className="text-sm font-medium text-foreground">{t.title}</h3>
          <p className={cn("text-3xl font-semibold tabular-nums text-foreground", t.tone)}>{t.value}</p>
          <p className="text-xs text-muted-foreground">{t.note}</p>
        </section>
      ))}
    </div>
  );
}

export function InvoicesScreen({ focus }: { focus?: { invoiceNo: string; n: number } | null } = {}) {
  const rows = useInvoices();
  const nav = usePortalNav();
  const requests = useRequests();
  const [openNo, setOpenNo] = React.useState<string | null>(null);
  /* TWO TABS (Pavan, 2026-10-15): the invoices, and the statement. */
  const [tab, setTab] = React.useState("invoices");
  const TABS = [
    { key: "invoices", label: "Invoices" },
    { key: "statement", label: "Statement" },
  ];
  /* OPENED FROM A LINK — the invoice behind an order. */
  React.useEffect(() => {
    if (focus) setOpenNo(focus.invoiceNo);
  }, [focus?.n]); // eslint-disable-line react-hooks/exhaustive-deps
  /* THE ORDER, AS A LINK when it is still on the Orders page (PRD FR-10). */
  const orderCell = (no: string) =>
    requests.some((r) => r.requestNo === no) ? (
      <RecordLink label={no} onOpen={() => nav.openOrder(no)} />
    ) : (
      <span className="text-sm tabular-nums">{no}</span>
    );
  const [applied, setApplied] = React.useState<{ ids: string[]; n: number } | undefined>();
  const [dismissed, setDismissed] = React.useState<Set<string>>(new Set());
  const [snoozed, setSnoozed] = React.useState<Record<string, number>>({});
  const download = (i: Invoice) => toast.success(`${i.invoiceNo}.pdf downloaded`);
  const filterTo = (status: string) => setApplied({ ids: [`status:${status}`], n: Date.now() });
  /* WHICH ALERT'S FILTER IS ON — the list's filter is exactly its status. */
  const [facets, setFacets] = React.useState<string[]>([]);
  const ALERT_STATUS: Record<string, string> = { overdue: "Overdue", disputed: "Payment disputed", due: "Payment due" };
  const appliedId =
    facets.length === 1 ? (Object.keys(ALERT_STATUS).find((k) => facets[0] === `status:${ALERT_STATUS[k]}`) ?? null) : null;

  /* THE ALERTS — what needs paying or settling, most urgent first. */
  const by = (st: Invoice["status"]) => rows.filter((i) => i.status === st);
  const items = (xs: Invoice[]) =>
    xs.map((i) => ({
      id: i.invoiceNo,
      title: `${i.invoiceNo} · ${usd.format(totalOf(i))}`,
      detail: `${i.shipTo} · ${dueNote(i) || printKey(i.due)}`,
      onApply: () => setOpenNo(i.invoiceNo),
    }));
  const overdue = by("Overdue");
  /* THE PAYMENT DISPUTES — the customer's own invoice dispute is off for now
     (Pavan, 2026-10-22). */
  const disputed = by("Payment disputed");
  const dueSoon = by("Payment due");
  const sum = (xs: Invoice[]) => usd0.format(xs.reduce((t, i) => t + totalOf(i), 0));
  const alerts = (
    [
      overdue.length > 0 && {
        id: "overdue",
        status: "warning" as const,
        tag: "Overdue",
        title: `${plural(overdue.length, "invoice is", "invoices are")} overdue`,
        detail: sum(overdue),
        count: overdue.length,
        onApply: () => filterTo("Overdue"),
        items: items(overdue),
      },
      disputed.length > 0 && {
        id: "disputed",
        status: "warning" as const,
        tag: "Disputed",
        title: `${plural(disputed.length, "invoice is", "invoices are")} disputed`,
        detail: usd0.format(disputed.reduce((t, i) => t + inQuestion(i), 0)),
        count: disputed.length,
        onApply: () => filterTo("Payment disputed"),
        items: disputed.map((i) => ({
          id: i.invoiceNo,
          title: `${i.invoiceNo} · ${usd.format(inQuestion(i))} in question`,
          detail: i.dispute?.reason ?? i.shipTo,
          onApply: () => setOpenNo(i.invoiceNo),
        })),
      },
      dueSoon.length > 0 && {
        id: "due",
        status: "caution" as const,
        tag: "Due soon",
        title: `${plural(dueSoon.length, "invoice is", "invoices are")} due this week`,
        detail: sum(dueSoon),
        count: dueSoon.length,
        onApply: () => filterTo("Payment due"),
        items: items(dueSoon),
      },
    ].filter(Boolean) as BannerAlert[]
  ).filter((a) => !dismissed.has(a.id) && !((snoozed[a.id] ?? 0) > Date.now()));

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      {tab === "statement" ? (
        <>
          <div className="mb-8 shrink-0">
            <Overview />
          </div>
          <StatementView invoices={rows} segments={TABS} segmentValue={tab} onSegmentChange={setTab} />
        </>
      ) : (
      <PortalList<Invoice, IK>
        segments={TABS}
        segmentValue={tab}
        onSegmentChange={setTab}
        above={<Overview />}
        banner={
          alerts.length > 0 ? (
            <AlertBanner
              alerts={alerts}
              onSnooze={(id, ms) => setSnoozed((p) => ({ ...p, [id]: Date.now() + ms }))}
              onDismiss={(id) => setDismissed((p) => new Set(p).add(id))}
              appliedId={appliedId}
              onClearApplied={() => setApplied({ ids: [], n: Date.now() })}
            />
          ) : undefined
        }
        applyFacets={applied}
        onFacetsChange={setFacets}
        rows={rows}
        columns={COLUMNS}
        rowId={(i) => i.invoiceNo}
        text={text}
        sortValue={(i, k) =>
          k === "amount" ? totalOf(i) : k === "issued" ? i.issued : k === "due" ? i.due : k === "status" ? (INVOICE_STATUSES as readonly string[]).indexOf(i.status) : undefined
        }
        renderCell={(i, k) => {
          switch (k) {
            case "invoice":
              return <span className="text-sm font-medium text-foreground">{i.invoiceNo}</span>;
            case "issued":
              return <span className="text-sm">{printKey(i.issued)}</span>;
            case "due": {
              const note = dueNote(i);
              return note ? (
                <span className="flex min-w-0 flex-col">
                  <span className="text-sm text-foreground">{printKey(i.due)}</span>
                  <span className={cn("text-xs", daysFrom(i.due) < 0 && i.status !== "Invoice disputed" ? "text-status-failed" : "text-muted-foreground")}>
                    {note}
                  </span>
                </span>
              ) : (
                <span className="text-sm">{printKey(i.due)}</span>
              );
            }
            case "order":
              return orderCell(i.orderNo);
            case "shipTo":
              return <TwoLineCell title={i.shipTo} description={i.billTo} />;
            case "amount":
              return <span className="text-sm tabular-nums text-foreground">{usd.format(amountDue(i))}</span>;
            case "status":
              return (
                <span className="flex flex-col items-start gap-0.5">
                  <StatusChip tone={INVOICE_STATUS_TONE[i.status]} variant="text">
                    {i.status}
                  </StatusChip>
                  {/* WHAT IS IN QUESTION, under a customer's open dispute. */}
                  {i.status === "Invoice disputed" && (
                    <span className="text-xs tabular-nums text-muted-foreground">{usd.format(inQuestion(i))} in question</span>
                  )}
                </span>
              );
            case "download":
              /* ONE ICON — highlighted only under the pointer; the press
                 stays here and does not open the row. */
              return (
                <div className="flex justify-center">
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        variant="ghost"
                        size="icon-sm"
                        aria-label={`Download ${i.invoiceNo}`}
                        className="text-muted-foreground hover:text-foreground"
                        onClick={(e) => {
                          e.stopPropagation();
                          download(i);
                        }}
                      >
                        <Download />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Download invoice</TooltipContent>
                  </Tooltip>
                </div>
              );
            default:
              return null;
          }
        }}
        facets={[
          { key: "status", label: "Status", options: [...INVOICE_STATUSES] },
          { key: "shipTo", label: "Ship-to", options: Array.from(new Set(rows.map((i) => i.shipTo))) },
        ]}
        facetValues={(i, f) => (f === "status" ? [i.status] : f === "shipTo" ? [i.shipTo] : [])}
        storageKey="portal-invoices"
        noun="invoices"
        nounOne="invoice"
        searchPlaceholder="Search invoices, orders, ship-tos…"
        onOpen={(i) => setOpenNo(i.invoiceNo)}
        openLabel={(i) => `Open invoice ${i.invoiceNo}`}
        emptyIcon={<ReceiptText />}
      />
      )}
      <InvoiceSheet
        invoice={rows.find((i) => i.invoiceNo === openNo) ?? null}
        open={openNo !== null}
        onOpenChange={(o) => !o && setOpenNo(null)}
        onDownload={download}
        orderLink={orderCell}
      />
    </div>
  );
}

import * as React from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import { Check, Loader2, MapPin, Search, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";
import { placeOf, reversePlace, searchPlaces, type NominatimPlace, type PlaceAddress } from "./geo";

/*
  THE SHIP-TO'S MAP (Pavan, 2026-10-13) — where the site is, found by search
  or by pressing the map, confirmed into the address fields; the address
  typed by hand moves the pin the other way. The geofence is drawn round the
  pin; the site's assets stand on it as small pins and can be dragged to
  where they really are.

  A REAL MAP, unlike the Unified View's schematic: OpenStreetMap tiles and
  its free address search (Nominatim) — no key, but it needs the internet.
  A production build would swap in a licensed provider; nothing else here
  would change.
*/

/* PINS ARE DS-COLOURED DIVS — Leaflet's own image pins break in a bundle. */
const sitePin = (pending: boolean) =>
  L.divIcon({
    className: "",
    iconSize: [28, 28],
    iconAnchor: [14, 28],
    html: `<div class="flex size-7 items-center justify-center rounded-full ${
      pending ? "bg-brand" : "bg-foreground"
    } text-white shadow-md ring-2 ring-white"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M20 10c0 4.993-5.539 10.193-7.399 11.799a1 1 0 0 1-1.202 0C9.539 20.193 4 14.993 4 10a8 8 0 0 1 16 0"/><circle cx="12" cy="10" r="3"/></svg></div>`,
  });
const assetPin = (name: string, active = false) =>
  L.divIcon({
    className: "",
    iconSize: active ? [20, 20] : [14, 14],
    iconAnchor: active ? [10, 10] : [7, 7],
    html: `<div title="${name.replace(/"/g, "&quot;")}" class="${
      active ? "size-5 bg-brand" : "size-3.5 bg-fp-lane-violet"
    } rounded-full ring-2 ring-white shadow"></div>`,
  });

export function LocationMap({
  location,
  geofence,
  assets,
  onConfirm,
  onAssetMove,
  onPress,
  className,
}: {
  /** The site's confirmed place — the dark pin. */
  location: { lat: number; lng: number } | null;
  /** Geofence radius in metres, or null for none. */
  geofence: number | null;
  /** `active` = the asset being placed (orange, larger); `fixed` = not draggable. */
  assets: { key: string; name: string; lat: number | null; lng: number | null; active?: boolean; fixed?: boolean }[];
  onConfirm?: (p: PlaceAddress) => void;
  /**
   * PLACING AN ASSET, not finding a site (Pavan, 2026-10-13): a press goes
   * straight here — no proposed pin, no address search, no Confirm.
   */
  onPress?: (lat: number, lng: number) => void;
  onAssetMove: (key: string, lat: number, lng: number) => void;
  className?: string;
}) {
  const box = React.useRef<HTMLDivElement>(null);
  const map = React.useRef<L.Map | null>(null);
  const layers = React.useRef<{ site?: L.Marker; pending?: L.Marker; fence?: L.Circle; assets: L.Marker[] }>({
    assets: [],
  });
  const [pending, setPending] = React.useState<PlaceAddress | null>(null);
  const [resolving, setResolving] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const [results, setResults] = React.useState<NominatimPlace[]>([]);
  const [searching, setSearching] = React.useState(false);
  const [offline, setOffline] = React.useState(false);
  const onAssetMoveRef = React.useRef(onAssetMove);
  onAssetMoveRef.current = onAssetMove;
  const onPressRef = React.useRef(onPress);
  onPressRef.current = onPress;

  /* A PRESS ON THE MAP is a proposed place: pin it, then look up its address. */
  const propose = React.useCallback(async (lat: number, lng: number) => {
    setPending({ lat, lng, street: "", city: "", state: "", zip: "" });
    setResolving(true);
    try {
      const p = await reversePlace(lat, lng);
      if (p) setPending({ ...placeOf(p), lat, lng });
      setOffline(false);
    } catch {
      setOffline(true);
    } finally {
      setResolving(false);
    }
  }, []);

  /* ONE MAP PER MOUNT. */
  React.useEffect(() => {
    if (!box.current || map.current) return;
    const m = L.map(box.current, { zoomControl: true, attributionControl: true }).setView(
      location ? [location.lat, location.lng] : [29.76, -95.37],
      location ? 16 : 10
    );
    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      maxZoom: 19,
      attribution: "© OpenStreetMap",
    }).addTo(m);
    m.on("click", (e: L.LeafletMouseEvent) =>
      onPressRef.current
        ? onPressRef.current(Number(e.latlng.lat.toFixed(6)), Number(e.latlng.lng.toFixed(6)))
        : propose(e.latlng.lat, e.latlng.lng)
    );
    map.current = m;
    /* THE SHEET SLIDES IN — measure again once it has. */
    const t = window.setTimeout(() => m.invalidateSize(), 350);
    return () => {
      window.clearTimeout(t);
      m.remove();
      map.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* THE CONFIRMED PIN AND ITS GEOFENCE follow the record — a typed address
     moves them, and the view goes with the pin. */
  React.useEffect(() => {
    const m = map.current;
    if (!m) return;
    const l = layers.current;
    l.site?.remove();
    l.fence?.remove();
    l.site = undefined;
    l.fence = undefined;
    if (!location) return;
    l.site = L.marker([location.lat, location.lng], { icon: sitePin(false) }).addTo(m);
    if (geofence)
      l.fence = L.circle([location.lat, location.lng], {
        radius: geofence,
        /* THE LANE VIOLET'S LITERAL — Leaflet writes SVG attributes, which
           cannot read a CSS variable; the token is the same in both themes. */
        color: "#8b5cf6",
        weight: 2,
        fillOpacity: 0.08,
        dashArray: "6 6",
      }).addTo(m);
    m.setView([location.lat, location.lng], Math.max(m.getZoom(), 16));
    // eslint-disable-next-line react-hooks/exhaustive-deps -- a new object each render is not a move
  }, [location?.lat, location?.lng, geofence]);

  /* THE PROPOSED PIN — orange until confirmed. */
  React.useEffect(() => {
    const m = map.current;
    if (!m) return;
    layers.current.pending?.remove();
    layers.current.pending = undefined;
    if (pending) {
      layers.current.pending = L.marker([pending.lat, pending.lng], { icon: sitePin(true) }).addTo(m);
      m.setView([pending.lat, pending.lng], Math.max(m.getZoom(), 16));
    }
  }, [pending?.lat, pending?.lng, pending]);

  /* THE ASSETS — small violet pins, dragged to where each one stands. */
  const assetKey = assets.map((a) => `${a.key}:${a.lat}:${a.lng}:${a.name}:${a.active}:${a.fixed}`).join("|");
  React.useEffect(() => {
    const m = map.current;
    if (!m) return;
    layers.current.assets.forEach((x) => x.remove());
    layers.current.assets = assets
      .filter((a) => a.lat !== null && a.lng !== null)
      .map((a) => {
        const mk = L.marker([a.lat!, a.lng!], {
          icon: assetPin(a.name || "Asset", a.active),
          draggable: !a.fixed,
          zIndexOffset: a.active ? 1000 : 0,
        })
          .bindTooltip(a.name || "Asset", { direction: "top", offset: [0, -8] })
          .addTo(m);
        mk.on("dragend", () => {
          const p = mk.getLatLng();
          onAssetMoveRef.current(a.key, Number(p.lat.toFixed(6)), Number(p.lng.toFixed(6)));
        });
        return mk;
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [assetKey]);

  /* SEARCH, DEBOUNCED — five places at most. A picked place's name in the
     box is not a new search. */
  const picked = React.useRef<string | null>(null);
  React.useEffect(() => {
    const q = query.trim();
    if (q === picked.current) return;
    if (q.length < 3) {
      setResults([]);
      return;
    }
    const ctl = new AbortController();
    const t = window.setTimeout(async () => {
      setSearching(true);
      try {
        setResults(await searchPlaces(q, ctl.signal));
        setOffline(false);
      } catch {
        if (!ctl.signal.aborted) setOffline(true);
      } finally {
        if (!ctl.signal.aborted) setSearching(false);
      }
    }, 450);
    return () => {
      window.clearTimeout(t);
      ctl.abort();
    };
  }, [query]);

  return (
    <div className={cn("relative isolate overflow-hidden rounded-lg border border-border", className)}>
      <div ref={box} className="size-full" />

      {/* THE SEARCH, INSIDE THE MAP (Pavan, 2026-10-13) — finding a site only. */}
      {!onPress && <div className="absolute top-2 right-2 left-14 z-[1000]">
        <div className="relative">
          <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search a location or address"
            aria-label="Search a location or address"
            className="h-9 bg-background pr-8 pl-8 shadow-sm"
          />
          {searching ? (
            <Loader2 className="absolute top-1/2 right-2.5 size-4 -translate-y-1/2 animate-spin text-muted-foreground" />
          ) : (
            query && (
              <button
                type="button"
                aria-label="Clear search"
                onClick={() => setQuery("")}
                className="absolute top-1/2 right-2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground hover:text-foreground"
              >
                <X className="size-4" />
              </button>
            )
          )}
        </div>
        {results.length > 0 && (
          <ul className="mt-1 max-h-56 overflow-auto rounded-md border border-border bg-popover p-1 shadow-md">
            {results.map((r, i) => (
              <li key={i}>
                <button
                  type="button"
                  onClick={() => {
                    const name = r.display_name.split(",").slice(0, 2).join(",");
                    picked.current = name.trim();
                    setPending(placeOf(r));
                    setResults([]);
                    setQuery(name);
                  }}
                  className="flex w-full items-start gap-2 rounded-sm px-2 py-1.5 text-left text-sm hover:bg-accent"
                >
                  <MapPin className="mt-0.5 size-4 shrink-0 text-muted-foreground" />
                  <span className="line-clamp-2">{r.display_name}</span>
                </button>
              </li>
            ))}
          </ul>
        )}
        {offline && (
          <p className="mt-1 rounded-md bg-background/95 px-2 py-1 text-xs text-muted-foreground shadow-sm">
            Location search is unavailable offline.
          </p>
        )}
      </div>}

      {/* CONFIRM — the proposed place goes into the address fields. */}
      {pending && (
        <div className="absolute right-2 bottom-6 left-2 z-[1000] flex items-center gap-3 rounded-md border border-border bg-background/95 px-3 py-2 shadow-md">
          <MapPin className="size-4 shrink-0 text-brand" />
          <span className="min-w-0 flex-1 truncate text-sm text-foreground">
            {resolving
              ? "Finding the address…"
              : [pending.street, pending.city, pending.state, pending.zip].filter(Boolean).join(", ") ||
                `${pending.lat.toFixed(5)}, ${pending.lng.toFixed(5)}`}
          </span>
          <Button variant="ghost" size="sm" onClick={() => setPending(null)}>
            Cancel
          </Button>
          <Button
            size="sm"
            disabled={resolving}
            onClick={() => {
              onConfirm?.(pending);
              setPending(null);
            }}
          >
            <Check />
            Confirm location
          </Button>
        </div>
      )}
    </div>
  );
}

