import { toast } from "sonner";
import { Download } from "lucide-react";
import { Button } from "@/components/ui/button";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { cn } from "@/lib/utils";
import { DATE_FMT } from "../unified-view/data";
import { ACCOUNT, TENANT, printKey } from "./orders";
import { PRICES_AS_OF } from "./orders";
import { OPEN, amountDue, daysFrom, totalOf, type Invoice } from "./invoices";

/*
  STATEMENT & BALANCE (Pavan, 2026-10-15 — PRD FR-09, a tab inside
  Invoices): the account's ledger for the last 90 days — every invoice as a
  charge, every confirmed payment as a credit, the running balance — under
  four figures (opening, charges, payments, closing). Dated from the ERP;
  downloads as PDF or CSV. A payment the customer reported but the tenant
  has not confirmed is not on the statement yet.
*/

const usd = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

interface Line {
  date: string;
  doc: string;
  what: string;
  charge: number;
  payment: number;
}

export function StatementView({
  invoices,
  segments,
  segmentValue,
  onSegmentChange,
}: {
  invoices: Invoice[];
  segments: { key: string; label: string }[];
  segmentValue: string;
  onSegmentChange: (k: string) => void;
}) {
  /* THE PERIOD — 90 days to today. */
  const inPeriod = (key: string) => daysFrom(key) >= -90 && daysFrom(key) <= 0;
  const lines: Line[] = [];
  for (const i of invoices) {
    if (inPeriod(i.issued))
      lines.push({ date: i.issued, doc: i.invoiceNo, what: `Invoice · ${i.orderNo} · ${i.shipTo}`, charge: totalOf(i), payment: 0 });
    if (i.status === "Payment confirmed" && i.paidOn && inPeriod(i.paidOn))
      lines.push({ date: i.paidOn, doc: i.invoiceNo, what: "Payment received", charge: 0, payment: totalOf(i) });
    /* A CREDIT NOTE FROM A DISPUTE IS ITS OWN ROW (Pavan, 2026-10-15). */
    const o = i.dispute?.outcome;
    if (o?.credit && o.creditNoteNo) {
      const k = o.at.slice(0, 10);
      if (inPeriod(k)) lines.push({ date: k, doc: o.creditNoteNo, what: `Credit note · ${i.invoiceNo} dispute`, charge: 0, payment: o.credit });
    }
  }
  lines.sort((a, b) => a.date.localeCompare(b.date) || b.charge - a.charge);
  const charges = lines.reduce((t, l) => t + l.charge, 0);
  const payments = lines.reduce((t, l) => t + l.payment, 0);
  /* THE CLOSING BALANCE IS WHAT IS STILL OPEN; the opening follows from it. */
  const closing = invoices.filter((i) => OPEN.includes(i.status) || i.status === "Paid").reduce((t, i) => t + amountDue(i), 0);
  /* ROUNDED TO THE CENT — no "-$0.00". */
  const opening = Math.round((closing - charges + payments) * 100) / 100 || 0;
  let running = opening;
  const rows = lines.map((l) => {
    running += l.charge - l.payment;
    return { ...l, balance: running };
  });

  const figures = [
    { label: "Opening balance", value: opening },
    { label: "Charges", value: charges },
    { label: "Payments", value: -payments },
    { label: "Closing balance", value: closing, strong: true },
  ];

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      {/* THE TAB SWITCH AND THE DOWNLOAD — the list's view-row place. */}
      <div className="flex h-12 shrink-0 items-end justify-between gap-3 border-b border-border">
        <p className="mb-2.5 text-xs text-muted-foreground">
          {ACCOUNT} · last 90 days · as of {DATE_FMT.format(PRICES_AS_OF)} from {TENANT}
        </p>
        <span className="mb-2.5 flex items-center gap-2">
          <ToggleGroup
            type="single"
            variant="outline"
            size="sm"
            value={segmentValue}
            onValueChange={(v) => v && onSegmentChange(v)}
            aria-label="Invoices or statement"
            className="h-7"
          >
            {segments.map((s) => (
              <ToggleGroupItem key={s.key} value={s.key} className="h-7 px-2.5 text-xs font-normal data-[state=on]:font-medium">
                {s.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
          <Button variant="outline" size="sm" className="h-7" onClick={() => toast.success("Statement downloaded")}>
            <Download />
            Download
          </Button>
        </span>
      </div>

      <div className="mt-4 grid shrink-0 grid-cols-2 divide-border rounded-xl border border-border bg-fp-surface-1b sm:grid-cols-4 sm:divide-x">
        {figures.map((f) => (
          <div key={f.label} className="flex flex-col gap-1 px-4 py-3">
            <span className="text-xs text-muted-foreground">{f.label}</span>
            <span className={cn("tabular-nums text-foreground", f.strong ? "text-xl font-semibold" : "text-lg font-medium")}>
              {usd.format(f.value)}
            </span>
          </div>
        ))}
      </div>

      <div className="mt-4 min-h-0 flex-1 overflow-auto rounded-xl border border-border">
        <table className="w-full table-fixed border-collapse text-sm">
          <colgroup>
            <col className="w-[130px]" />
            <col className="w-[120px]" />
            <col />
            <col className="w-[140px]" />
            <col className="w-[140px]" />
            <col className="w-[150px]" />
          </colgroup>
          <thead className="sticky top-0 z-10">
            <tr className="border-b border-border bg-fp-table-header text-left text-xs font-medium text-muted-foreground">
              <th className="px-4 py-2.5 font-medium">Date</th>
              <th className="px-3 py-2.5 font-medium">Document</th>
              <th className="px-3 py-2.5 font-medium">Description</th>
              <th className="px-3 py-2.5 font-medium">Charges</th>
              <th className="px-3 py-2.5 font-medium">Payments</th>
              <th className="px-4 py-2.5 font-medium">Balance</th>
            </tr>
          </thead>
          <tbody>
            <tr className="h-11 border-b border-border text-muted-foreground">
              <td className="px-4" colSpan={5}>
                Opening balance
              </td>
              <td className="px-4 tabular-nums">{usd.format(opening)}</td>
            </tr>
            {rows.map((l, k) => (
              <tr key={k} className="h-11 border-b border-border last:border-b-0">
                <td className="px-4 text-foreground">{printKey(l.date)}</td>
                <td className="px-3 tabular-nums text-foreground">{l.doc}</td>
                <td className="truncate px-3 text-muted-foreground">{l.what}</td>
                <td className="px-3 tabular-nums text-foreground">{l.charge ? usd.format(l.charge) : "—"}</td>
                <td className="px-3 tabular-nums text-foreground">{l.payment ? usd.format(l.payment) : "—"}</td>
                <td className="px-4 font-medium tabular-nums text-foreground">{usd.format(l.balance)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import * as React from "react";
import { ArrowUpRight, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/utils";
import { CELL, RecordSheet } from "../unified-view/RecordSheet";
import {
  SHIP_TOS,
  daysToEmpty,
  daysUntil,
  levelBand,
  orderListRows,
  printKey,
  todayKey,
  NOT_DELIVERED,
  YET_TO_DELIVER,
  type Asset,
  type LevelBand,
  type OrderRequest,
} from "./orders";
import { BatteryCell, DaysToEmpty, LevelReading } from "./TankLevel";

/*
  TANK HEALTH (Pavan, 2026-10-20) — the dashboard's tank unit, in the
  Schedule card's shape: three boxes, the corner arrow opens the table.

    Tank levels      every monitored tank by the monitor's own bands
                     (≤10 urgent · 10–49 low · 50–79 moderate · 80+ fine),
                     one coloured bar and a count per band
    Days to empty    tanks running dry in 1, 2 and 3 days — and how many
                     will run dry before their next delivery (none planned
                     in time): the ones to order for now
    Monitor battery  monitors below 40%, 20%, 10% and 5% (Pavan, 2026-10-20),
                     in the Days-to-empty box's shape

  Every count is a button: it opens the table showing just those tanks.
  Each row can start an order for its tank.
*/

const BANDS: { band: LevelBand; label: string; fill: string }[] = [
  { band: "Urgent", label: "Urgent", fill: "bg-fp-lane-red" },
  { band: "Low", label: "Low", fill: "bg-fp-lane-red/55" },
  { band: "Moderate", label: "Moderate", fill: "bg-fp-lane-yellow" },
  { band: "Sufficient", label: "Fine", fill: "bg-fp-lane-green" },
];
const BATTERY_STEPS = [40, 20, 10, 5] as const;
type BatteryStep = (typeof BATTERY_STEPS)[number];

interface Tank {
  a: Asset;
  shipTo: string;
  /** Days to empty at today's usage — null without usage. */
  empty: number | null;
  /** The next delivery planned for it, `YYYY-MM-DD`. */
  next: string | null;
  /** Runs dry before its next delivery — or has none. */
  dry: boolean;
}

type Filter =
  | { kind: "all" }
  | { kind: "band"; band: LevelBand }
  | { kind: "days"; days: 1 | 2 | 3 }
  | { kind: "dry" }
  | { kind: "battery"; below: BatteryStep };

const FILTER_TITLE = (f: Filter) =>
  f.kind === "band"
    ? `${BANDS.find((b) => b.band === f.band)!.label} tanks`
    : f.kind === "days"
      ? `Empty in ${f.days} ${f.days === 1 ? "day" : "days"}`
      : f.kind === "dry"
        ? "Running dry before the next delivery"
        : f.kind === "battery"
          ? `Monitor battery below ${f.below}%`
          : "Monitored tanks";

function tanksOf(rows: OrderRequest[]): Tank[] {
  const t = todayKey();
  const coming = orderListRows(rows).filter(
    (r) => r.date >= t && (NOT_DELIVERED.includes(r.status) || YET_TO_DELIVER.includes(r.status))
  );
  return SHIP_TOS.flatMap((s) =>
    s.assets
      .filter((a) => a.monitor && a.status === "Active")
      .map((a) => {
        const empty = daysToEmpty(a);
        const next =
          coming
            .filter((r) => r.lines.some((l) => l.assetId === a.id))
            .map((r) => r.date)
            .sort()[0] ?? null;
        const dry = empty !== null && (next === null || daysUntil(next) > empty);
        return { a, shipTo: s.name, empty, next, dry };
      })
  ).sort((x, y) => x.a.level - y.a.level);
}

const matches = (f: Filter, t: Tank) =>
  f.kind === "all"
    ? true
    : f.kind === "band"
      ? levelBand(t.a.level) === f.band
      : f.kind === "days"
        ? t.empty !== null && (f.days === 1 ? t.empty <= 1 : t.empty === f.days)
        : f.kind === "dry"
          ? t.dry
          : t.a.battery < f.below;

/** A count that opens the table at its tanks. */
function CountButton({
  children,
  onClick,
  label,
  className,
}: {
  children: React.ReactNode;
  onClick: () => void;
  label: string;
  className?: string;
}) {
  return (
    <button
      type="button"
      aria-label={label}
      onClick={onClick}
      className={cn(
        "flex min-w-0 flex-col items-start gap-0.5 rounded-md px-1.5 py-1 text-left outline-none -mx-1.5 transition-colors hover:bg-fp-row-hover focus-visible:ring-2 focus-visible:ring-ring/50",
        className
      )}
    >
      {children}
    </button>
  );
}

function Box({ title, children, className }: { title: string; children: React.ReactNode; className?: string }) {
  return (
    <section className={cn("flex min-w-0 flex-1 flex-col gap-2 px-4 py-3", className)}>
      <h3 className="text-sm font-medium text-foreground">{title}</h3>
      {children}
    </section>
  );
}

export function TankHealthCard({
  rows,
  onCreateOrder,
}: {
  rows: OrderRequest[];
  /** Start an order for one tank — its ship-to and asset. */
  onCreateOrder: (shipTo: string, assetId: string) => void;
}) {
  const tanks = React.useMemo(() => tanksOf(rows), [rows]);
  const [filter, setFilter] = React.useState<Filter | null>(null);
  const open = (f: Filter) => setFilter(f);
  const count = (f: Filter) => tanks.filter((t) => matches(f, t)).length;
  const dry = count({ kind: "dry" });
  const shown = filter ? tanks.filter((t) => matches(filter, t)) : [];

  return (
    <>
      <div className="relative shrink-0 rounded-xl border border-border bg-fp-surface-1b">
        <div className="flex flex-col divide-y divide-border md:flex-row md:divide-x md:divide-y-0">
          <Box title="Tank levels">
            <p className="flex items-baseline gap-2">
              <span className="text-3xl font-semibold tabular-nums text-foreground">{tanks.length}</span>
              <span className="text-sm text-muted-foreground">monitored tanks</span>
            </p>
            {/* ONE BAR, A SEGMENT PER BAND — the monitors' own colours. */}
            <div className="flex h-2 w-full gap-0.5 overflow-hidden rounded-full" role="img" aria-label="Tanks by level">
              {BANDS.map((b) => {
                const n = count({ kind: "band", band: b.band });
                return n ? <span key={b.band} className={cn("h-full", b.fill)} style={{ flex: n }} /> : null;
              })}
            </div>
            <div className="grid grid-cols-4 gap-2">
              {BANDS.map((b) => (
                <CountButton key={b.band} label={`Show ${b.label.toLowerCase()} tanks`} onClick={() => open({ kind: "band", band: b.band })}>
                  <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
                    <span aria-hidden className={cn("size-2 rounded-[2px]", b.fill)} />
                    {b.label}
                  </span>
                  <span className="text-sm font-medium tabular-nums text-foreground">{count({ kind: "band", band: b.band })}</span>
                </CountButton>
              ))}
            </div>
          </Box>

          <Box title="Days to empty">
            <div className="grid grid-cols-3 gap-2">
              {([1, 2, 3] as const).map((d) => (
                <CountButton key={d} label={`Show tanks empty in ${d} ${d === 1 ? "day" : "days"}`} onClick={() => open({ kind: "days", days: d })}>
                  <span className="text-xs text-muted-foreground">
                    {d} {d === 1 ? "day" : "days"}
                  </span>
                  <span className="text-2xl font-semibold tabular-nums text-foreground">{count({ kind: "days", days: d })}</span>
                </CountButton>
              ))}
            </div>
            <CountButton label="Show tanks running dry before their next delivery" onClick={() => open({ kind: "dry" })}>
              <span className={cn("text-sm", dry ? "font-medium text-status-failed" : "text-muted-foreground")}>
                {dry} will run dry before their next delivery
              </span>
            </CountButton>
          </Box>

          {/* Room for the corner button. */}
          <Box title="Monitor battery" className="pr-12">
            <div className="grid grid-cols-4 gap-2">
              {BATTERY_STEPS.map((p) => (
                <CountButton key={p} label={`Show monitors with battery below ${p}%`} onClick={() => open({ kind: "battery", below: p })}>
                  <span className="whitespace-nowrap text-xs text-muted-foreground">Below {p}%</span>
                  <span className="text-2xl font-semibold tabular-nums text-foreground">{count({ kind: "battery", below: p })}</span>
                </CountButton>
              ))}
            </div>
          </Box>
        </div>
        {/* THE ONE CONTROL, IN THE CARD'S CORNER — every tank. */}
        <Button
          variant="outline"
          size="icon-sm"
          aria-label="View every monitored tank"
          title="View details"
          onClick={() => open({ kind: "all" })}
          className="absolute top-2.5 right-2.5 rounded-full"
        >
          <ArrowUpRight />
        </Button>
      </div>

      <RecordSheet
        fit={{ tables: [[CELL.name, CELL.pick, CELL.level, CELL.number, CELL.date, CELL.battery, CELL.pick]] }}
        open={filter !== null}
        onOpenChange={(o) => !o && setFilter(null)}
        mode="edit"
        editTitle={filter ? FILTER_TITLE(filter) : ""}
        createTitle=""
        createAction=""
        showCancel={false}
        onSubmit={() => {}}
        footerPrimary={null}
      >
        {shown.length === 0 ? (
          <p className="text-sm text-muted-foreground">No tanks.</p>
        ) : (
          <div className="overflow-hidden rounded-md border border-border">
            <Table>
              <TableHeader>
                <TableRow className="bg-fp-table-header hover:bg-fp-table-header">
                  <TableHead className="pl-4">Asset</TableHead>
                  <TableHead>Ship-to</TableHead>
                  <TableHead>Current level</TableHead>
                  <TableHead>Days to empty</TableHead>
                  <TableHead>Next delivery</TableHead>
                  <TableHead>Battery</TableHead>
                  <TableHead className="pr-4" />
