    <div className="flex min-h-0 flex-1 flex-col">
      <PortalList<PortalUser, UK>
        rows={users}
        columns={COLUMNS}
        rowId={(u) => u.id}
        text={text}
        sortValue={(u, k) =>
          k === "lastLogin" ? (u.lastLoginAt ?? "") : k === "deactivated" ? (u.deactivatedAt ?? "") : undefined
        }
        renderCell={(u, k) => {
          switch (k) {
