          }
        }}
        facets={[
          { key: "role", label: "Role", options: [...PORTAL_ROLES] },
          { key: "invite", label: "Invite status", options: ["Active", "Pending"] },
          { key: "state", label: "Account", options: ["Active", "Deactivated"] },
        ]}
