  return (
    <div className="flex">
      <BreakdownPopover
        align="end"
        className="rounded-sm"
        label={`Show quantity breakdown of ${r.requestNo}`}
        trigger={face}
        card={{
          title: "Quantity by tank",
          rows: r.lines.map((l) => ({ label: assetName(l), sub: l.product || "No product", value: lineQty(l) })),
