  if (!then) return null;
  const d = Math.round(((now - then) / then) * 100);
  return <TrendChip dir={d === 0 ? "same" : d > 0 ? "up" : "down"}>{d === 0 ? "Same" : `${Math.abs(d)}%`}</TrendChip>;
}

