/* ---------------------------------------------------------------- trip --- */

/*
  THE TRIP, STEP BY STEP (PRD FR-05) — loaded (the BOL), departed, the ETA
  changed and why, arriving in 30 minutes, arrived, unloading, delivered.
  Out for delivery: the steps so far, the rest to come. Delivered: all of
  them, from the window. Times INVENTED around the trip and the window.
*/
export function tripSteps(r: OrderRequest) {
  const day = dateOfKey(r.date);
  const dep = r.trip ? Date.parse(r.trip.departedAt) : day ? day.getTime() + (r.windowStart - 45) * 60_000 : null;
  const eta = r.trip ? Date.parse(r.trip.eta) : dep ? dep + 75 * 60_000 : null;
  if (!dep || !eta) return [];
  const late = r.flags.find((f) => f.kind === "At risk of being late");
  const steps = [
    { at: dep - 30 * 60_000, what: `Loaded · BOL B-${4400 + Number(r.requestNo.slice(-2))}` },
    { at: dep, what: `Departed${r.trip ? ` · ${r.trip.truck}` : ""}` },
    ...(late ? [{ at: dep + 15 * 60_000, what: `ETA changed · ${late.detail}` }] : []),
    { at: eta - 30 * 60_000, what: "Arriving in 30 minutes" },
    { at: eta, what: "Arrived on site" },
    { at: eta + 5 * 60_000, what: "Unloading" },
    { at: eta + 40 * 60_000, what: r.status === "Partial delivery" ? "Partly delivered" : "Delivered · ticket ready" },
  ];
  const now = Date.now();
  const delivered = r.status !== "Out for delivery";
  return steps.map((s) => ({ ...s, done: delivered || s.at <= now }));
}

const hm = (t: number) => {
  const d = new Date(t);
  return formatMinutes(d.getHours() * 60 + d.getMinutes());
};

export function TripTimeline({ r }: { r: OrderRequest }) {
  const steps = tripSteps(r);
  if (steps.length === 0) return null;
  const nextAt = steps.findIndex((s) => !s.done);
  return (
    <ol className="flex flex-col">
      {steps.map((s, i) => (
        <li key={i} className="relative flex gap-3 pb-3 last:pb-0">
          {/* THE STEPPER'S COLOURS (Pavan, 2026-10-19): done green and the
              line green up to the step in progress; that step violet (the
              accent); the rest grey. */}
          {i < steps.length - 1 && (
            <span
              aria-hidden
              className={cn("absolute top-3 bottom-0 left-[5px] w-0.5 -translate-x-[0.5px]", s.done ? "bg-status-success" : "bg-border")}
            />
          )}
          <span
            aria-hidden
            className={cn(
              "relative mt-1 size-[11px] shrink-0 rounded-full border-2",
              s.done
                ? "border-status-success bg-status-success"
                : i === nextAt
                  ? "border-accent-violet bg-fp-surface-1b"
                  : "border-border bg-fp-surface-1b"
            )}
          />
          <span className="flex min-w-0 flex-1 items-baseline justify-between gap-3">
            <span
              className={cn(
                "text-sm",
                s.done ? "text-foreground" : i === nextAt ? "font-medium text-accent-violet-ink" : "text-muted-foreground"
              )}
            >
              {s.what}
            </span>
            <span className="shrink-0 text-xs tabular-nums text-muted-foreground">{s.done ? hm(s.at) : `~${hm(s.at)}`}</span>
          </span>
        </li>
      ))}
    </ol>
  );
}

export const replyActor = PORTAL_ACTOR;

import * as React from "react";
import {
  DELIVERED,
  LIVE,
  PORTAL_ACTOR,
  SHIP_TOS,
  allRequests,
  todayKey,
  categoryOf,
  renameShipToInRequests,
  type ActiveStatus,
  type Asset,
  type ShipTo,
} from "./orders";

/*
  THE SITES STORE (Pavan, 2026-10-13) — ship-tos and assets, kept by the
  customer with no approval step. It edits `SHIP_TOS` in place, so the order
  sheet and the map read new records at once, and hands React a new snapshot
  on every change. The setter writes the activity log.
*/

let snapshot: ShipTo[] = [...SHIP_TOS];
const listeners = new Set<() => void>();
const emit = () => {
  snapshot = [...SHIP_TOS];
  listeners.forEach((l) => l());
};
const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};

export function useShipTos(): ShipTo[] {
  return React.useSyncExternalStore(subscribe, () => snapshot);
}

const log = (audit: ShipTo["audit"], change: string) => [
  ...(audit ?? []),
  { at: new Date().toISOString(), by: PORTAL_ACTOR, changes: [change] },
];

let seq = 0;
const newId = (p: string) => `${p}-new-${Date.now().toString(36)}-${++seq}`;

export type AssetDraft = Omit<Asset, "id" | "audit" | "level" | "battery" | "dailyUse"> & { id?: string };
export type ShipToDraft = Omit<ShipTo, "id" | "audit" | "assets"> & { assets: AssetDraft[] };

/* ONE PRODUCT LIST — `product` is its first (what an order line starts
   from); categories left empty follow the products chosen. */
const toAsset = (d: AssetDraft, keep?: Asset): Asset => ({
  ...d,
  product: d.products[0] ?? "",
  categories: d.categories.length
    ? d.categories
    : Array.from(new Set(d.products.map(categoryOf).filter(Boolean))),
  id: d.id ?? newId("as"),
  level: keep?.level ?? 0,
  battery: keep?.battery ?? 100,
  dailyUse: keep?.dailyUse ?? 0,
  audit: keep?.audit ?? [{ at: new Date().toISOString(), by: PORTAL_ACTOR, changes: ["Asset added"] }],
});

export function blankAsset(): AssetDraft {
  return {
    name: "",
    code: "",
    rfid: "",
    erpId: "",
    type: "",
    categories: [],
    products: [],
    product: "",
    capacity: 0,
    rented: false,
    monitor: false,
    monitorId: "",
    lat: null,
    lng: null,
    status: "Active",
    notes: "",
  };
}

export function blankShipTo(): ShipToDraft {
  return {
    name: "",
    street: "",
    city: "",
    state: "",
    zip: "",
    lat: NaN,
    lng: NaN,
    contactName: "",
    contactPhone: "",
    hoursStart: 6 * 60,
    hoursEnd: 18 * 60,
    accessNotes: "",
    poNumber: "",
    geofence: null,
    status: "Active",
    assets: [],
  };
}

/*
  MAPPING AN EXISTING ASSET MOVES IT (Pavan, 2026-10-14 — step 2 of a
  ship-to maps assets to it). An asset stands at one ship-to, so a draft row
  that carries the id of an asset somewhere else takes it from there, with its
  reading and its history, and logs the move.
*/
function claim(d: AssetDraft, toId: string, toName: string): Asset {
  const from = SHIP_TOS.find((x) => x.id !== toId && x.assets.some((a) => a.id === d.id));
  if (!from || !d.id) return toAsset(d, SHIP_TOS.find((x) => x.id === toId)?.assets.find((a) => a.id === d.id));
  const prev = from.assets.find((a) => a.id === d.id)!;
  from.assets = from.assets.filter((a) => a.id !== d.id);
  from.audit = log(from.audit, `${prev.name} moved to ${toName}`);
  const a = toAsset(d, prev);
  return { ...a, audit: log(a.audit, `Moved from ${from.name} to ${toName}`) };
}

export function createShipTo(d: ShipToDraft): ShipTo {
  const at = new Date().toISOString();
  const id = newId("st");
  const s: ShipTo = {
    ...d,
    id,
    assets: d.assets.map((a) => claim(a, id, d.name)),
    audit: [{ at, by: PORTAL_ACTOR, changes: ["Ship-to created"] }],
  };
  SHIP_TOS.unshift(s);
  emit();
  return s;
}

/** Write a ship-to's draft — its assets too: new rows are added, gone ones removed. */
export function updateShipTo(id: string, d: ShipToDraft, change?: string) {
  const i = SHIP_TOS.findIndex((s) => s.id === id);
  if (i < 0) return;
  const prev = SHIP_TOS[i];
  renameShipToInRequests(prev.name, d.name);
  SHIP_TOS[i] = {
    ...prev,
    ...d,
    assets: d.assets.map((a) => claim(a, id, d.name)),
    audit: change ? log(prev.audit, change) : prev.audit,
  };
  emit();
}

export function createAsset(shipToId: string, d: AssetDraft): Asset {
  const s = SHIP_TOS.find((x) => x.id === shipToId);
  const a = toAsset(d);
  s?.assets.unshift(a);
  emit();
  return a;
}

/** Write an asset; a new ship-to moves it there. */
export function updateAsset(id: string, shipToId: string, d: AssetDraft, change?: string) {
  const from = SHIP_TOS.find((s) => s.assets.some((a) => a.id === id));
  const prev = from?.assets.find((a) => a.id === id);
  if (!from || !prev) return;
  const next: Asset = { ...prev, ...d, product: d.products[0] ?? "", id, audit: change ? log(prev.audit, change) : prev.audit };
  if (from.id === shipToId) {
    from.assets = from.assets.map((a) => (a.id === id ? next : a));
  } else {
    from.assets = from.assets.filter((a) => a.id !== id);
    SHIP_TOS.find((s) => s.id === shipToId)?.assets.unshift(next);
  }
  emit();
}

export function setShipToStatus(id: string, status: ActiveStatus) {
  const s = SHIP_TOS.find((x) => x.id === id);
  if (!s) return;
  s.status = status;
  s.audit = log(s.audit, status === "Active" ? "Reactivated" : "Deactivated");
  emit();
}

export function setAssetStatus(id: string, status: ActiveStatus) {
  const s = SHIP_TOS.find((x) => x.assets.some((a) => a.id === id));
  if (!s) return;
  s.assets = s.assets.map((a) =>
    a.id === id ? { ...a, status, audit: log(a.audit, status === "Active" ? "Reactivated" : "Deactivated") } : a
  );
  emit();
}

/** Requests still on their way to this asset — they block deactivating it. */
export function openOrdersForAsset(id: string): number {
  return allRequests().filter(
    (r) =>
      LIVE.includes(r.status) && !DELIVERED.includes(r.status) && r.lines.some((l) => l.assetId === id)
  ).length;
}

/** The same, for a ship-to. */
export function openOrdersForShipTo(name: string): number {
  return allRequests().filter(
    (r) => LIVE.includes(r.status) && !DELIVERED.includes(r.status) && r.shipTo === name
  ).length;
}

/* A SHIP-TO'S LAST AND NEXT DELIVERY (the real product shows both) —
   derived from the requests, never stored. */
export function lastDeliveryToShipTo(name: string): string | null {
  const d = allRequests()
    .filter((r) => r.shipTo === name && DELIVERED.includes(r.status) && r.date)
    .map((r) => r.date)
    .sort();
  return d.length ? d[d.length - 1] : null;
}
export function nextDeliveryToShipTo(name: string): string | null {
  const today = todayKey();
  const d = allRequests()
    .filter((r) => r.shipTo === name && LIVE.includes(r.status) && !DELIVERED.includes(r.status) && r.date >= today)
    .map((r) => r.date)
    .sort();
  return d.length ? d[0] : null;
}

/** The last request delivered to this asset, if any. */
export function lastDeliveryFor(id: string): string | null {
  const d = allRequests()
    .filter((r) => DELIVERED.includes(r.status) && r.lines.some((l) => l.assetId === id) && r.date)
    .map((r) => r.date)
    .sort();
  return d.length ? d[d.length - 1] : null;
}

/** Who added the asset, and when — its first log entry. */
export function createdOf(a: Asset): { by: string; at: string } | null {
  const e = a.audit?.[0];
  return e ? { by: e.by, at: e.at } : null;
}

