  orderNo: string;
  typeLabel: string;
  shipTo: string;
}

const toRecord = (o: OrderRef): RecordRef => ({
  id: o.orderNo,
  cells: [o.typeLabel, o.shipTo],
});

const ORDER_HEADERS = ["Order No", "Order Type", "ShipTo/Terminal"];

export function OrderMiniTable({ orders }: { orders: OrderRef[] }) {
