import * as React from "react";
import { CalendarDays } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DatePanel, DatePopover } from "@/components/ui/date-picker";
import { Combobox } from "@/components/ui/combobox";
import { Input } from "@/components/ui/input";
import { PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Switch } from "@/components/ui/switch";
import { SheetField, SheetSection } from "@/components/side-sheet/parts";
import type { PendingItem } from "./PendingStrip";
import { dateKeyOf, formatFullDate } from "./data";
import { useSalesSettings, type FormField, type SalesFormKind } from "./salesSettings";

/*
  A SALES SHEET'S BODY, AS SALES SETTINGS LAY IT OUT (Pavan, 2026-10-07 —
  "fix it all", C). The order of the rows on Form customization is the order
  the sheet draws its fields; a section is drawn where its first field sits;
  every label is the configured one; a hidden field is not drawn; a required
  one is marked, and the sheet's commit lists it until it is filled.

  The sheet hands over HOW to draw each of its own fields. Everything else — a
  field added from the library, a custom one, or a built-in one whose type was
  changed — is drawn here from its type, and its value lives in the record's
  `extra`.
*/

export type ExtraValue = string | boolean;
export type ExtraValues = Record<string, ExtraValue>;

export interface BuiltInField {
  /** The control, under the configured label. */
  control?: React.ReactNode;
  /** Draws its own label — a switch row. Given the configured label. */
  bare?: (label: string) => React.ReactNode;
  /** Sits beside the next half field, two to a row. */
  half?: boolean;
  className?: string;
  /* A FIELD THAT IS A TABLE. Its section goes flush round it (ui §10f); a
     field before it in the section sits in the box above the table, one
     after it sits under the box — the notes rule (ux §Record sheets). */
  table?: {
    node: React.ReactNode;
    hanging?: React.ReactNode;
    action?: React.ReactNode;
  };
}

export const sectionId = (kind: SalesFormKind, section: string) =>
  `${kind}-sec-${section.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

/** Is this field drawn by the sheet's own control, or from its type? */
export const isNative = (f: FormField, renderers: Record<string, unknown>) =>
  f.source === "built-in" && (!f.nativeType || f.type === f.nativeType) && f.key in renderers;

export const extraFilled = (v: ExtraValue | undefined) =>
  typeof v === "boolean" ? true : typeof v === "string" && v.trim() !== "";

/**
 * WHAT THE COMMIT IS STILL WAITING ON — every field marked required and drawn
 * that has nothing in it, in the form's order, as an instruction. A switch is
 * always answered, so it never waits.
 */
export function missingRequired(
  kind: SalesFormKind,
  fields: FormField[],
  filled: (f: FormField) => boolean
): PendingItem[] {
  return fields
    .filter((f) => f.visible && f.required && f.type !== "Toggle" && !filled(f))
    .map((f) => {
      const name = f.label.trim() || "the custom field";
      const verb =
        f.type === "Select" || f.type === "Date" ? "Choose" : f.type === "File" ? "Attach" : "Enter";
      return { key: `req-${f.key}`, label: `${verb} ${name}`, target: sectionId(kind, f.section) };
    });
}

/** The visible fields, grouped into sections in the order their first field sits. */
function sectionsOf(fields: FormField[]): { title: string; fields: FormField[] }[] {
  const out: { title: string; fields: FormField[] }[] = [];
  for (const f of fields) {
    if (!f.visible) continue;
    const title = f.section.trim() || "Other";
    const at = out.find((s) => s.title === title);
    if (at) at.fields.push(f);
    else out.push({ title, fields: [f] });
  }
  return out;
}

const SwitchRow = ({
  label,
  checked,
  onChange,
  disabled,
}: {
  label: string;
  checked: boolean;
  onChange: (v: boolean) => void;
  disabled?: boolean;
}) => (
  /* The order sheet's "Mark as Urgent" row: label left, switch right. */
  <div className="flex items-center justify-between gap-4">
    <span className="text-sm font-medium">{label}</span>
    <Switch checked={checked} disabled={disabled} onCheckedChange={onChange} aria-label={label} />
  </div>
);

/** A field the sheet does not draw itself — drawn from its type. */
function ExtraControl({
  f,
  value,
  onChange,
}: {
  f: FormField;
  value: ExtraValue | undefined;
  onChange: (v: ExtraValue) => void;
}) {
  const label = f.label.trim() || "Custom field";
  const text = typeof value === "string" ? value : "";
  switch (f.type) {
    case "Number":
      return (
        <Input
          inputMode="decimal"
          value={text}
          placeholder="0"
          aria-label={label}
          onChange={(e) => onChange(e.target.value.replace(/[^0-9.-]/g, ""))}
        />
      );
    case "Select": {
      const options = Array.from(new Set([...(f.options ?? []), ...(text ? [text] : [])]));
      return (
        <Combobox
          className="w-full"
          value={text}
          onValueChange={onChange}
          options={options}
          placeholder="Select"
          aria-label={label}
          allowCreate
          createLabel={(q) => `Add “${q}”`}
          /* AN OPTIONAL PICKER OFFERS ITS EMPTY CHOICE; a required one
             does not (ux §Forms). */
          clearLabel={f.required ? undefined : `No ${label.toLowerCase()}`}
        />
      );
    }
    case "Date": {
      const [y, m, d] = text.split("-").map(Number);
      const day = text ? new Date(y, m - 1, d) : null;
      return (
        <DatePopover>
          <PopoverTrigger asChild>
            <Button variant="outline" className="w-full justify-start font-normal" aria-label={label}>
              <CalendarDays />
              {day ? (
                formatFullDate(day)
              ) : (
                <span className="text-muted-foreground">Select date</span>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent align="start" className="w-auto p-0">
            <DatePanel
              selected={day ?? undefined}
              onSelect={(next) => next && onChange(dateKeyOf(next))}
            />
          </PopoverContent>
        </DatePopover>
      );
    }
    case "File":
      return (
        <div className="flex flex-col gap-1">
          <Input
            type="file"
            multiple
            aria-label={label}
            onChange={(e) =>
              onChange(
                Array.from(e.target.files ?? [])
                  .map((x) => x.name)
                  .join(", ")
              )
            }
          />
          {text && <span className="truncate text-xs text-muted-foreground">{text}</span>}
        </div>
      );
    default:
      return (
        <Input value={text} aria-label={label} onChange={(e) => onChange(e.target.value)} />
      );
  }
}

/**
 * THE SHEET'S BODY. `renderers` draws each built-in field the sheet owns;
 * `together` names fields that are one control (a table's columns) — the
 * first of them in the order draws it, the rest are skipped.
 */
export function ConfiguredForm({
  kind,
  renderers,
  together = [],
  extra,
  onExtraChange,
  className,
}: {
  kind: SalesFormKind;
  renderers: Record<string, (f: FormField) => BuiltInField>;
  together?: string[][];
  extra: ExtraValues;
  onExtraChange: (key: string, value: ExtraValue) => void;
  className?: string;
}) {
  const fields = useSalesSettings().forms[kind];
  const sections = sectionsOf(fields);
  const drawn = new Set<string>();

  /** One field, as the pieces a section lays out. */
  const piece = (f: FormField): (BuiltInField & { key: string; label: string; required: boolean }) | null => {
    if (drawn.has(f.key)) return null;
    for (const g of together) if (g.includes(f.key)) g.forEach((k) => drawn.add(k));
    drawn.add(f.key);
    const label = f.label.trim() || "Custom field";
    const base = { key: f.key, label, required: f.required };
    if (isNative(f, renderers)) return { ...base, ...renderers[f.key](f) };
    if (f.type === "Toggle")
      return {
        ...base,
        bare: (l) => (
          <SwitchRow
            label={l}
            checked={extra[f.key] === true}
            onChange={(v) => onExtraChange(f.key, v)}
          />
        ),
      };
    return {
      ...base,
      control: (
        <ExtraControl f={f} value={extra[f.key]} onChange={(v) => onExtraChange(f.key, v)} />
      ),
    };
  };

  /* Half fields run two to a row; anything else takes the row. */
  const layFields = (
    ps: NonNullable<ReturnType<typeof piece>>[],
    sectionTitle: string
  ): React.ReactNode[] => {
    const out: React.ReactNode[] = [];
    let row: React.ReactNode[] = [];
    const flush = () => {
      if (row.length) out.push(<div key={`row-${out.length}`} className="grid grid-cols-2 gap-4">{row}</div>);
      row = [];
    };
    /* A SECTION THAT IS ONE FIELD OF ITS OWN NAME IS THAT FIELD — the Tags
       section: the heading carries the name, and the mark. */
    const sole = ps.length === 1 && ps[0].label.toLowerCase() === sectionTitle.toLowerCase();
    for (const p of ps) {
      const node = p.bare ? (
        <React.Fragment key={p.key}>{p.bare(p.label)}</React.Fragment>
      ) : sole ? (
        <React.Fragment key={p.key}>{p.control}</React.Fragment>
      ) : (
        <SheetField key={p.key} label={p.label} required={p.required} className={p.className}>
          {p.control}
        </SheetField>
      );
      if (p.half) {
        row.push(node);
        if (row.length === 2) flush();
      } else {
        flush();
        out.push(node);
      }
    }
    flush();
    return out;
  };

  return (
    <div className={cn("contents", className)}>
      {sections.map((s) => {
        const ps = s.fields.map(piece).filter((p): p is NonNullable<typeof p> => p !== null);
        if (ps.length === 0) return null;
        const id = sectionId(kind, s.title);
        const at = ps.findIndex((p) => p.table);
        if (at === -1) {
          const sole =
            ps.length === 1 && !ps[0].bare && ps[0].label.toLowerCase() === s.title.toLowerCase();
          return (
            <SheetSection
              key={s.title}
              id={id}
              title={s.title}
              note={
                sole && ps[0].required ? <span className="text-sm text-destructive">*</span> : undefined
              }
            >
              {layFields(ps, s.title)}
            </SheetSection>
          );
        }
        /* ONE TABLE PER BOX. A second table in the same section gets a box of
           its own under the same name. */
        const before = ps.slice(0, at);
        const tbl = ps[at];
        const rest = ps.slice(at + 1);
        const nextTable = rest.findIndex((p) => p.table);
        const after = nextTable === -1 ? rest : rest.slice(0, nextTable);
        const more = nextTable === -1 ? [] : rest.slice(nextTable);
        return (
          <div key={s.title} className="flex flex-col gap-4">
            <SheetSection
              id={id}
              title={s.title}
              flush
              hanging={tbl.table!.hanging}
              action={tbl.table!.action}
            >
              {before.length > 0 && (
                <div className="flex flex-col gap-5 border-b border-border p-4">
                  {layFields(before, s.title)}
                </div>
              )}
              {tbl.table!.node}
            </SheetSection>
            {after.length > 0 && layFields(after, s.title)}
            {more.map((p) =>
              p.table ? (
                <SheetSection
                  key={p.key}
                  title={s.title}
                  flush
                  hanging={p.table.hanging}
                  action={p.table.action}
                >
                  {p.table.node}
                </SheetSection>
              ) : (
                layFields([p], s.title)
              )
            )}
          </div>
        );
      })}
    </div>
  );
}

import { cn } from "@/lib/utils";
import * as React from "react";
import { Plus, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Combobox } from "@/components/ui/combobox";
import { MultiSelectList } from "@/components/ui/multi-select-list";
import { StatusChip } from "@/components/ui/status-chip";
import { SheetField, SheetSection } from "@/components/side-sheet/parts";
import { DraftStatusChip, RecordSheet, useDraftSaveState } from "./RecordSheet";
import {
  BILLING_TERMS,
  LINES_OF_SERVICE,
  type Customer,
  type CustomerStatus,
  type LineOfService,
} from "./customers";
import { ACTIVE_KIND, kindTone } from "./statusKind";

/**
 * Customer side sheet — same shell and rhythm as the two order sheets.
 *
 * TWO CHOICES WORTH KNOWING:
 *
 * 1. STATUS IS A SWITCH, not a picker. The rulebook (§6) says active/inactive is
 *    controlled by a "labelled toggle row (label + helper + switch)" and
 *    "reflected as a status value in lists" — so the list column is a projection
 *    of this switch, which is exactly the pattern §6 describes.
 *
 * 2. LOS uses the DS `MultiSelectList` with `searchable={false}`. Three options
 *    can be taken in at once, and that component's own rule is that a filter
 *    field is opt-in for exactly this reason.
 *
 * Ship-tos are edited as removable chips plus an add field. A customer's ship-to
 * list is the one thing here that is a collection of free text rather than a pick
 * from a fixed set, so it cannot be a select.
 */

export interface CustomerDraft {
  name: string;
  erpId: string;
  shipTos: string[];
  los: LineOfService[];
  status: CustomerStatus;
  billingTerms: string;
  contactName: string;
  contactEmail: string;
  contactPhone: string;
  note: string;
}

function draftFrom(c: Customer): CustomerDraft {
  return {
    name: c.name,
    erpId: c.erpId,
    shipTos: [...c.shipTos],
    los: [...c.los],
    status: c.status,
    billingTerms: c.billingTerms,
    contactName: c.contactName,
    contactEmail: c.contactEmail,
    contactPhone: c.contactPhone,
    note: c.note,
  };
}

/** A blank customer. `status: "Active"` — a switch has no empty state. */
function emptyDraft(): CustomerDraft {
  return {
    name: "",
    erpId: "",
    shipTos: [],
    los: [],
    status: "Active",
    billingTerms: "",
    contactName: "",
    contactEmail: "",
    contactPhone: "",
    note: "",
  };
}

export interface CustomerSheetProps {
  customer: Customer | null;
  mode?: "edit" | "create";
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (customer: Customer, draft: CustomerDraft) => void;
  onCreate?: (draft: CustomerDraft) => void;
}

export function CustomerSheet({
  customer,
  mode = "edit",
  open,
  onOpenChange,
  onSave,
  onCreate,
}: CustomerSheetProps) {
  const [draft, setDraft] = React.useState<CustomerDraft | null>(null);
  const [newShipTo, setNewShipTo] = React.useState("");
  const creating = mode === "create";
  const saveState = useDraftSaveState(draft, open);
  /* WHAT WENT OUT LAST. The row comes back changed by our own save, so
     without this the sheet would answer its own write with a rebuild. */
  const lastSaved = React.useRef<string | null>(null);

  /* THE DRAFT IS BUILT ONCE PER RECORD, keyed on the id rather than the row.
     Keyed on the row, every autosave would rebuild the form under the
     cursor. */
  const customerId = customer?.id ?? null;
  React.useEffect(() => {
    if (!open) return;
    const next = creating ? emptyDraft() : customer ? draftFrom(customer) : null;
    lastSaved.current = next ? JSON.stringify(next) : null;
    setDraft(next);
    setNewShipTo("");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, creating, customerId]);

  /* AUTOSAVED, DEBOUNCED — 600ms, the same everywhere. */
  React.useEffect(() => {
    if (creating || !customer || !draft) return;
    const serialised = JSON.stringify(draft);
    if (serialised === lastSaved.current) return;
    const t = window.setTimeout(() => {
      lastSaved.current = serialised;
      onSave(customer, draft);
    }, 600);
    return () => window.clearTimeout(t);
  }, [draft, customer, creating, onSave]);

  if (!draft || (!creating && !customer)) return null;

  const set = <K extends keyof CustomerDraft>(key: K, value: CustomerDraft[K]) =>
    setDraft((d) => (d ? { ...d, [key]: value } : d));

  const addShipTo = () => {
    const v = newShipTo.trim();
    if (!v || draft.shipTos.includes(v)) return;
    set("shipTos", [...draft.shipTos, v]);
    setNewShipTo("");
  };

  return (
    <RecordSheet
      /* A RECORD IS DATA-INTENSIVE — 1200, fields three across; creating is
         a 600 form (Pavan, 2026-10-15). */
      size={creating ? "form" : "data"}
      open={open}
      onOpenChange={onOpenChange}
      mode={mode}
      editTitle={customer?.name ?? ""}
      createTitle="Create New Customer"
      // Matches the header and the rail CTA verbatim; Asset Orders does the same.
      createAction="Create New Customer"
      /* IT AUTOSAVES, SO THERE IS NOTHING TO CANCEL AND NOTHING TO SAVE.
         Creating still takes an act. */
      showCancel={false}
      footerPrimary={creating ? undefined : null}
      headerAside={
        <span className="flex items-center gap-2">
          <StatusChip
            tone={kindTone(ACTIVE_KIND(draft.status === "Active"))}
            variant="soft"
          >
            {draft.status}
          </StatusChip>
          {saveState !== "idle" && (
            <DraftStatusChip tone="neutral" label="Draft" saveState={saveState} />
          )}
        </span>
      }
      onSubmit={() => {
        if (creating) onCreate?.(draft);
      }}
    >
      <SheetSection title="Customer Details">
        <div className={cn("grid gap-4", creating ? "grid-cols-2" : "grid-cols-3")}>
          <SheetField label="Customer Name">
            <Input
              value={draft.name}
              placeholder="e.g. Morris Group"
              onChange={(e) => set("name", e.target.value)}
            />
          </SheetField>
          <SheetField label="ERP ID">
            <Input
              value={draft.erpId}
              placeholder="e.g. ERP 505112"
              onChange={(e) => set("erpId", e.target.value)}
            />
          </SheetField>
        </div>

        {/* §6's labelled toggle row: label + helper + switch. The list's Status
            column is a projection of this control. */}
        <div className="flex items-start justify-between gap-4">
          <div className="flex flex-col gap-1">
            <span className="text-sm font-medium">Active</span>
            <span className="text-xs text-muted-foreground">
              Inactive customers stay on record but are excluded from new orders.
            </span>
          </div>
          <Switch
            checked={draft.status === "Active"}
            onCheckedChange={(on) => set("status", on ? "Active" : "Inactive")}
            aria-label="Active"
          />
        </div>
      </SheetSection>

      <SheetSection title="Line of Service">
        <SheetField
          label="LOS"
        >
          <MultiSelectList
            options={LINES_OF_SERVICE}
            value={draft.los}
            onChange={(next) => set("los", next as LineOfService[])}
            searchable={false}
          />
        </SheetField>
      </SheetSection>

      <SheetSection title="Ship-Tos">
        <SheetField
          label={`Ship-Tos (${draft.shipTos.length})`}
        >
          <div className="flex flex-col gap-2">
            {draft.shipTos.length > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {draft.shipTos.map((s) => (
                  <span
                    key={s}
                    className="inline-flex h-7 items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground"
                  >
                    {s}
                    <button
                      type="button"
                      aria-label={`Remove ${s}`}
                      onClick={() =>
                        set(
                          "shipTos",
                          draft.shipTos.filter((x) => x !== s)
                        )
                      }
                      className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                    >
                      <X className="size-3" />
                    </button>
                  </span>
                ))}
              </div>
            )}
            <div className="flex items-center gap-2">
              <Input
                value={newShipTo}
                placeholder="Add a ship-to…"
                onChange={(e) => setNewShipTo(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.preventDefault();
                    addShipTo();
                  }
                }}
              />
              <Button
                variant="outline"
                size="icon-sm"
                aria-label="Add ship-to"
                disabled={!newShipTo.trim()}
                onClick={addShipTo}
              >
                <Plus />
              </Button>
            </div>
          </div>
        </SheetField>
      </SheetSection>

      <SheetSection title="Billing & Contact">
        <SheetField label="Billing Terms">
          <Combobox
            className="w-full"
            value={draft.billingTerms}
            onValueChange={(v) => set("billingTerms", v)}
            options={BILLING_TERMS}
            placeholder="Select terms"
            /* OPTIONAL, SO THE EMPTY CHOICE FIRST (G46, Pavan, 2026-10-07). */
            clearLabel="No billing terms"
          />
        </SheetField>

        <SheetField label="Contact Name">
          <Input
            value={draft.contactName}
            placeholder="e.g. Dev Morris"
            onChange={(e) => set("contactName", e.target.value)}
          />
        </SheetField>

        <div className={cn("grid gap-4", creating ? "grid-cols-2" : "grid-cols-3")}>
          <SheetField label="Email">
            <Input
              type="email"
              value={draft.contactEmail}
              placeholder="name@company.com"
              onChange={(e) => set("contactEmail", e.target.value)}
            />
          </SheetField>
          <SheetField label="Phone">
            <Input
              value={draft.contactPhone}
              placeholder="(555) 555-0100"
              onChange={(e) => set("contactPhone", e.target.value)}
            />
          </SheetField>
        </div>

        <SheetField label="Note">
          <Textarea
            value={draft.note}
            placeholder="Account notes, billing exceptions…"
            onChange={(e) => set("note", e.target.value)}
            className="min-h-24"
          />
        </SheetField>
      </SheetSection>
    </RecordSheet>
  );
}

import * as React from "react";
import { toast } from "sonner";
