  type Customer,
  type CustomerColumnKey,
  type CustomerSortState,
} from "./customers";
import { ACTIVE_KIND, kindTone } from "./statusKind";

/**
 * Customers list — the same shell as the two order screens: preset-view row with
 * the CTA and Export, the action bar, the table, pagination.
 *
 * NOT DATE-SCOPED, and that is the one deliberate difference. A customer record
 * carries no date, so the toolbar's date stepper is omitted rather than shown
 * with nothing to scope. `ListToolbar` makes it optional for exactly this case.
 *
 * No bulk-action bar, for the same reason as Asset Orders: which fields a
 * customer needs edited in bulk was not specified.
 */
const TOGGLE_COLUMNS = CUSTOMER_COLUMNS.filter((c) => c.label).map((c) => ({
  key: c.key,
  label: c.label,
}));

interface ViewState {
  /** THE DISPLAY IT OPENS IN — table, board or map (Pavan, 2026-10-21). */
  mode?: ListView;
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  pageSize: number;
  colScope: string;
  colQuery: string;
  /** The filter row's boxes, by column key. Optional so a view saved before
   *  the row still applies. */
  colFilters?: Record<string, string>;
  /* ORDER AND WIDTHS (Pavan, 2026-10-07) — what 3PL's views keep. Optional so
     a view saved before them still applies. */
  /** Column order as keys. Empty means "as declared". */
  columnOrder?: string[];
  /** Reader-set column widths in px, by key. Empty means "as declared". */
  columnWidths?: Record<string, number>;
  /* FACETS (Pavan, 2026-10-07). Optional so a view saved before them applies. */
  facets?: string[];
}

/* FILTERS APPLY (Pavan, 2026-10-07). The panel used to tick and do nothing;
   now it stages, applies and shows chips — 3PL's and Quotes'. */
const CUSTOMER_FACETS: ListFacet[] = [
  { key: "status", label: "Status", options: ["Active", "Inactive"] },
  { key: "los", label: "LOS", options: [...LINES_OF_SERVICE] },
];

const keyOf = (s: ViewState) =>
  JSON.stringify({
    ...s,
    mode: s.mode ?? "table",
    hidden: [...s.hidden].sort(),
    facets: [...(s.facets ?? [])].sort(),
    /* Empty boxes are no filter — typing then clearing one is not a change. */
    colFilters: Object.fromEntries(
      Object.entries(s.colFilters ?? {}).filter(([, v]) => v.trim() !== "").sort(([a], [b]) => a.localeCompare(b))
    ),
  });

/**
 * WHAT EACH COLUMN PRINTS, as text a header box can match — the same rule as
 * `brokerColumnText` in 3PL: a box under a header matches what is written
 * above the rows beneath it. Ship-tos match every one, not only the first the
 * cell shows — the rest are one hover away behind its `+N`.
 */
function customerColumnText(c: Customer, key: CustomerColumnKey): string {
  switch (key) {
    case "name":
      return `${c.name} ${c.erpId}`;
    case "shipTos":
      return c.shipTos.join(" ");
    case "los":
      return c.los.join(" ");
    case "status":
      return c.status;
    default:
      return "";
  }
}

export function CustomersScreen({ focus }: { focus?: { id: string; n: number } | null } = {}) {
  const [rows, setRows] = React.useState<Customer[]>(CUSTOMERS);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [creating, setCreating] = React.useState(false);
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState<CustomerSortState | null>(null);
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(25);
  const [hidden, setHidden] = React.useState<Set<CustomerColumnKey>>(new Set());
  const [colScope, setColScope] = React.useState("name");
  const [colQuery, setColQuery] = React.useState("");
  const [view, setView] = React.useState<ListView>("table");
  /* Empty = the table's declared order; the table fills in anything a saved
     order does not mention, so a stale view never costs a column. */
  const [columnOrder, setColumnOrder] = React.useState<string[]>([]);
  const [columnWidths, setColumnWidths] = React.useState<Record<string, number>>({});
  /** One box per column, under the headers — see `ListTableProps.columnFilters`. */
  const [colFilters, setColFilters] = React.useState<Record<string, string>>({});
  const [colFiltersOpen, setColFiltersOpen] = React.useState(false);
  const [facetSel, setFacetSel] = React.useState<ReadonlySet<string>>(new Set());
  /* EXPORT ASKS FIRST (G10, Pavan, 2026-10-07) — 3PL's ExportSheet. */
  const [exporting, setExporting] = React.useState(false);
  const activeColFilters = React.useMemo(
    () => Object.entries(colFilters).filter(([, v]) => v.trim() !== ""),
    [colFilters]
  );

  const current: ViewState = {

    mode: view,
    search,
    sortKey: sort?.key ?? null,
    sortDir: sort?.dir ?? null,
    hidden: [...hidden],
    pageSize,
    colScope,
    colQuery,
    colFilters,
    columnOrder,
    columnWidths,
    facets: [...facetSel],
  };
  const defaultState: ViewState = React.useMemo(
    () => ({
    mode: "table",
      search: "",
      sortKey: null,
      sortDir: null,
      hidden: [],
      pageSize: 25,
      colScope: "name",
      colQuery: "",
      colFilters: {},
      columnOrder: [],
      columnWidths: {},
      facets: [],
    }),
    []
  );

  const applyState = (s: ViewState) => {

    setView(s.mode ?? "table");
    setSearch(s.search);
    setSort(
      s.sortKey && s.sortDir
        ? { key: s.sortKey as CustomerColumnKey, dir: s.sortDir }
        : null
    );
    setHidden(new Set(s.hidden as CustomerColumnKey[]));
    setPageSize(s.pageSize);
    setColScope(s.colScope);
    setColQuery(s.colQuery);
    const filters = s.colFilters ?? {};
    setColFilters(filters);
    /* The row opens when the view has something typed in it. */
    setColFiltersOpen(Object.values(filters).some((v) => v.trim() !== ""));
    setColumnOrder(s.columnOrder ?? []);
    setColumnWidths(s.columnWidths ?? {});
    setFacetSel(new Set(s.facets ?? []));
    setPage(1);
  };

  const savedViews = useSavedViews({ current, defaultState, keyOf, apply: applyState, storageKey: "sales-customers" });

  // A global-search hit lands here: open that customer's sheet on arrival.
  React.useEffect(() => {
    if (!focus) return;
    setCreating(false);
    setOpenId(focus.id);
  }, [focus]);

  const q = search.trim().toLowerCase();
  const cq = colQuery.trim().toLowerCase();
  const searched = React.useMemo(
    () =>
      rows.filter(
        (c) =>
          (!q || matchesCustomer(c, q)) &&
          (!cq || matchesCustomerIn(c, cq, colScope)) &&
          /* AND-ed, and each box matches the text its own column PRINTS —
             see `customerColumnText`. */
          activeColFilters.every(([key, value]) =>
            customerColumnText(c, key as CustomerColumnKey)
              .toLowerCase()
              .includes(value.trim().toLowerCase())
          )
      ),
    [rows, q, cq, colScope, activeColFilters]
  );
  /* Facets AND across, OR within one. A customer with several lines passes
     LOS when any of its lines is ticked. */
  const narrowFacets = React.useCallback(
    (sel: ReadonlySet<string>) => {
      if (sel.size === 0) return searched;
      const on = (facet: string) => [...sel].some((id) => id.startsWith(`${facet}:`));
      return searched.filter(
        (c) =>
          (!on("status") || sel.has(`status:${c.status}`)) &&
          (!on("los") || c.los.some((l) => sel.has(`los:${l}`)))
      );
    },
    [searched]
  );
  const filtered = React.useMemo(() => narrowFacets(facetSel), [narrowFacets, facetSel]);
  /* THE VIEW BAR — the table's and the board's tools render into it. */
  const bar = useViewBar();
  const sorted = React.useMemo(() => sortCustomers(filtered, sort), [filtered, sort]);
  /* Grouping. The hook owns the dimension stack and the collapsed set, and
     suspends pagination while grouped — a group cannot straddle a page
     boundary and still have an honest header. */
  const g = useGrouping<(typeof sorted)[number], CustomerColumnKey>({
    dimensions: CUSTOMER_GROUP_DIMS,
    rows: sorted,
    rowId: React.useCallback((r) => r.id, []),
    measureOf: React.useCallback((r: (typeof sorted)[number]) => r.shipTos.length, []),
    hiddenColumns: hidden,
    page,
    pageSize,
  });

  const onSort = (key: CustomerColumnKey) => {
    setSort((prev) => {
      if (prev?.key !== key) return { key, dir: "asc" };
      if (prev.dir === "asc") return { key, dir: "desc" };
      return null;
    });
    setPage(1);
  };

  const saveCustomer = (customer: Customer, draft: CustomerDraft) =>
    setRows((prev) =>
      prev.map((c) => (c.id !== customer.id ? c : { ...c, ...draft }))
    );

  const createCustomer = (draft: CustomerDraft) => {
    setRows((prev) => [
      { id: `cu-new-${prev.length + 1}`, ...draft },
      ...prev,
    ]);
    setPage(1);
  };

  const renderCell = (c: Customer, key: CustomerColumnKey) => {
    switch (key) {
      case "name":
        return <TwoLineCell title={c.name} description={c.erpId} />;
      case "shipTos":
        return <OverflowList values={c.shipTos} label="ship-tos" />;
      case "los":
        // Every line of service is shown — an account carries at most three, so
        // there is nothing to truncate behind a +N here.
        return (
          <div className="flex min-w-0 flex-wrap items-center gap-1">
            {c.los.map((l) => (
              <Pill key={l}>
                {l}
              </Pill>
            ))}
          </div>
        );
      case "status":
        return (
          <StatusChip
            tone={kindTone(ACTIVE_KIND(c.status === "Active"))}
            variant="text"
          >
            {c.status}
          </StatusChip>
        );
      default:
        return null;
    }
  };

  /* EVERY NARROWING THAT IS ON, for the export sheet to list — each drops
     what the shelf's own chip drops (3PL's, 2026-10-07). */
  const dropFacets = (gone: string[]) => {
    const next = new Set(facetSel);
    for (const id of gone) next.delete(id);
    setFacetSel(next);
    setPage(1);
  };
  const exportFilters: ExportFilterRow[] = [
    {
      key: "search",
      label: "Search",
      values: search.trim()
        ? [{ value: search.trim(), onRemove: () => { setSearch(""); setPage(1); } }]
        : [],
    },
    {
      key: "colSearch",
      label: CUSTOMER_SEARCH_FIELDS.find((f) => f.key === colScope)?.label ?? "Column",
      values: colQuery.trim()
        ? [{ value: colQuery.trim(), onRemove: () => { setColQuery(""); setPage(1); } }]
        : [],
    },
    ...activeColFilters.map(([key, value]) => ({
      key: `col:${key}`,
      label: CUSTOMER_COLUMNS.find((c) => c.key === key)?.label ?? key,
      values: [
        {
          value: value.trim(),
          onRemove: () => {
            setColFilters((prev) => ({ ...prev, [key]: "" }));
            setPage(1);
          },
        },
      ],
    })),
    ...CUSTOMER_FACETS.map((f) => {
      const mine = [...facetSel].filter((id) => id.startsWith(`${f.key}:`));
      return {
        key: f.key,
        label: f.label,
        values: mine.map((id) => ({
          value: id.slice(id.indexOf(":") + 1),
          onRemove: () => dropFacets([id]),
        })),
        onRemoveAll: () => dropFacets(mine),
      };
    }),
  ];

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <FuelOrdersViewBar
        {...savedViews}
        ctaLabel="Create New Customer"
        onCreateOrder={() => setCreating(true)}
        onExport={() => setExporting(true)}
      />

      <div className="mt-4 shrink-0">
        <ListToolbar
          viewToolsInto={bar.into}
          viewStatement={<ViewStatement count={sorted.length} one="customer" many="customers" />}
          searchValue={search}
          onSearchChange={(v) => {
            setSearch(v);
            setPage(1);
          }}
          searchPlaceholder="Search customers, ERP IDs, ship-tos…"
          filters={
            <ListFilters
              facets={CUSTOMER_FACETS}
              value={facetSel}
              countFor={(sel) => narrowFacets(sel).length}
              onApply={(sel) => {
                setFacetSel(sel);
                setPage(1);
              }}
            />
          }
          groupBy={{
            dimensions: g.menuDimensions,
            value: g.groupBy,
            onChange: (next) => {
              g.setGrouping(next);
              setPage(1);
            },
          }}
          columns={TOGGLE_COLUMNS}
          hiddenColumns={hidden}
          columnOrder={columnOrder}
          onReorderColumns={setColumnOrder}
          onToggleColumn={(k) =>
            setHidden((prev) => {
              const next = new Set(prev);
              if (next.has(k)) next.delete(k);
              else next.add(k);
              return next;
            })
          }
          onShowAllColumns={() => setHidden(new Set())}
          searchFields={CUSTOMER_SEARCH_FIELDS}
          colScope={colScope}
          onColScopeChange={(v) => {
            setColScope(v);
            setPage(1);
          }}
          colQuery={colQuery}
          onColQueryChange={(v) => {
            setColQuery(v);
            setPage(1);
          }}
          /* THE ROW, NOT THE POPOVER — the 3PL behaviour. Table view only. */
          columnFiltersOpen={view === "table" && colFiltersOpen}
          onToggleColumnFilters={
            view !== "table"
              ? undefined
              : () =>
                  setColFiltersOpen((open) => {
                    /* Closing the row clears it: a narrowing with no boxes on
                       screen would be one nobody could see. */
                    if (open) {
                      setColFilters({});
                      setPage(1);
                    }
                    return !open;
                  })
          }
          columnFilterCount={activeColFilters.length}
          view={view}
          onViewChange={setView}
        />
        {/* ONE SHELF for the facets and the column search — 3PL's. */}
        <FilterChips
          facets={CUSTOMER_FACETS}
          selected={facetSel}
          onChange={(next) => {
            setFacetSel(next);
            setPage(1);
          }}
        >
          <ColumnSearchChip
            /* ALONE ON THE SHELF it keeps its own top margin (Pavan, 2026-10-07). */
            className={facetSel.size > 0 ? "" : undefined}
            searchFields={CUSTOMER_SEARCH_FIELDS}
            colScope={colScope}
            colQuery={colQuery}
            onClear={() => {
              setColQuery("");
              setPage(1);
            }}
          />
        </FilterChips>
        {/* One chip per header box that has something typed in it. */}
        {activeColFilters.length > 0 && (
          <div className="mt-3 flex flex-wrap items-center gap-2">
            {activeColFilters.map(([key, value]) => (
              <ColumnSearchChip
                key={key}
                className=""
                searchFields={TOGGLE_COLUMNS}
                colScope={key}
                colQuery={value.trim()}
                onClear={() => {
                  setColFilters((prev) => ({ ...prev, [key]: "" }));
                  setPage(1);
                }}
              />
            ))}
          </div>
        )}
      </div>

      <div className="relative mt-4 min-h-0 flex-1">
        <div className="h-full min-h-0">
          {/* THE ROW STAYS WHILE IT IS OPEN. An empty result swaps the table
              for the empty state, which would take the boxes with it — the
              reader would lose the thing they were typing in. */}
          {sorted.length === 0 && !(view === "table" && colFiltersOpen) ? (
            <Empty className="h-full">
              <EmptyHeader>
                <EmptyMedia variant="icon">{q ? <SearchX /> : <Users />}</EmptyMedia>
                <EmptyTitle>
                  {q ? "No matching customers" : "No customers yet"}
                </EmptyTitle>
                <EmptyDescription>
                  {q
                    ? `No customers match “${search.trim()}”.`
                    : "Create the first customer to get started."}
                </EmptyDescription>
              </EmptyHeader>
              <EmptyContent>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    if (q) setSearch("");
                    else setCreating(true);
                    setPage(1);
                  }}
                >
                  {q ? "Clear search" : "Create New Customer"}
                </Button>
              </EmptyContent>
            </Empty>
          ) : (
            <ListTable
              topBar={bar.slot}
              rows={g.visibleRows}
              nodes={g.grouped ? g.groups.nodes : undefined}
              collapsedGroups={g.collapsed}
              onToggleGroupCollapse={g.toggleGroupCollapse}
              groupNoun="account"
              groupUnit="ship-tos"
              columns={CUSTOMER_COLUMNS}
              hidden={g.effectiveHidden}
              sort={sort}
              onSort={onSort}
              rowId={(c) => c.id}
              renderCell={renderCell}
              actionsKey="actions"
              columnOrder={columnOrder}
              onReorderColumns={setColumnOrder}
              columnWidths={columnWidths}
              onResizeColumns={setColumnWidths}
              openLabel={(c) => `Open customer ${c.name}`}
              onOpenRow={(c) => setOpenId(c.id)}
              showColumnFilters={colFiltersOpen}
              columnFilters={colFilters}
              onColumnFilterChange={(key, value) => {
                setColFilters((prev) => ({ ...prev, [key]: value }));
                setPage(1);
              }}
            />
          )}
        </div>
      </div>

      {/* EXPORT ASKS BEFORE IT ACTS (G10, Pavan, 2026-10-07). What leaves is
          the whole narrowed set, not the page. */}
      <ExportSheet
        open={exporting}
        onOpenChange={setExporting}
        title="Export Customers"
        noun="customers"
        nounOne="customer"
        count={sorted.length}
        filtersControl={
          <ListFilters
            facets={CUSTOMER_FACETS}
            value={facetSel}
            countFor={(sel) => narrowFacets(sel).length}
            onApply={(sel) => {
              setFacetSel(sel);
              setPage(1);
            }}
            fullWidth
          />
        }
        filters={exportFilters}
        onExport={(format) => {
          setExporting(false);
          toast.success(`Exporting ${sorted.length} ${sorted.length === 1 ? "customer" : "customers"} as .${format}`);
        }}
      />

      <CustomerSheet
        customer={rows.find((c) => c.id === openId) ?? null}
        mode={creating ? "create" : "edit"}
        open={creating || openId !== null}
        onOpenChange={(o) => {
          if (o) return;
          setCreating(false);
          setOpenId(null);
        }}
        onSave={saveCustomer}
        onCreate={createCustomer}
      />

      <div className={cn("mt-4 shrink-0", view === "board" && "hidden")}>
        {g.grouped ? (
          <GroupedListFooter
            groupCount={g.groups.groupCount}
            rowCount={g.groups.rowCount}
            noun="account"
            total={g.total}
            unit="ship-tos"
            overCounts={g.groups.overCounts}
            allCollapsed={g.allCollapsed}
            onExpandAll={g.expandAll}
            onCollapseAll={g.collapseAll}
          />
        ) : (
          <TablePagination
            page={page}
            pageSize={pageSize}
            total={sorted.length}
            onPageChange={setPage}
            onPageSizeChange={(size) => {
              setPageSize(size);
              setPage(1);
            }}
          />
        )}
      </div>
    </div>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

/*
  THE MODULE DASHBOARD'S PARTS (Pavan, 2026-10-05) — shared by 3PL and Sales.

  EVERYTHING ON A DASHBOARD IS A WAY INTO A LIST. A number, a bar or a row is
  pressed to open the list it counts, already narrowed to exactly those rows,
  so the dashboard never states a figure the reader cannot go and check.

  WHITE CARDS ON A GROUND (2026-10-05, after the reference dashboard): the
  dashboard sits on the inner-panel grey and every card is the content layer,
  borderless, rounded large. In dark the two swap so the cards still sit
  above their ground.

  COLOUR BY THE JOB IT DOES, from the validated `--fp-viz-*` palette:
  · a count over stages or time is ONE series — slot 1 blue, the peak lit and
    the rest a quiet tint of it, so the eye finds the busiest bar first;
  · a share of a whole is IDENTITY — one segment per part in the palette's
    fixed order, with a dot beside each name so colour is never alone;
  · a ranking is ONE series again — slot 1 blue throughout.
*/

/** The dashboard's ground — wraps the cards. */
export const DASHBOARD_GROUND = "rounded-xl bg-fp-surface-1a p-3 dark:bg-fp-surface-1b";
const CARD = "rounded-xl bg-fp-surface-1b shadow-xs dark:bg-fp-surface-1a";

const BAR = "bg-fp-viz-1";
/** Categorical slots in their fixed order. Literal so Tailwind keeps them. */
const VIZ = [
  "bg-fp-viz-1",
  "bg-fp-viz-2",
  "bg-fp-viz-3",
  "bg-fp-viz-4",
  "bg-fp-viz-5",
  "bg-fp-viz-6",
  "bg-fp-viz-7",
  "bg-fp-viz-8",
];

export function Panel({
  title,
  aside,
  className,
  children,
}: {
  title: string;
  aside?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
}) {
  return (
    <section className={cn("flex min-w-0 flex-col", CARD, className)}>
      <header className="flex items-baseline justify-between gap-3 px-5 pt-4">
        <h3 className="text-base font-semibold text-foreground">{title}</h3>
        {aside && <span className="text-xs text-muted-foreground">{aside}</span>}
      </header>
      <div className="min-w-0 flex-1 px-5 pt-4 pb-5">{children}</div>
    </section>
  );
}

/** A headline number. Pressing it opens the rows it counts. */
export function StatTile({
  label,
  value,
  note,
  onOpen,
}: {
  label: string;
  value: string;
  note?: string;
  onOpen?: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onOpen}
      disabled={!onOpen}
      className={cn(
        "flex min-w-0 flex-col items-start gap-2 p-5 text-left outline-none transition-shadow enabled:hover:shadow-sm focus-visible:ring-2 focus-visible:ring-ring/50",
        CARD
      )}
    >
      <span className="text-sm font-medium text-foreground">{label}</span>
      <span className="text-3xl font-semibold tabular-nums text-foreground">{value}</span>
      {note && <span className="text-xs text-muted-foreground">{note}</span>}
    </button>
  );
}

export interface BarDatum {
  key: string;
  label: string;
  value: number;
  /** What the tooltip says, e.g. "3 orders · $9,323". */
  detail?: string;
  onOpen?: () => void;
}

/**
 * VERTICAL BARS — a count per stage or per day. The value sits above each
 * bar and the label under it; hover names it in full; press opens it. Bars
 * keep a 4px rounded top on a shared baseline and a 2px gap between them.
 */
export function BarColumns({ data, height = 140 }: { data: BarDatum[]; height?: number }) {
  const max = Math.max(1, ...data.map((d) => d.value));
  /* THE PEAK IS LIT — the first bar at the maximum, when there is one. */
  const peak = data.findIndex((d) => d.value === max && d.value > 0);
  return (
    <div className="flex items-end gap-0.5" style={{ height: height + 40 }}>
      {data.map((d, i) => (
        <Tooltip key={d.key}>
          <TooltipTrigger asChild>
            <button
              type="button"
              onClick={d.onOpen}
              disabled={!d.onOpen}
              className="group flex min-w-0 flex-1 flex-col items-center gap-1.5 rounded-sm px-0.5 outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <span
                className={cn(
                  "text-xs tabular-nums",
                  i === peak ? "font-semibold text-foreground" : "text-muted-foreground"
                )}
              >
                {d.value}
              </span>
              <span className="flex w-full items-end justify-center" style={{ height }}>
                <span
                  className={cn(
                    "w-full max-w-11 rounded-md transition-colors",
                    d.value === 0
                      ? "bg-fp-outline-1"
                      : i === peak
                        ? BAR
                        : "bg-fp-viz-1/15 group-hover:bg-fp-viz-1/40 dark:bg-fp-viz-1/25 dark:group-hover:bg-fp-viz-1/50"
                  )}
                  style={{ height: d.value > 0 ? Math.max(6, (d.value / max) * height) : 3 }}
                />
              </span>
              <span
                className={cn(
                  "w-full truncate text-center text-xs",
                  i === peak ? "font-medium text-foreground" : "text-muted-foreground"
                )}
              >
                {d.label}
              </span>
            </button>
          </TooltipTrigger>
          <TooltipContent>
            <span className="font-medium">{d.label}</span>
            {" · "}
            {d.detail ?? d.value}
          </TooltipContent>
        </Tooltip>
      ))}
    </div>
  );
}

/**
 * A RANKED LIST WITH BARS — share of a whole, or the top few of something.
 * Name on the left, the figure and its share on the right, the bar under the
 * name. Press a row to open it.
 */
export function BarList({
  data,
  format = (n) => n.toLocaleString(),
  share = false,
}: {
  data: BarDatum[];
  format?: (n: number) => string;
  /**
   * A SHARE OF A WHOLE: one segmented bar across the top, a segment per part
   * in the palette's fixed order, and a coloured dot beside each name below.
   * A ninth part and beyond fold into the last slot's neighbour — keep
   * shares to eight.
   */
  share?: boolean;
}) {
  const total = data.reduce((s, d) => s + d.value, 0) || 1;
  const max = Math.max(1, ...data.map((d) => d.value));
  if (data.length === 0)
    return <p className="py-6 text-center text-sm text-muted-foreground">Nothing in this range.</p>;
  if (share) return <ShareBar data={data} format={format} total={total} />;
  return (
    <ul className="flex flex-col gap-1">
      {data.map((d) => (
        <li key={d.key}>
          <Tooltip>
            <TooltipTrigger asChild>
              <button
                type="button"
                onClick={d.onOpen}
                disabled={!d.onOpen}
                className="flex w-full flex-col gap-1 rounded-md px-2 py-1.5 text-left outline-none transition-colors enabled:hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                <span className="flex items-baseline justify-between gap-3 text-sm">
                  <span className="truncate text-foreground">{d.label}</span>
                  <span className="shrink-0 tabular-nums text-foreground">
                    {format(d.value)}
                    <span className="ml-2 inline-block w-10 text-right text-xs text-muted-foreground">
                      {Math.round((d.value / total) * 100)}%
                    </span>
                  </span>
                </span>
                <span className="h-2 w-full rounded-full bg-fp-viz-1/12 dark:bg-fp-viz-1/20">
                  <span
                    className={cn("block h-full rounded-full", BAR)}
                    style={{ width: `${(d.value / max) * 100}%` }}
                  />
                </span>
              </button>
            </TooltipTrigger>
            <TooltipContent>
              <span className="font-medium">{d.label}</span>
              {" · "}
              {d.detail ?? format(d.value)}
            </TooltipContent>
          </Tooltip>
        </li>
      ))}
    </ul>
  );
}

/** The share form of `BarList` — see its `share` prop. */
function ShareBar({
  data,
  format,
  total,
}: {
  data: BarDatum[];
  format: (n: number) => string;
  total: number;
}) {
  const parts = data.slice(0, VIZ.length);
  return (
    <div className="flex flex-col gap-4">
      {/* 2px surface gaps between segments; rounded only at the two ends. */}
      <div className="flex h-3 w-full gap-0.5 overflow-hidden rounded-full">
        {parts.map((d, i) =>
          d.value > 0 ? (
            <Tooltip key={d.key}>
              <TooltipTrigger asChild>
                <button
                  type="button"
                  onClick={d.onOpen}
                  disabled={!d.onOpen}
                  aria-label={`${d.label}: ${format(d.value)}`}
                  className={cn("h-full min-w-1 outline-none transition-opacity hover:opacity-80 focus-visible:ring-2 focus-visible:ring-ring/50", VIZ[i])}
                  style={{ width: `${(d.value / total) * 100}%` }}
                />
              </TooltipTrigger>
              <TooltipContent>
                <span className="font-medium">{d.label}</span>
                {" · "}
                {d.detail ?? format(d.value)}
              </TooltipContent>
            </Tooltip>
          ) : null
        )}
      </div>
      <ul className="flex flex-col gap-0.5">
        {parts.map((d, i) => (
          <li key={d.key}>
            <button
              type="button"
              onClick={d.onOpen}
              disabled={!d.onOpen}
              className="flex w-full items-center justify-between gap-3 rounded-md px-2 py-1.5 text-left text-sm outline-none transition-colors enabled:hover:bg-accent/50 focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <span className="flex min-w-0 items-center gap-2">
                <span aria-hidden className={cn("size-2.5 shrink-0 rounded-full", VIZ[i])} />
                <span className="truncate text-foreground">{d.label}</span>
              </span>
              <span className="shrink-0 tabular-nums text-foreground">
                {format(d.value)}
                <span className="ml-2 inline-block w-10 text-right text-xs text-muted-foreground">
                  {Math.round((d.value / total) * 100)}%
                </span>
              </span>
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { ChevronLeft, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DateField } from "@/components/ui/date-picker";
import { formatFullDate, startOfDay } from "./data";

/**
 * Delivery-date filter — ‹ date › stepper with a calendar picker.
 *
 * Defaults to today and steps a day at a time in either direction, so past and
 * future dates are both reachable. The pill opens the shared date picker in
 * its one-date form — Today is its first preset.
 *
 * Sits in the toolbar rather than inside the Filters panel: it is the one filter
 * whose current value has to stay legible at a glance, since every row on screen
 * is scoped by it.
 */
export interface DateFilterProps {
  value: Date;
  onChange: (next: Date) => void;
}

export function DateFilter({ value, onChange }: DateFilterProps) {
  const step = (days: number) => {
    const next = new Date(value);
    next.setDate(next.getDate() + days);
    onChange(startOfDay(next));
  };

  return (
    <div className="flex items-center gap-1">
      <Button
        variant="outline"
        size="icon-sm"
        aria-label="Previous day"
        onClick={() => step(-1)}
      >
        <ChevronLeft />
      </Button>

      {/* THE SHARED PICKER, one date (DS ui §10p). */}
      <DateField value={value} onChange={(d) => d && onChange(startOfDay(d))} align="end">
        <Button
          variant="outline"
          size="sm"
          aria-label={`Delivery date: ${formatFullDate(value)}. Pick a date`}
        >
          {formatFullDate(value)}
        </Button>
      </DateField>

      <Button
        variant="outline"
        size="icon-sm"
        aria-label="Next day"
        onClick={() => step(1)}
      >
        <ChevronRight />
      </Button>
    </div>
  );
}

import * as React from "react";
import { TriangleAlert, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SheetField } from "@/components/side-sheet/parts";
import { HangingAdd } from "./HangingAdd";
import { Slider } from "@/components/ui/slider";
import {
  formatSpan,
  formatWindow,
} from "@/components/form-layout/TimeWindowSlider";
import { cn } from "@/lib/utils";
/** A stretch of the day, minutes from midnight. */
export interface TimeSpan {
  start: number;
  end: number;
}

/*
  DELIVERY WINDOW & PREFERRED TIME (Pavan, 2026-10-20, after his reference;
  shared by every module's order sheet) —
  ONE day, drawn once, full width. The delivery window is the range on the
  track; each preferred time is a light-blue bar under it, on the same scale,
  with dashed lines up to the track and its two times under its ends. A bar
  is moved by dragging it, sized by dragging an end, and removed with its ✕;
  the + hanging off the box (as a table's add) puts a new one in the
  window's next free stretch.

  Keyboard: a bar takes focus — ← → move it half an hour, Shift + ← → move
  its end, Delete removes it.

  NEVER OVERLAPPING (Pavan, 2026-10-20) — a bar stops at its neighbours,
  whichever way it is dragged or typed; with no free half hour left in the
  window, + says to delete or adjust one first. PRESS A TIME under a bar to
  type its start and end to the minute — the slider and the box are the same
  value.
*/

const DAY = 24 * 60;
const STEP = 30;
/** Every third hour labelled, as the reference. */
const TICKS = [0, 3, 6, 9, 12, 15, 18, 21, 24];
const pct = (m: number) => `${(m / DAY) * 100}%`;
/** `4a`, `1:30p` — the reference's short times. */
const short = (m: number) => {
  const h24 = Math.floor((((m % DAY) + DAY) % DAY) / 60);
  const mm = m % 60;
  const h = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h}${mm ? `:${String(mm).padStart(2, "0")}` : ""}${h24 < 12 ? "a" : "p"}`;
};
const hhmm = (m: number) =>
  `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
const fromHhmm = (v: string) => {
  const m = v.match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const tick = (h: number) =>
  h === 0 || h === 24
    ? "12a"
    : h === 12
      ? "12p"
      : h < 12
        ? `${h}a`
        : `${h - 12}p`;

type Drag = {
  i: number;
  mode: "move" | "start" | "end";
  grab: number;
  from: TimeSpan;
};

export function DeliveryWindowTimeline({
  start,
  end,
  onWindowChange,
  preferred,
  onPreferredChange,
  disabled,
  required,
  label = "Delivery window & preferred time",
}: {
  /** The field's label, outside the box — every module says it its own way. */
  label?: string;
  /** The delivery window, minutes from midnight. */
  start: number;
  end: number;
  onWindowChange: (start: number, end: number) => void;
  preferred: TimeSpan[];
  onPreferredChange: (next: TimeSpan[]) => void;
  disabled?: boolean;
  required?: boolean;
}) {
  const scale = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(0);
  React.useLayoutEffect(() => {
    if (!scale.current) return;
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width));
    ro.observe(scale.current);
    return () => ro.disconnect();
  }, []);
  const drag = React.useRef<Drag | null>(null);
  /* THE NEW BAR TAKES FOCUS (DS ui §10f) — so ← → move it at once. */
  const [focusNew, setFocusNew] = React.useState<number | null>(null);
  /** The bar whose times are being typed, and which box opened it. */
  const [edit, setEdit] = React.useState<{
    i: number;
    field: "start" | "end";
  } | null>(null);
  const [full, setFull] = React.useState(false);
  React.useEffect(() => setFull(false), [preferred, start, end]);

  /* THE ROOM A BAR HAS — from its neighbours (or the window) either side. */
  const room = (i: number, at: TimeSpan) => {
    const others = preferred.filter((_, j) => j !== i);
    return {
      lo: Math.max(
        start,
        ...others.filter((q) => q.end <= at.start).map((q) => q.end),
      ),
      hi: Math.min(
        end,
        ...others.filter((q) => q.start >= at.end).map((q) => q.start),
      ),
    };
  };

  const toMin = (clientX: number) => {
    const r = scale.current!.getBoundingClientRect();
    return Math.round((((clientX - r.left) / r.width) * DAY) / STEP) * STEP;
  };
  const clampSpan = (
    i: number,
    at: TimeSpan,
    s: number,
    e: number,
    mode: Drag["mode"],
  ): TimeSpan => {
    const { lo, hi } = room(i, at);
    if (mode === "move") {
      const len = e - s;
      const a = Math.min(Math.max(s, lo), hi - len);
      return { start: a, end: a + len };
    }
    if (mode === "start")
      return { start: Math.min(Math.max(s, lo), e - STEP), end: e };
    return { start: s, end: Math.max(Math.min(e, hi), s + STEP) };
  };
  const setAt = (i: number, p: TimeSpan) =>
    onPreferredChange(preferred.map((x, j) => (j === i ? p : x)));

  const onDown = (e: React.PointerEvent, i: number, mode: Drag["mode"]) => {
    if (disabled) return;
    e.preventDefault();
    e.stopPropagation();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    drag.current = { i, mode, grab: toMin(e.clientX), from: preferred[i] };
  };
  const onMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    const delta = toMin(e.clientX) - d.grab;
    const s = d.mode === "end" ? d.from.start : d.from.start + delta;
    const en = d.mode === "start" ? d.from.end : d.from.end + delta;
    setAt(d.i, clampSpan(d.i, d.from, s, en, d.mode));
  };
  const onUp = () => (drag.current = null);

  const add = () => {
    /* THE FIRST FREE STRETCH OF HALF AN HOUR OR MORE, up to two hours. */
    const taken = [...preferred].sort((a, b) => a.start - b.start);
    let at = start;
    for (const q of [...taken, { start: end, end }]) {
      if (q.start - at >= STEP) {
        setFocusNew(preferred.length);
        onPreferredChange([
          ...preferred,
          { start: at, end: Math.min(q.start, at + 120) },
        ]);
        return;
      }
      at = Math.max(at, q.end);
    }
    setFull(true);
  };
  /* A TYPED PAIR — what's wrong with it, or null when it fits. */
  const problem = (i: number, s: number | null, e: number | null) => {
    if (s === null || e === null) return "Enter both times";
    if (e <= s) return "End after the start";
    if (s < start || e > end)
      return `Inside the delivery window, ${formatWindow(start, end)}`;
    if (preferred.some((q, j) => j !== i && s < q.end && e > q.start))
      return "Overlaps another preferred time";
    return null;
  };
  const onKey = (e: React.KeyboardEvent, i: number) => {
    const p = preferred[i];
    const by =
      e.key === "ArrowRight" ? STEP : e.key === "ArrowLeft" ? -STEP : 0;
    if (by) {
      e.preventDefault();
      setAt(
        i,
        e.shiftKey
          ? clampSpan(i, p, p.start, p.end + by, "end")
          : clampSpan(i, p, p.start + by, p.end + by, "move"),
      );
    } else if (e.key === "Delete" || e.key === "Backspace") {
      e.preventDefault();
      onPreferredChange(preferred.filter((_, j) => j !== i));
    }
  };

  const has = preferred.length > 0;
  const canAdd = !disabled && end - start >= STEP;
  return (
    /* THE LABEL OUTSIDE, as every field's (Pavan, 2026-10-20); the unit in
       the input's own outline; the add hangs off its corner, as a table's. */
    <SheetField label={label} required={required}>
      <div className="flex flex-col">
        <div
          className={cn(
            "flex flex-col gap-2 rounded-md border border-input bg-fp-surface-1b px-4 pt-3 pb-3 transition-[color,box-shadow] focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/50 dark:bg-fp-field-fill",
            canAdd && "rounded-bl-none",
          )}
        >
          <div className="flex min-w-0 items-baseline justify-between gap-3">
            <span className="text-sm whitespace-nowrap tabular-nums text-foreground">
              {formatWindow(start, end)}
            </span>
            <span className="min-w-0 truncate text-xs text-muted-foreground">
              {formatSpan(start, end)}
            </span>
          </div>

          {/* THE SCALE — track, hours, then the preferred bars on the same day. */}
          <div
            ref={scale}
            className={cn("relative", has ? "h-[78px]" : "h-10")}
            onPointerMove={onMove}
            onPointerUp={onUp}
          >
            <Slider
              className="absolute inset-x-0 top-0 h-5 [&_[data-slot=slider-thumb]]:size-5 [&_[data-slot=slider-track]]:h-2.5"
              aria-label="Delivery window"
              min={0}
              max={DAY}
              step={STEP}
              minStepsBetweenThumbs={60 / STEP}
              value={[start, end]}
              disabled={disabled}
              onValueChange={([a, b]) => onWindowChange(a, b)}
            />
            <div
              aria-hidden
              className="absolute inset-x-0 top-6 h-3.5 select-none"
            >
              {TICKS.map((h, i) => (
                <span
                  key={h}
                  className={cn(
                    "absolute top-0 text-xs leading-none tabular-nums text-muted-foreground",
                    i === 0 && "left-0",
                    i === TICKS.length - 1 && "right-0",
                    i > 0 && i < TICKS.length - 1 && "-translate-x-1/2",
                  )}
                  style={
                    i === 0 || i === TICKS.length - 1
                      ? undefined
                      : { left: `${(h / 24) * 100}%` }
                  }
                >
                  {tick(h)}
                </span>
              ))}
            </div>

            {preferred.map((p, i) => {
              /* A NARROW BAR PUTS ITS TIMES OUTSIDE ITS ENDS, so they never meet. */
              const narrow =
                width > 0 && ((p.end - p.start) / DAY) * width < 84;
              /* WHERE TWO BARS MEET, THE TIME IS PRINTED ONCE — by the later bar. */
              const shared = preferred.some(
                (q, j) => j !== i && q.start === p.end,
              );
              return (
                <React.Fragment key={i}>
                  {[p.start, p.end].map((m, k) => (
                    <span
                      key={k}
                      aria-hidden
                      className="absolute top-4 h-7 border-l border-dashed border-muted-foreground/60"
                      style={{ left: pct(m) }}
                    />
                  ))}
                  <div
                    role="group"
                    ref={(el) => {
                      if (el && i === focusNew) {
                        el.focus({ preventScroll: true });
                        setFocusNew(null);
                      }
                    }}
                    autoFocus={i === focusNew}
                    tabIndex={disabled ? -1 : 0}
                    aria-label={`Preferred time ${formatWindow(p.start, p.end)}`}
                    onKeyDown={(e) => !disabled && onKey(e, i)}
                    onPointerDown={(e) => onDown(e, i, "move")}
                    className={cn(
                      "group/bar absolute top-11 h-2.5 rounded-xs bg-fp-lane-blue/30 outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
                      !disabled &&
                        "cursor-grab active:cursor-grabbing hover:bg-fp-lane-blue/45",
                    )}
                    /* 1px of air each side, so two bars that meet stay two. */
                    style={{
                      left: `calc(${pct(p.start)} + 1px)`,
                      width: `calc(${pct(p.end - p.start)} - 2px)`,
                    }}
                  >
                    {!disabled && (
                      <>
                        {/* THE ENDS SIZE IT — a grip wider than the line. */}
                        <span
                          onPointerDown={(e) => onDown(e, i, "start")}
                          className="absolute inset-y-[-4px] -left-1.5 w-3 cursor-ew-resize"
                        />
                        <span
                          onPointerDown={(e) => onDown(e, i, "end")}
                          className="absolute inset-y-[-4px] -right-1.5 w-3 cursor-ew-resize"
                        />
                        <button
                          type="button"
                          aria-label={`Remove preferred time ${formatWindow(p.start, p.end)}`}
                          onPointerDown={(e) => e.stopPropagation()}
                          onClick={() =>
                            onPreferredChange(
                              preferred.filter((_, j) => j !== i),
                            )
                          }
                          className="absolute top-1/2 -right-6 flex size-5 -translate-y-1/2 items-center justify-center rounded-sm text-muted-foreground opacity-0 outline-none transition-opacity group-hover/bar:opacity-100 group-focus-visible/bar:opacity-100 hover:text-foreground focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <X className="size-3.5" />
                        </button>
                      </>
                    )}
                  </div>
                  {/* A SHORT BAR CARRIES ONE LABEL, BOTH TIMES — two would run
                      into each other or into the next bar's. */}
                  <TimeLabel
                    m={p.start}
                    text={
                      narrow && !shared
                        ? `${short(p.start)}–${short(p.end)}`
                        : undefined
                    }
                    open={edit?.i === i && edit.field === "start"}
                    onOpenChange={(o) =>
                      setEdit(o ? { i, field: "start" } : null)
                    }
                    disabled={disabled}
                  >
                    <TimesEditor
                      p={p}
                      focus="start"
                      check={(a, b) => problem(i, a, b)}
                      onCommit={(np) => setAt(i, np)}
                    />
                  </TimeLabel>
                  {!shared && !narrow && (
                    <TimeLabel
                      m={p.end}
                      className="-translate-x-full"
                      open={edit?.i === i && edit.field === "end"}
                      onOpenChange={(o) =>
                        setEdit(o ? { i, field: "end" } : null)
                      }
                      disabled={disabled}
                    >
                      <TimesEditor
                        p={p}
                        focus="end"
                        check={(a, b) => problem(i, a, b)}
                        onCommit={(np) => setAt(i, np)}
                      />
                    </TimeLabel>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>
        <div className="flex items-start gap-3">
          {canAdd && <HangingAdd label="Add preferred time" onClick={add} />}
          {/* NO ROOM LEFT (Pavan, 2026-10-20) — said where the add was pressed. */}
          {full && (
            <p
              role="alert"
              className="flex items-center gap-1.5 pt-1.5 text-xs text-status-failed"
            >
              <TriangleAlert className="size-3.5 shrink-0" />
              Delete or adjust the current preferred time to add a new one.
            </p>
          )}
        </div>
      </div>
    </SheetField>
  );
}

/** A bar's time under its end — pressed, it opens the typed times. */
function TimeLabel({
  m,
  text,
  className,
  open,
  onOpenChange,
  disabled,
  children,
}: {
  m: number;
  /** In place of the one time — a short bar's "8a–9:20a". */
  text?: string;
  className?: string;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  const label = (
    <span
      className={cn(
        "absolute top-[59px] text-xs leading-none tabular-nums text-foreground",
        className,
      )}
      style={{ left: pct(m) }}
    >
      {text ?? short(m)}
    </span>
  );
  if (disabled) return label;
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`Type the preferred time, ${short(m)}`}
          className={cn(
            "absolute top-[57px] -ml-0.5 rounded-sm px-0.5 py-0.5 text-xs leading-none tabular-nums text-foreground underline decoration-current/40 decoration-dotted underline-offset-2 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
            className,
          )}
          style={{ left: pct(m) }}
        >
          {text ?? short(m)}
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-3">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/** START AND END TO THE MINUTE — each change that fits is kept at once. */
function TimesEditor({
  p,
  focus,
  check,
  onCommit,
}: {
  p: TimeSpan;
  focus: "start" | "end";
  check: (s: number | null, e: number | null) => string | null;
  onCommit: (p: TimeSpan) => void;
}) {
  const [a, setA] = React.useState(hhmm(p.start));
  const [b, setB] = React.useState(hhmm(p.end));
  const err = check(fromHhmm(a), fromHhmm(b));
  const put = (na: string, nb: string) => {
    const s = fromHhmm(na);
    const e = fromHhmm(nb);
    if (!check(s, e)) onCommit({ start: s!, end: e! });
  };
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-end gap-2">
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          Start
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={a}
            autoFocus={focus === "start"}
            onChange={(e) => {
              setA(e.target.value);
              put(e.target.value, b);
            }}
          />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          End
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={b}
            autoFocus={focus === "end"}
            onChange={(e) => {
              setB(e.target.value);
              put(a, e.target.value);
            }}
          />
        </label>
      </div>
      {err && <p className="text-xs text-status-failed">{err}</p>}
    </div>
  );
}

import { Download, Upload } from "lucide-react";
import { Button } from "@/components/ui/button";
import { FileTypeIcon } from "@/components/ui/file-type-icon";

/*
  THE DOCUMENTS TABLE — one for every record that keeps files (3PL Delivery
  Orders, the portal's order requests and invoice disputes). The 3PL
  anatomy, which is the source of truth (Pavan, 2026-10-14):

    Document (its format icon, then the name) · Added · By · ↓
    (No Kind column — Pavan, 2026-10-14: the format icon says what it is.)

  ALWAYS A TABLE, AND NEVER EMPTY OF ROWS. With nothing uploaded it still
  holds one row (Pavan, 2026-10-14): where the reader can add, that row IS
  the upload — press it to pick files; where they cannot, it says what will
  arrive. The section never changes shape when the first file lands.
*/

export interface DocumentRow {
  id: string;
  kind: string;
  name: string;
  /** Already formatted for reading. */
  added: string;
  by: string;
}

export function DocumentsTable({
  rows,
  onAdd,
  emptyText = "No documents yet.",
  onDownload,
}: {
  rows: DocumentRow[];
  /** Given, the empty row is an upload slot. */
  onAdd?: () => void;
  /** The empty row's words when there is no upload here. */
  emptyText?: string;
  onDownload?: (row: DocumentRow) => void;
}) {
  return (
    <table className="w-full table-fixed text-sm">
      <colgroup>
        <col />
        <col className="w-[18%]" />
        <col className="w-[20%]" />
        <col className="w-12" />
      </colgroup>
      <thead>
        <tr className="border-b border-border bg-fp-table-header">
          {["Document", "Added", "By"].map((h) => (
            <th key={h} className="px-3 py-2 text-left text-xs font-medium text-muted-foreground">
              {h}
            </th>
          ))}
          <th className="w-10 px-3 py-2" />
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 &&
          (onAdd ? (
            /* THE EMPTY ROW IS THE UPLOAD. */
            <tr className="h-12 cursor-pointer border-b border-border last:border-0 hover:bg-fp-row-hover" onClick={onAdd}>
              <td className="px-3">
                <button
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation();
                    onAdd();
                  }}
                  className="flex items-center gap-2 rounded-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <Upload className="size-4" />
                  Upload a document
                </button>
              </td>
              <td className="px-3 text-muted-foreground">—</td>
              <td className="px-3 text-muted-foreground">—</td>
              <td />
            </tr>
          ) : (
            <tr className="h-12">
              <td colSpan={4} className="px-3 text-muted-foreground">
                {emptyText}
              </td>
            </tr>
          ))}
        {rows.map((doc) => (
          <tr key={doc.id} className="h-12 border-b border-border last:border-0">
            <td className="px-3">
              <span className="flex min-w-0 items-center gap-2.5">
                <FileTypeIcon name={doc.name} />
                <span className="truncate text-foreground" title={doc.name}>
                  {doc.name}
                </span>
              </span>
            </td>
            <td className="truncate px-3 text-muted-foreground">{doc.added}</td>
            <td className="truncate px-3 text-muted-foreground">{doc.by}</td>
            <td className="px-2">
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={`Download ${doc.name}`}
                className="text-muted-foreground"
                onClick={() => onDownload?.(doc)}
              >
                <Download />
              </Button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import * as React from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { SheetSection } from "@/components/side-sheet/parts";
import { RecordSheet } from "./RecordSheet";


/**
 * Export, as a side sheet that shows what is about to leave the building.
 *
 * THE EXPORT IS THE LIST, and that is the whole idea: the file you get is the
 * rows you are looking at, narrowed by the same questions the toolbar asked.
 * Pressing Export straight from the toolbar exported that set silently, which
 * meant the one moment a reader needs to check their narrowing — the moment
 * the data goes somewhere it can no longer be corrected — was the one moment
 * the narrowing was invisible.
 *
 * THE FORMAT IS A FOOTER DECISION, beside the count and the button. It is the
 * last thing you choose and the only one that does not change what is in the
 * file, so it has no business among the narrowings above.
 *
 * THE SHEET'S CONTROLS ARE THE SCREEN'S CONTROLS. The date stepper and the
 * Filters button are the same two the toolbar carries, behaving the same way —
 * a reader who has narrowed the board has already learnt this sheet. The one
 * thing the sheet adds is the LIST OF WHAT IS ON, under them: the panel shows
 * one facet at a time and cannot answer "what am I exporting" on its own, and
 * the answer includes narrowings that are not facets at all.
 *
 * It edits the LIST'S OWN state rather than keeping a private copy: two filter
 * models that can disagree is how a reader ends up exporting one thing while
 * looking at another.
 */

export type ExportFormat = "csv" | "pdf" | "doc";

const FORMATS: { value: ExportFormat; label: string }[] = [
  { value: "csv", label: ".csv" },
  { value: "pdf", label: ".pdf" },
  { value: "doc", label: ".doc" },
];

/** A narrowing that can be taken off here, one chip per applied value. */
export interface ExportFilterRow {
  key: string;
  label: string;
  values: { value: string; onRemove: () => void }[];
  /** Takes the whole row off at once. Shown only when the row holds several. */
  onRemoveAll?: () => void;
}

/** The shelf's chip, again — same shape, because it is the same fact. */
function ValueChip({
  value,
  label,
  onRemove,
}: {
  value: string;
  label: string;
  onRemove: () => void;
}) {
  return (
    <span className="inline-flex h-7 max-w-full items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground">
      <span className="truncate">{value}</span>
      <button
        type="button"
        aria-label={`Remove filter ${label}: ${value}`}
        onClick={onRemove}
        className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
      >
        <X className="size-3" />
      </button>
    </span>
  );
}

export function ExportSheet({
  open,
  onOpenChange,
  title = "Export",
  /** Plural noun for the count — "orders", "vendors". */
  noun,
  /** Its singular, for a count of one. Defaults to `noun` minus a trailing s. */
  nounOne,
  /** How many rows the current narrowing leaves. */
  count,
  /** The date control — the screen's own, the one the toolbar carries. */
  date,
  filtersControl,
  filters,
  onExport,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  noun: string;
  nounOne?: string;
  count: number;
  date?: React.ReactNode;
  /** The facet panel's trigger — the screen's own `ListFilters`. */
  filtersControl?: React.ReactNode;
  /** The applied narrowings, listed under the panel. */
  filters: ExportFilterRow[];
  onExport: (format: ExportFormat) => void;
}) {
  const on = filters.filter((f) => f.values.length > 0);
  const [format, setFormat] = React.useState<ExportFormat>("csv");

  return (
    <RecordSheet
      /* Controls, not a form — no step column. */
      stepNav={false}
      /* 510. Wider than the 392 the flattened calendar was squeezed into, and
         still short of the DS narrow's 560: this sheet holds controls, not a
         two-column form. */
      size="compact"
      open={open}
      onOpenChange={onOpenChange}
      mode="create"
      editTitle={title}
      createTitle={title}
      createAction="Export"
      /* NO CANCEL. This sheet commits nothing on its way through — the
         narrowings it edits are the list's own and are already visible behind
         it — so there is nothing for Cancel to undo that Close does not do, and
         a button promising to undo what it cannot is worse than no button. */
      showCancel={false}
      /* THE COUNT KEEPS THE LEFT. It is the number the reader is deciding
         about, and in the body it scrolled away from the decision. */
      footerAside={
        <span className="text-sm text-foreground">
          <span className="font-medium tabular-nums">{count}</span>{" "}
          <span className="text-muted-foreground">
            {count === 1 ? (nounOne ?? noun.replace(/s$/, "")) : noun}
          </span>
        </span>
      }
      /* THE FORMAT TRAVELS WITH THE BUTTON, 12px off it. It is part of the act
         — "export, as this" — not a fact about the list, and out on the left
         beside the count it read as one, half a sheet away from the control it
         qualifies. */
      footerPrimary={
        <div className="flex items-center gap-3">
          <Select
            value={format}
            onValueChange={(v) => setFormat(v as ExportFormat)}
          >
            <SelectTrigger size="sm" className="w-[92px]" aria-label="File format">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {FORMATS.map((f) => (
                <SelectItem key={f.value} value={f.value}>
                  {f.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button disabled={count === 0} onClick={() => onExport(format)}>
            Export
          </Button>
        </div>
      }
      /* `footerPrimary` carries its own disabled state, so `canSubmit` has
         nothing to gate. `onSubmit` stays wired for the Enter key. */
      onSubmit={() => count > 0 && onExport(format)}
    >
      {/* PLAIN SECTIONS, NOT CARDS. A card draws an edge to say where a block
          starts and ends; each of these is one control under one heading, and a
          box around it was a third edge inside a sheet that is itself a
          bordered surface. The heading and the 40px between sections carry
          it. */}
      {/* THE DATE IS ONE LINE, UNDER ITS HEADING. The control prints the window
          it is on and opens the rest on click, so there is nothing for a second
          row to hold — and the sheet's subject is the filters below, which a
          laid-out calendar was burying. It takes the full width like every
          other block here rather than perching on the heading's right. */}
      {date && (
        <SheetSection variant="plain" title="Date">
          {date}
        </SheetSection>
      )}

      <SheetSection variant="plain" title="Filters">
        {/* THE CONTROL AND WHAT IT PRODUCED ARE ONE UNIT, 12px apart. The
            section's 16px belongs to heading→content; inside the content the
            button and the list it filled are the same thought, and the 48 that
            used to sit here read as a second section with no heading. */}
        <div className="flex flex-col gap-3">
          {filtersControl}

          {/* 24px BETWEEN GROUPS, now spent as 12 / rule / 12 rather than as
              one gap. Several rows wrap onto two lines of chips, and a gap
              alone could not say whether a second line belonged to the row
              above it or the one below — the rule says it. */}
          {on.length > 0 && (
            <div className="flex flex-col gap-3">
              {on.map((f, i) => (
                /* THE RULE RUNS THE WHOLE WIDTH, label column included: the
                   row is one thing — a question and its answer — and a line
                   that started at the chips cut the row in half rather than
                   separating it from the next. Not after the last row: there is
                   nothing below to separate it from. */
                <div
                  key={f.key}
                  className={cn(
                    "flex items-start gap-3",
                    i < on.length - 1 && "border-b border-border pb-3"
                  )}
                >
                  <span className="w-[140px] shrink-0 pt-0.5 text-xs text-muted-foreground">
                    {f.label}
                  </span>
                  <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
                    {f.values.map((v) => (
                      <ValueChip
                        key={v.value}
                        value={v.value}
                        label={f.label}
                        onRemove={v.onRemove}
                      />
                    ))}
                    {/* CLEAR THE ROW, only where there is a row to clear. On a
                        single value it would be a second control doing what the
                        chip's own X already does. */}
                    {f.values.length > 1 && f.onRemoveAll && (
                      <Button
                        variant="ghost"
                        size="xs"
                        className="h-5 px-1 text-[11px] text-muted-foreground"
                        onClick={f.onRemoveAll}
                      >
                        Clear
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </SheetSection>
    </RecordSheet>
  );
}

import * as React from "react";
import {
  Calendar as CalendarIcon,
  Clock,
  Package,
  Tag,
  Trash2,
  User,
  X,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { DatePanel } from "@/components/ui/date-picker";
import { Input } from "@/components/ui/input";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  BeforeAfterTable,
  BulkEditDialog,
  OrderMiniTable,
  StandingLoad,
  type OrderRef,
} from "./BulkEditDialog";
import { MultiSelectList } from "@/components/ui/multi-select-list";
import { DATE_FMT, splitGallons } from "./data";
import type { FuelOrder } from "./types";

/**
 * Floating bulk-action bar for Fuel Orders.
 *
 * Geometry, entrance animation, count chip and delete-confirm are the DS's
 * "FAB bulk actions" (Figma 27631:11151) — `bulk-bar-in`, rounded-lg, 1px
 * border, p-1.5, a primary count chip with a clear ×, a hairline
 * before the destructive zone, and Delete always behind an AlertDialog. Labels
 * are mandatory on the field actions, per the DS's own note that these are never
 * icon-only.
 *
 * Every field action opens the two-step `BulkEditDialog` — pick, then review
 * what already exists and what changes, then commit. That is `02-rules/
 * interaction-and-behavior.md` §4b (locked decision 11), which assigns each
 * attribute an editor by CARDINALITY, and these are not all the same tier:
 *
 *   Tier 1  scalar, one value for every row      Planned date, Planned time
 *   Tier 2  one value per row                    Driver
 *   Tier 3  a collection per row                 Products, Tags
 *
 * They previously shared one flat popover that committed on click, which met
 * none of §4b: no dialog, no scope+count header, no preview, and — worst — no
 * confirmation on Products, which REPLACES an order's product lines and so
 * silently rewrites the Qty column that sums them.
 *
 * THREE DELIBERATE DIFFERENCES FROM THE DS BAR:
 *
 * 1. FILL — no longer a difference. The DS bar has since been fixed the same way
 *    and this fork now copies it verbatim: `bg-fp-surface-1a` (white) in light,
 *    `dark:bg-fp-card-1` (#2a2f37) in dark. Both themes had the same original
 *    problem for opposite reasons: `bg-popover` is byte-identical to
 *    `--fp-surface-1b` in BOTH (#ffffff light, #1b2028 dark), so the fill matched
 *    the content layer it floats over. Note white-on-white means LIGHT still has
 *    no fill contrast against the content layer — the outline and
 *    `shadow-fp-overlay` carry the separation there, which is why the border is
 *    explicit rather than inherited.
 *
 * 2. ACTION SET. The DS bar's verbs (Assign / Unassign / Unblock / Verify /
 *    Unverify) plus Copy and a ··· More menu are not this screen's actions, and
 *    the component takes no way to change them. This screen's set is the five
 *    fields a dispatcher edits across orders, plus Delete. No Copy, no More.
 *
 * 3. ELEVATION. §4b specifies `--shadow-md` for this bar. Measured, that is
 *    WEAKER than the `shadow-lg` this file used to carry (Tailwind's md is 10%
 *    black at 4px; lg is 10% black at 10px), and both are effectively invisible
 *    here — because of difference 1's root cause. The bar only ever appears
 *    WHEN ROWS ARE SELECTED, so its real backdrop on three sides is selected
 *    rows, and the selected-row fill is `--accent` = #2a2f37 in FP-dark,
 *    byte-identical to this bar's own `--fp-card-1`. Measured delta against its
 *    own backdrop: [0,0,0]. With no fill contrast available the shadow carries
 *    the whole separation, so this uses `shadow-fp-overlay` — a new overlay
 *    elevation tier, theme-aware because 10% black does not register on
 *    #2a2f37. See src/index.css.
 *
 * DS FOLLOW-UP: parameterise `tables-layout/BulkActionBar` so the verb set is a
 * prop, and move the fill off `bg-popover`. Then this file deletes itself.
 * Fourth component in this prototype copied for want of a prop — see also
 * TokenMultiSelect and ProductTable.
 */

export interface FuelOrdersBulkBarProps {
  count: number;
  /**
   * HOW MANY OF THEM THE FIELD EDITS REACH (Pavan, 2026-10-07) — Sales Orders
   * mixes fuel and asset orders, and the five edits are a fuel order's
   * fields. Defaults to `count`; at 0 only Delete is offered.
   */
  editCount?: number;
  onClear: () => void;
  /**
   * Replace every selected order's product lines with these products, splitting
   * that order's own total gallons across them.
   */
  onSetProducts: (products: string[]) => void;
  /** `null` clears the driver, which also makes the orders Unassigned. */
  onSetDriver: (driver: string | null) => void;
  onSetPlannedDate: (date: Date) => void;
  onSetPlannedTime: (time: string) => void;
  /** Adds tags to whatever each order already carries. */
  onAddTags: (tags: string[]) => void;
  onDelete: () => void;
  productOptions: string[];
  driverOptions: string[];
  tagOptions: string[];
  /** The orders being edited — what the preview step reads. */
  selectedOrders: FuelOrder[];
  /**
   * Every order NOT in the selection. A driver's standing load is derived from
   * this, so an order that is both already theirs and in the selection is
   * counted once, under "being added", rather than appearing on both sides.
   */
  unselectedOrders: FuelOrder[];
}

/** Bar trigger — a labelled button that opens that action's dialog. */
function FieldAction({
  icon,
  label,
  onClick,
}: {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
}) {
  return (
    <Button variant="ghost" size="sm" onClick={onClick}>
      {icon}
      {label}
    </Button>
  );
}

type ActionKey = "products" | "driver" | "date" | "time" | "tags";

/**
 * Order -> the identity every summary table renders. Lives here rather than
 * beside `OrderRef` so BulkEditDialog exports components only and stays inside
 * react-refresh's one-warning budget.
 */
function toOrderRef(o: FuelOrder): OrderRef {
  return {
    orderNo: o.orderNo,
    typeLabel: o.type.label,
    shipTo: o.customer.description,
  };
}

/** "Shriya Test 2" -> "ST". Matches how the Driver column builds its avatar. */
function initialsOf(name: string) {
  return name
    .split(" ")
    .map((w) => w[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

export function FuelOrdersBulkBar({
  count,
  editCount = count,
  onClear,
  onSetProducts,
  onSetDriver,
  onSetPlannedDate,
  onSetPlannedTime,
  onAddTags,
  onDelete,
  productOptions,
  driverOptions,
  tagOptions,
  selectedOrders,
  unselectedOrders,
}: FuelOrdersBulkBarProps) {
  const [action, setAction] = React.useState<ActionKey | null>(null);

  // Pending values — nothing is committed until Confirm on step 2.
  const [products, setProducts] = React.useState<string[]>([]);
  // `undefined` = nothing picked yet; `null` = the explicit "Unassigned" option.
  const [driver, setDriver] = React.useState<string | null | undefined>(undefined);
  const [date, setDate] = React.useState<Date | undefined>(undefined);
  const [time, setTime] = React.useState("");
  const [tags, setTags] = React.useState<string[]>([]);

  const close = () => {
    setAction(null);
    setProducts([]);
    setDriver(undefined);
    setDate(undefined);
    setTime("");
    setTags([]);
  };

  /**
   * Every driver's standing load, keyed by name — SCOPED TO THE DELIVERY
   * DATE(S) THE SELECTION IS ON. The dataset spans four days (TOTAL 115 rows
   * over dayOffset -1..+2) while the list is date-filtered to one, so counting
   * every date answered a question nobody asked: it reported Shriya at 38 when
   * only 12 of those share the day being dispatched. A driver's load on the day
   * you are assigning is the number that decides whether to give them another
   * order. Selections cannot straddle dates today — the date filter scopes the
   * list first — but this keys off the selection rather than the filter so it
   * stays correct if that ever changes.
   */
  const scopeDateKeys = React.useMemo(
    () => new Set(selectedOrders.map((o) => o.dateKey)),
    [selectedOrders]
  );
  const standingLoad = React.useMemo(() => {
    const m = new Map<string, FuelOrder[]>();
    for (const o of unselectedOrders) {
      if (!o.driver) continue;
      if (!scopeDateKeys.has(o.dateKey)) continue;
      const list = m.get(o.driver.name);
      if (list) list.push(o);
      else m.set(o.driver.name, [o]);
    }
    return m;
  }, [unselectedOrders, scopeDateKeys]);

  const added = selectedOrders.map(toOrderRef);

  /** Before/after rows for one field. */
  const preview = (before: (o: FuelOrder) => string, after: string) =>
    selectedOrders.map((o) => ({
      orderNo: o.orderNo,
      before: before(o),
      after,
    }));

  if (count <= 0) return null;

  return (
    <>
      {/* Fill and border are copied VERBATIM from the DS bar
          (`tables-layout/BulkActionBar`) so the fork cannot drift from it again:
          white in light, the card surface in dark, with the outline stepping up a
          shade in dark. This fork had been left on `bg-fp-card-1` when the DS bar
          was moved to white, so the fix never reached this screen. */}
      <div className="bulk-bar-in flex items-center gap-1 rounded-lg border border-fp-outline-1 bg-fp-surface-1a p-1.5 shadow-fp-overlay dark:border-fp-outline-2 dark:bg-fp-card-1">
        {/* Count chip — primary filled, with a clear ×. */}
        <span className="flex items-center gap-2 rounded-md bg-primary py-1 pr-1.5 pl-2.5 text-sm font-medium text-primary-foreground">
          {count} Selected
          <button
            type="button"
            aria-label="Clear selection"
            onClick={onClear}
            className="rounded-sm text-primary-foreground/80 outline-none transition-colors hover:text-primary-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            <X className="size-3.5" />
          </button>
        </span>

        {editCount > 0 && (
          <>
            <FieldAction
              icon={<Package />}
              label="Products"
              onClick={() => setAction("products")}
            />
            <FieldAction
              icon={<User />}
              label="Driver"
              onClick={() => setAction("driver")}
            />
            <FieldAction
              icon={<CalendarIcon />}
              label="Planned date"
              onClick={() => setAction("date")}
            />
            <FieldAction
              icon={<Clock />}
              label="Planned time"
              onClick={() => setAction("time")}
            />
            <FieldAction
              icon={<Tag />}
              label="Add tags"
              onClick={() => setAction("tags")}
            />
            <div className="mx-1 h-5 w-px bg-border" aria-hidden />
          </>
        )}

        {/* Delete — icon only, and always behind a confirm. */}
        <AlertDialog>
          <AlertDialogTrigger asChild>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Delete"
              className="text-destructive hover:bg-destructive/10 hover:text-destructive"
            >
              <Trash2 />
            </Button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>
                Delete {count} {count === 1 ? "order" : "orders"}?
              </AlertDialogTitle>
              <AlertDialogDescription>
                This will affect {count} {count === 1 ? "order" : "orders"} and
                cannot be undone.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction variant="destructive" onClick={onDelete}>
                Delete
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>

      {/* ---- Tier 3 · Products. Replaces the product lines, so the preview is
           the only thing standing between the operator and a rewritten Qty. --- */}
      <BulkEditDialog
        open={action === "products"}
        onOpenChange={(o) => !o && close()}
        title="Products"
        scopeVerb="Set the products on"
        count={editCount}
        canProceed={products.length > 0}
        summaryDescription={
          products.length === 1
            ? "Each order's existing product lines are replaced by this one product, keeping that order's own total gallons."
            : `Each order's existing product lines are replaced by these ${products.length} products. That order's own total gallons are split evenly across them, so the Qty column does not change.`
        }
        onConfirm={() => products.length > 0 && onSetProducts(products)}
        summary={
          <BeforeAfterTable
            valueHeader="Products"
            rows={selectedOrders.map((o) => {
              const split = splitGallons(o.qtyGal, products.length);
              return {
                orderNo: o.orderNo,
                before: o.products
                  .map((pr) => `${pr.name} (${pr.gal.toLocaleString()} gal)`)
                  .join(", "),
                // Gallons are printed, not just names: the split is an
                // assumption (see splitGallons) and this is where it is visible.
                after: products
                  .map((n, i) => `${n} (${split[i].toLocaleString()} gal)`)
                  .join(", "),
              };
            })}
          />
        }
      >
        <MultiSelectList
          placeholder="Search products..."
          empty="No products found."
          options={productOptions}
          value={products}
          onChange={setProducts}
        />
      </BulkEditDialog>

      {/* ---- Tier 2 · Driver. The list surfaces each driver's standing load,
           and the summary opens it up next to what is being added. ---------- */}
      <BulkEditDialog
        open={action === "driver"}
        onOpenChange={(o) => !o && close()}
        title="Driver"
        scopeVerb="Assign driver to"
        count={editCount}
        canProceed={driver !== undefined}
        summaryDescription={
          driver
            ? "The driver will be assigned to all the selected orders."
            : "The driver will be cleared from all the selected orders, returning them to Unassigned."
        }
        onConfirm={() => driver !== undefined && onSetDriver(driver)}
        summary={
          <div className="flex flex-col gap-5">
            {driver ? (
              <StandingLoad
                name={driver}
                orders={(standingLoad.get(driver) ?? []).map(toOrderRef)}
              />
            ) : null}
            <div className="flex flex-col gap-2">
              <span className="text-sm text-muted-foreground">
                {driver ? "Orders being added" : "Orders being unassigned"}
              </span>
              <OrderMiniTable orders={added} />
            </div>
          </div>
        }
      >
        <Command className="rounded-md border border-border">
          <CommandInput placeholder="Search driver" />
          <CommandList>
            <CommandEmpty>No drivers found.</CommandEmpty>
            <CommandGroup>
              <CommandItem
                value="Unassigned"
                selected={driver === null}
                onSelect={() => setDriver(null)}
              >
                <span className="text-muted-foreground italic">— Unassigned</span>
              </CommandItem>
              {driverOptions.map((d) => {
                const n = standingLoad.get(d)?.length ?? 0;
                return (
                  <CommandItem
                    key={d}
                    value={d}
                    selected={driver === d}
                    onSelect={() => setDriver(d)}
                    icon={
                      <Avatar className="size-6">
                        <AvatarFallback className="text-[10px]">
                          {initialsOf(d)}
                        </AvatarFallback>
                      </Avatar>
                    }
                    shortcut={
                      n === 0
                        ? "No orders assigned"
                        : `${n} ${n === 1 ? "order" : "orders"} assigned`
                    }
                  >
                    {d}
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </BulkEditDialog>

      {/* ---- Tier 1 · Planned date. Scalar, but rows differ going in — some
           carry no planned date at all, so the preview still informs. ------- */}
      <BulkEditDialog
        open={action === "date"}
        onOpenChange={(o) => !o && close()}
        title="Planned date"
        scopeVerb="Set the planned date on"
        count={editCount}
        canProceed={date !== undefined}
        summaryDescription="This planned date replaces whatever each selected order carries now. The delivery date is unaffected."
        onConfirm={() => date && onSetPlannedDate(date)}
        summary={
          <BeforeAfterTable
            valueHeader="planned date"
            rows={preview(
              (o) => o.planned?.date ?? "",
              date ? DATE_FMT.format(date) : ""
            )}
          />
        }
      >
        <div className="flex justify-center">
          <DatePanel selected={date} onSelect={setDate} />
        </div>
      </BulkEditDialog>

      {/* ---- Tier 1 · Planned time. ------------------------------------- */}
      <BulkEditDialog
        open={action === "time"}
        onOpenChange={(o) => !o && close()}
        title="Planned time"
        scopeVerb="Set the planned time on"
        count={editCount}
        canProceed={time.trim().length > 0}
        summaryDescription="This planned time replaces whatever each selected order carries now."
        onConfirm={() => time.trim() && onSetPlannedTime(time.trim())}
        summary={
          <BeforeAfterTable
            valueHeader="planned time"
            rows={preview((o) => o.planned?.time ?? "", time.trim())}
          />
        }
      >
        <div className="flex flex-col gap-2">
          <label htmlFor="bulk-planned-time" className="text-sm font-medium">
            Planned time
          </label>
          <Input
            id="bulk-planned-time"
            autoFocus
            value={time}
            placeholder="e.g. 1:35 AM"
            onChange={(e) => setTime(e.target.value)}
          />
        </div>
      </BulkEditDialog>

      {/* ---- Tier 3 · Tags. ADDITIVE — the preview shows the union, not a
           replacement, which is why "before" is never struck through here in
           spirit even though the shared table renders it that way. --------- */}
      <BulkEditDialog
        open={action === "tags"}
        onOpenChange={(o) => !o && close()}
        title="Add tags"
        scopeVerb="Add tags to"
        count={editCount}
        canProceed={tags.length > 0}
        summaryDescription="These tags are ADDED to whatever each order already carries — nothing is removed."
        onConfirm={() => tags.length > 0 && onAddTags(tags)}
        summary={
          <BeforeAfterTable
            valueHeader="tags"
            rows={selectedOrders.map((o) => ({
              orderNo: o.orderNo,
              before: o.tags.join(", "),
              after: Array.from(new Set([...o.tags, ...tags])).join(", "),
            }))}
          />
        }
      >
        <MultiSelectList
          placeholder="Search tags..."
          empty="No tags found."
          options={tagOptions}
          value={tags}
          onChange={setTags}
        />
      </BulkEditDialog>
    </>
  );
}

import * as React from "react";
import { Pill } from "@/components/ui/pill";
import { type CodeDiscTone } from "@/components/ui/code-disc";
import { type StatusTone } from "@/components/ui/status-chip";
import { BreakdownPopover, OverflowChip } from "./BreakdownCard";
import type {
  FuelOrderStatus,
  OrderTypeCode,
  ProductQty,
  PlannedAt,
} from "./types";
import { statusTones } from "./statusKind";
import { useUnitShort } from "./salesSettings";

/*
  THE FUEL ORDER CELLS (Pavan, 2026-10-07). The Fuel Orders table went when
  Fuel and Asset Orders became one Orders page (`SalesOrdersScreen`); its
  fuel cells and its type and status mappings live on here, and that page's
  table renders a fuel row with them.
*/

const QTY_FMT = new Intl.NumberFormat("en-US");

/*
  The two mappings below are ALL this screen owns about type and status. The
  rendering lives in the DS (`CodeDisc`, `StatusChip`); the DS ships hues and
  channels and binds no meaning to them, so declaring the meaning is the
  application's job. This is the same split the DS's own table uses via
  `statusTone` in tables-layout/data.ts.
*/

/** Order type → pastel hue. */
export const TYPE_TONE: Record<OrderTypeCode, CodeDiscTone> = {
  D: "pastel-blue",
  E: "pastel-amber",
};

/** Order status → colour channel. Exported so the map view reads a status the
 *  same way the table does rather than keeping a second copy of the mapping. */
export const STATUS_TONE: Record<FuelOrderStatus, StatusTone> = statusTones({
  /* Waiting on a dispatcher to schedule it. */
  Requested: "caution",
  /* True, and asks nothing — not finished. */
  Scheduled: "info",
  Dispatched: "info",
  Delivered: "success",
  /* Not a warning — grey, never red. */
  Canceled: "neutral",
});

/** Planned date over planned time. Em-dash when nothing is planned yet. */
export function PlannedCell({ planned }: { planned: PlannedAt | null }) {
  if (!planned) {
    return <span className="text-sm text-muted-foreground">—</span>;
  }
  return (
    <div className="flex min-w-0 flex-col">
      <span className="truncate text-sm text-foreground">{planned.date}</span>
      <span className="truncate text-xs tabular-nums text-muted-foreground">
        {planned.time}
      </span>
    </div>
  );
}

/**
 * Product cell — comma-separated names, truncated to whatever the column can
 * actually hold, with the remainder collapsed into a "+N" chip that reveals the
 * full list on hover.
 *
 * Width-driven rather than a fixed count: the column is a fixed 220px but names
 * run from "123" to "200* Diesel Onroad clear", so any fixed count either wastes
 * the cell or overflows it. An invisible sibling measures the real joined string
 * (and the real chip) so the fit is exact rather than estimated, and the count is
 * recomputed whenever the cell resizes. `truncate` on the visible span is the
 * safety net if a measurement is ever momentarily stale.
 */
export function ProductCell({ products }: { products: ProductQty[] }) {
  const rowRef = React.useRef<HTMLDivElement>(null);
  const measureRef = React.useRef<HTMLDivElement>(null);
  const textRef = React.useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = React.useState(products.length);

  React.useLayoutEffect(() => {
    const row = rowRef.current;
    const probe = textRef.current;
    const measure = measureRef.current;
    if (!row || !probe || !measure) return;

    const names = products.map((p) => p.name);

    const compute = () => {
      const avail = row.clientWidth;
      if (!avail) return;
      // The chip is only present when something is actually hidden; measure the
      // real element (its width changes with the digit count) plus the flex gap.
      const chip = measure.lastElementChild as HTMLElement | null;
      const chipW = chip ? chip.offsetWidth + 4 : 0;

      // Walk down from "all of them" to the largest prefix that fits.
      let fit = 1;
      for (let k = names.length; k >= 1; k--) {
        probe.textContent = names.slice(0, k).join(", ");
        const needed = probe.offsetWidth + (k < names.length ? chipW : 0);
        if (needed <= avail) {
          fit = k;
          break;
        }
      }
      setVisible(fit);
    };

    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(row);
    return () => ro.disconnect();
  }, [products]);

  const hidden = products.length - visible;

  return (
    <div
      ref={rowRef}
      className="relative flex min-w-0 items-center gap-1 overflow-hidden"
    >
      <span className="truncate text-sm text-foreground">
        {products
          .slice(0, visible)
          .map((p) => p.name)
          .join(", ")}
      </span>

      {hidden > 0 && (
        /* ON CLICK, the shared way (Pavan, 2026-10-14). */
        <OverflowChip
          count={hidden}
          label={`Show all ${products.length} products`}
          width={260}
          card={{ title: `All products (${products.length})`, rows: products.map((p) => ({ label: p.name })) }}
        />
      )}

      {/* Measurement only — never painted, never hit-tested, out of the a11y tree. */}
      <div
        ref={measureRef}
        aria-hidden
        className="pointer-events-none invisible absolute top-0 left-0 flex items-center gap-1 whitespace-nowrap"
      >
        <span ref={textRef} className="text-sm" />
        <Pill className="tabular-nums">
          +{Math.max(1, products.length - 1)}
        </Pill>
      </div>
    </div>
  );
}

/**
 * Tags cell — badges, as many as genuinely fit, remainder behind a "+N" chip.
 *
 * Same measured approach as ProductCell but measuring BADGES rather than a
 * joined string, and capped at two even when more would fit: a row of tags is
 * scannable at two and becomes noise past that.
 */
const TAGS_MAX = 2;

export function TagsCell({ tags }: { tags: string[] }) {
  const rowRef = React.useRef<HTMLDivElement>(null);
  const measureRef = React.useRef<HTMLDivElement>(null);
  const [visible, setVisible] = React.useState(Math.min(tags.length, TAGS_MAX));

  React.useLayoutEffect(() => {
    const row = rowRef.current;
    const measure = measureRef.current;
    if (!row || !measure || tags.length === 0) return;

    const compute = () => {
      const avail = row.clientWidth;
      if (!avail) return;
      const kids = [...measure.children] as HTMLElement[];
      const badges = kids.slice(0, tags.length);
      const chip = kids[tags.length];
      const chipW = chip ? chip.offsetWidth + 4 : 0;

      let fit = 0;
      let used = 0;
      for (let i = 0; i < Math.min(badges.length, TAGS_MAX); i++) {
        const w = badges[i].offsetWidth + (i > 0 ? 4 : 0);
        const remains = i < tags.length - 1;
        if (used + w + (remains ? chipW : 0) > avail) break;
        used += w;
        fit = i + 1;
      }
      // Always show at least one tag; it truncates rather than vanishing.
      setVisible(Math.max(1, fit));
    };

    compute();
    const ro = new ResizeObserver(compute);
    ro.observe(row);
    return () => ro.disconnect();
  }, [tags]);

  if (tags.length === 0) {
    return <span className="text-sm text-muted-foreground">—</span>;
  }

  const hidden = tags.length - visible;

  return (
    <div
      ref={rowRef}
      className="relative flex min-w-0 items-center gap-1 overflow-hidden"
    >
      {tags.slice(0, visible).map((t) => (
        <Pill key={t} className="min-w-0 truncate">
          {t}
        </Pill>
      ))}

      {hidden > 0 && (
        <OverflowChip
          count={hidden}
          label={`Show all ${tags.length} tags`}
          width={220}
          card={{ title: `All tags (${tags.length})`, rows: tags.map((t) => ({ label: t })) }}
        />
      )}

      {/* Measurement only — never painted, never hit-tested. */}
      <div
        ref={measureRef}
        aria-hidden
        className="pointer-events-none invisible absolute top-0 left-0 flex items-center gap-1 whitespace-nowrap"
      >
        {tags.map((t) => (
          <Pill key={t}>
            {t}
          </Pill>
        ))}
        <Pill className="tabular-nums">
          +{Math.max(1, tags.length - 1)}
        </Pill>
      </div>
    </div>
  );
}

/**
 * Qty cell — the row total, with a per-product gallon breakdown on hover when
 * the order has more than one product line. Single-line orders have nothing to
 * break down, so they stay plain text rather than offering a dead trigger.
 */
export function QtyCell({ products, total }: { products: ProductQty[]; total: number }) {
  const amount = QTY_FMT.format(total);
  /* THE PRIMARY UNIT'S LABEL — Sales Settings › Preferences (2026-10-07). */
  const unit = useUnitShort();

  if (products.length < 2) {
    return (
      <span className="text-sm text-foreground">
        <span className="font-medium tabular-nums">{amount}</span>{" "}
        <span className="text-xs text-muted-foreground">{unit}</span>
      </span>
    );
  }

  /* THE WHOLE CELL IS THE FIGURE, so the figure is what opens it — on
     click, the shared way (Pavan, 2026-10-14). The underline stays on the
     number alone. */
  return (
    <BreakdownPopover
      className="group/qty rounded-sm text-sm text-foreground"
      label={`${amount} ${unit} across ${products.length} products`}
      card={{
        title: "Quantity by product",
        rows: products.map((p) => ({ label: p.name, value: QTY_FMT.format(p.gal) })),
        total: { label: "Total", value: QTY_FMT.format(total) },
      }}
      trigger={
        <>
          <span className="font-medium tabular-nums underline-offset-4 group-hover/qty:underline group-focus-visible/qty:underline">
            {amount}
          </span>{" "}
          <span className="text-xs text-muted-foreground">{unit}</span>
        </>
      }
    />
  );
}

import * as React from "react";
import { Check, ChevronDown, MoreHorizontal, Plus, RefreshCw, Upload } from "lucide-react";
import { cn } from "@/lib/utils";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { suggestViewName } from "./filterMemory";

/**
 * Preset-view row.
 *
 * The interaction is the DS's finalized one, from the Data Action Control unit
 * (`data-action-control/DataActionControl.tsx`, rows 177–228) — NOT the
 * `PresetTabs` helper in `experiments/dac-rebuild`, which is archived
 * (`arc-rebuild-*` in App.tsx's ARCHIVE_KEYS) and only stubs view creation by
 * appending "View 1", "View 2" with no name and no state.
 *
 * What that means concretely:
 *   • "Default" is a reset control, not a tab — it restores the default state.
 *   • Creating a view opens a Dialog and the view is NAMED. A view captures the
 *     current search / sort / hidden columns / page size / delivery date, and
 *     selecting it restores them. A view that carries no state is just a label.
 *   • Each saved view has a `⋯` menu revealed on hover: Update view (only when
 *     the current state has drifted), Rename, Delete.
 *   • A brand dot next to the active tab marks unsaved drift.
 *   • Tabs are plain buttons with a `border-b-2` active underline — not the
 *     shadcn Tabs component, so the `⋯` control can sit inside the tab.
 */

/** The slice of screen state a saved view captures and restores. */
export interface ViewState {
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  /**
   * Column order as keys, outermost left. Part of the view because which two
   * columns sit side by side IS the view for anyone comparing them — a view
   * that restored the filters but not the arrangement would rebuild half the
   * thing. Empty means "as the table declares them".
   */
  columnOrder: string[];
  /** Reader-set column widths in px, by key. Empty means "as declared". */
  columnWidths: Record<string, number>;
  pageSize: number;
  /** Delivery date as `YYYY-MM-DD` — views are date-scoped like everything else. */
  dateKey: string;
  /** Which column the "Search by column" tool is pointed at. */
  colScope: string;
  /** Its query. Captured so a saved view restores the narrowing it was built with. */
  colQuery: string;
  /**
   * Active grouping dimensions, outermost first. ORDER IS SIGNIFICANT and is
   * compared as given — Status › Customer and Customer › Status are different
   * views, not the same one.
   */
  groupBy: string[];
}

export interface SavedView {
  id: string;
  name: string;
  state: ViewState;
}

/** Order-independent comparison, so drift detection can't be fooled by key order. */
export function viewStateKey(s: ViewState): string {
  return JSON.stringify({
    search: s.search,
    sortKey: s.sortKey,
    sortDir: s.sortDir,
    hidden: [...s.hidden].sort(),
    pageSize: s.pageSize,
    dateKey: s.dateKey,
    colScope: s.colScope,
    colQuery: s.colQuery,
    // Not sorted: the order of the dimensions is part of the state.
    groupBy: s.groupBy ?? [],
  });
}

export interface FuelOrdersViewBarProps {
  /**
   * Only the id and name are read here — the captured state is opaque to this
   * component, which is why Asset Orders and Customers can reuse the row with
   * their own state shapes.
   */
  views: { id: string; name: string }[];
  /**
   * BUILT-IN VIEWS, sitting FIRST, ruled off from Default and the saved ones.
   *
   * A saved view is something a reader MADE; a preset is something the business
   * already is. The businesses inside a line of service — fuel's transport and
   * tank wagon — are the second kind: a broker works one of them, all day, and
   * would otherwise rebuild the same filter every morning and save it under the
   * name it already has.
   *
   * They carry no `⋯` menu, because there is nothing to rename, update or
   * delete about a fact. Picking one is picking Default AND that narrowing, so
   * the two selections are one control and only one tab is ever underlined —
   * and picking one from inside a saved view drops that view.
   */
  presets?: { key: string; label: string }[];
  /** `null` = no preset; the Default tab owns the underline. */
  presetKey?: string | null;
  /** `null` clears the preset — the row sends it when a view takes over. */
  onPresetChange?: (key: string | null) => void;
  /** `null` = the Default view is active. */
  activeId: string | null;
  /** Current state differs from the active view (or from default). */
  dirty: boolean;
  onApply: (id: string) => void;
  onResetToDefault: () => void;
  onCreate: (name: string) => void;
  onRename: (id: string, name: string) => void;
  onUpdate: (id: string) => void;
  onDelete: (id: string) => void;
  /**
   * A segmented scope control, seated at the right of this row ahead of the
   * actions. For a list that holds two KINDS of record rather than two filters
   * of one — fuel orders and asset orders take different forms and answer
   * different questions, so which of them you are looking at is a decision made
   * before anything else on the row applies.
   */
  segments?: { key: string; label: string }[];
  segmentValue?: string;
  onSegmentChange?: (key: string) => void;
  /** Primary CTA — rendered at the right end of this row. */
  onCreateOrder?: () => void;
  /**
   * Turns the CTA into a menu. A list whose Create means several DIFFERENT
   * records — a delivery, an asset out, an asset back — cannot express that in
   * one button: the three take different forms, so the choice has to be made
   * before the form opens rather than by a Type field inside it.
   *
   * Each option carries a `detail` because the names alone do not separate
   * them: "Asset Delivery" and "Asset Pickup" are one word apart and opposite.
   */
  createMenu?: {
    key: string;
    label: string;
    /** Optional — Sales' menu carries names only (Pavan, 2026-10-07). */
    detail?: string;
    /**
     * Turns the entry into a GROUP: its label and detail stop being a button
     * and become the heading over a radio list. Use it where one kind of thing
     * comes in two named variants — the variant is a property of the thing, not
     * a third kind, and a flat menu of near-identical names is where a one-word
     * difference gets misread.
     *
     * Choosing an entry ACTS in one click: `onCreateSelect` gets the
     * chosen key. Each entry starts its order; nothing is held selected.
     */
    choices?: { key: string; label: string; detail?: string }[];
  }[];
  onCreateSelect?: (key: string) => void;
  /** CTA label. Defaults to Fuel Orders' own verb. */
  ctaLabel?: string;
  /** Export — sits immediately left of the CTA. */
  onExport?: () => void;
}

const tabCls = (isActive: boolean) =>
  cn(
    /* `self-end` IS THE WHOLE POINT OF THE ACTIVE RULE. The row is
       `items-center` and its height is set by the taller right cluster, so a
       centred tab floated a couple of pixels clear of the hairline and its 2px
       underline read as a second, parallel line. Bottom-aligned, the two meet:
       the tab's rule lands on the divider with nothing between them. */
    "self-end px-3 py-2 text-xs whitespace-nowrap outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
    isActive
      ? "font-medium text-foreground"
      : "text-muted-foreground hover:text-foreground"
  );

/** Brand dot marking unsaved drift on the active tab. */
function DirtyDot() {
  return (
    <span
      className="ml-1.5 inline-block size-1.5 rounded-full bg-brand align-middle"
      aria-label="unsaved changes"
    />
  );
}

export function FuelOrdersViewBar({
  views,
  activeId,
  dirty,
  onApply,
  onResetToDefault,
  presets,
  presetKey = null,
  onPresetChange,
  onCreate,
  onRename,
  onUpdate,
  onDelete,
  segments,
  segmentValue,
  onSegmentChange,
  onCreateOrder,
  createMenu,
  onCreateSelect,
  onExport,
  ctaLabel = "Create Order",
}: FuelOrdersViewBarProps) {
  const [dialog, setDialog] = React.useState<{
    mode: "new" | "rename";
    id?: string;
    name: string;
    /** A NEW VIEW'S SUGGESTED NAME, from the filters on (Pavan, 2026-10-21) —
        the placeholder; → or Tab takes it to type on from, and Save with
        the box empty saves it. */
    suggestion?: string;
  } | null>(null);


  const submit = () => {
    if (!dialog) return;
    const name = dialog.name.trim() || (dialog.mode === "new" ? dialog.suggestion ?? "" : "");
    if (!name) return;
    /* Creating activates the new view, so it clears the business for the same
       reason applying one does. */
    if (dialog.mode === "new") {
      onPresetChange?.(null);
      onCreate(name);
    }
    else if (dialog.id) onRename(dialog.id, name);
    setDialog(null);
  };

  return (
    <>
      {/* -mx-4 -mt-4 cancels the content layer's 16px inset so the hairline spans
          the full panel width, as it does on the DS screen. */}
      {/* NO BOTTOM PADDING. The active tab's 2px rule has to LAND ON the row's
          hairline — that is what makes it read as a tab and not as an underline
          floating above a line. The row used to keep 2px under the tabs, which
          left a hairline gap between the two rules and made the whole tab strip
          look one notch high. Everything on the right measures its own distance
          from the divider with `self-end` + a margin, so those margins carry
          the 2px that came out of here. */}
      <div className="-mx-4 -mt-4 flex shrink-0 items-center gap-1 border-b border-border px-3 pt-0.5">
        {/* THE BUSINESSES COME FIRST, then a rule, then the views.

            They are two different kinds of thing and the row was reading as one
            list of six. A preset is WHICH BUSINESS this is — a fact about the
            work, true before anyone opened the screen; a view is a narrowing
            somebody MADE and can rename or delete. Ordering the facts first and
            ruling them off says which half of the row you are in, and puts the
            thing a broker changes least often where it is easiest to find.

            DEFAULT IS STILL THE RESTING STATE — it holds the underline when no
            business and no view is on, and it is the first thing after the
            rule, which is where the reader's eye lands once they are past the
            facts. */}
        {presets?.map((p) => (
          <button
            key={p.key}
            type="button"
            /* A PRESET IS DEFAULT PLUS A NARROWING, so picking one from inside
               a saved view drops the view as well. The row used to hide the
               presets while a view was active rather than answer this; hidden
               controls are a worse answer than a stated rule. */
            onClick={() => {
              if (activeId !== null) onResetToDefault();
              onPresetChange?.(p.key);
            }}
            className={cn(
              tabCls(presetKey === p.key),
              "border-b-2",
              presetKey === p.key ? "border-foreground" : "border-transparent"
            )}
          >
            {p.label}
          </button>
        ))}

        {presets && presets.length > 0 && (
          <span aria-hidden className="mx-2 mb-2 h-5 w-px shrink-0 self-end bg-border" />
        )}

        <button
          type="button"
          onClick={onResetToDefault}
          className={cn(
            tabCls(activeId === null && presetKey === null),
            "border-b-2",
            activeId === null && presetKey === null
              ? "border-foreground"
              : "border-transparent"
          )}
        >
          All
          {activeId === null && presetKey === null && dirty && <DirtyDot />}
        </button>

        {views.map((v) => {
          const isActive = v.id === activeId;
          return (
            /* The wrapper is the flex child, so the alignment lives here —
               `tabCls`'s own `self-end` cannot reach past it. */
            <div key={v.id} className="group/tab flex items-end self-end pr-1">
              <button
                type="button"
                /* A VIEW AND A BUSINESS ARE MUTUALLY EXCLUSIVE, because only
                   one tab in this row can hold the underline and a narrowing
                   nobody can see is the thing Default exists to prevent. A
                   saved view does not capture the business — `ViewState` has no
                   field for it — so taking a view means leaving the business,
                   the same way picking a business leaves the view. */
                onClick={() => {
                  onPresetChange?.(null);
                  onApply(v.id);
                }}
                className={cn(
                  tabCls(isActive),
                  "border-b-2",
                  isActive ? "border-foreground" : "border-transparent"
                )}
              >
                {v.name}
              </button>
              {/* CHANGED SINCE SAVED — THE UPDATE IS ONE PRESS, beside the
                  name (Pavan, 2026-10-21), not a dot that sends you to ⋯.
                  The two-arrow refresh glyph, in grey (2026-10-22). */}
              {isActive && dirty && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      aria-label={`Update ${v.name} with the changes`}
                      onClick={() => onUpdate(v.id)}
                      className="mb-1.5 ml-0.5 inline-flex size-6 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                    >
                      <RefreshCw className="size-3.5" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>Update changes</TooltipContent>
                </Tooltip>
              )}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <button
                    type="button"
                    aria-label={`${v.name} options`}
                    className="ml-0.5 rounded p-0.5 text-muted-foreground opacity-0 outline-none transition-opacity hover:text-foreground focus-visible:opacity-100 group-hover/tab:opacity-100 data-[state=open]:opacity-100"
                  >
                    <MoreHorizontal className="size-3.5" />
                  </button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start">
                  {isActive && dirty && (
                    <DropdownMenuItem onClick={() => onUpdate(v.id)}>
                      <Check /> Update view
                    </DropdownMenuItem>
                  )}
                  <DropdownMenuItem
                    onClick={() =>
                      setDialog({ mode: "rename", id: v.id, name: v.name })
                    }
                  >
                    Rename
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    variant="destructive"
                    onClick={() => onDelete(v.id)}
                  >
                    Delete
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          );
        })}

        <button
          type="button"
          onClick={() => setDialog({ mode: "new", name: "", suggestion: suggestViewName() })}
          /* Not a tab — it has no rule to land, so it keeps 4px off the
             hairline rather than sitting on it. */
          className="mb-1 ml-1 inline-flex items-center gap-1 self-end rounded-md px-2 py-1 text-xs text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <Plus className="size-4" /> View
        </button>

        {/*
          Primary CTA, moved up here from the toolbar's right cluster so it sits
          on the preset-view row.

          `size="xs"` — the DS step below `sm` (h-6/24px vs h-8/32px). This row
          carries text tabs, not controls, so the 32px button sat heavy on it.

          `rounded-[4px]` is OFF the DS radius scale, which runs
          xs 2px / sm 6px / md 8px / lg 10px — there is no 4px step. Asked for
          directly, so it stands as a literal, but it is the one raw value in
          this file. FOLLOW-UP: either add a 4px step to the radius scale in
          src/index.css and swap this for the token, or move the button to
          `rounded-sm` (6px). A decision to make here, not a Figma round-trip.

          `mr-1` is load-bearing: this row cancels the content layer's 16px inset
          with -mx-4 and re-pads at px-3 (12px) so its hairline spans the whole
          panel, which would leave the button 4px further right than the toolbar
          controls below it. The extra 4px puts both right edges on the same line.

          `self-end mb-3` sets the gap to the hairline. The row is
          `items-center`, so the button opts out of centring and measures from the
          bottom instead; 12px of margin puts exactly 12px between the button's
          lower edge and the divider. (It was 10 + the row's own 2px of bottom
          padding, until the tabs took that padding away so their rule could land
          on the hairline.)
        */}
        {/* THE SCOPE, THEN SPACE, THEN THE ACTIONS. The segments choose WHICH
            list this is; the buttons act on it. A 20px gap says they are not
            the same kind of control (a rule did, until 2026-10-05). It takes the `ml-auto` so the whole right cluster sits
            right; the CTA below no longer needs it. */}
        {segments && segments.length > 0 && (
          <>
            <ToggleGroup
              type="single"
              variant="outline"
              size="sm"
              value={segmentValue}
              /* Radix emits "" when the active item is pressed again. A scope is
                 never empty — ignore the deselect so one segment stays chosen. */
              onValueChange={(next) => next && onSegmentChange?.(next)}
              aria-label="Order kind"
              className="mb-2.5 ml-auto h-7 self-end"
            >
              {segments.map((seg) => (
                <ToggleGroupItem
                  key={seg.key}
                  value={seg.key}
                  className="h-7 px-2.5 text-xs font-normal data-[state=on]:font-medium"
                >
                  {seg.label}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
            {/* SPACE, NOT A RULE (Pavan, 2026-10-05): 12px here plus the
                row's 4px gap each side — 20px between the scope and the CTA. */}
            <span aria-hidden className="w-3 shrink-0" />
          </>
        )}

        {/* NO HANDLER, NO BUTTON. A list without a create flow — Vendors, where
            a carrier is onboarded through a contract rather than typed into a
            table — should not carry a CTA that does nothing when pressed. The
            `ml-auto` moves to the Export button below so the right cluster
            still sits right. */}
        {createMenu && createMenu.length > 0 ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                size="xs"
                className={cn(
                  "mb-3 self-end rounded-[4px]",
                  !segments?.length && "ml-auto"
                )}
              >
                <Plus />
                {ctaLabel}
                <ChevronDown />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-80">
              {createMenu.map((o, i) =>
                o.choices?.length ? (
                  <React.Fragment key={o.key}>
                    {i > 0 && <DropdownMenuSeparator />}
                    {/* The group's own name is a HEADING, not a button — the
                        entries below it are the choice. Plain entries, no
                        radios (Pavan, 2026-10-05): each one STARTS an order,
                        so there is no selection for a dot to hold. */}
                    <DropdownMenuLabel className="flex flex-col items-start gap-0.5 py-2 font-normal">
                      <span className="text-sm font-medium text-foreground">
                        {o.label}
                      </span>
                      {o.detail && (
                        <span className="text-xs text-muted-foreground">{o.detail}</span>
                      )}
                    </DropdownMenuLabel>
                    {o.choices.map((c) => (
                      <DropdownMenuItem
                        key={c.key}
                        className="flex-col items-start gap-0.5 py-2"
                        onSelect={() => onCreateSelect?.(c.key)}
                      >
                        <span className="text-sm text-foreground">{c.label}</span>
                        {c.detail && (
                          <span className="text-xs text-muted-foreground">
                            {c.detail}
                          </span>
                        )}
                      </DropdownMenuItem>
                    ))}
                  </React.Fragment>
                ) : (
                  <DropdownMenuItem
                    key={o.key}
                    className="flex-col items-start gap-0.5 py-2"
                    onSelect={() => onCreateSelect?.(o.key)}
                  >
                    <span className="text-sm font-medium text-foreground">{o.label}</span>
                    {o.detail && (
                      <span className="text-xs text-muted-foreground">{o.detail}</span>
                    )}
                  </DropdownMenuItem>
                )
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : (
          onCreateOrder && (
            <Button
              size="xs"
              className={cn(
                "mb-3 self-end rounded-[4px]",
                !segments?.length && "ml-auto"
              )}
              onClick={onCreateOrder}
            >
              <Plus />
              {ctaLabel}
            </Button>
          )
        )}

        {/*
          Export, moved down from the page header so both actions for this list
          sit together. `icon-xs` (24px) matches the CTA's height, and the same
          self-end/mb-3 puts them on one baseline.

          It is the rightmost item, so it carries the `mr-1` that keeps this row
          aligned with the toolbar below: the row cancels the content layer's
          16px inset with -mx-4 and re-pads at px-3, so without the extra 4px the
          trailing control would sit proud of every toolbar control under it.
        */}
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label="Export"
              onClick={onExport}
              className={cn(
                "mr-1 mb-3 self-end",
                // Takes over pushing the right cluster right when there is no CTA.
                onCreateOrder || createMenu || segments?.length ? "ml-1.5" : "ml-auto"
              )}
            >
              <Upload />
            </Button>
          </TooltipTrigger>
          <TooltipContent>Export</TooltipContent>
        </Tooltip>
      </div>

      <Dialog open={dialog !== null} onOpenChange={(o) => !o && setDialog(null)}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>
              {dialog?.mode === "rename" ? "Rename view" : "Save current view"}
            </DialogTitle>
          </DialogHeader>
          <div className="grid gap-2">
            <Label htmlFor="fuel-view-name">View name</Label>
            <Input
              id="fuel-view-name"
              autoFocus
              value={dialog?.name ?? ""}
              onChange={(e) =>
                setDialog((d) => (d ? { ...d, name: e.target.value } : d))
              }
              onKeyDown={(e) => {
                if (e.key === "Enter") submit();
                /* TAKE THE SUGGESTION to add to it. */
                if ((e.key === "ArrowRight" || e.key === "Tab") && !dialog?.name && dialog?.suggestion) {
                  e.preventDefault();
                  setDialog((d) => (d ? { ...d, name: `${d.suggestion} ` } : d));
                }
              }}
              placeholder={(dialog?.mode === "new" && dialog.suggestion) || "e.g. Unassigned today"}
            />
          </div>
          <DialogFooter>
            <DialogClose asChild>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button
              onClick={submit}
              disabled={!dialog?.name.trim() && !(dialog?.mode === "new" && dialog.suggestion)}
            >
              {dialog?.mode === "rename" ? "Rename" : "Save view"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import * as React from "react";
import {
  Caravan,
  ClipboardList,
  Contact,
  Database,
  Droplet,
  FileText,
  Fuel,
  HardHat,
  LayoutGrid,
  Search,
  Truck,
  Users,
  Wrench,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Pill } from "@/components/ui/pill";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import { Kbd } from "@/components/ui/kbd";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  MODULE_LABEL,
  SEARCH_INDEX,
  TYPE_LABEL,
  TYPE_ORDER,
  TYPE_SINGULAR,
  matchedKeyword,
  moduleCounts,
  queryTerms,
  searchAll,
  typeCounts,
  type ScopeCount,
  type SearchEntry,
  type SearchModule,
  type SearchType,
} from "./searchIndex";

/**
 * Global search — one query across every module, with counts (Pavan,
 * 2026-10-23 — the LinkedIn pattern).
 *
 * FIRST PILL ROW: "All" plus one pill per module that has results, each with
 * its count. SECOND ROW, once a module is chosen: that module's record types
 * with their counts. Every count is the number of matches in the whole index;
 * a capped group says how many more it holds.
 *
 * Built on the DS `Command` (cmdk) inside a `Dialog`, so arrow-key navigation,
 * the active-row highlight and Enter are the DS's behaviour rather than
 * re-implemented. cmdk's own filter is off — `shouldFilter` false — because
 * the matching is done in `searchAll`, which matches every word of the query in
 * any order across every field; cmdk's single fuzzy pass would disagree with
 * the counts on the pills.
 *
 * KEYBOARD: ↑ ↓ move, Enter opens, Tab steps through the module pills and
 * Shift+Tab through the record-type pills of the chosen module. The pills keep
 * focus in the query field when clicked, so typing carries on.
 *
 * DS FOLLOW-UP: this is a command palette, not a Unified View thing. It belongs
 * in the DS beside `top-bar/`, taking its index and scopes as props.
 */

const TYPE_ICON: Record<SearchType, React.ReactNode> = {
  "delivery-order": <Truck />,
  "fuel-order": <Fuel />,
  "asset-order": <ClipboardList />,
  quote: <FileText />,
  "service-order": <Wrench />,
  customer: <Users />,
  vendor: <Contact />,
  product: <Droplet />,
  asset: <Database />,
  "rental-asset": <Caravan />,
  technician: <HardHat />,
  page: <LayoutGrid />,
};

/** Seeded so the empty state is not blank on first open. */
const RECENT_IDS = ["page-sales-orders", "cu-cu-2"];

/** Rows a group shows before it says how many more it holds. */
const CAP_ALL = 5;
const CAP_MODULE = 5;
const CAP_TYPE = 50;

export interface GlobalSearchProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /**
   * Go to a result: switch MODULE and rail destination, then open the record if
   * there is one. The module is part of the address — without it a 3PL hit found
   * while the Sales module is active would set a rail key that module does not
   * have.
   */
  onNavigate: (moduleKey: string, navKey: string, recordId: string | null) => void;
}

/** The text with every query term set in the foreground ink. */
function Highlight({ text, terms }: { text: string; terms: string[] }) {
  if (terms.length === 0) return <>{text}</>;
  const escaped = terms.map((t) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const parts = text.split(new RegExp(`(${escaped.join("|")})`, "gi"));
  return (
    <>
      {parts.map((p, i) =>
        i % 2 === 1 ? (
          <span key={i} className="font-semibold text-foreground">
            {p}
          </span>
        ) : (
          <React.Fragment key={i}>{p}</React.Fragment>
        )
      )}
    </>
  );
}

/** A scope pill — a button around the DS pill; selected wears the selection tokens. */
function ScopePill({
  label,
  count,
  selected,
  onSelect,
}: {
  label: string;
  count: number;
  selected: boolean;
  onSelect: () => void;
}) {
  return (
    <button
      type="button"
      aria-pressed={selected}
      // Keep focus in the query field so typing and ↑ ↓ carry on.
      onMouseDown={(e) => e.preventDefault()}
      onClick={onSelect}
      className="shrink-0 rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      <Pill
        className={cn(
          "gap-1.5 transition-colors",
          selected
            ? "bg-selected font-medium text-selected-foreground"
            : "hover:text-foreground"
        )}
      >
        {label} <span className="tabular-nums">{count.toLocaleString("en-US")}</span>
      </Pill>
    </button>
  );
}

function PillRow<K extends string>({
  label,
  all,
  items,
  value,
  onChange,
}: {
  label: string;
  /** The "All" pill's count. */
  all: number;
  items: ScopeCount<K>[];
  value: K | null;
  onChange: (key: K | null) => void;
}) {
  return (
    <div role="group" aria-label={label} className="flex flex-wrap items-center gap-1.5">
      <ScopePill label="All" count={all} selected={value === null} onSelect={() => onChange(null)} />
      {items.map((s) => (
        <ScopePill
          key={s.key}
          label={s.label}
          count={s.count}
          selected={value === s.key}
          onSelect={() => onChange(s.key)}
        />
      ))}
    </div>
  );
}

export function GlobalSearch({ open, onOpenChange, onNavigate }: GlobalSearchProps) {
  const [query, setQuery] = React.useState("");
  const [moduleScope, setModuleScope] = React.useState<SearchModule | null>(null);
  const [typeScope, setTypeScope] = React.useState<SearchType | null>(null);

  // Reset on every open — a palette that reopens mid-query is disorienting.
  React.useEffect(() => {
    if (!open) return;
    setQuery("");
    setModuleScope(null);
    setTypeScope(null);
  }, [open]);

  const terms = React.useMemo(() => queryTerms(query), [query]);
  const searching = terms.length > 0;

  /* EVERY COUNT COMES FROM THE FULL HIT LIST — never from what a group shows. */
  const hits = React.useMemo(() => (searching ? searchAll(query) : []), [query, searching]);
  const modules = React.useMemo(() => {
    const counts = moduleCounts(hits);
    // A chosen module stays on the row at 0 rather than vanishing under the cursor.
    if (moduleScope && !counts.some((m) => m.key === moduleScope))
      counts.push({ key: moduleScope, label: MODULE_LABEL[moduleScope], count: 0 });
    return counts;
  }, [hits, moduleScope]);
  const inModule = React.useMemo(
    () => (moduleScope ? hits.filter((e) => e.moduleKey === moduleScope) : hits),
    [hits, moduleScope]
  );
  const types = React.useMemo(() => {
    const counts = typeCounts(inModule);
    if (typeScope && !counts.some((t) => t.key === typeScope))
      counts.push({ key: typeScope, label: TYPE_LABEL[typeScope], count: 0 });
    return counts;
  }, [inModule, typeScope]);
  const shown = React.useMemo(
    () => (typeScope ? inModule.filter((e) => e.type === typeScope) : inModule),
    [inModule, typeScope]
  );

  /* GROUPS: by module under "All", by record type once a module is chosen. */
  const groups = React.useMemo(() => {
    if (!moduleScope) {
      return modules
        .filter((m) => m.count > 0)
        .map((m) => ({
          key: m.key,
          label: m.label,
          // Index rank, not type order: a title match leads whatever its type.
          items: shown.filter((e) => e.moduleKey === m.key),
          cap: CAP_ALL,
        }));
    }
    return TYPE_ORDER.map((t) => ({
      key: t,
      label: TYPE_LABEL[t],
      items: shown.filter((e) => e.type === t),
      cap: typeScope ? CAP_TYPE : CAP_MODULE,
    })).filter((g) => g.items.length > 0);
  }, [modules, moduleScope, typeScope, shown]);

  // Empty state: recents, then every page.
  const recents = React.useMemo(
    () =>
      RECENT_IDS.map((id) => SEARCH_INDEX.find((e) => e.id === id)).filter(
        (e): e is SearchEntry => Boolean(e)
      ),
    []
  );
  const pages = React.useMemo(() => SEARCH_INDEX.filter((e) => e.type === "page"), []);

  /* THE ACTIVE ROW IS HELD HERE so a scope change never leaves Enter with no
     row: when the active row leaves the list, the first row takes over. */
  const visibleIds = React.useMemo(
    () =>
      searching
        ? groups.flatMap((g) => g.items.slice(0, g.cap).map((e) => e.id))
        : [...recents, ...pages].map((e) => e.id),
    [searching, groups, recents, pages]
  );
  const [active, setActive] = React.useState("");
  React.useEffect(() => {
    if (!visibleIds.includes(active)) setActive(visibleIds[0] ?? "");
  }, [visibleIds, active]);

  const go = (e: SearchEntry) => {
    onNavigate(e.moduleKey, e.navKey, e.recordId);
    onOpenChange(false);
  };

  const chooseModule = (m: SearchModule | null) => {
    setModuleScope(m);
    setTypeScope(null);
  };

  const cycleModule = () => {
    const keys: (SearchModule | null)[] = [null, ...modules.map((m) => m.key)];
    chooseModule(keys[(keys.indexOf(moduleScope) + 1) % keys.length]);
  };
  const cycleType = () => {
    if (!moduleScope) return;
    const keys: (SearchType | null)[] = [null, ...types.map((t) => t.key)];
    setTypeScope(keys[(keys.indexOf(typeScope) + 1) % keys.length]);
  };

  const scopeName = typeScope
    ? `${TYPE_LABEL[typeScope]} in ${MODULE_LABEL[moduleScope!]}`
    : moduleScope
      ? MODULE_LABEL[moduleScope]
      : null;

  const Row = ({ entry }: { entry: SearchEntry }) => {
    const extra = searching ? matchedKeyword(entry, terms) : null;
    return (
      <CommandItem
        key={entry.id}
        value={entry.id}
        onSelect={() => go(entry)}
        className="gap-3 py-2"
        icon={
          <span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-fp-card-1 text-muted-foreground [&_svg]:size-4">
            {TYPE_ICON[entry.type]}
          </span>
        }
      >
        <span className="flex min-w-0 flex-col items-start gap-1">
          <span className="flex min-w-0 max-w-full items-center gap-2">
            <span className="truncate text-sm font-medium text-foreground">
              <Highlight text={entry.title} terms={terms} />
            </span>
            <Pill className="shrink-0">
              {TYPE_SINGULAR[entry.type]} · {MODULE_LABEL[entry.moduleKey]}
            </Pill>
          </span>
          <span className="max-w-full truncate text-xs text-muted-foreground">
            <Highlight text={entry.subtitle} terms={terms} />
            {extra && (
              <>
                {" · "}
                <Highlight text={extra} terms={terms} />
              </>
            )}
          </span>
        </span>
      </CommandItem>
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        showCloseButton={false}
        aria-describedby={undefined}
        className="top-[12%] w-full translate-y-0 gap-0 overflow-hidden p-0 sm:max-w-2xl"
      >
        <DialogTitle className="sr-only">Global search</DialogTitle>
        <Command
          shouldFilter={false}
          loop
          value={active}
          onValueChange={setActive}
          onKeyDown={(e) => {
            // Tab steps the module pills; Shift+Tab the chosen module's types.
            if (e.key === "Tab" && searching) {
              e.preventDefault();
              if (e.shiftKey) cycleType();
              else cycleModule();
            }
          }}
        >
          {/* Query row */}
          <div className="flex items-center gap-2 border-b border-border px-4">
            <Search className="size-4 shrink-0 text-muted-foreground" />
            <input
              autoFocus
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search every module — orders, customers, vendors, assets, pages"
              aria-label="Search every module"
              className="h-12 flex-1 bg-transparent text-sm text-foreground outline-none placeholder:text-muted-foreground"
            />
            <Kbd>Esc</Kbd>
          </div>

          {/* Scope pills — modules, then the chosen module's record types */}
          {searching && (hits.length > 0 || moduleScope) && (
            <div className="flex flex-col items-start gap-2 border-b border-border px-3 py-2">
              <PillRow
                label="Module"
                all={hits.length}
                items={modules}
                value={moduleScope}
                onChange={chooseModule}
              />
              {moduleScope && (
                <PillRow
                  label="Record type"
                  all={inModule.length}
                  items={types}
                  value={typeScope}
                  onChange={setTypeScope}
                />
              )}
            </div>
          )}

          <CommandList className="max-h-[52vh]">
            {searching ? (
              <>
                <CommandEmpty>
                  No results for “{query.trim()}”{scopeName ? ` in ${scopeName}` : ""}.
                </CommandEmpty>
                {groups.map((g) => (
                  <CommandGroup key={g.key} heading={g.label}>
                    {g.items.slice(0, g.cap).map((e) => (
                      <Row key={e.id} entry={e} />
                    ))}
                    {g.items.length > g.cap && (
                      <div className="px-2 py-1.5 text-xs text-muted-foreground">
                        {(g.items.length - g.cap).toLocaleString("en-US")} more in {g.label}
                      </div>
                    )}
                  </CommandGroup>
                ))}
              </>
            ) : (
              <>
                {recents.length > 0 && (
                  <CommandGroup heading="Recent">
                    {recents.map((e) => (
                      <Row key={e.id} entry={e} />
                    ))}
                  </CommandGroup>
                )}
                <CommandGroup heading="Pages">
                  {pages.map((e) => (
                    <Row key={e.id} entry={e} />
                  ))}
                </CommandGroup>
              </>
            )}
          </CommandList>

          {/* Keyboard hints */}
          <div className="flex items-center gap-4 border-t border-border px-4 py-2.5 text-xs text-muted-foreground">
            <span className="flex items-center gap-1.5">
              <Kbd>↑</Kbd>
              <Kbd>↓</Kbd> navigate
            </span>
            <span className="flex items-center gap-1.5">
              <Kbd>↵</Kbd> open
            </span>
            <span className="flex items-center gap-1.5">
              <Kbd>Tab</Kbd> scope
            </span>
            <span className="ml-auto flex items-center gap-1.5">
              <Kbd>⌘</Kbd>
              <Kbd>K</Kbd> toggle
            </span>
          </div>
        </Command>
      </DialogContent>
    </Dialog>
  );
}

import * as React from "react";
import { Plus } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  THE ADD ON A TABLE — a tab hanging off the card's bottom-left corner.

  WHY NOT A BAND INSIDE THE CARD. A full-width strip draws a rule across the
  whole card to carry one small act, and what it reads as is an empty extra
  row of the table. (Pavan, 2026-09-22 — after both were built and put side by
  side.)

  WHY FILLED AND NOT OUTLINED. It takes the table's own header tint, so it
  continues the table rather than sitting near it as a separate control. An
  outline would be a second box under a card that already has one, which is
  the nesting `docs/ds/ui/2-rules.md` §10f exists to remove.

  A PLUS, AND THE WORDS ON HOVER. The row it adds is one of many and the sign
  says the act; a permanent label makes an ordinary add look like the
  section's main one. The label still arrives on keyboard focus, so it is not
  a thing only a mouse can find, and the button keeps its `aria-label` either
  way — the collapsed state is a visual economy, never a nameless control.
*/

/* IT CAN OPEN A MENU (Pavan, 2026-10-07). When one add offers a choice of
   row — the quote's Fee or Tax — it is a menu's trigger, so whatever the
   trigger hands it (ref, pointer and key handlers, aria) is passed through.
   Nothing about how it looks changes. */
export function HangingAdd({
  label,
  onClick,
  disabled,
  className,
  ...trigger
}: {
  /** "Add products", "Add vendor" — the table's own noun, always plural-safe. */
  label: string;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  disabled?: boolean;
  className?: string;
} & Omit<React.ComponentPropsWithRef<"button">, "onClick" | "className" | "disabled">) {
  const [open, setOpen] = React.useState(false);

  return (
    <button
      {...trigger}
      type="button"
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={() => setOpen(false)}
      className={cn(
        /* SQUARE ON TOP, ROUNDED BELOW — the top edge is the card's bottom
           edge, and a radius there would show a notch between them. */
        "flex h-8 items-center rounded-t-none rounded-b-md bg-fp-table-header px-2.5",
        "text-sm font-medium text-foreground outline-none transition-colors",
        "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
        "disabled:pointer-events-none disabled:opacity-50",
        className
      )}
    >
      <Plus className="size-4 shrink-0" />
      <span
        className={cn(
          "overflow-hidden whitespace-nowrap transition-[max-width,opacity,padding] duration-200",
          open ? "max-w-[140px] pl-1.5 opacity-100" : "max-w-0 opacity-0"
        )}
      >
        {label}
      </span>
    </button>
  );
}

