/*
  Order side sheet.

  SPACING AND PADDING ARE THE DS'S, taken from side-sheet/SheetNarrow.tsx
  (Figma "Side Sheet" 27610:58293) rather than chosen here:
    • SheetContent      gap-0 p-4-less  (`gap-0 p-0`), width 560 = DS `narrow`
    • header            border-b, p-4, items-start justify-between gap-4
    • body              p-4, flex-col gap-10       ← 40px BETWEEN GROUPS *
    • SheetSection      flex-col gap-5             ← 20px between fields  *
    • SheetField        flex-col gap-1.5           ← 6px label→control
    • two-up rows       grid grid-cols-2 gap-4
    • RadioGroup        gap-3
    • footer            border-t, p-4, items-center justify-end gap-3

  * DELIBERATE OVERRIDE of the DS's gap-7 / gap-3. This sheet carries far more
    fields than the DS reference, and at the DS rhythm the groups stopped
    reading as groups. The ratio is kept at roughly 1:2 so the hierarchy is
    unchanged — only the scale moved. Everything else above is the DS's.

  CREATE, THEN AUTOSAVE — 3PL's order sheet (Pavan, 2026-10-07). Nothing is
  kept until Create Order; from then on every edit is kept 600ms after it
  settles, the header says so, and there is no Cancel or Confirm. The footer
  carries the next stage instead. Product lines live in ProductTable, which
  owns the derived total — the total is never an input, since it must always
  equal the lines above it.
*/

const DRIVERS = ["Shriya", "Shriya Test 2", "Aakash"];


/** Sample option sets — the source app never exposed these lists. */
const TAG_OPTIONS = [
  "Keep Full",
  "Rush",
  "Night",
  "Weekend",
  "Split Load",
  "Hazmat",
  "After Hours",
];
const POC_OPTIONS = ["Site manager", "Dispatch desk", "Night supervisor"];

export interface OrderDraft {
  /** The stage before the driver rule — see `stageAfterDriver`. */
  status: FuelOrderStatus;
  typeCode: OrderTypeCode;
  customer: string;
  shipTo: string;
  products: { name: string; gal: number }[];
  plannedDate: Date | null;
  plannedTime: string;
  driver: string | null;
  tags: string[];
  urgent: boolean;
  site: string;
  poc: string;
  note: string;
  /** Fields added in Sales Settings, by key (2026-10-07). */
  extra: ExtraValues;
  /** The stage a move is waiting on approval for. */
  approvalFor?: string;
}

function draftFrom(order: FuelOrder): OrderDraft {
  const [y, m, d] = order.dateKey.split("-").map(Number);
  const delivery = new Date(y, m - 1, d);
  /* THE PLANNED DAY IS ITS OWN (2026-10-07). It was read off the delivery
     date, so once every edit saves, opening an order a bulk edit had moved
     would have quietly moved it back. */
  const planned = order.planned ? new Date(order.planned.date) : null;
  return {
    status: order.status,
    typeCode: order.type.code,
    customer: order.customer.title,
    shipTo: order.customer.description,
    products: order.products.map((p) => ({ ...p })),
    plannedDate: planned
      ? Number.isNaN(planned.getTime())
        ? delivery
        : startOfDay(planned)
      : null,
    plannedTime: order.planned?.time ?? "",
    driver: order.driver?.name ?? null,
    tags: [...order.tags],
    urgent: order.urgent,
    site: order.customer.description,
    poc: "",
    note: "",
    extra: { ...(order.extra ?? {}) },
    approvalFor: order.approvalFor,
  };
}

/**
 * A blank order. `Create Order` opens the SAME sheet as editing — same sections,
 * same order, same spacing — with nothing filled in, so there is one layout to
 * learn instead of a separate create form that drifts from the edit one.
 *
 * `products: []` is deliberate: the section carries a hanging "Add" tab, so the
 * operator adds the first line rather than being handed a placeholder line to
 * correct. `urgent: false` is the only non-empty value, because a switch has no
 * empty state.
 */
function emptyDraft(): OrderDraft {
  return {
    status: "Requested",
    typeCode: "D",
    customer: "",
    shipTo: "",
    products: [],
    plannedDate: null,
    plannedTime: "",
    driver: null,
    tags: [],
    urgent: false,
    site: "",
    poc: "",
    note: "",
    /* AUTO-ASSIGN OWNER — the signed-in user in a Sales rep field, where the
       form has one (Sales Settings › Preferences, 2026-10-07). */
    extra: ownerOnCreate("fuel") ? { salesRep: ownerOnCreate("fuel") } : {},
  };
}

/** The notification a move into this stage raises. */
const EVENT_OF: Record<string, string> = {
  Dispatched: "dispatched",
  Delivered: "delivered",
  Canceled: "canceled",
};
/** Would that notification show? Then it is the move's toast, not a second one. */
const notifies = (stage: string) =>
  Boolean(getSalesSettings().notifications.find((n) => n.key === EVENT_OF[stage])?.inApp);

export interface OrderSheetProps {
  /** The order being edited. `null` in create mode. */
  order: FuelOrder | null;
  /** `create` opens the sheet blank; `edit` seeds it from `order`. */
  mode?: "edit" | "create";
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSave: (order: FuelOrder, draft: OrderDraft) => void;
  /** Create Order. The caller makes the row and points the sheet at it. */
  onCreate?: (draft: OrderDraft) => void;
  /** Option lists derived from the dataset, so pickers can't drift from rows. */
  customers: string[];
  shipTos: string[];
  productNames: string[];
}

export function OrderSheet({
  order,
  mode = "edit",
  open,
  onOpenChange,
  onSave,
  onCreate,
  customers,
  shipTos,
  productNames,
}: OrderSheetProps) {
  const [draft, setDraft] = React.useState<OrderDraft | null>(null);
  /* The product line just added — its first cell takes the cursor. */
  const [focusProduct, setFocusProduct] = React.useState<number | undefined>();
  const creating = mode === "create";
  /* SALES SETTINGS LAY THE SHEET OUT (Pavan, 2026-10-07 — "fix it all", C):
     which fields, in what order and sections, under what labels, which are
     required. A hidden field keeps its value; it is only not asked. */
  const settings = useSalesSettings();
  const formFields = settings.forms.fuel;
  /* WHAT THE NEXT ACT IS WAITING ON — raised by pressing it (the quote
     sheet's PendingStrip rule: a dead primary says why on press). */
  const [pendingShown, setPendingShown] = React.useState(false);
  const [quoteBlocked, setQuoteBlocked] = React.useState(false);

  /* BUILT ONCE PER RECORD, NOT ONCE PER SAVE — 3PL's `builtFor`. Every
     autosave hands back a new row; rebuilding from it would move the caret
     and lose what was typed since. The create handover (the key going from
     "create" to the new id) keeps the draft in hand, because it IS that
     order. */
  const builtFor = React.useRef<string | null>(null);
  /* WHAT WAS LAST HANDED OVER, so the row coming back does not start the
     next save. */
  const lastSaved = React.useRef<string | null>(null);
  React.useEffect(() => {
    if (!open) {
      builtFor.current = null;
      return;
    }
    const key = creating ? "create" : (order?.id ?? null);
    if (builtFor.current === key) return;
    const handover = builtFor.current === "create" && key !== null;
    builtFor.current = key;
    setPendingShown(false);
    setQuoteBlocked(false);
    if (handover) return;
    const built = creating ? emptyDraft() : order ? draftFrom(order) : null;
    /* Opening a record is not a change to it. */
    lastSaved.current = built ? JSON.stringify(built) : null;
    setDraft(built);
  }, [open, creating, order]);

  /* AUTOSAVE, DEBOUNCED — the unit of a save is a pause in the work, not a
     keystroke, so the change log gets a line per pause rather than per key.
     Nothing is kept before Create Order (3PL, 2026-10-06). */
  React.useEffect(() => {
    if (!open || !draft || creating || !order) return;
    const shape = JSON.stringify(draft);
    if (lastSaved.current === shape) return;
    const t = window.setTimeout(() => {
      lastSaved.current = shape;
      onSave(order, draft);
    }, 600);
    return () => window.clearTimeout(t);
  }, [draft, open, creating, order, onSave]);

  const saveState = useDraftSaveState(draft, open);

  /* CLOSING AN UNCREATED ORDER ASKS FIRST — it is about to be thrown away. */
  const [confirmDiscard, setConfirmDiscard] = React.useState(false);
  const [confirmCancel, setConfirmCancel] = React.useState(false);
  const requestClose = (o: boolean) => {
    if (
      !o &&
      creating &&
      draft &&
      JSON.stringify(draft) !== JSON.stringify(emptyDraft())
    ) {
      setConfirmDiscard(true);
      return;
    }
    onOpenChange(o);
  };

  if (!draft || (!creating && !order)) return null;

  const set = <K extends keyof OrderDraft>(key: K, value: OrderDraft[K]) =>
    setDraft((d) => (d ? { ...d, [key]: value } : d));

  const unusedProduct = productNames.find(
    (o) => !draft.products.some((l) => l.name === o)
  );

  const fromQuote = order?.fromQuote;
  // The stage the driver pick leaves — see `driverStage`.
  const status: FuelOrderStatus = driverStage(
    { status: liveStage(draft.status, settings), fromQuote },
    Boolean(draft.driver),
    settings
  );

  /* THE FOOTER'S PRIMARY IS THE NEXT STAGE, in the order Sales Settings
     keeps (Pavan, 2026-10-07). The stage right before Scheduled moves on by
     picking a driver; Delivered and Canceled are done. */
  const target = creating ? null : nextStage(status, settings);
  const toScheduled = target === "Scheduled";
  const needsDriver = toScheduled && !draft.driver;
  const quoteOk = quoteAllows({ fromQuote }, settings);
  const approval = target ? stageNeedsApproval(target, settings) : false;
  /* A MOVE ASKED FOR — to the next stage, or to Canceled. */
  const awaiting = draft.approvalFor;

  const advance = (next: FuelOrderStatus) => {
    if (!notifies(next)) toast.success(`${order?.orderNo ?? "Order"} → ${stageLabel(next, settings)}`);
    setDraft((d) => (d ? { ...d, status: next, approvalFor: undefined } : d));
  };

  /* A STAGE THAT REQUIRES APPROVAL IS TWO PRESSES (Pavan, 2026-10-07): the
     move is asked for, the order says so, and the same button then approves
     it and moves it. No approver, roles or queue exist in the prototype —
     the second press stands for the approver's. */
  const requestApproval = (next: string) => {
    set("approvalFor", next);
    const said = `${order?.orderNo ?? "Order"} · approval requested to move to ${stageLabel(next, settings)}`;
    /* The Approval requested notification when its row is routed in-app;
       otherwise the plain confirmation. */
    if (settings.notifications.find((n) => n.key === "approval")?.inApp) notify("approval", said);
    else toast.success(said);
  };

  /* CANCEL ORDER — 3PL's: behind the ··· and a confirm (Pavan, 2026-10-07).
     Not on an order already Delivered or Canceled. It goes through the same
     autosave as "Move to …", so the change log records it. */
  const cancellable = !creating && status !== "Delivered" && status !== "Canceled";
  const cancelOrder = () => {
    /* CANCELLED CAN ASK FOR APPROVAL TOO (Sales Settings › Workflow). */
    if (stageNeedsApproval("Canceled", settings)) {
      requestApproval("Canceled");
      return;
    }
    if (!notifies("Canceled")) toast.success(`${order?.orderNo ?? "Order"} canceled`);
    setDraft((d) => (d ? { ...d, status: "Canceled", approvalFor: undefined } : d));
  };

  /* ---- what each field is filled by ---------------------------------- */

  const filled = (f: FormField): boolean => {
    if (!isNative(f, renderers)) return extraFilled(draft.extra[f.key]);
    switch (f.key) {
      case "customer":
        return Boolean(draft.customer);
      case "shipTo":
        return Boolean(draft.shipTo);
      case "driver":
        return Boolean(draft.driver);
      case "planDate":
        return Boolean(draft.plannedDate);
      case "planTime":
        return Boolean(draft.plannedTime.trim());
      case "product":
        return draft.products.length > 0 && draft.products.every((l) => l.name);
      case "quantity":
        return draft.products.length > 0 && draft.products.every((l) => l.gal > 0);
      case "tags":
        return draft.tags.length > 0;
      case "site":
        return Boolean(draft.site);
      case "poc":
        return Boolean(draft.poc);
      case "note":
        return Boolean(draft.note.trim());
      default:
        return true;
    }
  };

  const label = (key: string, fallback: string) =>
    formFields.find((f) => f.key === key)?.label.trim() || fallback;
  const unit = UNIT_SHORT[settings.unit];

  /* ---- the sheet's own fields, as Sales Settings place them ---------- */

  const renderers: Record<string, (f: FormField) => BuiltInField> = {
    orderType: () => ({
      /* 12px from the label to the options; the two sit 24px apart. */
      className: "gap-3",
      control: (
        <RadioGroup
          value={draft.typeCode}
          onValueChange={(v) => set("typeCode", v as OrderTypeCode)}
          className="flex gap-6"
        >
          {(
            [
              ["D", "Delivery"],
              ["E", "Extraction"],
            ] as const
          ).map(([code, text]) => (
            <div key={code} className="flex items-center gap-2">
              <RadioGroupItem value={code} id={`type-${code}`} />
              <Label htmlFor={`type-${code}`} className="font-normal">
                {text}
              </Label>
            </div>
          ))}
        </RadioGroup>
      ),
    }),
    customer: () => ({
      half: true,
      control: (
        <Combobox
          className="w-full"
          value={draft.customer}
          onValueChange={(v) => set("customer", v)}
          options={customers}
          placeholder="Select customer"
          searchPlaceholder="Search customers…"
          emptyText="No customer found."
        />
      ),
    }),
    shipTo: () => ({
      half: true,
      control: (
        <Combobox
          className="w-full"
          value={draft.shipTo}
          onValueChange={(v) => set("shipTo", v)}
          options={shipTos}
          placeholder="Select ship-to"
        />
      ),
    }),
    driver: (f) => ({
      control: (
        <Combobox
          className="w-full"
          value={draft.driver ?? (f.required ? "" : "none")}
          placeholder="Select driver"
          onValueChange={(v) => {
            const driver = v === "none" ? null : v;
            /* THE PICK THAT WOULD SCHEDULE, AND MAY NOT, SAYS WHY (Pavan,
               2026-10-07): the driver is kept, the order stays where it is,
               and the strip names the accepted quote it is waiting on. */
            if (driver && status === stageBeforeScheduled(settings) && !quoteOk) {
              setQuoteBlocked(true);
              setPendingShown(true);
            }
            set("driver", driver);
          }}
          /* "Unassigned" is a real choice, not the absence of one. A
             REQUIRED FIELD GETS NO EMPTY CHOICE (ux §Forms). */
          options={[
            ...(f.required ? [] : [{ value: "none", label: "— Unassigned" }]),
            ...DRIVERS,
          ]}
          searchPlaceholder="Search drivers…"
          emptyText="No driver found."
        />
      ),
    }),
    planDate: () => ({
      half: true,
      control: (
        <DatePopover>
          <PopoverTrigger asChild>
            <Button variant="outline" className="w-full justify-start font-normal">
              <CalendarDays />
              {draft.plannedDate ? formatFullDate(draft.plannedDate) : "Not planned"}
            </Button>
          </PopoverTrigger>
          <PopoverContent align="start" className="w-auto p-0">
            <DatePanel
              selected={draft.plannedDate ?? undefined}
              onSelect={(d) => d && set("plannedDate", d)}
            />
          </PopoverContent>
        </DatePopover>
      ),
    }),
    planTime: () => ({
      half: true,
      control: (
        <div className="relative">
          <Input
            value={draft.plannedTime}
            placeholder="e.g. 1:35 AM"
            onChange={(e) => set("plannedTime", e.target.value)}
            className="pr-9"
          />
          <Clock className="pointer-events-none absolute top-1/2 right-3 size-4 -translate-y-1/2 text-muted-foreground" />
        </div>
      ),
    }),
    urgent: () => ({
      bare: (text) => (
        <div className="flex items-center justify-between">
          <span className="text-sm font-medium">{text}</span>
          <Switch
            checked={draft.urgent}
            onCheckedChange={(v) => set("urgent", v)}
            aria-label={text}
          />
        </div>
      ),
    }),
    product: () => productTable,
    quantity: () => productTable,
    tags: () => ({
      control: (
        <TokenMultiSelect
          options={TAG_OPTIONS}
          value={draft.tags}
          onChange={(next) => set("tags", next)}
          addLabel="Add tags"
          searchPlaceholder="Search tags..."
        />
      ),
    }),
    site: () => ({
      control: (
        <Combobox
          className="w-full"
          value={draft.site}
          onValueChange={(v) => set("site", v)}
          options={shipTos}
          placeholder="Select site"
        />
      ),
    }),
    poc: (f) => ({
      control: (
        <Combobox
          className="w-full"
          value={draft.poc || (f.required ? "" : "none")}
          onValueChange={(v) => set("poc", v === "none" ? "" : v)}
          options={[...(f.required ? [] : [{ value: "none", label: "Not set" }]), ...POC_OPTIONS]}
          placeholder="Select PoC"
          searchPlaceholder="Search contacts…"
          emptyText="No contact found."
        />
      ),
    }),
    note: () => ({
      control: (
        <Textarea
          value={draft.note}
          placeholder="Gate codes, access notes, anything the driver needs…"
          onChange={(e) => set("note", e.target.value)}
          className="min-h-24"
        />
      ),
    }),
  };

  /* THE PRODUCT TABLE IS TWO ROWS OF THE FORM — its two columns — and is
     drawn where the first of them sits. The add hangs off the card (ui
     §10f); with nothing left to add it is not rendered. */
  const productTable: BuiltInField = {
    table: {
      hanging:
        unusedProduct !== undefined ? (
          <HangingAdd
            label="Add product"
            onClick={() => {
              setFocusProduct(draft.products.length);
              set("products", [...draft.products, { name: unusedProduct, gal: 0 }]);
            }}
          />
        ) : undefined,
      node: (
        <ProductTable
          lines={draft.products}
          options={productNames}
          focusRow={focusProduct}
          onChange={(next) => set("products", next)}
          productLabel={label("product", "Product")}
          qtyLabel={`${label("quantity", "Quantity")} (${unit.charAt(0).toUpperCase()}${unit.slice(1)})`}
        />
      ),
    },
  };

  /* ---- the next act ---------------------------------------------------- */

  const pending: PendingItem[] = creating
    ? missingRequired("fuel", formFields, filled)
    : quoteBlocked && toScheduled && !quoteOk
      ? [
          {
            key: "quote",
            label: `${stageLabel("Scheduled", settings)} needs an accepted quote`,
            target: sectionId("fuel", formFields.find((f) => f.key === "driver")?.section ?? ""),
          },
        ]
      : [];

  const commit = () => {
    if (pending.length > 0) {
      setPendingShown(true);
      return;
    }
    onCreate?.(draft);
    toast.success("Order created");
  };

  let footerPrimary: React.ReactNode = null;
  if (creating) footerPrimary = <Button onClick={commit}>Create Order</Button>;
  else if (awaiting && awaiting !== status) {
    /* THE SECOND PRESS — it stands for the approver's. */
    footerPrimary = (
      <Button onClick={() => advance(awaiting)}>
        Approve &amp; move to {stageLabel(awaiting, settings)}
      </Button>
    );
  } else if (target && !needsDriver) {
    const name = stageLabel(target, settings);
    footerPrimary =
      toScheduled && !quoteOk ? (
        /* PRESSABLE, AND PRESSING SAYS WHY — the quote rule. */
        <Button
          onClick={() => {
            setQuoteBlocked(true);
            setPendingShown(true);
          }}
        >
          Move to {name}
        </Button>
      ) : approval ? (
        <Button onClick={() => requestApproval(target)}>Request approval</Button>
      ) : (
        <Button onClick={() => advance(target)}>Move to {name}</Button>
      );
  }

  return (
    <>
      <RecordSheet
        /* WIDTH FROM ITS TABLES (Pavan, 2026-10-15 — like the Delivery
           Order): products = product · qty · bin; the rail once it exists. */
        fit={{ tables: [[CELL.name, CELL.number, CELL.bin]], rail: !creating }}
        open={open}
        onOpenChange={requestClose}
        mode={creating ? "create" : "edit"}
        editTitle={`Order #: ${order?.orderNo ?? ""}`}
        createTitle="Create Order"
        createAction="Create Order"
        /* AUTOSAVED, so Cancel is a promise the sheet cannot keep. */
        showCancel={false}
        headerAside={
          <span className="flex items-center gap-2">
            <DraftStatusChip
              tone={stageTone(status, settings)}
              color={stageColor(status, settings)}
              label={stageLabel(status, settings)}
              /* Nothing is kept before Create Order, so nothing to report. */
              saveState={creating ? "idle" : saveState}
            />
            {awaiting && (
              <StatusChip tone={kindTone("caution")} variant="soft">
                Needs approval
              </StatusChip>
            )}
          </span>
        }
        headerMenu={
          cancellable ? (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="icon-sm" aria-label="More order actions">
                  <MoreHorizontal />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-52">
                <DropdownMenuItem
                  onSelect={(e) => {
                    e.preventDefault();
                    setConfirmCancel(true);
                  }}
                >
                  <Ban />
                  Cancel order
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          ) : undefined
        }
        footerBanner={
          pendingShown && (creating || pending.length > 0) ? (
            <PendingStrip
              tone="caution"
              pending={pending}
              clearLabel="Everything this order needs is filled in"
            />
          ) : undefined
        }
        onSubmit={() => {}}
        footerPrimary={footerPrimary}
      >
        <div className={cn("grid items-start gap-6", !creating && "lg:grid-cols-[minmax(0,1fr)_340px]")}>
          <div className="flex min-w-0 flex-col gap-10">
            <ConfiguredForm
              kind="fuel"
              renderers={renderers}
              together={[["product", "quantity"]]}
              extra={draft.extra}
              onExtraChange={(key, value) => set("extra", { ...draft.extra, [key]: value })}
            />
          </div>

          {/* WHAT THE ORDER HAS BECOME — read-only, sticky; no rail while
              creating (G29 · G30 · G31 · G32, Pavan, 2026-10-07). */}
          {!creating && order && (
            <aside className="flex min-w-0 flex-col gap-6 lg:sticky lg:top-0">
              <SummaryCard title="Order summary">
                <dl className="flex flex-col">
                  {draft.products.length === 0 ? (
                    <RailRow variant="line" label={label("product", "Product")} value="—" />
                  ) : (
                    draft.products.map((l, i) => (
                      <RailRow
                        key={`${l.name}-${i}`}
                        variant="line"
                        label={l.name || "—"}
                        value={`${l.gal.toLocaleString("en-US")} ${unit}`}
                      />
                    ))
                  )}
                </dl>
                <div aria-hidden className="border-t border-dashed border-border" />
                <dl className="flex flex-col">
                  {fromQuote && <RailRow variant="line" label="Quote" value={fromQuote} />}
                  <RailRow
                    variant="total"
                    label={`Total ${label("quantity", "Quantity").toLowerCase()}`}
                    value={`${draft.products.reduce((n, l) => n + l.gal, 0).toLocaleString("en-US")} ${unit}`}
                  />
                </dl>
              </SummaryCard>
              <ActivityCard entries={order.audit} timeZone={settings.timeZone} />
            </aside>
          )}
        </div>
      </RecordSheet>

      <AlertDialog open={confirmCancel} onOpenChange={setConfirmCancel}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel {order?.orderNo}?</AlertDialogTitle>
            <AlertDialogDescription>
              It moves to Canceled, keeping its history.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction variant="destructive" onClick={cancelOrder}>
              Cancel order
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={confirmDiscard} onOpenChange={setConfirmDiscard}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Discard this order?</AlertDialogTitle>
            <AlertDialogDescription>
              All the details you've added will be discarded.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep editing</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={() => onOpenChange(false)}
            >
              Discard
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight, CircleCheck, Info } from "lucide-react";

/**
 * THE PENDING STRIP — what a sheet's next act is still waiting on.
 *
 * SHARED, BECAUSE THE SECOND SHEET TO NEED IT IS THE PROMOTION SIGNAL. It was
 * written twice — once for the 3PL order and once for the service order — and
 * two copies of something this fiddly would have drifted in whichever half
 * gets opened less.
 *
 * It goes in `RecordSheet`'s `footerBanner`: the reason a primary is dead
 * belongs beside it, and beside it there is room for a clause, not for a list.
 * Each caller supplies its own items and its own section ids.
 */

export interface PendingItem {
  key: string;
  /** The INSTRUCTION — "Choose a customer", not "Customer". */
  label: string;
  /** The `id` of the section this item is about. Omitted = not pressable. */
  target?: string;
}

/**
 * SEND THE READER TO THE SECTION, and say which one it was.
 *
 * A strip that names a missing field and cannot take you to it is a label for
 * a hunt. The press scrolls the section into view and then blinks its outline
 * — because after a scroll the eye is on the MOVEMENT, not on the thing that
 * moved, and "it is this one" is a different statement from "here is some of
 * the form".
 *
 * ONCE, AND IT LEAVES NO TRACE (Pavan, 2026-09-22 — it was twice). Two flashes
 * is a thing asking to be watched; one is a thing pointing at itself and then
 * getting out of the way, and the reader is already looking because the scroll
 * took them there. Three times reads as an error, and a ring that stays is a
 * state — nothing about the record changed, so nothing about it should still
 * look different in a second.
 */
export function attend(id: string) {
  const el = document.getElementById(id);
  if (!el) return;

  /* SCROLL THE CONTAINER, NOT THE ELEMENT. `scrollIntoView` picks its own
     ancestor and hands the animation to the browser. Finding the scrollport
     and setting its offset is deterministic. */
  let port: HTMLElement | null = el.parentElement;
  while (port && port.scrollHeight <= port.clientHeight + 4) {
    port = port.parentElement;
  }
  if (!port) return;
  /* 12px of air above the section, so it does not sit flush against the header
     and read as clipped. */
  const top =
    port.scrollTop +
    el.getBoundingClientRect().top -
    port.getBoundingClientRect().top -
    12;

  /* ANIMATED BY HAND, because `behavior: "smooth"` does not survive in here.
     MEASURED in the running sheet: an instant scroll to 400 lands at 400; the
     same call with `smooth` lands at 0 — the sheet's scroll lock cancels the
     browser's animation the frame after it starts. The rAF loop is not
     decoration: without it the section either does not move or teleports, and
     the travel is what tells the reader this is the same sheet they were
     already in rather than a new screen. */
  const from = port.scrollTop;
  const distance = top - from;
  const started = performance.now();
  const DURATION = 320;
  const scroller = port;
  const step = (now: number) => {
    const t = Math.min((now - started) / DURATION, 1);
    /* ease-out cubic — fast away, slow into place, which is what makes an
       arrival read as an arrival. */
    scroller.scrollTop = from + distance * (1 - Math.pow(1 - t, 3));
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);

  /* NO FOCUS MOVE. Focusing the section, or a control inside it, was tried and
     dropped: inside a focus-trapped sheet the trap restores the scroll position
     of whatever it considers focused, which fights the travel. The blink is
     what says "this one", and focus stays on the strip — which is where the
     reader presses next if more than one item is outstanding.
     KEYBOARD GAP, KNOWN: a reader who presses this with the keyboard is shown
     the section but still has to Tab to it. */

  /* THE BLINK WAITS FOR THE SCROLL. Flashing a section that is still
     travelling spends the whole animation off screen. */
  window.setTimeout(() => blink(id), 320);
}

/** How long `blink` takes, start to finish — for anything sequencing after it. */
export const BLINK_MS = 800;

/**
 * THE FLASH ON ITS OWN, WITHOUT THE TRAVEL.
 *
 * FOR A SECOND, NARROWER "THIS ONE". After a section has been brought into
 * view and named, the thing actually worth reading inside it can be named
 * too — the Pricing unit, then the vendor's own column. Two statements, not
 * one longer one: "here" and then "this part of here". They must not overlap,
 * or the second reads as the first still going.
 */
export function blink(id: string) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.remove("fp-attention");
  /* Re-adding in the same frame does not restart a CSS animation; the reflow
     between the two is what does. */
  void el.offsetWidth;
  el.classList.add("fp-attention");
  window.setTimeout(() => el.classList.remove("fp-attention"), BLINK_MS);
}

/**
 * THE SAME FLASH, ACROSS SOMETHING THAT IS NOT ONE BOX.
 *
 * A column of a grid is a stack of separate cells: an outline round each of
 * them is a ladder, not a column. Every cell that belongs to the thing carries
 * `data-blink="<name>"`, and they flash a FILL together — which reads as the
 * one unit it is. (Pavan, 2026-09-22 — "blink should happen through this whole
 * unit".)
 */
export function blinkGroup(name: string) {
  const els = document.querySelectorAll<HTMLElement>(`[data-blink="${name}"]`);
  els.forEach((el) => {
    el.classList.remove("fp-attention-fill");
    /* Re-adding in the same frame does not restart a CSS animation; the reflow
       between the two is what does. */
    void el.offsetWidth;
    el.classList.add("fp-attention-fill");
    window.setTimeout(() => el.classList.remove("fp-attention-fill"), BLINK_MS);
  });
}

/**
 * One outstanding item at a time, with a counter and a way to step through
 * them, so three missing fields cost one line rather than three.
 *
 * THE WORD "PENDING" DOES NOT MOVE. It is the strip's subject and it is true
 * of every item under it; stepping swaps only the item. A label that changed
 * with the content would make the reader re-read what KIND of line this is on
 * every press.
 *
 * WHEN NOTHING IS OUTSTANDING IT SAYS SO, in the success channel, rather than
 * disappearing: an empty strip and a satisfied one are different states.
 */
export function PendingStrip({
  pending,
  /** What the strip says when the list is empty. */
  clearLabel = "Everything this record needs is filled in",
  tone = "neutral",
}: {
  pending: PendingItem[];
  clearLabel?: string;
  /**
   * `caution` once the strip is raised by pressing the primary with
   * something missing (2026-10-05) — it is the answer to a press and has to
   * be noticed. `neutral` (grey) where it simply stands on the sheet.
   */
  tone?: "neutral" | "caution";
}) {
  const [at, setAt] = React.useState(0);
  /* The list shortens as items are cleared, so the cursor has to be pulled
     back with it rather than pointing past the end. */
  const i = Math.min(at, Math.max(pending.length - 1, 0));
  React.useEffect(() => {
    if (at > pending.length - 1) setAt(Math.max(pending.length - 1, 0));
  }, [at, pending.length]);

  if (pending.length === 0) {
    return (
      <div className="flex items-center gap-2 text-sm text-fp-banner-accent-success">
        <CircleCheck className="size-4 shrink-0" />
        {clearLabel}
      </div>
    );
  }

  const step = pending[i];
  const chevron =
    "rounded-sm p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-30";

  return (
    /* IN THE STEP COLUMN (a narrow `@container`) the strip is two rows
       (Pavan, 2026-10-05): "Pending" on the left with the stepper on the
       right, and the item itself underneath, wrapping rather than truncating.
       No icon there. The first span dissolves (`contents`) so its pieces can
       be laid out against the counter. In the full-width footer band nothing
       changes. GREY, not caution orange (Pavan, 2026-10-05): what is left to
       do is information, not an alarm. */
    <div className="flex items-center justify-between gap-3 @max-[20rem]:flex-wrap @max-[20rem]:gap-y-1">
      <span
        className={cn(
          "flex min-w-0 items-center gap-2 text-sm @max-[20rem]:contents",
          tone === "caution" ? "text-fp-banner-accent-caution" : "text-muted-foreground"
        )}
      >
        <Info className="size-4 shrink-0 @max-[20rem]:hidden" />
        <span className="shrink-0 font-medium @max-[20rem]:order-1">Pending</span>
        {step.target ? (
          <button
            type="button"
            onClick={() => attend(step.target!)}
            className="min-w-0 truncate rounded-sm text-left @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal underline decoration-current/40 underline-offset-4 outline-none transition-[text-decoration-color] hover:decoration-current focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            {step.label}
          </button>
        ) : (
          <span className="truncate @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal">{step.label}</span>
        )}
      </span>
      <span className="flex shrink-0 items-center gap-0.5 text-xs tabular-nums text-muted-foreground @max-[20rem]:order-2">
        <button
          type="button"
          aria-label="Previous pending item"
          disabled={i === 0}
          onClick={() => setAt(i - 1)}
          className={chevron}
        >
          <ChevronLeft className="size-3.5" />
        </button>
        {i + 1} of {pending.length}
        <button
          type="button"
          aria-label="Next pending item"
          disabled={i >= pending.length - 1}
          onClick={() => setAt(i + 1)}
          className={chevron}
        >
          <ChevronRight className="size-3.5" />
        </button>
      </span>
    </div>
  );
}

import type * as React from "react";
import {
  TableCellInput,
  TableCellSelect,
  TableRequiredLabel,
} from "@/components/form-layout/table-cells";
import { TableRowRemove } from "@/components/form-layout/table-cells";

/**
 * Product lines as an editable table.
 *
 * This is the DS's `form-layout/EditableTable` — "Input / Dropdown Tables
 * Layout" + "Add more and hover and delete" (Figma 27593:15012 / 27592:33634),
 * with the delete confirm from 28133:1526. Shell, cell behaviour, add chip and
 * delete interaction are copied class-for-class:
 *
 *   • shell        rounded-md with a SQUARED bottom-left, so the add chip reads
 *                  as an extension of the table rather than a loose button
 *   • header       bg-fp-surface-1a, px-3 py-2.5, required columns marked *
 *   • cells        p-0 td; the control fills the whole cell so hover paints edge
 *                  to edge (`hover:bg-accent` — the cell sits on Surface-1b, so
 *                  accent is what stays visible), focus ring inset
 *   • delete       hidden until row hover, then a trash icon; clicking swaps the
 *                  same cell for a vertical split — ✕ cancel over ✓ confirm on
 *                  destructive. Deleting a row is never one careless click.
 *   • add row      ghost chip pinned to the table's bottom-left, 1px below the
 *                  stroke, icon-only until hover/focus when the label slides out
 *
 * DS FOLLOW-UP: `EditableTable` is not exported from `form-layout/index.ts` and
 * takes no props — its columns, options and rows are hardcoded — so it cannot be
 * pointed at another dataset. Parameterise it (columns + rows + change handlers)
 * and delete this file.
 *
 * TWO DELIBERATE DEVIATIONS, both noted so they are not mistaken for drift:
 *   1. Cells are ONE line. The DS reference renders a title over a description
 *      ("Table Cell Text / Description Text"); a product has only a name, and a
 *      second line would be filler. Row height therefore tracks a single line,
 *      and the delete confirm sizes to the row rather than the DS's fixed 52px.
 *   2. The last remaining row cannot be deleted. An order with no product lines
 *      has no meaning; the DS table has no such constraint because its rows are
 *      optional.
 */

export interface ProductLine {
  name: string;
  gal: number;
}

/*
  THE CELLS ARE THE DS'S `TableCell*` SINCE 2026-09-23. This table had its own
  `CellSelect` (a menu with no search) and `CellNumber`, so the one sales table
  looked and behaved unlike every 3PL and service table beside it — and the
  boxed-table check could not see it, because it looked for the DS names.
*/

/**
 * A COLUMN AFTER THE GALLONS (Pavan, 2026-10-07) — for a quote, which prices
 * each line. The cell is the caller's; the table keeps the shell, the add, the
 * delete and the total row. An order passes none and is unchanged.
 */
export interface ProductTableColumn<L extends ProductLine> {
  key: string;
  label: string;
  /** A colgroup width class, e.g. `w-[18%]`. */
  width: string;
  cell: (line: L, i: number) => React.ReactNode;
  /** The column's figure in the Total row. */
  total?: React.ReactNode;
  required?: boolean;
}

export interface ProductTableProps<L extends ProductLine = ProductLine> {
  lines: L[];
  options: string[];
  onChange: (next: L[]) => void;
  /** The row just added — its first cell takes the cursor (DS ui §10f). */
  focusRow?: number;
  /** Priced columns after the gallons — see `ProductTableColumn`. */
  columns?: ProductTableColumn<L>[];
  /* THE TWO HEADINGS, AS SALES SETTINGS NAME THEM (Pavan, 2026-10-07) — the
     form's Product and Quantity rows, and the Preferences unit after the
     quantity. */
  productLabel?: string;
  qtyLabel?: string;
}

export function ProductTable<L extends ProductLine = ProductLine>({
  lines,
  options,
  onChange,
  focusRow,
  columns = [],
  productLabel = "Product",
  qtyLabel = "Quantity (Gal)",
}: ProductTableProps<L>) {
  const update = (i: number, patch: Partial<ProductLine>) =>
    onChange(lines.map((l, idx) => (idx === i ? { ...l, ...patch } : l)));

  const removeRow = (i: number) =>
    onChange(lines.filter((_, idx) => idx !== i));

  const total = lines.reduce((n, l) => n + l.gal, 0);

  return (
    <div>
      {/* NO BORDER AND NO RADIUS OF ITS OWN — the card supplies both. The
          section is `flush`, so the table's edges are the card's edges
          (DS ui §10f). */}
      <div className="overflow-hidden">
        <table className="w-full table-fixed border-collapse">
          {/* Delete column pinned; the two data columns scale to the rest. */}
          <colgroup>
            {columns.length === 0 ? (
              <>
                <col className="w-[58%]" />
                <col className="w-[42%]" />
              </>
            ) : (
              <>
                <col className="w-[30%]" />
                <col className="w-[16%]" />
                {columns.map((c) => (
                  <col key={c.key} className={c.width} />
                ))}
              </>
            )}
            <col className="w-[52px]" />
          </colgroup>
          <thead>
            <tr className="border-b border-border bg-fp-table-header">
              <th className="px-3 py-2.5 text-left">
                <TableRequiredLabel required>{productLabel}</TableRequiredLabel>
              </th>
              <th className="px-3 py-2.5">
                <TableRequiredLabel required>{qtyLabel}</TableRequiredLabel>
              </th>
              {columns.map((c) => (
                <th key={c.key} className="px-3 py-2.5">
                  <TableRequiredLabel required={c.required}>{c.label}</TableRequiredLabel>
                </th>
              ))}
              <th aria-hidden />
            </tr>
          </thead>
          <tbody>
            {lines.map((line, i) => (
              <tr
                key={i}
                className="group/row h-11 border-b border-border last:border-b-0"
              >
                <td className="relative p-0">
                  <TableCellSelect
                    value={line.name}
                    options={options}
                    placeholder="Select product"
                    autoFocus={i === focusRow}
                    aria-label={`Product for row ${i + 1}`}
                    onChange={(v) => update(i, { name: v })}
                    /* SEVERAL AT ONCE MAKES ROWS (DS ui §10f) — from a blank
                       row; each new row starts as this one, named. */
                    multiple={
                      line.name
                        ? undefined
                        : {
                            taken: lines.map((l) => l.name).filter(Boolean),
                            onApply: (names) => {
                              const next = [...lines];
                              next.splice(i, 1, ...names.map((name) => ({ ...line, name })));
                              onChange(next);
                            },
                          }
                    }
                  />
                </td>
                <td className="relative p-0">
                  <TableCellInput
                    value={String(line.gal)}
                    numeric
                    placeholder="Enter gallons"
                    aria-label={`Gallons of ${line.name || `row ${i + 1}`}`}
                    onChange={(v) => update(i, { gal: Number(v.replace(/[^0-9]/g, "")) || 0 })}
                  />
                </td>
                {columns.map((c) => (
                  <td key={c.key} className="relative p-0">
                    {c.cell(line, i)}
                  </td>
                ))}
                {/* THE CONFIRM IS THE DS's NOW — `TableRowRemove`, the same ✕ / ✓
                    every table asks with. An order needs a product line, so
                    the last row keeps no bin. */}
                <td className="relative p-0 text-center">
                  <TableRowRemove
                    aria-label={`Remove ${line.name || `product ${i + 1}`}`}
                    disabled={lines.length === 1}
                    onRemove={() => removeRow(i)}
                  />
                </td>
              </tr>
            ))}
          </tbody>
          {/* Summary row — inside the table so it reads as part of the ledger and
              stays aligned to the Quantity column. Derived from the rows above,
              so it can never disagree with them. */}
          <tfoot>
            <tr className="h-11 border-t border-border">
              <td className="px-3 text-sm text-muted-foreground">
                Total
              </td>
              <td className="px-3 text-sm font-medium tabular-nums text-foreground">
                {total.toLocaleString()}
              </td>
              {columns.map((c) => (
                <td
                  key={c.key}
                  className="px-3 text-sm font-medium tabular-nums text-foreground"
                >
                  {c.total}
                </td>
              ))}
              <td aria-hidden />
            </tr>
          </tfoot>
        </table>
      </div>

    </div>
  );
}

import * as React from "react";
import { UserRound } from "lucide-react";
