/*
  THE QUOTE SHEET (Pavan, 2026-10-07). The record exists from the moment
  Create Quote is pressed, as a Draft, and every pause in the typing is kept —
  so there is no Save and no Cancel. The footer is the next act:

    Draft     Save as Draft (outline, closes) · Send quote
    Sent      Mark as accepted — which makes the fuel order
    Expired   nothing; moving the valid-through date on makes it Sent again
    Accepted  nothing; the order it made is in the summary

  TWO COLUMNS: what you fill in on the left, what that makes on the right
  (ux §Side-sheet anatomy).

  No helper text, hints or sub-labels anywhere (Pavan, 2026-10-07 — decision
  5): labels, values and controls only.
*/

/** The part of a quote the form edits. Stage, number and order are not typed. */
type QuoteDraft = Pick<
  Quote,
  | "customer"
  | "shipTo"
  | "email"
  | "validThrough"
  | "market"
  | "lines"
  | "margin"
  | "fees"
  | "taxes"
  | "notes"
  | "extra"
>;

const draftOf = (q: Quote): QuoteDraft => ({
  customer: q.customer,
  shipTo: q.shipTo,
  email: q.email,
  validThrough: q.validThrough,
  market: q.market,
  lines: q.lines,
  margin: q.margin,
  fees: q.fees,
  taxes: q.taxes,
  notes: q.notes,
  /* Fields added in Sales Settings, by key (2026-10-07). */
  extra: q.extra ?? {},
});

const ACTIVE_CUSTOMERS = CUSTOMERS.filter((c) => c.status === "Active");
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** One row of the Pricing breakdown. */
interface PricingRow {
  key: string;
  /** What the row is called — and, for an added fee or tax, what it is named. */
  label: string;
  value: Adjust;
  onChange: (next: Adjust) => void;
  /** An added fee or tax: its name is typed in its cell. */
  onRename?: (name: string) => void;
  /** An added fee or tax: it can go. */
  onRemove?: () => void;
  /** "fee 2" — the subject of a blank row's remove. */
  blankName?: string;
  autoFocus?: boolean;
}

/**
 * THE PRICING BREAKDOWN IS A TABLE (Pavan, 2026-10-07): one row per charge,
 * every value cell editable, and the unit ($/gal · $ · %) chosen INSIDE that
 * cell rather than as a toggle beside a field. A set of like inputs in a form
 * defaults to the editable table (DS ui §10f).
 *
 * FEES AND TAXES CAN BE ADDED (Pavan, 2026-10-07). Margin is one row; the
 * first Fees and the first Tax are the defaults; every row added after them
 * has its name typed in its Charge cell and a remove that asks ✕ / ✓.
 */
function PricingTable({ rows, disabled }: { rows: PricingRow[]; disabled?: boolean }) {
  return (
    <table className="w-full table-fixed border-collapse">
      <colgroup>
        <col className="w-[40%]" />
        <col />
        <col className="w-[52px]" />
      </colgroup>
      <thead>
        <tr className="border-b border-border bg-fp-table-header">
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel>Charge</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5">
            <TableRequiredLabel>Value</TableRequiredLabel>
          </th>
          {/* UNNAMED, like every row remove — DS ui §10f. */}
          <th aria-hidden />
        </tr>
      </thead>
      <tbody>
        {rows.map((r) => {
          const unit = ADJUST_UNITS.find((u) => u.value === r.value.unit)!;
          const name = r.label || r.blankName || "";
          return (
            <tr key={r.key} className="group/row h-11 border-b border-border last:border-b-0">
              {r.onRename ? (
                <td className="relative p-0">
                  <TableCellInput
                    value={r.label}
                    placeholder="Enter name"
                    disabled={disabled}
                    autoFocus={r.autoFocus}
                    aria-label={`Name of ${name}`}
                    onChange={r.onRename}
                  />
                </td>
              ) : (
                <td className="px-3 text-sm text-foreground">{r.label}</td>
              )}
              <td className="relative p-0">
                <div className="flex h-11 items-stretch">
                  <div className="relative min-w-0 flex-1">
                    <TableCellInput
                      numeric
                      disabled={disabled}
                      aria-label={name}
                      value={String(r.value.value)}
                      onChange={(v) => {
                        const n = Number(v);
                        r.onChange({ ...r.value, value: Number.isFinite(n) ? n : 0 });
                      }}
                    />
                  </div>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild disabled={disabled}>
                      <button
                        type="button"
                        aria-label={`${name} unit`}
                        className="flex w-[72px] shrink-0 items-center gap-1 px-3 text-sm text-muted-foreground outline-none transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50"
                      >
                        {unit.label}
                        <ChevronDown className="size-4 shrink-0" />
                      </button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="min-w-24">
                      <DropdownMenuRadioGroup
                        value={r.value.unit}
                        onValueChange={(u) => r.onChange({ ...r.value, unit: u as AdjustUnit })}
                      >
                        {ADJUST_UNITS.map((u) => (
                          <DropdownMenuRadioItem key={u.value} value={u.value}>
                            {u.label}
                          </DropdownMenuRadioItem>
                        ))}
                      </DropdownMenuRadioGroup>
                    </DropdownMenuContent>
                  </DropdownMenu>
                </div>
              </td>
              <td className="relative p-0 text-center">
                {r.onRemove && (
                  <TableRowRemove
                    aria-label={`Remove ${name}`}
                    disabled={disabled}
                    onRemove={r.onRemove}
                  />
                )}
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

export interface QuoteSheetProps {
  quote: Quote | null;
  open: boolean;
  /** Opened by Create Quote — the title says so, and closing it untouched drops it. */
  creating: boolean;
  onOpenChange: (open: boolean) => void;
  /** The fuel order an accepted quote made. */
  onOpenOrder: (orderId: string) => void;
}

export function QuoteSheet({ quote, open, creating, onOpenChange, onOpenOrder }: QuoteSheetProps) {
  /* THE DRAFT CARRIES THE ID IT WAS BUILT FOR, so the sheet reopened on
     another quote never shows — or counts as an edit — the last one's. */
  const [held, setHeld] = React.useState<{ id: string; d: QuoteDraft } | null>(null);
  const draft = held && quote && held.id === quote.id ? held.d : null;
  const setDraft = (fn: (d: QuoteDraft | null) => QuoteDraft | null) =>
    setHeld((h) => {
      const d = h ? fn(h.d) : null;
      return h && d ? { id: h.id, d } : h;
    });
  const [focusProduct, setFocusProduct] = React.useState<number | undefined>();
  /** The fee or tax just added — its name cell takes the cursor. */
  const [focusCharge, setFocusCharge] = React.useState<string | undefined>();
  /** The kind picked in the Add charge menu, added once the menu has closed. */
  const pickedCharge = React.useRef<ChargeKind | null>(null);
  const [pendingShown, setPendingShown] = React.useState(false);
  const [emailOpen, setEmailOpen] = React.useState(false);
  /* SALES SETTINGS LAY THE LEFT COLUMN OUT (Pavan, 2026-10-07 — "fix it
     all", C): order, sections, labels, hidden and required fields. */
  const settings = useSalesSettings();
  const formFields = settings.forms.quote;

  /* BUILT ONCE PER RECORD, NOT ONCE PER SAVE — the order sheet's `builtFor`:
     every autosave hands back a new quote, and rebuilding from it would move
     the caret and lose what was typed since. */
  const builtFor = React.useRef<string | null>(null);
  const lastSaved = React.useRef<string | null>(null);
  /** The blank a Create Quote opened on — closing still equal to it keeps nothing. */
  const blank = React.useRef<string | null>(null);
  React.useEffect(() => {
    if (!open || !quote) {
      builtFor.current = null;
      return;
    }
    if (builtFor.current === quote.id) return;
    builtFor.current = quote.id;
    const built = draftOf(quote);
    lastSaved.current = JSON.stringify(built);
    blank.current = creating ? lastSaved.current : null;
    setPendingShown(false);
    setHeld({ id: quote.id, d: built });
  }, [open, quote, creating]);

  /* AUTOSAVE, DEBOUNCED — a save per pause in the work, not per keystroke. */
  React.useEffect(() => {
    if (!open || !draft || !quote) return;
    const shape = JSON.stringify(draft);
    if (lastSaved.current === shape) return;
    const t = window.setTimeout(() => {
      lastSaved.current = shape;
      updateQuote(quote.id, draft);
    }, 600);
    return () => window.clearTimeout(t);
  }, [draft, open, quote]);

  const saveState = useDraftSaveState(draft, open);

  /** Write whatever the debounce has not yet. */
  const flush = () => {
    if (!draft || !quote) return;
    const shape = JSON.stringify(draft);
    if (lastSaved.current === shape) return;
    lastSaved.current = shape;
    updateQuote(quote.id, draft);
  };

  const close = () => {
    if (quote && draft && blank.current !== null && JSON.stringify(draft) === blank.current) {
      /* NOTHING WAS TYPED, so there is nothing to keep — an empty draft left
         in the list would be a record of a button press. */
      discardQuote(quote.id);
    } else {
      flush();
    }
    onOpenChange(false);
  };

  if (!draft || !quote) return null;

  const set = <K extends keyof QuoteDraft>(key: K, value: QuoteDraft[K]) =>
    setDraft((d) => (d ? { ...d, [key]: value } : d));

  const status = quoteStatus({ ...quote, validThrough: draft.validThrough });
  /* ACCEPTED IS FINAL. It has become an order; a quote edited after that
     would no longer say what the customer agreed to. */
  const locked = quote.stage === "Accepted";
  const price = priceQuote(draft);
  const customer = CUSTOMERS.find((c) => c.name === draft.customer);
  const shipTos = customer?.shipTos ?? [];
  const unusedProduct = QUOTE_PRODUCTS.find((p) => !draft.lines.some((l) => l.name === p));
  const anyOverride = draft.lines.some((l) => l.baseSet);
  const today = startOfDay(new Date());
  /* THE PRIMARY UNIT, as the quantity heading prints it (2026-10-07). */
  const unitHead = { Gallons: "Gal", Litres: "L", Drums: "Drums" }[settings.unit];


  const pickCustomer = (name: string) => {
    const next = CUSTOMERS.find((c) => c.name === name);
    const prevEmail = customer?.contactEmail ?? "";
    setDraft((d) =>
      d
        ? {
            ...d,
            customer: name,
            /* A SHIP-TO BELONGS TO ITS CUSTOMER — one that is not the new
               customer's goes, and a customer with one ship-to has it. */
            shipTo: next?.shipTos.includes(d.shipTo)
              ? d.shipTo
              : next?.shipTos.length === 1
                ? next.shipTos[0]
                : "",
            /* The account's contact, unless somebody typed another address. */
            email: !d.email || d.email === prevEmail ? (next?.contactEmail ?? "") : d.email,
          }
        : d
    );
  };

  const setLines = (lines: QuoteLine[]) => set("lines", reprice(lines, draft.market));

  /* FEES AND TAXES ARE LISTS (Pavan, 2026-10-07). The first of each is the
     default — named, and not removable; every one added after it is. */
  const listKey = (kind: ChargeKind) => (kind === "fee" ? "fees" : "taxes");
  const addCharge = (kind: ChargeKind) => {
    const id = newChargeId(kind);
    setFocusCharge(id);
    const key = listKey(kind);
    set(key, [...draft[key], { id, name: "", value: 0, unit: kind === "fee" ? "perGal" : "percent" }]);
  };
  const chargeRows = (kind: ChargeKind): PricingRow[] => {
    const key = listKey(kind);
    const list = draft[key];
    const patch = (id: string, p: Partial<Charge>) =>
      set(key, list.map((c) => (c.id === id ? { ...c, ...p } : c)));
    return list.map((c, i) => ({
      key: c.id,
      label: c.name,
      value: c,
      onChange: (v: Adjust) => patch(c.id, v),
      ...(i > 0 && {
        onRename: (name: string) => patch(c.id, { name }),
        onRemove: () => set(key, list.filter((x) => x.id !== c.id)),
        blankName: `${kind} ${i + 1}`,
        autoFocus: c.id === focusCharge,
      }),
    }));
  };
  /** A fee or tax as the summary names it — a blank added one by its kind. */
  const partsOf = (list: Charge[], parts: number[], fallback: string) =>
    list.length > 1
      ? list.map((c, i) => ({ label: c.name || fallback, value: RATE(parts[i] ?? 0) }))
      : undefined;

  /* ---- the quote's own fields, as Sales Settings place them ---------- */

  const renderers: Record<string, (f: FormField) => BuiltInField> = {
    customer: () => ({
      half: true,
      control: (
        <Combobox
          className="w-full"
          value={draft.customer}
          onValueChange={pickCustomer}
          options={ACTIVE_CUSTOMERS.map((c) => c.name)}
          placeholder="Select customer"
          searchPlaceholder="Search customers…"
          emptyText="No customer found."
        />
      ),
    }),
    shipTo: () => ({
      half: true,
      /* THE GATE LIVES IN THE PICKER (ux §Side-sheet anatomy): only the
         chosen customer's ship-tos, and with none chosen it says why it is
         empty. */
      control: (
        <Combobox
          className="w-full"
          value={draft.shipTo}
          onValueChange={(v) => set("shipTo", v)}
          options={shipTos}
          placeholder={customer ? "Select ship-to" : "Choose a customer first"}
          emptyText="No ship-to found."
        />
      ),
    }),
    email: () => ({
      half: true,
      control: (
        <Input
          type="email"
          value={draft.email}
          placeholder="name@company.com"
          onChange={(e) => set("email", e.target.value)}
        />
      ),
    }),
    validThrough: () => ({
      half: true,
      control: (
        <DatePopover>
          <PopoverTrigger asChild>
            <Button variant="outline" className="w-full justify-start font-normal">
              <CalendarDays />
              {draft.validThrough ? (
                formatFullDate(dateOfKey(draft.validThrough)!)
              ) : (
                <span className="text-muted-foreground">Select date</span>
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent align="start" className="w-auto p-0">
            <DatePanel
              selected={dateOfKey(draft.validThrough) ?? undefined}
              onSelect={(d) => d && set("validThrough", dateKeyOf(d))}
              disabled={{ before: today }}
            />
          </PopoverContent>
        </DatePopover>
      ),
    }),
    market: () => ({
      half: true,
      control: (
        <Combobox
          className="w-full"
          value={draft.market}
          onValueChange={(m) =>
            setDraft((d) => (d ? { ...d, market: m, lines: reprice(d.lines, m) } : d))
          }
          options={MARKETS}
          placeholder="Select market"
        />
      ),
    }),
    products: () => ({
      table: {
        action:
          /* Only when a rate was typed over the list's — otherwise every
             line is already on it. */
          anyOverride && !locked ? (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => set("lines", reapplyRates(draft.lines, draft.market))}
            >
              Reapply rate
            </Button>
          ) : undefined,
        hanging:
          unusedProduct !== undefined && !locked ? (
            <HangingAdd
              label="Add product"
              onClick={() => {
                setFocusProduct(draft.lines.length);
                setLines([
                  ...draft.lines,
                  { name: unusedProduct, gal: 0, base: null, baseSet: false },
                ]);
              }}
            />
          ) : undefined,
        node: (
          <ProductTable<QuoteLine>
            lines={draft.lines}
            options={QUOTE_PRODUCTS}
            focusRow={focusProduct}
            onChange={setLines}
            qtyLabel={`Quantity (${unitHead})`}
            columns={[
              {
                key: "base",
                label: "Base $/gal",
                width: "w-[18%]",
                required: true,
                cell: (l, i) => (
                  <TableCellInput
                    value={l.base === null ? "" : l.base.toFixed(3)}
                    numeric
                    prefix="$"
                    placeholder="—"
                    aria-label={`Base rate of ${l.name || `row ${i + 1}`}`}
                    onChange={(v) => {
                      const n = Number(v.replace(/[^0-9.]/g, ""));
                      /* Typed, it is this line's rate until Reapply;
                         emptied, the line goes back to the list's. */
                      setLines(
                        draft.lines.map((x, j) =>
                          j !== i
                            ? x
                            : v.trim() === ""
                              ? { ...x, baseSet: false }
                              : { ...x, baseSet: true, base: Number.isFinite(n) ? n : 0 }
                        )
                      );
                    }}
                  />
                ),
              },
              {
                key: "net",
                label: "Net $/gal",
                width: "w-[16%]",
                cell: (_, i) => (
                  <div className="flex h-11 items-center px-3 text-sm tabular-nums text-foreground">
                    {price.lines[i] ? RATE(price.lines[i]!.net) : "—"}
                  </div>
                ),
                total: price.gallons > 0 ? RATE(price.net) : "—",
              },
              {
                key: "total",
                label: "Line total",
                width: "w-[20%]",
                cell: (_, i) => (
                  <div className="flex h-11 items-center px-3 text-sm tabular-nums text-foreground">
                    {price.lines[i] ? MONEY(price.lines[i]!.total) : "—"}
                  </div>
                ),
                total: MONEY(price.total),
              },
            ]}
          />
        ),
      },
    }),
    pricing: () => ({
      table: {
        hanging:
          /* ONE ADD, TWO KINDS OF ROW (Pavan, 2026-10-07). A table has one
             hanging add; a choice of Fee or Tax is a menu off it, never a
             second tab beside it. */
          locked ? undefined : (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <HangingAdd label="Add charge" />
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="start"
                className="min-w-28"
                /* THE ROW IS ADDED ONCE THE MENU HAS CLOSED, so its name
                   cell can take the cursor — an open menu holds focus, and
                   handing it back would land on the add. */
                onCloseAutoFocus={(e) => {
                  const kind = pickedCharge.current;
                  if (!kind) return;
                  e.preventDefault();
                  pickedCharge.current = null;
                  addCharge(kind);
                }}
              >
                <DropdownMenuItem onSelect={() => (pickedCharge.current = "fee")}>
                  Fee
                </DropdownMenuItem>
                <DropdownMenuItem onSelect={() => (pickedCharge.current = "tax")}>
                  Tax
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          ),
        node: (
          <PricingTable
            disabled={locked}
            rows={[
              {
                key: "margin",
                label: "Margin",
                value: draft.margin,
                onChange: (v) => set("margin", v),
              },
              ...chargeRows("fee"),
              ...chargeRows("tax"),
            ]}
          />
        ),
      },
    }),
    /* THE NOTES ARE THEIR OWN UNIT, IN THE SAME GROUP (Pavan, 2026-10-07 —
       ux §Record sheets): under the table's box, not inside it. */
    notes: () => ({
      control: (
        <Textarea
          value={draft.notes}
          onChange={(e) => set("notes", e.target.value)}
          className="min-h-24"
        />
      ),
    }),
  };

  /* WHERE EACH FIELD SITS NOW — the strip sends the reader to its section. */
  const secOf = (key: string) =>
    sectionId("quote", formFields.find((f) => f.key === key)?.section ?? "");
  const pending: PendingItem[] = [
    !draft.customer && { key: "customer", label: "Choose a customer", target: secOf("customer") },
    !draft.shipTo && { key: "shipTo", label: "Choose a ship-to", target: secOf("shipTo") },
    !EMAIL_RE.test(draft.email.trim()) && {
      key: "email",
      label: "Enter the customer's email",
      target: secOf("email"),
    },
    !draft.validThrough && {
      key: "valid",
      label: "Choose a valid-through date",
      target: secOf("validThrough"),
    },
    draft.validThrough &&
      draft.validThrough < dateKeyOf(today) && {
        key: "validPast",
        label: "Move the valid-through date to today or later",
        target: secOf("validThrough"),
      },
    !draft.market && { key: "market", label: "Choose a market", target: secOf("market") },
    draft.lines.some((l) => !l.name) && {
      key: "product",
      label: "Choose a product",
      target: secOf("products"),
    },
    draft.lines.some((l) => l.gal <= 0) && {
      key: "gal",
      label: "Enter gallons",
      target: secOf("products"),
    },
    draft.market &&
      draft.lines.some((l) => l.name && l.base === null) && {
        key: "base",
        label: "Enter a base rate",
        target: secOf("products"),
      },
    /* AND EVERY OTHER FIELD SALES SETTINGS MARK REQUIRED — the locked ones
       are asked above, in the quote's own words. */
    ...missingRequired(
      "quote",
      formFields.filter((f) => !f.locked),
      (f) => (isNative(f, renderers) ? Boolean(draft.notes.trim()) : extraFilled(draft.extra?.[f.key]))
    ),
  ].filter(Boolean) as PendingItem[];

  const footerPrimary =
    quote.stage === "Draft" ? (
      <div className="flex items-center gap-3">
        <Button
          variant="outline"
          onClick={() => {
            flush();
            toast.success(`${quote.quoteNo} saved as a draft`);
            onOpenChange(false);
          }}
        >
          Save as Draft
        </Button>
        <Button
          onClick={() => {
            /* PRESSABLE, AND PRESSING SAYS WHAT IS MISSING — it raises the
               pending strip rather than acting (the service sheet's rule). */
            if (pending.length > 0) setPendingShown(true);
            else {
              flush();
              setEmailOpen(true);
            }
          }}
        >
          <Send />
          Send quote
        </Button>
      </div>
    ) : status === "Sent" ? (
      <Button
        onClick={() => {
          flush();
          const order = acceptQuote(quote.id);
          /* acceptQuote raises the Quote accepted notification; this is the
             plain confirmation for when that row is off (2026-10-07). */
          if (order && !settings.notifications.find((n) => n.key === "quoteAccepted")?.inApp)
            toast.success(`${quote.quoteNo} accepted · Order ${order.orderNo} created`);
        }}
      >
        Mark as accepted
      </Button>
    ) : null;

  return (
    <>
      <RecordSheet
        /* WIDTH FROM ITS TABLES (Pavan, 2026-10-15 — like the Delivery
           Order): products = product · qty · base $/gal · bin; pricing =
           charge · value · bin. The rail beside. */
        fit={{
          tables: [
            [CELL.name, CELL.number, CELL.number, CELL.bin],
            [CELL.name, CELL.number, CELL.bin],
          ],
          rail: true,
        }}
        open={open}
        onOpenChange={(o) => (o ? onOpenChange(o) : close())}
        mode={creating ? "create" : "edit"}
        editTitle={`Quote #: ${quote.quoteNo}`}
        createTitle="Create Quote"
        createAction="Send quote"
        /* AUTOSAVED, so Cancel is a promise the sheet cannot keep. */
        showCancel={false}
        /* THE STEPPED LOOK, WITHOUT THE STEP COLUMN — as the 3PL order sheet
           (archived 2026-10-06). */
        headerAside={
          <DraftStatusChip tone={QUOTE_STATUS_TONE[status]} label={status} saveState={saveState} />
        }
        footerBanner={
          quote.stage === "Draft" && pendingShown ? (
            <PendingStrip
              tone="caution"
              pending={pending}
              clearLabel="Everything this quote needs is filled in"
            />
          ) : undefined
        }
        onSubmit={() => {}}
        footerPrimary={footerPrimary}
      >
        <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_340px]">
          <fieldset disabled={locked} className="flex min-w-0 flex-col gap-10">
            <ConfiguredForm
              kind="quote"
              renderers={renderers}
              extra={draft.extra ?? {}}
              onExtraChange={(key, value) => set("extra", { ...(draft.extra ?? {}), [key]: value })}
            />
          </fieldset>

          {/* WHAT THE FORM MAKES — read-only, and it stays put while the form
              scrolls (ux §Side-sheet anatomy, the two-column sheet). */}
          <aside className="flex min-w-0 flex-col gap-6 lg:sticky lg:top-0">
            {/* THE SHARED SUMMARY CARD (Pavan, 2026-10-07 — ux §Record
                sheets): the 3PL Quotation summary's shell. A fee or tax row
                made of several shows its parts on hover. */}
            <SummaryCard title="Quote summary">
              <dl className="flex flex-col">
                <RailRow variant="line" label="Base rate" value={RATE(price.base)} />
                <RailRow variant="line" label="Margin" value={RATE(price.margin)} />
                <RailRow
                  variant="line"
                  label="Fees"
                  value={RATE(price.fees)}
                  breakdown={partsOf(draft.fees, price.feeParts, "Fee")}
                />
                <RailRow
                  variant="line"
                  label="Tax"
                  value={RATE(price.tax)}
                  breakdown={partsOf(draft.taxes, price.taxParts, "Tax")}
                />
              </dl>
              <div aria-hidden className="border-t border-dashed border-border" />
              <dl className="flex flex-col">
                <RailRow
                  variant="line"
                  label="Net effective price per gallon"
                  value={RATE(price.net)}
                />
                <RailRow variant="total" label="Quote total" value={MONEY(price.total)} />
              </dl>
              {quote.orderId && quote.orderNo && (
                <>
                  <div aria-hidden className="border-t border-border" />
                  <dl className="flex flex-col">
                    <RailRow
                      variant="line"
                      label="Fuel order"
                      value={
                        <Button
                          variant="link"
                          className="h-auto p-0 tabular-nums"
                          onClick={() => onOpenOrder(quote.orderId!)}
                        >
                          {quote.orderNo}
                        </Button>
                      }
                    />
                  </dl>
                </>
              )}
            </SummaryCard>
            {/* THE SHARED ACTIVITY CARD (Pavan, 2026-10-07). */}
            <ActivityCard entries={quote.audit} timeZone={settings.timeZone} />
          </aside>
        </div>
      </RecordSheet>

      <QuoteEmailSheet
        quote={quote}
        draft={draft}
        open={emailOpen}
        onOpenChange={setEmailOpen}
        onSend={() => {
          updateQuote(quote.id, { ...draft, stage: "Sent" });
          lastSaved.current = JSON.stringify(draft);
          /* QUOTE SENT — the in-app notification when its row says so;
             otherwise the plain confirmation (2026-10-07). */
          if (settings.notifications.find((n) => n.key === "quoteSent")?.inApp)
            notify("quoteSent", `${quote.quoteNo} sent to ${draft.email}`);
          else toast.success(`${quote.quoteNo} sent to ${draft.email}`);
        }}
      />
    </>
  );
}

/*
  SEND QUOTE IS A STEP, NOT A BUTTON THAT FIRES (Pavan, 2026-10-07 — decision
  4). The email the customer will get, built from the quote: who it goes to,
  the subject, the body. It can be changed here; the quote is not. The last
  press is Send, which is what moves the quote to Sent.
*/
function QuoteEmailSheet({
  quote,
  draft,
  open,
  onOpenChange,
  onSend,
}: {
  quote: Quote;
  draft: QuoteDraft;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSend: () => void;
}) {
  const [to, setTo] = React.useState<string[]>([]);
  const [subject, setSubject] = React.useState("");
  const [body, setBody] = React.useState("");

  /* SEEDED ONCE PER OPEN — the partner invitation's rule. */
  React.useEffect(() => {
    if (!open) return;
    const price = priceQuote(draft);
    const contact = CUSTOMERS.find((c) => c.name === draft.customer)?.contactName.split(" ")[0];
    setTo(draft.email ? [draft.email.trim()] : []);
    setSubject(`Fuel quote ${quote.quoteNo} · ${draft.shipTo}`);
    setBody(
      [
        `Hi ${contact ?? "there"},`,
        "",
        `Here is our quote ${quote.quoteNo} for delivery to ${draft.shipTo} (${draft.market}).`,
        "",
        ...draft.lines.map((l, i) => {
          const p = price.lines[i];
          return `${l.name} — ${l.gal.toLocaleString()} gal at ${p ? RATE(p.net) : "—"}/gal = ${p ? MONEY(p.total) : "—"}`;
        }),
        "",
        `Net effective price: ${RATE(price.net)}/gal`,
        `Quote total: ${MONEY(price.total)}`,
        `Valid through ${printKey(draft.validThrough)}.`,
        ...(draft.notes.trim() ? ["", draft.notes.trim()] : []),
        "",
        "Dana Whitfield",
      ].join("\n")
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  const nothingToSend = to.length === 0 || subject.trim() === "";

  return (
    <RecordSheet
      level={2}
      /* WIDTH FROM ITS TABLES (Pavan, 2026-10-15): no table — an email
         (to, subject, message) — so the form's 600. */
      size="form"
      open={open}
      onOpenChange={onOpenChange}
      mode="create"
      editTitle=""
      createTitle={`Send quote ${quote.quoteNo}`}
      createAction="Send"
      showCancel={false}
      canSubmit={!nothingToSend}
      onSubmit={onSend}
      footerPrimary={
        <Button
          disabled={nothingToSend}
          onClick={() => {
            onSend();
            onOpenChange(false);
          }}
        >
          <Send />
          Send
        </Button>
      }
    >
      <SheetSection title="Email">
        <SheetField label="To">
          <EmailChips id="quote-to" value={to} onChange={setTo} placeholder="name@company.com" />
        </SheetField>
        <SheetField label="Subject">
          <Input value={subject} onChange={(e) => setSubject(e.target.value)} />
        </SheetField>
        <SheetField label="Message">
          <Textarea
            value={body}
            onChange={(e) => setBody(e.target.value)}
            className="min-h-80 font-normal"
          />
        </SheetField>
      </SheetSection>
    </RecordSheet>
  );
}

import * as React from "react";
import { toast } from "sonner";
import { ReceiptText, SearchX } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { StatusChip } from "@/components/ui/status-chip";
import { TablePagination } from "@/components/tables-layout/TablePagination";
import { FuelOrdersViewBar } from "./FuelOrdersViewBar";
import { ListToolbar, ColumnSearchChip, FilterChips, type ListView, useViewBar, ViewStatement } from "./ListToolbar";
import { ListFilters, type ListFacet } from "./ListFilters";
import { ExportSheet, type ExportFilterRow } from "./ExportSheet";
import { ListTable, OverflowList, TwoLineCell } from "./ListTable";
import { useSavedViews } from "./useSavedViews";
import { MONEY, RATE } from "./data";
import {
  MARKETS,
  QUOTE_COLUMNS,
  QUOTE_SEARCH_FIELDS,
  QUOTE_STATUSES,
  QUOTE_STATUS_TONE,
  matchesQuote,
  priceQuote,
  printKey,
  quoteColumnText,
  quoteStatus,
  sortQuotes,
  type Quote,
  type QuoteColumnKey,
  type QuoteSort,
} from "./quotes";
import { createQuote, reportExpired, useQuotes } from "./quoteStore";
import { dateIn, timeIn, useSalesSettings } from "./salesSettings";
import { QuoteSheet } from "./QuoteSheet";

/**
 * QUOTES — a Sales list (Pavan, 2026-10-07). The same shell as Customers and
 * Asset Orders: the view row with the CTA, the toolbar, the table, pagination.
 *
 * NOT DATE-SCOPED. A quote's dates (valid through, updated) are columns that
 * sort, not a day the list is about, so the toolbar carries no date control.
 * No board and no map: no lanes have been decided for a quote.
 */
const TOGGLE_COLUMNS = QUOTE_COLUMNS.filter((c) => c.label).map((c) => ({
  key: c.key,
  label: c.label,
}));

interface ViewState {
  /** THE DISPLAY IT OPENS IN — table, board or map (Pavan, 2026-10-21). */
  mode?: ListView;
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  pageSize: number;
  colScope: string;
  colQuery: string;
  colFilters: Record<string, string>;
  columnOrder: string[];
  columnWidths: Record<string, number>;
  facets: string[];
}

const keyOf = (s: ViewState) =>
  JSON.stringify({
    ...s,
    mode: s.mode ?? "table",
    hidden: [...s.hidden].sort(),
    facets: [...s.facets].sort(),
    /* Empty boxes are no filter — typing then clearing one is not a change. */
    colFilters: Object.fromEntries(
      Object.entries(s.colFilters)
        .filter(([, v]) => v.trim() !== "")
        .sort(([a], [b]) => a.localeCompare(b))
    ),
  });

const DEFAULT_STATE: ViewState = {
  mode: "table",
  search: "",
  sortKey: null,
  sortDir: null,
  hidden: [],
  pageSize: 25,
  colScope: "customer",
  colQuery: "",
  colFilters: {},
  columnOrder: [],
  columnWidths: {},
  facets: [],
};

/* WHICH CREATE PRESS HAS BEEN ANSWERED. Outside the component on purpose:
   the screen remounts on every visit, and a nonce answered again on the way
   back would make a second blank quote. */
let answeredCreate: number | null = null;

export function QuotesScreen({
  focus,
  create,
  onOpenOrder,
}: {
  focus?: { id: string; n: number } | null;
  /** Create Quote pressed elsewhere (Orders' Create menu) — a nonce, so twice still opens. */
  create?: number | null;
  onOpenOrder: (orderId: string) => void;
}) {
  const rows = useQuotes();
  const { timeZone } = useSalesSettings();
  /* QUOTE EXPIRED — an in-app notification, once per quote (2026-10-07). */
  React.useEffect(() => {
    reportExpired(rows.filter((q) => quoteStatus(q) === "Expired"));
  }, [rows]);
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [creatingId, setCreatingId] = React.useState<string | null>(null);
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState<QuoteSort | null>(null);
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(25);
  const [hidden, setHidden] = React.useState<Set<QuoteColumnKey>>(new Set());
  const [colScope, setColScope] = React.useState("customer");
  const [colQuery, setColQuery] = React.useState("");
  const [view, setView] = React.useState<ListView>("table");
  const [columnOrder, setColumnOrder] = React.useState<string[]>([]);
  const [columnWidths, setColumnWidths] = React.useState<Record<string, number>>({});
  const [colFilters, setColFilters] = React.useState<Record<string, string>>({});
  const [colFiltersOpen, setColFiltersOpen] = React.useState(false);
  const [facetSel, setFacetSel] = React.useState<ReadonlySet<string>>(new Set());
  /* EXPORT ASKS FIRST (G10, Pavan, 2026-10-07) — 3PL's ExportSheet. */
  const [exporting, setExporting] = React.useState(false);
  const activeColFilters = React.useMemo(
    () => Object.entries(colFilters).filter(([, v]) => v.trim() !== ""),
    [colFilters]
  );

  const current: ViewState = {

    mode: view,
    search,
    sortKey: sort?.key ?? null,
    sortDir: sort?.dir ?? null,
    hidden: [...hidden],
    pageSize,
    colScope,
    colQuery,
    colFilters,
    columnOrder,
    columnWidths,
    facets: [...facetSel],
  };

  const applyState = (s: ViewState) => {

    setView(s.mode ?? "table");
    setSearch(s.search);
    setSort(s.sortKey && s.sortDir ? { key: s.sortKey as QuoteColumnKey, dir: s.sortDir } : null);
    setHidden(new Set(s.hidden as QuoteColumnKey[]));
    setPageSize(s.pageSize);
    setColScope(s.colScope);
    setColQuery(s.colQuery);
    setColFilters(s.colFilters);
    /* The row opens when the view has something typed in it. */
    setColFiltersOpen(Object.values(s.colFilters).some((v) => v.trim() !== ""));
    setColumnOrder(s.columnOrder);
    setColumnWidths(s.columnWidths);
    setFacetSel(new Set(s.facets));
    setPage(1);
  };

  const savedViews = useSavedViews({
    current,
    defaultState: DEFAULT_STATE,
    keyOf,
    apply: applyState,
    storageKey: "sales-quotes",
  });

  const startCreate = React.useCallback(() => {
    /* CREATE, THEN AUTOSAVE: the Draft exists from this press on. */
    const q = createQuote();
    setCreatingId(q.id);
    setOpenId(q.id);
    setPage(1);
  }, []);

  // A global-search hit lands here: open that quote's sheet on arrival.
  React.useEffect(() => {
    if (!focus) return;
    setCreatingId(null);
    setOpenId(focus.id);
  }, [focus]);

  React.useEffect(() => {
    if (!create || create === answeredCreate) return;
    answeredCreate = create;
    startCreate();
  }, [create, startCreate]);

  const q = search.trim().toLowerCase();
  const cq = colQuery.trim().toLowerCase();
  const searched = React.useMemo(
    () =>
      rows.filter(
        (r) =>
          (!q || matchesQuote(r, q)) &&
          (!cq || quoteColumnText(r, colScope as QuoteColumnKey).toLowerCase().includes(cq)) &&
          /* AND-ed, and each box matches the text its own column PRINTS. */
          activeColFilters.every(([key, value]) =>
            quoteColumnText(r, key as QuoteColumnKey)
              .toLowerCase()
              .includes(value.trim().toLowerCase())
          )
      ),
    [rows, q, cq, colScope, activeColFilters]
  );
  /* Facets AND across, OR within one — Asset Orders' rule. */
  const narrowFacets = React.useCallback(
    (sel: ReadonlySet<string>) => {
      if (sel.size === 0) return searched;
      const pass = (facet: string, value: string) =>
        ![...sel].some((id) => id.startsWith(`${facet}:`)) || sel.has(`${facet}:${value}`);
      return searched.filter(
        (r) =>
          pass("status", quoteStatus(r)) && pass("customer", r.customer) && pass("market", r.market)
      );
    },
    [searched]
  );
  const filtered = React.useMemo(() => narrowFacets(facetSel), [narrowFacets, facetSel]);
  /* THE VIEW BAR — the table's and the board's tools render into it. */
  const bar = useViewBar();
  const sorted = React.useMemo(() => sortQuotes(filtered, sort), [filtered, sort]);
  const pageRows = sorted.slice((page - 1) * pageSize, page * pageSize);

  const facets: ListFacet[] = React.useMemo(
    () => [
      { key: "status", label: "Status", options: [...QUOTE_STATUSES] },
      {
        key: "customer",
        label: "Customer",
        options: Array.from(new Set(rows.map((r) => r.customer).filter(Boolean))),
        searchable: true,
      },
      { key: "market", label: "Market", options: MARKETS },
    ],
    [rows]
  );

  const onSort = (key: QuoteColumnKey) => {
    setSort((prev) => {
      if (prev?.key !== key) return { key, dir: "asc" };
      if (prev.dir === "asc") return { key, dir: "desc" };
      return null;
    });
    setPage(1);
  };

  const renderCell = (r: Quote, key: QuoteColumnKey) => {
    const p = priceQuote(r);
    const muted = <span className="text-sm text-muted-foreground">—</span>;
    const num = (s: string) => <span className="text-sm tabular-nums text-foreground">{s}</span>;
    switch (key) {
      case "quoteNo":
        return <span className="text-sm font-medium text-foreground">{r.quoteNo}</span>;
      case "customer":
        return r.customer ? <span className="truncate text-sm">{r.customer}</span> : muted;
      case "shipTo":
        return r.shipTo ? <span className="truncate text-sm">{r.shipTo}</span> : muted;
      case "products":
        return <OverflowList values={r.lines.map((l) => l.name).filter(Boolean)} label="products" />;
      case "gallons":
        return p.gallons > 0 ? num(p.gallons.toLocaleString()) : muted;
      case "market":
        return r.market ? <span className="text-sm">{r.market}</span> : muted;
      case "net":
        return p.gallons > 0 ? num(RATE(p.net)) : muted;
      case "total":
        return p.gallons > 0 ? num(MONEY(p.total)) : muted;
      case "email":
        return r.email ? <span className="truncate text-sm">{r.email}</span> : muted;
      case "validThrough":
        return r.validThrough ? <span className="text-sm">{printKey(r.validThrough)}</span> : muted;
      case "status": {
        const s = quoteStatus(r);
        return (
          <StatusChip tone={QUOTE_STATUS_TONE[s]} variant="text">
            {s}
          </StatusChip>
        );
      }
      case "updated": {
        const d = new Date(r.updatedAt);
        return (
          /* IN THE SALES TIME ZONE (Preferences, 2026-10-07). */
          <TwoLineCell title={dateIn(d, timeZone)} description={timeIn(d, timeZone)} />
        );
      }
      default:
        return null;
    }
  };

  const nothing = sorted.length === 0 && !colFiltersOpen;

  /* EVERY NARROWING THAT IS ON, for the export sheet to list — each drops
     what the shelf's own chip drops (3PL's, 2026-10-07). */
  const dropFacets = (gone: string[]) => {
    const next = new Set(facetSel);
    for (const id of gone) next.delete(id);
    setFacetSel(next);
    setPage(1);
  };
  const exportFilters: ExportFilterRow[] = [
    {
      key: "search",
      label: "Search",
      values: search.trim()
        ? [{ value: search.trim(), onRemove: () => { setSearch(""); setPage(1); } }]
        : [],
    },
    {
      key: "colSearch",
      label: QUOTE_SEARCH_FIELDS.find((f) => f.key === colScope)?.label ?? "Column",
      values: colQuery.trim()
        ? [{ value: colQuery.trim(), onRemove: () => { setColQuery(""); setPage(1); } }]
        : [],
    },
    ...activeColFilters.map(([key, value]) => ({
      key: `col:${key}`,
      label: QUOTE_COLUMNS.find((c) => c.key === key)?.label ?? key,
      values: [
        {
          value: value.trim(),
          onRemove: () => {
            setColFilters((prev) => ({ ...prev, [key]: "" }));
            setPage(1);
          },
        },
      ],
    })),
    ...facets.map((f) => {
      const mine = [...facetSel].filter((id) => id.startsWith(`${f.key}:`));
      return {
        key: f.key,
        label: f.label,
        values: mine.map((id) => ({
          value: id.slice(id.indexOf(":") + 1),
          onRemove: () => dropFacets([id]),
        })),
        onRemoveAll: () => dropFacets(mine),
      };
    }),
  ];

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <FuelOrdersViewBar
        {...savedViews}
        ctaLabel="Create Quote"
        onCreateOrder={startCreate}
        onExport={() => setExporting(true)}
      />

      <div className="mt-4 shrink-0">
        <ListToolbar
          viewToolsInto={bar.into}
          viewStatement={<ViewStatement count={sorted.length} one="quote" many="quotes" />}
          searchValue={search}
          onSearchChange={(v) => {
            setSearch(v);
            setPage(1);
          }}
          searchPlaceholder="Search quotes, customers, ship-tos…"
          filters={
            <ListFilters
              facets={facets}
              value={facetSel}
              countFor={(sel) => narrowFacets(sel).length}
              onApply={(sel) => {
                setFacetSel(sel);
                setPage(1);
              }}
            />
          }
          columns={TOGGLE_COLUMNS}
          hiddenColumns={hidden}
          columnOrder={columnOrder}
          onReorderColumns={setColumnOrder}
          onToggleColumn={(k) =>
            setHidden((prev) => {
              const next = new Set(prev);
              if (next.has(k)) next.delete(k);
              else next.add(k);
              return next;
            })
          }
          onShowAllColumns={() => setHidden(new Set())}
          searchFields={QUOTE_SEARCH_FIELDS}
          colScope={colScope}
          onColScopeChange={(v) => {
            setColScope(v);
            setPage(1);
          }}
          colQuery={colQuery}
          onColQueryChange={(v) => {
            setColQuery(v);
            setPage(1);
          }}
          columnFiltersOpen={colFiltersOpen}
          onToggleColumnFilters={() =>
            setColFiltersOpen((open) => {
              /* Closing the row clears it: a narrowing with no boxes on
                 screen would be one nobody could see. */
              if (open) {
                setColFilters({});
                setPage(1);
              }
              return !open;
            })
          }
          columnFilterCount={activeColFilters.length}
          view={view}
          onViewChange={setView}
          /* No grouping was asked for here (2026-10-07); a Group By that
             groups nothing is a dead control. */
          showGroupBy={false}
        />
        {/* ONE SHELF for the facets and the column search — 3PL's. */}
        <FilterChips
          facets={facets}
          selected={facetSel}
          onChange={(next) => {
            setFacetSel(next);
            setPage(1);
          }}
        >
          <ColumnSearchChip
            /* ALONE ON THE SHELF it keeps its own top margin (Pavan, 2026-10-07). */
            className={facetSel.size > 0 ? "" : undefined}
            searchFields={QUOTE_SEARCH_FIELDS}
            colScope={colScope}
            colQuery={colQuery}
            onClear={() => {
              setColQuery("");
              setPage(1);
            }}
          />
        </FilterChips>
        {activeColFilters.length > 0 && (
          <div className="mt-3 flex flex-wrap items-center gap-2">
            {activeColFilters.map(([key, value]) => (
              <ColumnSearchChip
                key={key}
                className=""
                searchFields={TOGGLE_COLUMNS}
                colScope={key}
                colQuery={value.trim()}
                onClear={() => {
                  setColFilters((prev) => ({ ...prev, [key]: "" }));
                  setPage(1);
                }}
              />
            ))}
          </div>
        )}
      </div>

      <div className="relative mt-4 min-h-0 flex-1">
        <div className="h-full min-h-0">
          {nothing ? (
            <Empty className="h-full">
              <EmptyHeader>
                <EmptyMedia variant="icon">{q ? <SearchX /> : <ReceiptText />}</EmptyMedia>
                <EmptyTitle>{q ? "No matching quotes" : "No quotes"}</EmptyTitle>
                {q && <EmptyDescription>{`No quotes match “${search.trim()}”.`}</EmptyDescription>}
              </EmptyHeader>
              <EmptyContent>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    if (q) setSearch("");
                    else startCreate();
                    setPage(1);
                  }}
                >
                  {q ? "Clear search" : "Create Quote"}
                </Button>
              </EmptyContent>
            </Empty>
          ) : (
            <ListTable
              topBar={bar.slot}
              rows={pageRows}
              columns={QUOTE_COLUMNS}
              hidden={hidden}
              sort={sort}
              onSort={onSort}
              rowId={(r) => r.id}
              renderCell={renderCell}
              actionsKey="actions"
              columnOrder={columnOrder}
              onReorderColumns={setColumnOrder}
              columnWidths={columnWidths}
              onResizeColumns={setColumnWidths}
              openLabel={(r) => `Open quote ${r.quoteNo}`}
              onOpenRow={(r) => {
                setCreatingId(null);
                setOpenId(r.id);
              }}
              showColumnFilters={colFiltersOpen}
              columnFilters={colFilters}
              onColumnFilterChange={(key, value) => {
                setColFilters((prev) => ({ ...prev, [key]: value }));
                setPage(1);
              }}
            />
          )}
        </div>
      </div>

      {/* EXPORT ASKS BEFORE IT ACTS (G10, Pavan, 2026-10-07). What leaves is
          the whole narrowed set, not the page. */}
      <ExportSheet
        open={exporting}
        onOpenChange={setExporting}
        title="Export Quotes"
        noun="quotes"
        nounOne="quote"
        count={sorted.length}
        filtersControl={
          <ListFilters
            facets={facets}
            value={facetSel}
            countFor={(sel) => narrowFacets(sel).length}
            onApply={(sel) => {
              setFacetSel(sel);
              setPage(1);
            }}
            fullWidth
          />
        }
        filters={exportFilters}
        onExport={(format) => {
          setExporting(false);
          toast.success(`Exporting ${sorted.length} ${sorted.length === 1 ? "quote" : "quotes"} as .${format}`);
        }}
      />

      <QuoteSheet
        quote={rows.find((r) => r.id === openId) ?? null}
        open={openId !== null}
        creating={creatingId !== null && creatingId === openId}
        onOpenChange={(o) => {
          if (o) return;
          setOpenId(null);
          setCreatingId(null);
        }}
        onOpenOrder={onOpenOrder}
      />

      <div className="mt-4 shrink-0">
        <TablePagination
          page={page}
          pageSize={pageSize}
          total={sorted.length}
          onPageChange={setPage}
          onPageSizeChange={(size) => {
            setPageSize(size);
            setPage(1);
          }}
        />
      </div>
    </div>
  );
}

import * as React from "react";
import { Check, Loader2, X } from "lucide-react";
import { StatusChip, type StatusTone } from "@/components/ui/status-chip";
import type { PillColor } from "@/components/ui/pill";
import { cn } from "@/lib/utils";
import { QuietPattern } from "@/components/ui/quiet-pattern";
import { Button } from "@/components/ui/button";
import { Sheet, SheetClose, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { SteppedFormBody } from "@/components/side-sheet/form-steps";
import { FormStepsContext } from "@/components/side-sheet/form-steps-context";
import { PendingStrip, attend, type PendingItem } from "./PendingStrip";

/**
 * Side-sheet shell for a single record — edit or create.
 *
 * Chrome is the DS's, taken from `side-sheet/SheetNarrow.tsx` (Figma "Side
 * Sheet" 27610:58293) and matched to the Fuel Orders order sheet so all three
 * sheets are identical where they should be:
 *   • SheetContent  w-560 (DS `narrow`), gap-0 p-0
 *   • header        border-b, p-4, items-start justify-between gap-4
 *   • body          p-4, flex-col gap-10   ← 40px between groups
 *   • footer        border-t, p-4, items-center justify-end gap-3
 *
 * The 40px group rhythm is the same deliberate override the order sheet
 * documents: these sheets carry far more fields than the DS reference, and at
 * the DS's gap-7 the groups stopped reading as groups. The 1:2 ratio against
 * SheetSection's gap-5 is preserved, so only the scale moved.
 *
 * CREATE AND EDIT ARE THE SAME SHEET. `mode="create"` swaps the title for the
 * create label and the submit button with it, and the caller seeds a blank
 * draft. One layout to learn, and no separate create form to drift.
 *
 * DS FOLLOW-UP: nothing here is screen-specific. This belongs beside
 * `side-sheet/` in the DS, with the order sheet moved onto it too.
 */
/**
 * A COLUMN'S COMFORTABLE WIDTH, by what it holds (Pavan, 2026-10-15). A
 * table-led sheet adds these up to find its width; one number per kind, so
 * the same column is the same width in every sheet.
 */
export const CELL = {
  /* TIGHTENED (Pavan, 2026-10-15): asset and product names are short, a
     quantity is at most six digits — the columns, and so the sheet, are only
     as wide as that. */
  /** A row's select checkbox, an expand chevron. */
  check: 44,
  /** "Top off" and other labelled checkboxes. */
  flag: 72,
  /** Top off — its label and the select-all, just before the quantity (DS ui §10i). */
  topOff: 104,
  /** A tank's level reading — gauge and % (portal, 2026-10-17). */
  level: 150,
  /** A tank monitor's battery. */
  battery: 100,
  /** The row's own thing — an asset, a product, a partner, a document. */
  name: 200,
  /** A pick from a short list — type, unit, condition, terminal. */
  pick: 160,
  /** A quantity or an amount, with its unit — six digits. */
  number: 110,
  date: 140,
  status: 140,
  /** Free text — a fault, a note. */
  text: 240,
  /** The row bin / a row menu. */
  bin: 52,
} as const;

export interface SheetFit {
  /** Each table's columns, as `CELL` widths; the widest table decides. */
  tables: number[][];
  /** The 340px right rail (summary · activity) beside the tables. */
  rail?: boolean;
}

/*
  THE PATTERN UNDER A SHORT FORM (Pavan, 2026-10-16). When what the sheet
  holds takes HALF the visible height or less, the DS quiet pattern fills
  the rest — to the body's left, right and bottom edges. Taller than that,
  there is no pattern and no space kept for it. Measured live, so a form
  that grows as it is filled loses the pattern when it passes half.
*/
const BODY_GAP = 40;
const BODY_PAD = 16;
function SheetPattern() {
  const ref = React.useRef<HTMLDivElement>(null);
  const [shown, setShown] = React.useState(false);
  React.useLayoutEffect(() => {
    const el = ref.current;
    const body = el?.parentElement;
    if (!el || !body) return;
    const measure = () => {
      const visible = body.clientHeight;
      if (!visible) return;
      const top = el.getBoundingClientRect().top - body.getBoundingClientRect().top + body.scrollTop;
      /* Where the content ends — the pattern's own gap taken out. */
      const content = top - BODY_PAD - (el.dataset.shown === "true" ? BODY_GAP : 0);
      setShown(content <= visible / 2);
    };
    const ro = new ResizeObserver(measure);
    ro.observe(body);
    for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
    const mo = new MutationObserver(() => {
      for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
      measure();
    });
    mo.observe(body, { childList: true });
    measure();
    return () => {
      ro.disconnect();
      mo.disconnect();
    };
  }, []);
  return (
    <div
      ref={ref}
      data-shown={shown}
      aria-hidden
      /* Hidden, it takes no room: zero height, and the gap above canceled. */
      className={cn(shown ? "-mx-4 -mb-4 flex min-h-24 flex-1" : "-mt-10 h-0 overflow-hidden")}
    >
      {shown && <QuietPattern className="flex-1" />}
    </div>
  );
}

/**
 * THE SHEET UNDERNEATH, for a sheet opened over it (Pavan, 2026-10-15). Now
 * that widths follow content, two sheets can be the same width, and the top
 * one would cover the other exactly — reading as the SAME sheet having
 * changed. A level-2 sheet is therefore never wider than the one beneath it
 * less the 56px gap, so a strip of it always shows.
 */
const ParentSheetWidth = React.createContext<number | null>(null);

/** BODY PADDING (16 + 16) AND THE TABLE BOX'S BORDERS. */
const FIT_PAD = 34;
const RAIL = 340 + 24;
export const FORM_WIDTH = 600;
export const DATA_WIDTH = 1200;
/** A data-intensive sheet's field grid — three across, at 1200. */
export const DATA_FIELDS = "grid grid-cols-3 gap-4";

/**
 * The width a table-led sheet takes. THE FORM SIDE IS NEVER NARROWER THAN A
 * 600 FORM'S (Pavan, 2026-10-15): beside a rail, small tables still leave the
 * fields two across at a readable width; the rail adds its own 364.
 */
export function fitWidth(fit: SheetFit): number {
  const widest = Math.max(0, ...fit.tables.map((t) => t.reduce((n, w) => n + w, 0)));
  return Math.max(FORM_WIDTH - FIT_PAD, widest) + FIT_PAD + (fit.rail ? RAIL : 0);
}

export interface RecordSheetProps {
  /**
   * THE WIDTH FOLLOWS WHAT IS IN THE SHEET (Pavan, 2026-10-15 — replaces the
   * fixed 560 / 864 / 1120 tiers and the 756 creation floor). A sheet sized
   * for more than it holds reads as empty.
   *
   *   `form`     600 — fields and text, no table. The default.
   *   `compact`  510 — CONTROLS rather than a form (a facet list).
   *   `data`     1200 at least — a DATA-INTENSIVE record's detail: many
   *              fields and several related-records tables (a 3PL customer,
   *              vendor, product, rental asset). Fields go three across
   *              (`DATA_FIELDS`); with `fit`, the wider of the two. Pavan,
   *              2026-10-15: "cramped … should have more width so that
   *              information can be easily consumed".
   *   `full`     the viewport less the gap — no form uses it now: every
   *              order sheet fits its tables (Pavan, 2026-10-15). Kept for a
   *              sheet showing its step column.
   *
   * A sheet that carries TABLES passes `fit` instead, and is as wide as its
   * widest table's columns at a comfortable width (`CELL`), plus the body's
   * padding, plus the 340px rail and its gap when it has one — never under
   * 600. Per step: a stepped sheet passes the tables of the step on show.
   *
   * THE GAP IS 56px AND IT IS THE ONE CONSTANT. Every width is clamped to
   * `100vw - 56px`, so no sheet reaches the edge or overflows a small screen.
   * A sheet opened OVER another one takes that gap TWICE — see `level`.
   */
  size?: "compact" | "form" | "data" | "full";
  /** Width from the sheet's tables — see `size` and `fitWidth`. */
  fit?: SheetFit;
  /**
   * HOW DEEP IN THE STACK THIS SHEET IS. `2` is a sheet opened OVER another
   * one — the invitation over an order, a partner's quote over an order.
   *
   * IT TAKES A SECOND GAP (Pavan, 2026-09-22). The 56px is what tells a reader
   * a sheet is over something; a second sheet at the same inset covers the
   * first exactly and reads as the SAME sheet having changed its contents.
   * 112px leaves a 56px strip of the sheet underneath showing, which says
   * "there is one of these behind this one" in the only language the stack
   * has.
   */
  level?: 1 | 2;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "edit" | "create";
  /** Header title when editing, e.g. `Order #: 6104420`. */
  editTitle: string;
  /** Header title when creating, e.g. `Create Asset Order`. */
  createTitle: string;
  /** Submit label when editing. Defaults to the DS's `Save Changes`. */
  /**
   * THE EDIT-MODE PRIMARY. "Confirm", not "Save Changes" — autosave is the
   * default now, so by the time anybody looks at the footer the change is
   * already written and a Save would be claiming credit for work already
   * done. What is left to do is agree that the record is right.
   *
   * It is a per-sheet word: a footer that commits the record to a NEXT ACT
   * should say that act instead. Changed 2026-09-22.
   */
  editAction?: string;
  /** Submit label when creating — usually the same words as `createTitle`. */
  createAction: string;
  /** Rendered beside the title, e.g. a StatusChip. */
  headerAside?: React.ReactNode;
  /**
   * A second line under the title, inside the sticky header.
   *
   * For a fact about the record that must not scroll away — "this partner
   * holds the order" is the answer to a question the reader has while they are
   * looking at any part of the sheet, and at the bottom of a long step it was
   * only true where nobody was looking.
   */
  headerSubtitle?: React.ReactNode;
  /**
   * DRAFT AUTOSAVE, SAID OUT LOUD.
   *
   * A sheet that keeps a draft has to tell the reader it is keeping it, or
   * they behave as though it does not — they finish fields they meant to come
   * back to, and they hesitate to close. Three states and nothing else:
   * `saving` while a change settles, `saved` once it has, and `idle` before
   * anything has been typed, which shows nothing at all because there is
   * nothing to reassure anybody about yet.
   *
   * It sits by the TITLE, not the footer: it is a statement about the record,
   * not a control, and beside Save it would read as a second button. The
   * caller passes it through `DraftStatusChip`, which on a Draft swaps the
   * chip for the line "Draft saved" rather than showing both.
   */
  /**
   * The ··· at the right of the header, between the history icon and Close.
   * For acts ON the record that are not part of filling it in — deleting it.
   */
  headerMenu?: React.ReactNode;
  /**
   * Cancel in the footer. OFF on a sheet that autosaves its draft: "Cancel"
   * promises to undo, and a sheet that has already kept everything typed
   * cannot keep that promise. Close is the honest exit there.
   */
  showCancel?: boolean;
  /**
   * Controls at the far right of the header, left of Close.
   *
   * For things that OPEN something rather than change the record — a history,
   * a preview, a related list. They live in the header because they are not
   * part of the form and must not scroll away with it, and left of Close
   * because Close is the last thing on that edge in every sheet.
   */
  headerActions?: React.ReactNode;
  /**
   * A step strip under the header — `SheetSteps`. It sits above the body and
   * outside its scroll, because which step you are on is not something that
   * should be able to scroll away from you.
   */
  steps?: React.ReactNode;
  /** Disable submit while the draft is incomplete. */
  canSubmit?: boolean;
  /**
   * WHAT THE DEFAULT PRIMARY IS WAITING ON (Pavan, 2026-10-07 — G25). Given,
   * the default primary never goes dead: it stays pressable, and a press while
   * anything is listed (or `canSubmit` is false) raises the pending strip above
   * the footer and takes the reader to the first gap — the 3PL order / Quote
   * pattern. Ignored when `footerPrimary` replaces the button, and the caller's
   * own `footerBanner` wins over the strip.
   */
  pending?: PendingItem[];
  /**
   * Replaces the footer's primary button — and `null` removes it entirely.
   *
   * THE FOOTER'S RIGHT EDGE IS "THE MAIN THING TO DO HERE", and on a
   * multi-step sheet that is not the same act on every step. A step whose work
   * ends in a decision — accept this price — has a better claim to that slot
   * than a generic Save, and a step with nothing left to commit has no claim
   * at all. Omit the prop for the default Save/Create.
   */
  footerPrimary?: React.ReactNode;
  /**
   * Controls that ride in the footer, left of Cancel/Submit. For decisions
   * taken at the moment of committing rather than while filling the form —
   * they stay in view no matter how far the body has scrolled.
   */
  footerAside?: React.ReactNode;
  onSubmit: () => void;
  /**
   * A FIXED STRIP DIRECTLY ABOVE THE FOOTER, spanning the sheet.
   *
   * For what the footer's act is waiting on. The reason a primary is disabled
   * belongs beside it, and beside it there is room for a clause — not for a
   * list. This is where a sheet says what is still outstanding, in the one
   * place that does not scroll away from the button it is about.
   */
  footerBanner?: React.ReactNode;
  /** Classes for the banner while it sits under a stepped form's column. */
  footerBannerClassName?: string;
  /** A control on the step column's "Step N of M" row — form settings. */
  stepsAction?: React.ReactNode;
  /**
   * THE FORM AS STEPS (Pavan, 2026-10-05) — a column on the left listing the
   * form's steps, the form as one long scroll beside it, and the pending strip
   * at the foot of that column instead of above the footer. On by default for
   * every first-level sheet; the sheet takes the full width while the column
   * shows. The column only shows when there are two or more steps — see
   * `components/side-sheet/form-steps`.
   */
  stepNav?: boolean;
  /**
   * The step column itself. Off = the stepped form without the column on the
   * left (Pavan, 2026-10-06 — removed from the 3PL order sheets, archived in
   * docs/ds/ui/archive/step-column.md). OFF IN EVERY MODULE since 2026-10-07
   * (Pavan): pass `true` to bring it back on one sheet.
   */
  stepColumn?: boolean;
  children: React.ReactNode;
}

/**
 * Watch a draft and report whether it has been kept.
 *
 * ONE HOOK, SO EVERY DRAFT SHEET SAYS THE SAME THING. A sheet that autosaves
 * silently is a sheet people do not trust with unfinished work: they either
 * finish fields they meant to return to, or they hesitate to close. The
 * feedback is the feature.
 *
 * `saving` for 500ms after a change settles, then `saved`. It stays `idle`
 * until the FIRST change, because before anyone has typed there is nothing to
 * reassure them about — and a sheet that opens saying "Saved" is claiming to
 * have done something it has not.
 */
export function useDraftSaveState(draft: unknown, enabled = true) {
  const [state, setState] = React.useState<"idle" | "saving" | "saved">("idle");
  const serialised = React.useMemo(() => JSON.stringify(draft ?? null), [draft]);
  const first = React.useRef<string | null>(null);

  React.useEffect(() => {
    if (!enabled) {
      first.current = null;
      setState("idle");
      return undefined;
    }
    /* A SHEET FILLS ITS DRAFT ONE RENDER AFTER IT OPENS, so the first value
       seen here is `null` and the second is the untouched form. Treating that
       as an edit made every sheet open saying "Saved" — claiming to have kept
       something nobody had typed. The baseline is the first REAL draft. */
    if (draft === null || draft === undefined) return undefined;
    if (first.current === null) {
      first.current = serialised;
      return undefined;
    }
    if (serialised === first.current) return undefined;
    setState("saving");
    const t = window.setTimeout(() => setState("saved"), 500);
    return () => window.clearTimeout(t);
  }, [serialised, enabled, draft]);

  return state;
}

/**
 * The record's state in the header: what it IS, and whether the draft is kept.
 *
 * ONE THING WHEN THEY ARE THE SAME WORD. On a Draft, a status dot, the word
 * "Draft", a separator dot and the word "Saved" were four marks for one fact.
 * Once typing starts the chip gives way to plain text — "Draft saving…", then
 * "Draft saved" — which carries the status and the reassurance in one line.
 *
 * TWO WHEN THEY ARE NOT. An Assigned order being edited still has a status
 * worth seeing, and "Assigned saved" is not a sentence — so the status keeps
 * its chip and the save note sits beside it. The word stays "Draft" either
 * way, because what is kept is the draft of the edit, not the order.
 */
export function DraftStatusChip({
  tone,
  color,
  label,
  saveState = "idle",
  showStatus = true,
}: {
  tone: StatusTone;
  /* A STAGE COLOUR THE USER CHOSE (Pavan, 2026-10-09) — Sales stages keep
     the colour set in Sales Settings, in the header as in the table. */
  color?: PillColor | null;
  label: string;
  saveState?: "idle" | "saving" | "saved";
  /**
   * False drops the status chip and keeps only the save note — for a sheet
   * whose stage is already shown on its own track (Pavan, 2026-10-05).
   */
  showStatus?: boolean;
}) {
  const note =
    saveState === "saving" ? (
      <>
        <Loader2 className="size-3 animate-spin" />
        Draft saving…
      </>
    ) : (
      <>
        <Check className="size-3" />
        Draft saved
      </>
    );

  if (!showStatus) {
    if (saveState === "idle") return null;
    return (
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    );
  }

  if (saveState === "idle") {
    return (
      <StatusChip tone={tone} color={color} variant="soft">
        {label}
      </StatusChip>
    );
  }

  /* A DRAFT SAYS IT ONCE. "Draft saved" already contains the status, so the
     chip — its dot, its fill, its own word "Draft" — would be saying the same
     thing a second and third time. Plain text, one mark, one meaning. */
  if (label.toLowerCase() === "draft") {
    return (
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    );
  }

  /* NOT A DRAFT, so two things are true at once. An Assigned order still has a
     status worth seeing, and "Assigned saved" is not a sentence — the status
     keeps its chip and the save note sits beside it. The word stays "Draft"
     because what is kept is the draft of the edit, not the order. */
  return (
    <span className="flex items-center gap-2">
      <StatusChip tone={tone} color={color} variant="soft">
        {label}
      </StatusChip>
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    </span>
  );
}

export function RecordSheet({
  size = "form",
  fit,
  level = 1,
  open,
  onOpenChange,
  mode,
  editTitle,
  createTitle,
  editAction = "Confirm",
  createAction,
  headerAside,
  headerSubtitle,
  headerActions,
  headerMenu,
  showCancel = true,
  steps,
  canSubmit = true,
  pending,
  footerPrimary,
  footerAside,
  onSubmit,
  footerBanner,
  footerBannerClassName,
  stepsAction,
  stepNav,
  stepColumn = false,
  children,
}: RecordSheetProps) {
  const creating = mode === "create";
  const stepped = stepNav ?? level !== 2;
  const [navOn, setNavOn] = React.useState(false);
  const navShown = stepped && navOn;
  /* FULL WIDTH WHILE THE STEP COLUMN SHOWS (Pavan, 2026-10-05). */
  const fills = size === "full" || navShown;
  const parentWidth = React.useContext(ParentSheetWidth);
  const own =
    size === "data"
      ? Math.max(DATA_WIDTH, fit ? fitWidth(fit) : 0)
      : fit
        ? fitWidth(fit)
        : size === "compact"
          ? 510
          : FORM_WIDTH;
  const width = level === 2 && parentWidth !== null ? Math.min(own, parentWidth - 56) : own;
  /* WHY (Pavan, 2026-10-07). A dead primary says why on press (G25): the
     strip is raised by the press, not shown up front, and drops on close. */
  const [pendingRaised, setPendingRaised] = React.useState(false);
  React.useEffect(() => {
    if (!open) setPendingRaised(false);
  }, [open]);
  const saysWhy = pending !== undefined;
  const notReady = !canSubmit || (pending?.length ?? 0) > 0;
  const banner =
    footerBanner ??
    (saysWhy && pendingRaised ? <PendingStrip tone="caution" pending={pending} /> : undefined);
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        showCloseButton={false}
        /* THE GAP IS A VARIABLE, so one set of classes serves both levels. A
           second-level sheet takes 112 — the constant, twice — and the strip
           of the sheet beneath it is what says it is second. */
        style={
          {
            "--fp-sheet-gap": level === 2 ? "112px" : "56px",
            /* SCALED IN THE WCAG MODES — wider text, wider sheet (§10n). */
            "--fp-sheet-w": `calc(${width}px * var(--fp-scale, 1))`,
          } as React.CSSProperties
        }
        className={cn(
          "gap-0 p-0",
          fills
            ? /* FULL — the intense forms, and any sheet showing its step column. */
              "w-[calc(var(--fp-vw)-var(--fp-sheet-gap))] sm:max-w-[calc(var(--fp-vw)-var(--fp-sheet-gap))]"
            : /* THE CONTENT'S WIDTH, clamped by the gap (`--fp-sheet-w`). */
              "w-[min(var(--fp-sheet-w),calc(var(--fp-vw)-var(--fp-sheet-gap)))] sm:max-w-[min(var(--fp-sheet-w),calc(var(--fp-vw)-var(--fp-sheet-gap)))]"
        )}
      >
        <div className="flex items-start justify-between gap-4 border-b border-border p-4">
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex items-center gap-2.5">
              <SheetTitle className="text-base">
                {creating ? createTitle : editTitle}
              </SheetTitle>
              {headerAside}
            </div>
            {headerSubtitle}
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {headerActions}
            {headerMenu}
            <SheetClose className="rounded-sm p-1 text-muted-foreground opacity-70 outline-none transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50">
              <X className="size-4" />
              <span className="sr-only">Close</span>
            </SheetClose>
          </div>
        </div>

        {/* ACROSS THE SHEET only without a step column; with one, the band
            starts where the form starts (Pavan, 2026-10-05). */}
        {steps && !navShown && (
          /* NO RULE UNDER THE STEPS (Pavan, 2026-10-16) — the strip keeps the
             sheet's own white, and the form scrolls under it. */
          <div className="shrink-0 bg-popover px-4">{steps}</div>
        )}

        {stepped ? (
          <SteppedFormBody
            footer={navShown ? banner : undefined}
            footerClassName={footerBannerClassName}
            top={navShown ? steps : undefined}
            onShownChange={setNavOn}
            stepsAction={stepsAction}
            hideColumn={!stepColumn}
          >
            <ParentSheetWidth.Provider value={fills ? 99999 : width}>{children}</ParentSheetWidth.Provider>
            <SheetPattern />
          </SteppedFormBody>
        ) : (
          <FormStepsContext.Provider value={false}>
            <div className="flex min-h-0 flex-1 flex-col gap-10 overflow-auto p-4">
              <ParentSheetWidth.Provider value={fills ? 99999 : width}>{children}</ParentSheetWidth.Provider>
            <SheetPattern />
            </div>
          </FormStepsContext.Provider>
        )}

        {banner && !navShown && (
          /* ABOVE THE FOOTER AND OUTSIDE THE SCROLL — the same reason the
             stage bar sits under the header: a strip that describes the
             footer's button has to be visible whenever the button is. */
          <div className="shrink-0 border-t border-border px-4 py-2.5">
            {banner}
          </div>
        )}

        <div className="flex shrink-0 flex-wrap items-center justify-between gap-3 border-t border-border p-4">
          <div className="flex flex-wrap items-center gap-x-8 gap-y-2">
            {footerAside}
          </div>
          <div className="flex items-center gap-3">
          {showCancel && (
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
          )}
          {/* `undefined` = the default Save/Create; anything else replaces it,
              and `null` leaves the slot empty on a step with nothing to
              commit. */}
          {footerPrimary !== undefined ? (
            footerPrimary
          ) : (
            /* WHY (Pavan, 2026-10-07). With `pending` the button is never
               disabled — a press while not ready names the gap (G25). Without
               it, the old `disabled` stays so no caller changes unasked. */
            <Button
              disabled={!saysWhy && !canSubmit}
              onClick={() => {
                if (saysWhy && notReady) {
                  setPendingRaised(true);
                  const first = pending?.find((p) => p.target);
                  if (first?.target) attend(first.target);
                  return;
                }
                onSubmit();
                onOpenChange(false);
              }}
            >
              {creating ? createAction : editAction}
            </Button>
          )}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { SheetSection, SheetSectionRemove } from "@/components/side-sheet/parts";
import { RuleFrequencyPicker, blankFrequency, type RuleFrequency } from "./threepl/RuleFrequency";

/*
  RECURRING ORDER, AS THE 3PL LOAD ORDER (Pavan, 2026-10-20) — an optional
  section on every order sheet that can repeat: a dashed "Add" row until it's
  asked for, then the recurring rule's own frequency unit in a box, removed
  with the section's minus. One unit for every module, so a repeat is set the
  same way wherever it's set.
*/
export function RecurringOrderSection({
  on,
  schedule,
  plannedDay,
  onChange,
  onRemove,
  locked,
  title = "Recurring order",
  id,
}: {
  on: boolean;
  schedule?: RuleFrequency | null;
  /** The planned date's weekday — a new repeat starts on it, weekly. */
  plannedDay?: number;
  /** Turned on, or changed — the unit as it now stands. */
  onChange: (f: RuleFrequency) => void;
  onRemove: () => void;
  locked?: boolean;
  title?: string;
  id?: string;
}) {
  if (locked && !on) return null;
  return (
    <SheetSection
      id={id}
      title={title}
      action={on && !locked ? <SheetSectionRemove label={`Remove ${title.toLowerCase()}`} onClick={onRemove} /> : undefined}
    >
      {!on ? (
        <div className="flex items-center justify-between gap-4 rounded-md border border-dashed border-fp-outline-1 px-4 py-3">
          <span className="text-sm text-foreground">Add Recurring Order</span>
          <Button
            variant="outline"
            size="sm"
            onClick={() => onChange(schedule ?? { ...blankFrequency(), days: [plannedDay ?? new Date().getDay()] })}
          >
            <Plus /> Add
          </Button>
        </div>
      ) : (
        <fieldset disabled={locked} className="min-w-0 rounded-md border border-fp-outline-1 p-4">
          <RuleFrequencyPicker value={schedule ?? blankFrequency()} onChange={onChange} />
        </fieldset>
      )}
    </SheetSection>
  );
}

import { cn } from "@/lib/utils";
import * as React from "react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Pill } from "@/components/ui/pill";
import { DateFilter } from "./DateFilter";
import { FUEL_ORDERS, dateKeyOf, startOfDay } from "./data";
import { BarColumns, BarList, Panel, StatTile, DASHBOARD_GROUND } from "./DashboardParts";
import type { FuelOrder } from "./types";
import { useUnitShort } from "./salesSettings";

/*
  SALES DASHBOARD (Pavan, 2026-10-05) — the module's overview and its landing
  page. ONE DAY AT A TIME, because Fuel Orders is: a dispatcher works a day
  and steps through days, and a dashboard over a week would open on a list
  that can only show one of them. Every press opens Orders on its Fuel Orders
  line (Pavan, 2026-10-07), on that day, narrowed with its own column boxes.

  WHAT IT ASKS: how much is going out and how much of it has a driver · who
  is carrying it · what kind of work · what product · for whom · what is
  still waiting.
*/

export interface SalesDrill {
  date: Date;
  /** Orders' column boxes — column key → text. */
  colFilters: Record<string, string>;
}

const GAL = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });

export function SalesDashboard({
  onDrill,
  onOpenOrder,
}: {
  onDrill: (d: SalesDrill) => void;
  onOpenOrder: (id: string, date: Date) => void;
}) {
  const [date, setDate] = React.useState(() => startOfDay(new Date()));
  /* THE PRIMARY UNIT'S LABEL — Sales Settings › Preferences (2026-10-07). */
  const unit = useUnitShort();
  const gal = (n: number) => `${GAL.format(n)} ${unit}`;
  const key = dateKeyOf(date);
  const rows = React.useMemo(() => FUEL_ORDERS.filter((r) => r.dateKey === key), [key]);
  const drill = (colFilters: Record<string, string> = {}) => onDrill({ date, colFilters });

  const unassigned = rows.filter((r) => !r.driver);
  const rush = rows.filter((r) => r.tags.includes("Rush"));
  const volume = rows.reduce((s, r) => s + r.qtyGal, 0);
  const extraction = rows.filter((r) => r.type.label === "Extraction").length;

  const count = (n: number) => `${n} ${n === 1 ? "order" : "orders"}`;
  const group = <K extends string>(
    keyOf: (r: FuelOrder) => K[],
    value: (mine: FuelOrder[]) => number
  ) => {
    const keys = [...new Set(rows.flatMap(keyOf))];
    return keys
      .map((k) => {
        const mine = rows.filter((r) => keyOf(r).includes(k));
        return { k, mine, value: value(mine) };
      })
      .sort((a, b) => b.value - a.value);
  };

  /* Who is carrying it — gallons per driver, the unassigned last. */
  const byDriver = group((r) => [r.driver?.name ?? "Unassigned"], (m) =>
    m.reduce((s, r) => s + r.qtyGal, 0)
  ).map((g) => ({
    key: g.k,
    label: g.k,
    value: g.value,
    detail: `${gal(g.value)} · ${count(g.mine.length)}`,
    onOpen: () => drill({ driver: g.k }),
  }));

  /* What kind of work — delivery or extraction. */
  const byType = group((r) => [r.type.label], (m) => m.length).map((g) => ({
    key: g.k,
    label: g.k,
    value: g.value,
    detail: count(g.value),
    onOpen: () => drill({ type: g.k }),
  }));

  /* What product — orders carrying each. */
  const byProduct = group((r) => r.products.map((p) => p.name), (m) => m.length)
    .slice(0, 8)
    .map((g) => ({
      key: g.k,
      label: g.k,
      value: g.value,
      detail: count(g.value),
      onOpen: () => drill({ products: g.k }),
    }));

  /* For whom — gallons ordered. */
  const byCustomer = group((r) => [r.customer.title], (m) =>
    m.reduce((s, r) => s + r.qtyGal, 0)
  )
    .slice(0, 6)
    .map((g) => ({
      key: g.k,
      label: g.k,
      value: g.value,
      detail: `${gal(g.value)} · ${count(g.mine.length)}`,
      onOpen: () => drill({ customer: g.k }),
    }));

  /* When in the day — orders per planned hour. */
  const hourOf = (r: FuelOrder) => {
    const m = r.planned?.time.match(/^(\d{1,2}):\d{2}\s*(AM|PM)$/i);
    if (!m) return null;
    return (Number(m[1]) % 12) + (m[2].toUpperCase() === "PM" ? 12 : 0);
  };
  const buckets = [
    { key: "early", label: "Before 6a", from: 0, to: 6 },
    { key: "morning", label: "6a–12p", from: 6, to: 12 },
    { key: "afternoon", label: "12p–6p", from: 12, to: 18 },
    { key: "evening", label: "After 6p", from: 18, to: 24 },
    { key: "none", label: "Not planned", from: -1, to: -1 },
  ].map((b) => {
    const n = rows.filter((r) => {
      const h = hourOf(r);
      return b.from < 0 ? h === null : h !== null && h >= b.from && h < b.to;
    }).length;
    return { key: b.key, label: b.label, value: n, detail: count(n) };
  });

  const waiting = [...rush, ...unassigned.filter((r) => !rush.includes(r))];

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto">
      <div className="flex shrink-0 items-center justify-end">
        <DateFilter value={date} onChange={setDate} />
      </div>

      {/* WHITE CARDS ON THEIR GROUND — see DashboardParts. */}
      <div className={cn("flex shrink-0 flex-col gap-3", DASHBOARD_GROUND)}>
      <div className="grid shrink-0 grid-cols-2 gap-3 lg:grid-cols-4">
        <StatTile
          label="Fuel orders"
          value={rows.length.toLocaleString()}
          note={`${rows.length - unassigned.length} with a driver`}
          onOpen={() => drill()}
        />
        <StatTile
          label="Volume ordered"
          value={gal(volume)}
          note={`${extraction} extraction ${extraction === 1 ? "job" : "jobs"}`}
          onOpen={() => drill()}
        />
        <StatTile
          label="Waiting on a driver"
          value={unassigned.length.toLocaleString()}
          note={rows.length ? `${Math.round((unassigned.length / rows.length) * 100)}% of the day` : "Nothing today"}
          onOpen={() => drill({ driver: "Unassigned" })}
        />
        <StatTile
          label="Rush"
          value={rush.length.toLocaleString()}
          note="tagged Rush"
          onOpen={() => drill({ tags: "Rush" })}
        />
      </div>

      <div className="grid shrink-0 gap-3 lg:grid-cols-2">
        <Panel title="Driver load" aside="gallons per driver">
          <BarList data={byDriver} format={gal} />
        </Panel>
        <Panel title="Orders by planned time" aside={`${rows.length} orders`}>
          <BarColumns data={buckets} />
        </Panel>
      </div>

      <div className="grid shrink-0 gap-3 lg:grid-cols-3">
        <Panel title="Delivery vs extraction" aside="share of orders">
          <BarList data={byType} share />
        </Panel>
        <Panel title="Product demand" aside="orders carrying each">
          <BarList data={byProduct} />
        </Panel>
        <Panel title="Top customers" aside="gallons ordered">
          <BarList data={byCustomer} format={gal} />
        </Panel>
      </div>

      <Panel title="Rush and unassigned" aside={count(waiting.length)}>
        {waiting.length === 0 ? (
          <p className="py-6 text-center text-sm text-muted-foreground">
            Every order has a driver.
          </p>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="hover:bg-transparent">
                <TableHead className="px-2 text-xs">Order</TableHead>
                <TableHead className="px-2 text-xs">Customer</TableHead>
                <TableHead className="px-2 text-xs">Type</TableHead>
                <TableHead className="px-2 text-xs">Driver</TableHead>
                <TableHead className="px-2 text-xs">Qty</TableHead>
                <TableHead className="px-2 text-xs">Planned</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {waiting.slice(0, 10).map((r) => (
                <TableRow
                  key={r.id}
                  className="cursor-pointer"
                  onClick={() => onOpenOrder(r.id, date)}
                >
                  <TableCell className="px-2 tabular-nums">{r.orderNo}</TableCell>
                  <TableCell className="max-w-48 truncate px-2">{r.customer.title}</TableCell>
                  <TableCell className="px-2">{r.type.label}</TableCell>
                  <TableCell className="px-2">
                    {r.driver ? (
                      r.driver.name
                    ) : (
                      <span className="text-muted-foreground">Unassigned</span>
                    )}
                    {r.tags.includes("Rush") && (
                      <Pill className="ml-2">
                        Rush
                      </Pill>
                    )}
                  </TableCell>
                  <TableCell className="px-2 tabular-nums">{gal(r.qtyGal)}</TableCell>
                  <TableCell className="px-2 tabular-nums text-muted-foreground">
                    {r.planned?.time ?? "—"}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </Panel>
      </div>
    </div>
  );
}

