import * as React from "react";
import {
  Ban,
  DollarSign,
  History as HistoryIcon,
  Layers,
  Mail,
  Pencil,
  Plus,
  Truck,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";

/*
  THE RECORD SHEET'S TWO SHARED CARDS (Pavan, 2026-10-07 — ux §Record sheets).
  Lifted out of the 3PL order sheet unchanged, so every module's sheet shows
  what its form computes in the SUMMARY CARD and its history in the ACTIVITY
  CARD, instead of each drawing its own. The 3PL sheet imports these back; a
  change here is a change there.
*/

/** The trail's clock: the day and the minute, which is the grain anyone asks
 *  a history in. Seconds would be precision nobody uses. */
const AUDIT_FMT = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  hour: "numeric",
  minute: "2-digit",
});

/**
 * WHAT AN ACTIVITY ENTRY IS ABOUT, from what it says.
 *
 * The audit trail is one line of prose per change, which is the right thing to
 * store and the wrong thing to scan: six lines of identical grey text hide the
 * one that matters. A mark gives each entry a kind at a glance — money, a
 * message that left the building, something added, something that moved
 * backwards — and money and creation get a tint, because those are the two the
 * eye should catch on the way past.
 */
function auditMark(text: string): { icon: React.ReactNode; tone: string } {
  const t = text.toLowerCase();
  if (/\bquote|price|\$|margin|rate/.test(t))
    return {
      icon: <DollarSign />,
      tone: "border-status-success/30 bg-status-success/10 text-status-success",
    };
  if (/invit|sent|notif|email|acknowled/.test(t))
    return {
      icon: <Mail />,
      tone: "border-fp-banner-accent-info/30 bg-fp-banner-accent-info/10 text-fp-banner-accent-info",
    };
  if (/created/.test(t))
    return {
      icon: <Plus />,
      tone: "border-status-success/30 bg-status-success/10 text-status-success",
    };
  if (/cancel|remov|delet|block/.test(t))
    return {
      icon: <Ban />,
      tone: "border-status-failed/30 bg-status-failed/10 text-status-failed",
    };
  if (/load order|terminal|supplier/.test(t))
    return { icon: <Layers />, tone: "border-border bg-card text-muted-foreground" };
  if (/asset|product|gal/.test(t))
    return { icon: <Truck />, tone: "border-border bg-card text-muted-foreground" };
  return { icon: <Pencil />, tone: "border-border bg-card text-muted-foreground" };
}

/**
 * A label/value row in a rail card, and — where there is one — the ARITHMETIC
 * BEHIND THE FIGURE, on hover.
 *
 * A total in a summary is a claim, and the reader's next question is always
 * the same: made of what? Without it the answer is a table two sections away,
 * and comparing the two means holding one number in your head while you scroll
 * to the other. A tooltip puts the working where the claim is. It is NOT a
 * substitute for the tables — those are where the figures are TYPED — it is
 * the read-only account of how they add up.
 */
export function RailRow({
  label,
  value,
  breakdown,
  variant = "rail",
}: {
  label: React.ReactNode;
  value: React.ReactNode;
  /** One line per contribution. Rendered only when there is something to show. */
  breakdown?: { label: string; value: string }[];
  /** `line` / `total` — the Summary card's statement rows (2026-10-05). */
  variant?: "rail" | "line" | "total";
}) {
  const row = (
    <div
      className={cn(
        "flex items-baseline justify-between gap-3",
        variant === "rail" ? "px-4 py-2.5" : "py-1",
        /* A TOTAL NEVER CUTS ITS LABEL (Pavan, 2026-10-20) — too long for
           one line, the figure drops under it, right-aligned. */
        variant === "total" && "flex-wrap gap-y-0.5",
        breakdown?.length && "cursor-help"
      )}
    >
      <dt
        className={cn(
          "min-w-0 truncate",
          variant === "rail" && "shrink-0 text-xs text-muted-foreground",
          variant === "line" && "text-sm text-foreground",
          variant === "total" && "shrink-0 overflow-visible text-base font-medium text-foreground"
        )}
      >
        {label}
      </dt>
      <dd
        className={cn(
          "min-w-0 shrink-0 truncate tabular-nums",
          variant === "rail" && "text-sm text-foreground",
          variant === "line" && "text-sm text-muted-foreground",
          variant === "total" && "ml-auto text-base font-semibold text-foreground",
          /* THE DOTTED RULE IS THE WHOLE AFFORDANCE. A figure that explains
             itself has to say so without a second control beside it. */
          breakdown?.length &&
            "underline decoration-dotted decoration-muted-foreground underline-offset-4"
        )}
      >
        {value}
      </dd>
    </div>
  );
  if (!breakdown?.length) return row;
  return (
    <Tooltip>
      <TooltipTrigger asChild>{row}</TooltipTrigger>
      <TooltipContent side="left" className="max-w-xs">
        <span className="flex flex-col gap-1">
          {breakdown.map((b) => (
            <span key={b.label} className="flex items-baseline justify-between gap-4">
              <span className="min-w-0 truncate">{b.label}</span>
              <span className="shrink-0 tabular-nums">{b.value}</span>
            </span>
          ))}
        </span>
      </TooltipContent>
    </Tooltip>
  );
}

/**
 * A rail card: the same bordered block `SheetSection` draws, with its own
 * header band and a flush body — the rail is nothing but read-outs, so every
 * card in it is a list running edge to edge.
 */
export function RailCard({
  title,
  icon,
  action,
  children,
}: {
  title: string;
  icon?: React.ReactNode;
  action?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <section className="shrink-0 overflow-hidden rounded-lg border border-border">
      <div className="flex items-center justify-between gap-3 border-b border-border bg-fp-surface-1a px-4 py-2.5">
        <h3 className="flex items-center gap-1.5 text-sm font-semibold text-muted-foreground">
          {icon && <span className="[&_svg]:size-3.5">{icon}</span>}
          {title}
        </h3>
        {action}
      </div>
      {children}
    </section>
  );
}

/**
 * THE SUMMARY CARD — the 3PL "Quotation summary" shell (Pavan, 2026-10-07):
 * a tinted frame, the title on the frame, and one inner card that holds the
 * label · value rows with the headline figure last.
 */
export function SummaryCard({
  title,
  children,
  fill = false,
}: {
  title: string;
  children: React.ReactNode;
  /** GROW TO THE COLUMN'S HEIGHT (Pavan, 2026-10-20) — when it's the only
      card in the rail; put `mt-auto` on what should sit at its bottom. */
  fill?: boolean;
}) {
  return (
    <section className={`${fill ? "flex min-h-64 flex-1 flex-col" : "shrink-0"} rounded-xl bg-[linear-gradient(170deg,color-mix(in_oklab,var(--pastel-violet)_55%,var(--fp-surface-1a))_0%,color-mix(in_oklab,var(--pastel-rose)_30%,var(--fp-surface-1a))_28%,var(--fp-surface-1a)_60%)] p-1 dark:bg-[linear-gradient(170deg,color-mix(in_oklab,var(--pastel-violet-foreground)_70%,var(--fp-surface-1a))_0%,color-mix(in_oklab,var(--pastel-rose-foreground)_35%,var(--fp-surface-1a))_30%,var(--fp-surface-1a)_65%)]`}>
      <h3 className="px-3 pt-2 pb-2.5 text-base font-semibold text-foreground">{title}</h3>
      <div className={`flex flex-col gap-3 rounded-lg border border-border bg-fp-surface-1b p-3${fill ? " min-h-0 flex-1 overflow-auto" : ""}`}>
        {children}
      </div>
    </section>
  );
}

/** One entry of a record's history — every module's audit has this shape. */
export interface TimelineEntry {
  at: string;
  by: string;
  changes: string[];
}

/**
 * THE ACTIVITY CARD — the 3PL rail card with its timeline (Pavan,
 * 2026-10-07): the six latest saves, each change on its own mark.
 */
export function ActivityCard({
  entries,
  timeZone,
}: {
  entries?: TimelineEntry[];
  /** Print the stamps in this zone — Sales' Preferences (2026-10-07). */
  timeZone?: string;
}) {
  const fmt = timeZone
    ? new Intl.DateTimeFormat("en-US", {
        month: "short",
        day: "numeric",
        year: "numeric",
        hour: "numeric",
        minute: "2-digit",
        timeZone,
      })
    : AUDIT_FMT;
  return (
    <RailCard title="Activity" icon={<HistoryIcon />}>
      {!entries || entries.length === 0 ? (
        <p className="px-4 py-3 text-sm text-muted-foreground">
          Nothing has changed yet.
        </p>
      ) : (
        /* A TIMELINE, NOT A LIST OF RULED ROWS. Six entries separated
           by hairlines is a table of one column; a line running down
           the marks says the obvious thing about an audit trail —
           these happened in an order, most recent first — without a
           word of chrome.

           WHAT CHANGED LEADS, WHO AND WHEN FOLLOWS. The reader is
           looking for the event; the name and the timestamp are what
           they check once they have found it. */
        <ol className="flex flex-col px-4 py-3">
          {[...entries]
            .reverse()
            .slice(0, 6)
            .flatMap((e, i) =>
              e.changes.map((c, j) => ({ e, c, key: `${e.at}-${i}-${j}` }))
            )
            .map(({ e, c, key }, idx, all) => {
              const mark = auditMark(c);
              return (
                <li key={key} className="relative flex gap-3 pb-4 last:pb-0">
                  {/* The connector stops at the last mark rather than
                      running off the end of the list. */}
                  {idx < all.length - 1 && (
                    <span
                      aria-hidden
                      className="absolute top-7 bottom-0 left-[13px] w-px bg-border"
                    />
                  )}
                  <span
                    className={cn(
                      "relative z-10 flex size-7 shrink-0 items-center justify-center rounded-full border [&_svg]:size-3.5",
                      mark.tone
                    )}
                  >
                    {mark.icon}
                  </span>
                  <span className="flex min-w-0 flex-col gap-0.5 pt-0.5">
                    <span className="text-sm text-foreground">{c}</span>
                    <span className="text-xs text-muted-foreground">
                      {fmt.format(new Date(e.at))} · {e.by}
                    </span>
                  </span>
                </li>
              );
            })}
        </ol>
      )}
    </RailCard>
  );
}

import * as React from "react";
import { toast } from "sonner";
import { SearchX } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { TablePagination } from "@/components/tables-layout/TablePagination";
import { FuelOrdersViewBar } from "./FuelOrdersViewBar";
import { ListToolbar, ColumnSearchChip, FilterChips, type ListView, useViewBar, ViewStatement } from "./ListToolbar";
import { ListFilters, type ListFacet } from "./ListFilters";
import { ExportSheet, type ExportFilterRow } from "./ExportSheet";
import { ListTable, type ListColumn, type ListSort } from "./ListTable";
import { useSavedViews } from "./useSavedViews";

/*
  THE STANDARD LIST — the Unified View list (Quotes / Orders) as one piece,
  so every table page has the same parts in the same places (the Customer
  Portal's lists, Service Work's reference pages — Pavan, 2026-10-22): the
  view row with saved views, a segment and the CTA; the toolbar with search,
  Filters, search by column and the column menu; the chip shelf; the table;
  pagination; export that asks first. One view (a table), so no view switch.

  A screen hands it its rows, columns, what each column prints, its facets,
  and what Create and opening a row do.
*/

interface ViewState {
  /** THE DISPLAY IT OPENS IN — table, board or map (Pavan, 2026-10-21). */
  mode?: ListView;
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  pageSize: number;
  colScope: string;
  colQuery: string;
  colFilters: Record<string, string>;
  columnOrder: string[];
  columnWidths: Record<string, number>;
  facets: string[];
}

const keyOf = (s: ViewState) =>
  JSON.stringify({
    ...s,
    mode: s.mode ?? "table",
    hidden: [...s.hidden].sort(),
    facets: [...s.facets].sort(),
    colFilters: Object.fromEntries(
      Object.entries(s.colFilters)
        .filter(([, v]) => v.trim() !== "")
        .sort(([a], [b]) => a.localeCompare(b))
    ),
  });

export interface StandardListProps<R, K extends string> {
  rows: R[];
  /** Must include the pinned `actions` column. */
  columns: ListColumn<K>[];
  defaultHidden?: K[];
  rowId: (r: R) => string;
  /** What a column PRINTS — searched, filtered by the header boxes, sorted. */
  text: (r: R, key: K) => string;
  /** A sort that is not the printed text — numbers, lifecycle position. */
  sortValue?: (r: R, key: K) => string | number | undefined;
  renderCell: (r: R, key: K) => React.ReactNode;
  facets: ListFacet[];
  /** The values a row has for a facet — several for a many-valued field. */
  facetValues: (r: R, facet: string) => string[];
  storageKey: string;
  noun: string;
  nounOne: string;
  searchPlaceholder: string;
  /** Omit both for a list the customer does not create in (Invoices). */
  ctaLabel?: string;
  onCreate?: () => void;
  /** Above the view row — a page's overview cards (Orders' layout). */
  above?: React.ReactNode;
  /** The alert banner — above the toolbar, as in every module (2026-10-23). */
  banner?: React.ReactNode;
  /**
   * Sets the facet filter from outside — a banner title applies its filter.
   * Ids are `facet:value`; `n` changes on every press.
   */
  applyFacets?: { ids: string[]; n: number };
  /** Reports the facet filter as it changes — a banner knows its filter is on. */
  onFacetsChange?: (ids: string[]) => void;
  /** Omit for a list whose rows open nothing (yet). */
  onOpen?: (r: R) => void;
  openLabel: (r: R) => string;
  emptyIcon: React.ReactNode;
  /** Beside the Filters button — e.g. Recommendations (3PL's place for it). */
  afterFilters?: React.ReactNode;
  segments?: { key: string; label: string }[];
  segmentValue?: string;
  onSegmentChange?: (key: string) => void;
}

export function StandardList<R, K extends string>({
  rows,
  columns,
  defaultHidden = [],
  rowId,
  text,
  sortValue,
  renderCell,
  facets,
  facetValues,
  storageKey,
  noun,
  nounOne,
  searchPlaceholder,
  ctaLabel,
  onCreate,
  above,
  banner,
  applyFacets,
  onFacetsChange,
  onOpen,
  openLabel,
  emptyIcon,
  segments,
  segmentValue,
  onSegmentChange,
  afterFilters,
}: StandardListProps<R, K>) {
  const labelled = columns.filter((c) => c.label);
  const firstKey = labelled[0]?.key ?? "";
  const toggleColumns = labelled.map((c) => ({ key: c.key, label: c.label }));
  const defaults: ViewState = {
    mode: "table",
    search: "",
    sortKey: null,
    sortDir: null,
    hidden: defaultHidden,
    pageSize: 25,
    colScope: firstKey,
    colQuery: "",
    colFilters: {},
    columnOrder: [],
    columnWidths: {},
    facets: [],
  };
  const [search, setSearch] = React.useState("");
  const [sort, setSort] = React.useState<ListSort<K> | null>(null);
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(25);
  const [hidden, setHidden] = React.useState<Set<K>>(() => new Set(defaultHidden));
  const [colScope, setColScope] = React.useState<string>(firstKey);
  const [colQuery, setColQuery] = React.useState("");
  const [view, setView] = React.useState<ListView>("table");
  const [columnOrder, setColumnOrder] = React.useState<string[]>([]);
  const [columnWidths, setColumnWidths] = React.useState<Record<string, number>>({});
  const [colFilters, setColFilters] = React.useState<Record<string, string>>({});
  const [colFiltersOpen, setColFiltersOpen] = React.useState(false);
  const [facetSel, setFacetSel] = React.useState<ReadonlySet<string>>(new Set());
  React.useEffect(() => {
    if (!applyFacets) return;
    setFacetSel(new Set(applyFacets.ids));
    setPage(1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [applyFacets?.n]);
  React.useEffect(() => {
    onFacetsChange?.([...facetSel]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [facetSel]);
  const [exporting, setExporting] = React.useState(false);
  const activeColFilters = React.useMemo(
    () => Object.entries(colFilters).filter(([, v]) => v.trim() !== ""),
    [colFilters]
  );

  const current: ViewState = {

    mode: view,
    search,
    sortKey: sort?.key ?? null,
    sortDir: sort?.dir ?? null,
    hidden: [...hidden],
    pageSize,
    colScope,
    colQuery,
    colFilters,
    columnOrder,
    columnWidths,
    facets: [...facetSel],
  };
  const applyState = (s: ViewState) => {
    setView(s.mode ?? "table");
    setSearch(s.search);
    setSort(s.sortKey && s.sortDir ? { key: s.sortKey as K, dir: s.sortDir } : null);
    setHidden(new Set(s.hidden as K[]));
    setPageSize(s.pageSize);
    setColScope(s.colScope);
    setColQuery(s.colQuery);
    setColFilters(s.colFilters);
    setColFiltersOpen(Object.values(s.colFilters).some((v) => v.trim() !== ""));
    setColumnOrder(s.columnOrder);
    setColumnWidths(s.columnWidths);
    setFacetSel(new Set(s.facets));
    setPage(1);
  };
  const savedViews = useSavedViews({ current, defaultState: defaults, keyOf, apply: applyState, storageKey });

  const q = search.trim().toLowerCase();
  const cq = colQuery.trim().toLowerCase();
  const searched = React.useMemo(
    () =>
      rows.filter(
        (r) =>
          (!q || labelled.some((c) => text(r, c.key).toLowerCase().includes(q))) &&
          (!cq || text(r, colScope as K).toLowerCase().includes(cq)) &&
          activeColFilters.every(([key, value]) =>
            text(r, key as K).toLowerCase().includes(value.trim().toLowerCase())
          )
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [rows, q, cq, colScope, activeColFilters, text]
  );
  /* Facets AND across, OR within one. */
  const narrowFacets = React.useCallback(
    (sel: ReadonlySet<string>) => {
      if (sel.size === 0) return searched;
      return searched.filter((r) =>
        facets.every((f) => {
          const mine = [...sel].filter((id) => id.startsWith(`${f.key}:`));
          return mine.length === 0 || facetValues(r, f.key).some((v) => sel.has(`${f.key}:${v}`));
        })
      );
    },
    [searched, facets, facetValues]
  );
  const filtered = React.useMemo(() => narrowFacets(facetSel), [narrowFacets, facetSel]);
  /* THE VIEW BAR — the table's and the board's tools render into it. */
  const bar = useViewBar();
  const sorted = React.useMemo(() => {
    if (!sort) return filtered;
    const dir = sort.dir === "asc" ? 1 : -1;
    const val = (r: R) => sortValue?.(r, sort.key) ?? text(r, sort.key).toLowerCase();
    return [...filtered].sort((a, b) => {
      const x = val(a);
      const y = val(b);
      return (x < y ? -1 : x > y ? 1 : 0) * dir;
    });
  }, [filtered, sort, sortValue, text]);
  const pageRows = sorted.slice((page - 1) * pageSize, page * pageSize);

  const onSort = (key: K) => {
    setSort((prev) => {
      if (prev?.key !== key) return { key, dir: "asc" };
      if (prev.dir === "asc") return { key, dir: "desc" };
      return null;
    });
    setPage(1);
  };

  const narrowed = q !== "" || cq !== "" || facetSel.size > 0 || activeColFilters.length > 0;
  const nothing = sorted.length === 0 && !colFiltersOpen;
  const dropFacets = (gone: string[]) => {
    const next = new Set(facetSel);
    for (const id of gone) next.delete(id);
    setFacetSel(next);
    setPage(1);
  };
  const exportFilters: ExportFilterRow[] = [
    {
      key: "search",
      label: "Search",
      values: search.trim() ? [{ value: search.trim(), onRemove: () => setSearch("") }] : [],
    },
    {
      key: "colSearch",
      label: toggleColumns.find((f) => f.key === colScope)?.label ?? "Column",
      values: colQuery.trim() ? [{ value: colQuery.trim(), onRemove: () => setColQuery("") }] : [],
    },
    ...facets.map((f) => {
      const mine = [...facetSel].filter((id) => id.startsWith(`${f.key}:`));
      return {
        key: f.key,
        label: f.label,
        values: mine.map((id) => ({ value: id.slice(id.indexOf(":") + 1), onRemove: () => dropFacets([id]) })),
        onRemoveAll: () => dropFacets(mine),
      };
    }),
  ];

  const filtersControl = (full?: boolean) => (
    <ListFilters
      facets={facets}
      value={facetSel}
      countFor={(sel) => narrowFacets(sel).length}
      onApply={(sel) => {
        setFacetSel(sel);
        setPage(1);
      }}
      fullWidth={full}
    />
  );

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      {above && <div className="mb-8 shrink-0">{above}</div>}
      <FuelOrdersViewBar
        {...savedViews}
        ctaLabel={ctaLabel}
        onCreateOrder={onCreate}
        onExport={() => setExporting(true)}
        segments={segments}
        segmentValue={segmentValue}
        onSegmentChange={onSegmentChange}
      />

      {banner && <div className="mt-4 shrink-0">{banner}</div>}
      <div className="mt-4 shrink-0">
        <ListToolbar
          viewToolsInto={bar.into}
          viewStatement={<ViewStatement count={sorted.length} one={nounOne} many={noun} />}
          searchValue={search}
          onSearchChange={(v) => {
            setSearch(v);
            setPage(1);
          }}
          searchPlaceholder={searchPlaceholder}
          filters={filtersControl()}
          afterFilters={afterFilters}
          columns={toggleColumns}
          hiddenColumns={hidden}
          columnOrder={columnOrder}
          onReorderColumns={setColumnOrder}
          onToggleColumn={(k) =>
            setHidden((prev) => {
              const next = new Set(prev);
              if (next.has(k)) next.delete(k);
              else next.add(k);
              return next;
            })
          }
          onShowAllColumns={() => setHidden(new Set())}
          searchFields={toggleColumns}
          colScope={colScope}
          onColScopeChange={(v) => {
            setColScope(v);
            setPage(1);
          }}
          colQuery={colQuery}
          onColQueryChange={(v) => {
            setColQuery(v);
            setPage(1);
          }}
          columnFiltersOpen={colFiltersOpen}
          onToggleColumnFilters={() =>
            setColFiltersOpen((open) => {
              if (open) {
                setColFilters({});
                setPage(1);
              }
              return !open;
            })
          }
          columnFilterCount={activeColFilters.length}
          view={view}
          onViewChange={setView}
          showGroupBy={false}
        />
        <FilterChips
          facets={facets}
          selected={facetSel}
          onChange={(next) => {
            setFacetSel(next);
            setPage(1);
          }}
        >
          <ColumnSearchChip
            className={facetSel.size > 0 ? "" : undefined}
            searchFields={toggleColumns}
            colScope={colScope}
            colQuery={colQuery}
            onClear={() => setColQuery("")}
          />
        </FilterChips>
      </div>


      <div className="relative mt-4 min-h-0 flex-1">
        {nothing ? (
          <Empty className="h-full">
            <EmptyHeader>
              <EmptyMedia variant="icon">{narrowed ? <SearchX /> : emptyIcon}</EmptyMedia>
              <EmptyTitle>{narrowed ? `No matching ${noun}` : `No ${noun} yet`}</EmptyTitle>
              {narrowed && (
                <EmptyDescription>{`${rows.length} ${noun} in all. Clear the search or a filter to see them.`}</EmptyDescription>
              )}
            </EmptyHeader>
            {(narrowed || ctaLabel) && <EmptyContent>
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  if (narrowed) {
                    setSearch("");
                    setColQuery("");
                    setColFilters({});
                    setFacetSel(new Set());
                  } else onCreate?.();
                  setPage(1);
                }}
              >
                {narrowed ? "Clear all" : ctaLabel}
              </Button>
            </EmptyContent>}
          </Empty>
        ) : (
          <ListTable
            topBar={bar.slot}
            rows={pageRows}
            columns={columns}
            hidden={hidden}
            sort={sort}
            onSort={onSort}
            rowId={rowId}
            renderCell={renderCell}
            actionsKey={"actions" as K}
            columnOrder={columnOrder}
            onReorderColumns={setColumnOrder}
            columnWidths={columnWidths}
            onResizeColumns={setColumnWidths}
            openLabel={openLabel}
            onOpenRow={onOpen}
            showColumnFilters={colFiltersOpen}
            columnFilters={colFilters}
            onColumnFilterChange={(key, value) => {
              setColFilters((prev) => ({ ...prev, [key]: value }));
              setPage(1);
            }}
          />
        )}
      </div>

      <ExportSheet
        open={exporting}
        onOpenChange={setExporting}
        title={`Export ${noun[0].toUpperCase()}${noun.slice(1)}`}
        noun={noun}
        nounOne={nounOne}
        count={sorted.length}
        filtersControl={filtersControl(true)}
        filters={exportFilters}
        onExport={(format) => {
          setExporting(false);
          toast.success(`Exporting ${sorted.length} ${sorted.length === 1 ? nounOne : noun} as .${format}`);
        }}
      />

      <div className="mt-4 shrink-0">
        <TablePagination
          page={page}
          pageSize={pageSize}
          total={sorted.length}
          onPageChange={setPage}
          onPageSizeChange={(size) => {
            setPageSize(size);
            setPage(1);
          }}
        />
      </div>
    </div>
  );
}

import * as React from "react";
import { Plus, X } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";

/**
 * Token multi-select — chips with a remove ×, plus an "+ Add …" affordance that
 * opens a searchable list with a check on the chosen options.
 *
 * This is the DS's `form-layout/MultiSelect` (Figma "Dropdown … Add Margins",
 * 27593:15012) — markup, sizes and classes copied verbatim so the two cannot
 * drift. The only change is the API: the DS version hardcodes its option list
 * and label and keeps selection in private state, so it can't be pointed at
 * anything. This one takes `options`, `value`, `onChange` and `addLabel`.
 *
 * DS FOLLOW-UP: generalise `MultiSelect` to take those four props and delete
 * this file. It is a copy only because the DS component cannot currently be
 * reused, not because this screen needs anything different.
 */

/** Small circular initial badge used as a token / item leading glyph. */
function InitialBadge({ label }: { label: string }) {
  return (
    <span className="flex size-4 items-center justify-center rounded-full bg-accent text-[9px] font-semibold uppercase">
      {label[0]}
    </span>
  );
}

export interface TokenMultiSelectProps {
  options: string[];
  value: string[];
  onChange: (next: string[]) => void;
  /** Trailing affordance, e.g. "Add tags". */
  addLabel: string;
  /** Search field placeholder, e.g. "Search tags...". */
  searchPlaceholder: string;
  /** Sits edge to edge inside a card: no border, no radius, no inset of its
   *  own — the card's edge is its edge. */
  flush?: boolean;
  /** Chips drawn with a blue outline — e.g. the products marked winter blend. */
  highlighted?: string[];
  /** A small word shown inside a highlighted chip, e.g. "Winter blend". */
  highlightLabel?: string;
  /** When set, clicking a chip calls this instead of opening the list. */
  onChipClick?: (opt: string) => void;
  /**
   * Bump it and every chip blinks a blue outline ONCE — "these are clickable
   * now". 0 never blinks.
   */
  flashKey?: number;
}

export function TokenMultiSelect({
  options,
  value,
  onChange,
  addLabel,
  searchPlaceholder,
  flush,
  highlighted,
  highlightLabel,
  onChipClick,
  flashKey = 0,
}: TokenMultiSelectProps) {
  const [open, setOpen] = React.useState(false);
  const [flashing, setFlashing] = React.useState(false);
  React.useEffect(() => {
    if (!flashKey) return;
    setFlashing(true);
    const t = window.setTimeout(() => setFlashing(false), 650);
    return () => window.clearTimeout(t);
  }, [flashKey]);

  const toggle = (opt: string) =>
    onChange(
      value.includes(opt) ? value.filter((o) => o !== opt) : [...value, opt]
    );

  const remove = (opt: string) => onChange(value.filter((o) => o !== opt));

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          type="button"
          className={cn(
            "flex min-h-11 w-full flex-wrap items-center gap-2 rounded-md border border-input bg-transparent px-2 py-2 text-left outline-none transition-colors",
            "hover:border-fp-outline-2 focus-visible:ring-2 focus-visible:ring-ring/50",
            "data-[state=open]:border-ring",
            /* FLUSH IS THE BOX, NOT THE CONTENT. The unit meets the card's
               edges, but the chips inside keep the card's 16px inset — a chip
               touching the edge reads as cut off. (Pavan, 2026-09-25.) */
            flush && "rounded-none border-0 px-4 py-2 hover:bg-fp-surface-1a focus-visible:ring-inset",
            value.length === 0 && "justify-center"
          )}
        >
          {value.map((opt) => (
            <span
              key={opt}
              role={onChipClick ? "button" : undefined}
              aria-pressed={onChipClick ? Boolean(highlighted?.includes(opt)) : undefined}
              onClick={
                onChipClick
                  ? (e) => {
                      e.stopPropagation();
                      e.preventDefault();
                      onChipClick(opt);
                    }
                  : undefined
              }
              className={cn(
                "inline-flex items-center gap-1.5 rounded-md border border-border bg-fp-surface-1b py-1 pr-1 pl-1.5 text-sm",
                onChipClick && "cursor-pointer hover:border-fp-outline-2",
                highlighted?.includes(opt) &&
                  "border-fp-banner-accent-info hover:border-fp-banner-accent-info",
                flashing && "fp-attention-info"
              )}
            >
              <InitialBadge label={opt} />
              {opt}
              {highlightLabel && highlighted?.includes(opt) && (
                <span className="rounded-sm bg-fp-banner-accent-info/10 px-1 text-xs text-fp-banner-accent-info">
                  {highlightLabel}
                </span>
              )}
              <span
                role="button"
                tabIndex={-1}
                aria-label={`Remove ${opt}`}
                onClick={(e) => {
                  e.stopPropagation();
                  remove(opt);
                }}
                className="flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:text-foreground"
              >
                <X className="size-3.5" />
              </span>
            </span>
          ))}
          <span className="inline-flex items-center gap-1 text-sm text-muted-foreground">
            <Plus className="size-4" />
            {addLabel}
          </span>
        </button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-(--radix-popover-trigger-width) p-0"
      >
        <Command>
          <CommandInput placeholder={searchPlaceholder} />
          <CommandList>
            <CommandEmpty>No options found.</CommandEmpty>
            <CommandGroup>
              {options.map((opt) => (
                <CommandItem
                  key={opt}
                  value={opt}
                  icon={<InitialBadge label={opt} />}
                  selected={value.includes(opt)}
                  // keep the menu open for multi-select; cmdk doesn't close it
                  onSelect={() => toggle(opt)}
                >
                  {opt}
                </CommandItem>
              ))}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

