export type AssetSortDir = "asc" | "desc";
export interface AssetTableSortState {
  key: AssetColumnKey;
  dir: AssetSortDir;
}

function sortValue(a: Asset, key: AssetColumnKey): string | number {
  switch (key) {
    case "asset":
      return a.displayName.toLowerCase();
    case "erpId":
      return a.erpId;
    case "hub":
      return a.hub.toLowerCase();
    case "los":
