/** Every stage, in the order an order moves through them. */
export const FUEL_ORDER_STAGES: CoreFuelStage[] = [
  "Requested",
  "Scheduled",
  "Dispatched",
  "Delivered",
  "Canceled",
];

/**
 * THE STAGE A DRIVER CHANGE LEAVES (2026-10-07). An order cannot be scheduled
 * without a driver, so picking one on a Requested order schedules it and
 * clearing it from a Scheduled one sends it back. Once it is on the road, done
 * or canceled, the driver no longer moves the stage.
 */
export function stageAfterDriver(
  status: FuelOrderStatus,
  hasDriver: boolean,
  /* THE STAGE BEFORE SCHEDULED, and whether the pick may schedule at all
     (Pavan, 2026-10-07). Sales Settings can put a stage in front of
     Scheduled, make Scheduled wait for an approval, or hold it for an
     accepted quote — `driverStage` in salesSettings.ts passes all three. */
  before: FuelOrderStatus = "Requested",
  maySchedule = true
): FuelOrderStatus {
  if (status === before && hasDriver && maySchedule) return "Scheduled";
  if (status === "Scheduled" && !hasDriver) return before;
  return status;
}

/**
 * SAMPLE STAGES — INVENTED. The source list only knew Assigned / Unassigned.
 * No driver = Requested. With a driver: past days are Delivered (a few
 * Canceled), today spreads over Scheduled, Dispatched and Delivered, and
 * later days are Scheduled.
 */
function seedStage(i: number, dayOffset: number, hasDriver: boolean): FuelOrderStatus {
  if (!hasDriver) return i % 11 === 5 ? "Canceled" : "Requested";
  if (dayOffset < 0) return i % 7 === 3 ? "Canceled" : "Delivered";
  if (dayOffset > 0) return "Scheduled";
  return (["Scheduled", "Dispatched", "Delivered"] as const)[i % 3];
}

/**
 * SAMPLE URGENCY — INVENTED (2026-10-07). The source list never showed the
 * flag, so every seventh order carries it: two of today's land early-morning
 * and still undispatched, so the overdue banner has something to count.
 */
const seedUrgent = (i: number) => i % 7 === 0;

/**
 * SAMPLE TIME IN STAGE — INVENTED (Pavan, 2026-10-07). How many hours ago
 * each order entered its stage, so the SLA flag has something to find: a few
 * Requested past a day, one Scheduled past two, some Dispatched past eight.
 */
function seedStageSince(i: number, stage: FuelOrderStatus): string {
  const hours =
    stage === "Requested"
      ? [2, 6, 30, 10, 14][i % 5]
      : stage === "Scheduled"
        ? [5, 20, 52, 12, 30, 8][i % 6]
        : stage === "Dispatched"
          ? [1, 3, 10, 4][i % 4]
          : 24;
  return new Date(Date.now() - hours * 3_600_000).toISOString();
}

/** The source list's total. Order numbers count down from the newest, as there. */
const TOTAL = 115;
const NEWEST_ORDER_NO = 4592866;

export const FUEL_ORDERS: FuelOrder[] = (() => {
  const today = startOfDay(new Date());
  return Array.from({ length: TOTAL }, (_, i) => {
    const { dayOffset, plannedTime, ...seed } = SEED[i % SEED.length];
    const when = addDays(today, dayOffset);
    return {
      ...seed,
      id: `fo-${i + 1}`,
      orderNo: String(NEWEST_ORDER_NO - i * 2),
      qtyGal: totalGal(seed.products),
      date: {
        title: DATE_FMT.format(when),
        description: relativeLabel(dayOffset, when),
      },
      dateKey: dateKeyOf(when),
      planned: plannedTime
        ? { date: DATE_FMT.format(when), time: plannedTime }
        : null,
      status: seedStage(i, dayOffset, Boolean(seed.driver)),
      stageSince: seedStageSince(i, seedStage(i, dayOffset, Boolean(seed.driver))),
      urgent: seedUrgent(i),
    };
  });
})();

/**
 * WHEN THE ORDER IS PLANNED, AS A MOMENT (2026-10-07). The row keeps it as two
 * printed strings; the overdue banner, the planned sort and the board's time
 * sorts all need one instant to compare. `null` when there is no plan or the
 * typed time does not read as one.
 */
export function plannedAt(row: FuelOrder): Date | null {
  if (!row.planned) return null;
  const day = new Date(row.planned.date);
  const t = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(row.planned.time.trim());
  if (Number.isNaN(day.getTime()) || !t) return null;
  const hour = (Number(t[1]) % 12) + (t[3].toUpperCase() === "PM" ? 12 : 0);
  return new Date(day.getFullYear(), day.getMonth(), day.getDate(), hour, Number(t[2]));
}

/**
 * Split an order's total gallons across N products.
 *
 * A bulk product change REPLACES an order's lines, and Qty (Gal) is the sum of
 * those lines — so the split has to preserve the order's own total exactly or
 * the bulk edit silently invents or destroys volume. Divides evenly and puts the
 * remainder on the FIRST line, so `sum(splitGallons(t, n)) === t` for every t
 * and n.
 *
 * ASSUMPTION, and the reason it is visible in the preview: an even split is a
 * guess. The source app has no bulk multi-product edit to copy, and nothing on
 * the order says how volume should divide between products. The confirm step
 * prints the resulting gallons per line so the operator sees the guess before
 * committing it rather than discovering it afterwards.
 */
export function splitGallons(total: number, n: number): number[] {
  if (n <= 0) return [];
  const base = Math.floor(total / n);
  const out = Array.from({ length: n }, () => base);
  out[0] += total - base * n;
  return out;
}

/** Free-text match across a row's text columns. */
export function matchesFuelOrder(row: FuelOrder, q: string): boolean {
  return [
    row.orderNo,
    row.type.label,
    row.customer.title,
    row.customer.description,
    row.products.map((p) => p.name).join(" "),
    row.date.title,
    row.planned ? `${row.planned.date} ${row.planned.time}` : "",
    row.tags.join(" "),
    row.status,
    row.driver?.name ?? "Unassigned",
  ]
    .join(" ")
    .toLowerCase()
    .includes(q);
}

import type { ListFacet, ListOption } from "./ListFilters";

/*
  WHAT A LIST'S FILTERS REMEMBER (Pavan, 2026-10-21):

    RECENT HISTORY   every set of filters applied in the last 24 hours, per
                     list, newest first — the Filters panel offers them back
                     under "Recent history" (only when there are any).
    SUGGESTED NAME   what "Save view" proposes, read off the filters that are
                     on: the line of service first, then the business, then
                     the rest in panel order — "Transport · Priya Raman".

  The toolbar's Filters control registers the list's facets and applied ticks
  here as it renders, so the view row on the same screen can name a view
  without every screen wiring the two together.
*/

const DAY = 24 * 3_600_000;
const MAX_ENTRIES = 8;

export interface HistoryEntry {
  at: number;
  ids: string[];
}

const storeKey = (list: string) => `fp-filter-history:${list}`;

/** The list's applied filter sets from the last 24 hours, newest first. */
export function readHistory(list: string): HistoryEntry[] {
  try {
    const raw = window.localStorage.getItem(storeKey(list));
    const all = raw ? (JSON.parse(raw) as HistoryEntry[]) : [];
    return all.filter((e) => Date.now() - e.at < DAY && e.ids.length > 0);
  } catch {
    return [];
  }
}

/** Keep an applied set — the same set again moves to the top, not twice. */
export function recordHistory(list: string, ids: Iterable<string>) {
  const sorted = [...ids].sort();
  if (sorted.length === 0) return;
  const key = sorted.join("|");
  const next = [{ at: Date.now(), ids: sorted }, ...readHistory(list).filter((e) => e.ids.join("|") !== key)].slice(
    0,
    MAX_ENTRIES
  );
  try {
    window.localStorage.setItem(storeKey(list), JSON.stringify(next));
  } catch {
    /* No storage — the history is simply not kept. */
  }
}

/** A list's identity for its history: which facets it has. */
export const listKeyOf = (facets: ListFacet[]) => facets.map((f) => f.key).join(",");

/* ------------------------------------------------- the active filters --- */

let active: { facets: ListFacet[]; ids: ReadonlySet<string> } | null = null;
export const setActiveFilters = (facets: ListFacet[], ids: ReadonlySet<string>) => {
  active = { facets, ids };
};
export const clearActiveFilters = (facets: ListFacet[]) => {
  if (active?.facets === facets) active = null;
};

/** The applied ticks, grouped by facet in panel order: label and values. */
export function groupIds(facets: ListFacet[], ids: Iterable<string>) {
  const set = new Set(ids);
  const value = (o: ListOption) => (typeof o === "string" ? o : o.value);
  return facets
    .map((f) => ({
      key: f.key,
      label: f.label,
      values: (f.options ?? f.sections?.flatMap((s) => s.options) ?? []).map(value).filter((v) => set.has(`${f.key}:${v}`)),
    }))
    .filter((g) => g.values.length > 0);
}

/* WHICH FACETS NAME A VIEW FIRST — the line of service, then the business. */
const LEADS = [["serviceLine", "line", "orderKind", "los"], ["business"]];

/**
 * THE SUGGESTED VIEW NAME (Pavan, 2026-10-21). From the filters on:
 *   - the line of service, then the business, then the other facets in panel
 *     order — a business stands in for its line ("Transport", not
 *     "Fuel · Transport");
 *   - a facet with one value gives that value, two give "A & B", more give
 *     the count and the facet's name ("3 Status");
 *   - at most three parts, joined with " · ".
 * Empty when nothing is filtered.
 */
export function suggestViewName(): string {
  if (!active || active.ids.size === 0) return "";
  const groups = groupIds(active.facets, active.ids);
  const rank = (key: string) => {
    const i = LEADS.findIndex((keys) => keys.includes(key));
    return i < 0 ? LEADS.length : i;
  };
  /* A BUSINESS SAYS ITS LINE — Transport is fuel — so the line drops. */
  const hasBusiness = groups.some((g) => LEADS[1].includes(g.key));
  const ordered = groups
    .filter((g) => !(hasBusiness && LEADS[0].includes(g.key)))
    .map((g, i) => ({ g, i }))
    .sort((a, b) => rank(a.g.key) - rank(b.g.key) || a.i - b.i)
    .map(({ g }) => g);
  return ordered
    .slice(0, 3)
    .map((g) =>
      g.values.length === 1 ? g.values[0] : g.values.length === 2 ? `${g.values[0]} & ${g.values[1]}` : `${g.values.length} ${g.label}`
    )
    .join(" · ");
}

/*
  Groupable dimensions, per list.

  What a list can be grouped by is a property of its DATA, not of the Group By
  control — which is why the DS menu now takes these as a prop. The DS's own
  fourteen-name default was generic: eight of those names (Created At, State,
  City, ZIP, Source, Truck, Created By, Assigned By) have no backing field on a
  fuel order, so they could never have grouped anything.

  Two rules hold across all four lists:

  • ONLY DIMENSIONS WITH USEFUL CARDINALITY. No order numbers, unique ids, ERP
    ids, raw timestamps, notes or contact fields — one group per row organises
    nothing.

  • A MULTI-VALUE DIMENSION NEVER SETS `hides`. Hiding the column it groups by
    would delete the row's OTHER values: an account grouped under
    "Transportation" is also Tank Wagon, and that has to stay on the row.
    Single-value dimensions do hide their column, because there every cell
    repeats its own group header.
*/
import type { GroupDim } from "@/components/tables-layout";
import type { Customer } from "./customers";
import type { Asset } from "./assets";
import { ASSET_STATUSES } from "./assets";

/* THE ORDERS PAGE'S DIMENSIONS live with its rows, in `salesOrders.ts`
   (Pavan, 2026-10-07) — fuel and asset orders, one list. */

/* -------------------------------------------------------------- customers --
   Measure: ship-tos. An account count alone would make every header say the
   same thing twice, and ship-to count is the one number that varies. */
export const CUSTOMER_GROUP_DIMS: GroupDim<Customer>[] = [
  {
    key: "status",
    label: "Status",
    hides: "status",
    order: ["Active", "Inactive"],
    valuesOf: (r) => [r.status],
  },
  {
    key: "los",
    label: "Line of Service",
    multi: true,
    valuesOf: (r) => r.los,
  },
  {
    key: "billingTerms",
    label: "Billing Terms",
    valuesOf: (r) => [r.billingTerms],
  },
];

/* ----------------------------------------------------------------- assets --
   Measure: capacity (gal) — the strongest rollup of the four lists. "Houston,
   TX — 14 assets, 82,000 gal" is a number the flat list cannot produce. */
export const ASSET_GROUP_DIMS: GroupDim<Asset>[] = [
  {
    key: "hub",
    label: "Hub",
    hides: "hub",
    valuesOf: (r) => [r.hub],
  },
  {
    key: "los",
    label: "LOS",
    hides: "los",
    valuesOf: (r) => [r.los],
  },
  {
    key: "status",
    label: "Status",
    hides: "status",
    order: ASSET_STATUSES,
    valuesOf: (r) => [r.status],
  },
  {
    key: "monitor",
    label: "Tank Monitor",
    hides: "monitor",
    // Two groups answering "what isn't monitored", which is the real question.
    order: ["Not monitored", "Monitored"],
    valuesOf: (r) => [r.tankMonitor ? "Monitored" : "Not monitored"],
  },
  {
    key: "products",
    label: "Product Compatibility",
    multi: true,
    valuesOf: (r) => r.products,
  },
];

import * as React from "react";
import { ACTOR } from "./activity";
import { DATE_FMT, FUEL_ORDERS, dateKeyOf, relativeLabel, startOfDay } from "./data";
import type { FuelOrder } from "./types";
import {
  FIRST_QUOTE_NO,
  SEED_QUOTES,
  diffQuote,
  newChargeId,
  type Quote,
} from "./quotes";
import { notify, ownerOnCreate } from "./salesSettings";

/*
  ONE OWNER FOR QUOTES, AND FOR THE ORDERS THEY MAKE (Pavan, 2026-10-07 —
  decision 1). A screen's own state is thrown away when the reader goes to
  another destination, so a quote accepted on Quotes could not reach Fuel
  Orders through either screen's state, and a quote list that reset on every
  visit would let the same quote be accepted twice. This module outlives both
  screens: Quotes reads and writes it, and Fuel Orders seeds its list from the
  orders in it.

  THE SETTER WRITES THE CHANGE LOG — the same rule as `useLoggedRows`: one
  wrapper round the only setter, so no path that edits a quote can forget to
  log it.
*/

let quotes: Quote[] = SEED_QUOTES;
let orders: FuelOrder[] = [];
const listeners = new Set<() => void>();

const emit = () => listeners.forEach((l) => l());
const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};

/** The quotes, live. */
export function useQuotes(): Quote[] {
  return React.useSyncExternalStore(subscribe, () => quotes);
}

/** The fuel orders accepted quotes have made, newest first. */
export function quoteOrders(): FuelOrder[] {
  return orders;
}

export function setQuotes(fn: (prev: Quote[]) => Quote[]) {
  const prev = quotes;
  const next = fn(prev);
  const at = new Date().toISOString();
  quotes = next.map((q) => {
    const before = prev.find((x) => x.id === q.id);
    if (!before)
      return q.audit?.length
        ? q
        : { ...q, updatedAt: at, audit: [{ at, by: ACTOR, changes: ["Quote created"] }] };
    if (before === q) return q;
    const changes = diffQuote(before, q);
    return {
      ...q,
      updatedAt: at,
      audit: changes.length > 0 ? [...(q.audit ?? []), { at, by: ACTOR, changes }] : q.audit,
    };
  });
  emit();
}

export function updateQuote(id: string, patch: Partial<Quote>) {
  setQuotes((prev) => prev.map((q) => (q.id === id ? { ...q, ...patch } : q)));
}

/** A blank Draft, made the moment Create Quote is pressed. */
export function createQuote(): Quote {
  const n = Math.max(FIRST_QUOTE_NO - 1, ...quotes.map((q) => Number(q.quoteNo.slice(2)))) + 1;
  const quote: Quote = {
    id: `qt-new-${n}`,
    quoteNo: `Q-${n}`,
    customer: "",
    shipTo: "",
    email: "",
    validThrough: "",
    /* No market yet: a default nobody chose would price the quote from a
       place nobody picked. */
    market: "",
    lines: [{ name: "", gal: 0, base: null, baseSet: false }],
    margin: { value: 0, unit: "perGal" },
    fees: [{ id: newChargeId("fee"), name: "Fees", value: 0, unit: "perGal" }],
    taxes: [{ id: newChargeId("tax"), name: "Tax", value: 0, unit: "percent" }],
    notes: "",
    stage: "Draft",
    updatedAt: new Date().toISOString(),
    /* AUTO-ASSIGN OWNER (Pavan, 2026-10-07) — only where the quote form has
       a Sales rep field to hold it. */
    extra: ownerOnCreate("quote") ? { salesRep: ownerOnCreate("quote") } : {},
  };
  setQuotes((prev) => [quote, ...prev]);
  return quotes.find((q) => q.id === quote.id)!;
}

/** Drop a quote outright — only an untouched new draft, closed unfilled. */
export function discardQuote(id: string) {
  quotes = quotes.filter((q) => q.id !== id);
  emit();
}

/* ------------------------------------------------- the order it makes --- */

const nextOrderNo = () =>
  String(Math.max(...FUEL_ORDERS.map((r) => Number(r.orderNo)), ...orders.map((r) => Number(r.orderNo))) + 2);

/*
  AN ACCEPTED QUOTE IS A FUEL ORDER AT REQUESTED (Pavan, 2026-10-07 —
  decision 1), carrying the customer, the ship-to and every product line with
  its gallons. Nothing else is known yet: no driver, no plan, no tags. Its
  delivery date is the day it was accepted — a quote carries no delivery date.
*/
function orderFrom(q: Quote, when: Date): FuelOrder {
  const day = startOfDay(when);
  const products = q.lines.filter((l) => l.name && l.gal > 0).map((l) => ({ name: l.name, gal: l.gal }));
  const no = nextOrderNo();
  return {
    id: `fo-quote-${no}`,
    orderNo: no,
    type: { code: "D", label: "Delivery" },
    customer: { title: q.customer, description: q.shipTo },
    products,
    qtyGal: products.reduce((n, p) => n + p.gal, 0),
    date: {
      title: DATE_FMT.format(day),
      description: relativeLabel(
        Math.round((day.getTime() - startOfDay(new Date()).getTime()) / 86_400_000),
        day
      ),
    },
    dateKey: dateKeyOf(day),
    planned: null,
    tags: [],
    status: "Requested",
    stageSince: when.toISOString(),
    /* MADE FROM AN ACCEPTED QUOTE — what "Require an accepted quote before
       scheduling" asks for (2026-10-07). */
    fromQuote: q.quoteNo,
    urgent: false,
    driver: null,
    audit: [{ at: when.toISOString(), by: ACTOR, changes: [`Order created from quote ${q.quoteNo}`] }],
  };
}

/** Mark as accepted: the quote moves on and its order is made, in one step. */
export function acceptQuote(id: string): FuelOrder | null {
  const q = quotes.find((x) => x.id === id);
  if (!q || q.stage !== "Sent") return null;
  const order = orderFrom(q, new Date());
  orders = [order, ...orders];
  updateQuote(id, { stage: "Accepted", orderId: order.id, orderNo: order.orderNo });
  notify("quoteAccepted", `${q.quoteNo} accepted · Order ${order.orderNo} created`);
  return order;
}

/* QUOTE EXPIRED IS SAID ONCE PER QUOTE PER VISIT (Pavan, 2026-10-07). A
   quote expires with the calendar, not with a press, so the Quotes page asks
   on arrival and a quote already reported is not reported again. */
const reportedExpired = new Set<string>();
export function reportExpired(expired: Quote[]) {
  const fresh = expired.filter((q) => !reportedExpired.has(q.id));
  if (fresh.length === 0) return;
  fresh.forEach((q) => reportedExpired.add(q.id));
  notify(
    "quoteExpired",
    fresh.length === 1
      ? `${fresh[0].quoteNo} expired`
      : `${fresh.length} quotes expired · ${fresh.map((q) => q.quoteNo).join(", ")}`
  );
}

/* THE SEEDED ACCEPTED QUOTES HAVE THEIR ORDERS TOO, so the link on each one
   lands on a real row. Dated the day each was accepted. INVENTED. */
quotes = quotes.map((q) => {
  if (q.stage !== "Accepted") return q;
  const order = orderFrom(q, new Date(q.updatedAt));
  orders = [order, ...orders];
  return { ...q, orderId: order.id, orderNo: order.orderNo };
});

import type { ActivityEntry } from "./activity";
import { CUSTOMERS } from "./customers";
import { DATE_FMT, FUEL_ORDERS, MONEY, dateKeyOf, startOfDay } from "./data";
import { statusTones } from "./statusKind";

/*
  QUOTES — a Sales destination (Pavan, 2026-10-07). A price offered to a
  customer for fuel at one ship-to; once the customer accepts it, it becomes a
  fuel order at Requested.

  Draft → Sent → Accepted. EXPIRED IS NOT STORED: it is a Sent quote whose
  valid-through date has passed, so it is derived every time it is read and
  cannot go on saying "Sent" after the date (Pavan, 2026-10-07).
*/

/** What is stored. */
export type QuoteStage = "Draft" | "Sent" | "Accepted";
/** What is shown — the stored stage, or Expired. */
export type QuoteStatus = QuoteStage | "Expired";

export const QUOTE_STATUSES: QuoteStatus[] = ["Draft", "Sent", "Accepted", "Expired"];

/* KINDS, NEVER TONES (Pavan, 2026-10-07) — docs/unified-view/1-components.md
   §Status kinds. Sent is waiting on the customer; Expired is an end that is
   not an outcome. */
export const QUOTE_STATUS_TONE = statusTones<QuoteStatus>({
  Draft: "neutral",
  Sent: "caution",
  Accepted: "success",
  Expired: "neutral",
});

/** How a margin, a fee or a tax is entered. */
export type AdjustUnit = "perGal" | "total" | "percent";

export interface Adjust {
  value: number;
  unit: AdjustUnit;
}

/**
 * A FEE OR A TAX — an `Adjust` with a name (Pavan, 2026-10-07). Fees and taxes
 * are lists: every quote starts with one "Fees" and one "Tax", and more of
 * either can be added under the table. The first of each list is that
 * default — its name is fixed and it cannot be removed.
 */
export interface Charge extends Adjust {
  id: string;
  name: string;
}

export type ChargeKind = "fee" | "tax";

let chargeSeq = 0;
/** A new charge's id — unique for the session. */
export const newChargeId = (kind: ChargeKind) => `${kind}-${++chargeSeq}`;

export const ADJUST_UNITS: { value: AdjustUnit; label: string }[] = [
  { value: "perGal", label: "$/gal" },
  { value: "total", label: "$" },
  { value: "percent", label: "%" },
];

/**
 * ONE PRODUCT LINE — the order's `{ name, gal }`, plus the base rate it is
 * priced from. `base` is filled from the price list for the line's product,
 * the quote's market and the line's gallon tier, and re-filled whenever any of
 * the three changes — unless somebody typed it (`baseSet`), which only
 * "Reapply rate" undoes.
 */
export interface QuoteLine {
  name: string;
  gal: number;
  /** $/gal. `null` while there is no market or product to price from. */
  base: number | null;
  baseSet: boolean;
}

export interface Quote {
  id: string;
  quoteNo: string;
  customer: string;
  shipTo: string;
  email: string;
  /** `YYYY-MM-DD`, or "" while unset. */
  validThrough: string;
  market: string;
  lines: QuoteLine[];
  /* QUOTE-LEVEL, NOT PER LINE (Pavan, 2026-10-07 — decision 2). One margin,
     and lists of fees and taxes (Pavan, 2026-10-07 — more can be added), each
     spread over every line by its unit. */
  margin: Adjust;
  fees: Charge[];
  taxes: Charge[];
  notes: string;
  stage: QuoteStage;
  /** ISO — the Updated column. */
  updatedAt: string;
  /** The fuel order an accepted quote made. */
  orderId?: string;
  orderNo?: string;
  audit?: ActivityEntry[];
  /** What a field added in Sales Settings holds, by its key (2026-10-07). */
  extra?: Record<string, string | boolean>;
}

/* ------------------------------------------------------------ status ----- */

const todayKey = () => dateKeyOf(startOfDay(new Date()));

/** Expired = Sent, and the valid-through date is behind today. */
export function quoteStatus(q: Quote): QuoteStatus {
  if (q.stage === "Sent" && q.validThrough && q.validThrough < todayKey()) return "Expired";
  return q.stage;
}

/* --------------------------------------------------------- price list ---- */

/*
  THE PRICE LIST — INVENTED (Pavan, 2026-10-07 — decision 3). A small stand-in
  for the pricing configuration Sales would read from: markets × products ×
  gallon tiers → base $/gal. Nothing here comes from a real rate card, and
  there is no Pricing-module work behind it.
*/
export const MARKETS = ["Houston", "Dallas–Fort Worth", "San Antonio"];

/** Gallon tiers, by the line's own gallons. INVENTED. */
const TIERS = [
  { from: 0, label: "Under 2,500 gal" },
  { from: 2500, label: "2,500–7,499 gal" },
  { from: 7500, label: "7,500+ gal" },
];

/** The products the fuel orders carry — a quote can only offer what an order can hold. */
export const QUOTE_PRODUCTS: string[] = Array.from(
  new Set(FUEL_ORDERS.flatMap((r) => r.products.map((p) => p.name)))
);

/** INVENTED base rates, $/gal, for the smallest tier in Houston. */
const PRODUCT_BASE: Record<string, number> = {
  "Gas Pr 1": 2.689,
  "123": 2.745,
  "200* Diesel Onroad clear": 3.412,
  "CLR DSL": 3.358,
  Test: 2.95,
  "1652": 3.104,
  CTL1: 3.215,
};

/** INVENTED market spreads over Houston, $/gal. */
const MARKET_SPREAD: Record<string, number> = {
  Houston: 0,
  "Dallas–Fort Worth": 0.064,
  "San Antonio": 0.038,
};

/** INVENTED tier discounts, $/gal off the smallest tier. */
const TIER_DISCOUNT = [0, 0.045, 0.092];

/** The price list as a table — market → product → one rate per tier. INVENTED. */
export const PRICE_LIST: Record<string, Record<string, number[]>> = Object.fromEntries(
  MARKETS.map((m) => [
    m,
    Object.fromEntries(
      QUOTE_PRODUCTS.map((p) => [
        p,
        TIER_DISCOUNT.map(
          (d) => Math.round(((PRODUCT_BASE[p] ?? 3) + (MARKET_SPREAD[m] ?? 0) - d) * 1000) / 1000
        ),
      ])
    ),
  ])
);

function tierOf(gal: number): number {
  let t = 0;
  TIERS.forEach((tier, i) => {
    if (gal >= tier.from) t = i;
  });
  return t;
}

/** The list rate for one line, or `null` when it cannot be priced yet. */
export function listRate(market: string, product: string, gal: number): number | null {
  return PRICE_LIST[market]?.[product]?.[tierOf(gal)] ?? null;
}

/** Re-fill every line nobody typed a rate into. */
export function reprice(lines: QuoteLine[], market: string): QuoteLine[] {
  return lines.map((l) => (l.baseSet ? l : { ...l, base: listRate(market, l.name, l.gal) }));
}

/** Every line back on the list rate — "Reapply rate". */
export function reapplyRates(lines: QuoteLine[], market: string): QuoteLine[] {
  return lines.map((l) => ({ ...l, baseSet: false, base: listRate(market, l.name, l.gal) }));
}

/* ------------------------------------------------------------ pricing ---- */

/*
  THE ARITHMETIC (Pavan, 2026-10-07 — decision 2).

  Margin, fees and taxes are set ONCE for the quote and applied to every line:
    $/gal    the same amount on every gallon;
    $ total  that amount spread evenly over every gallon on the quote;
    %        margin is a % of the line's base, a fee a % of base + margin,
             a tax a % of base + margin + ALL the fees (tax is on the selling
             price).
  SEVERAL FEES ADD, AND SEVERAL TAXES ADD (Pavan, 2026-10-07): each is worked
  out by its own unit on the same footing, never one on top of another.
  So each line has its own net $/gal, the quote total is the sum of the lines,
  and the net effective $/gal is that total over the total gallons — the
  build-up beside it is the gallon-weighted average of each part, so the parts
  add up to the net exactly.
*/
export interface LinePrice {
  base: number;
  margin: number;
  /** Every fee, summed. */
  fees: number;
  /** Every tax, summed. */
  tax: number;
  net: number;
  total: number;
  /** $/gal of each fee and each tax, in list order. */
  feeParts: number[];
  taxParts: number[];
}

export interface QuotePrice {
  gallons: number;
  lines: (LinePrice | null)[];
  /** Gallon-weighted $/gal for each part, over the priced lines. */
  base: number;
  margin: number;
  fees: number;
  tax: number;
  net: number;
  total: number;
  /** Gallon-weighted $/gal of each fee and each tax, in list order. */
  feeParts: number[];
  taxParts: number[];
  /** Every line has a product, gallons and a base rate. */
  complete: boolean;
}

function perGal(a: Adjust, on: number, gallons: number): number {
  if (a.unit === "perGal") return a.value;
  if (a.unit === "total") return gallons > 0 ? a.value / gallons : 0;
  return (on * a.value) / 100;
}

export function priceQuote(q: Pick<Quote, "lines" | "margin" | "fees" | "taxes">): QuotePrice {
  const priced = q.lines.filter((l) => l.base !== null && l.name && l.gal > 0);
  const gallons = priced.reduce((n, l) => n + l.gal, 0);
  const lines = q.lines.map((l): LinePrice | null => {
    if (l.base === null || !l.name || l.gal <= 0) return null;
    const base = l.base;
    const margin = perGal(q.margin, base, gallons);
    const feeParts = q.fees.map((f) => perGal(f, base + margin, gallons));
    const fees = feeParts.reduce((n, v) => n + v, 0);
    const taxParts = q.taxes.map((t) => perGal(t, base + margin + fees, gallons));
    const tax = taxParts.reduce((n, v) => n + v, 0);
    const net = base + margin + fees + tax;
    return { base, margin, fees, tax, net, total: net * l.gal, feeParts, taxParts };
  });
  type Scalar = Exclude<keyof LinePrice, "feeParts" | "taxParts">;
  const sum = (k: Scalar) =>
    lines.reduce((n, p, i) => (p ? n + p[k] * q.lines[i].gal : n), 0);
  const avg = (k: Scalar) => (gallons > 0 ? sum(k) / gallons : 0);
  const avgParts = (k: "feeParts" | "taxParts", count: number) =>
    Array.from({ length: count }, (_, j) =>
      gallons > 0
        ? lines.reduce((n, p, i) => (p ? n + p[k][j] * q.lines[i].gal : n), 0) / gallons
        : 0
    );
  const total = lines.reduce((n, p) => n + (p?.total ?? 0), 0);
  return {
    gallons,
    lines,
    base: avg("base"),
    margin: avg("margin"),
    fees: avg("fees"),
    tax: avg("tax"),
    net: gallons > 0 ? total / gallons : 0,
    total,
    feeParts: avgParts("feeParts", q.fees.length),
    taxParts: avgParts("taxParts", q.taxes.length),
    complete: q.lines.length > 0 && lines.every(Boolean),
  };
}

