/** A `YYYY-MM-DD` key as the app prints a date. */
export const dateOfKey = (key: string): Date | null => {
  if (!key) return null;
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
};
export const printKey = (key: string) => {
  const d = dateOfKey(key);
  return d ? DATE_FMT.format(d) : "—";
};

/** What each column PRINTS, as text a header box or a search can match. */
export function quoteColumnText(q: Quote, key: QuoteColumnKey): string {
  const p = priceQuote(q);
  switch (key) {
    case "quoteNo":
      return q.quoteNo;
    case "customer":
      return q.customer;
    case "shipTo":
      return q.shipTo;
    case "products":
      return q.lines.map((l) => l.name).join(" ");
    case "gallons":
      return String(p.gallons);
    case "market":
      return q.market;
    case "net":
      return p.gallons > 0 ? p.net.toFixed(3) : "";
    case "total":
      return p.total.toFixed(2);
    case "email":
      return q.email;
    case "validThrough":
      return printKey(q.validThrough);
    case "status":
      return quoteStatus(q);
    case "updated":
      return DATE_FMT.format(new Date(q.updatedAt));
    default:
      return "";
  }
}

export const QUOTE_SEARCH_FIELDS = QUOTE_COLUMNS.filter((c) => c.label).map((c) => ({
  key: c.key,
  label: c.label,
}));

export function matchesQuote(q: Quote, query: string): boolean {
  return QUOTE_SEARCH_FIELDS.map((f) => quoteColumnText(q, f.key))
    .join(" ")
    .toLowerCase()
    .includes(query);
}

function sortValue(q: Quote, key: QuoteColumnKey): string | number {
  const p = priceQuote(q);
  switch (key) {
    case "gallons":
      return p.gallons;
    case "net":
      return p.net;
    case "total":
      return p.total;
    case "validThrough":
      return q.validThrough;
    case "updated":
      return q.updatedAt;
    case "status":
      return QUOTE_STATUSES.indexOf(quoteStatus(q));
    default:
      return quoteColumnText(q, key).toLowerCase();
  }
}

export interface QuoteSort {
  key: QuoteColumnKey;
  dir: "asc" | "desc";
}

export function sortQuotes(rows: Quote[], sort: QuoteSort | null): Quote[] {
  if (!sort) return rows;
  const dir = sort.dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const av = sortValue(a, sort.key);
    const bv = sortValue(b, sort.key);
    if (av === bv) return 0;
    return av > bv ? dir : -dir;
  });
}

/* ------------------------------------------------------------ activity --- */

const say = (out: string[], label: string, from: unknown, to: unknown) => {
  if (String(from ?? "") === String(to ?? "")) return;
  out.push(`${label}: ${from || "—"} → ${to || "—"}`);
};

/** What a quote writes down — the events, not every keystroke. */
export function diffQuote(a: Quote, b: Quote): string[] {
  const out: string[] = [];
  say(out, "Status", a.stage, b.stage);
  say(out, "Customer", a.customer, b.customer);
  say(out, "Ship-to", a.shipTo, b.shipTo);
  say(out, "Market", a.market, b.market);
  say(out, "Valid through", a.validThrough && printKey(a.validThrough), b.validThrough && printKey(b.validThrough));
  const lines = (q: Quote) => q.lines.map((l) => `${l.name || "—"} ${l.gal} gal`).join(" · ");
  say(out, "Products", lines(a), lines(b));
  const total = (q: Quote) => {
    const p = priceQuote(q);
    return p.gallons > 0 ? MONEY(p.total) : "";
  };
  /* A FEE OR TAX ADDED, REMOVED OR RENAMED is an event (Pavan, 2026-10-07);
     its value is not — that shows as the quote total moving. */
  const charges = (kind: string, from: Charge[], to: Charge[]) => {
    to.forEach((c) => {
      const was = from.find((x) => x.id === c.id);
      if (!was) out.push(`${kind} added${c.name ? `: ${c.name}` : ""}`);
      else say(out, kind, was.name, c.name);
    });
    from
      .filter((c) => !to.some((x) => x.id === c.id))
      .forEach((c) => out.push(`${kind} removed${c.name ? `: ${c.name}` : ""}`));
  };
  charges("Fee", a.fees, b.fees);
  charges("Tax", a.taxes, b.taxes);
  say(out, "Quote total", total(a), total(b));
  return out;
}

import type { FuelOrder } from "./types";
import type { AssetOrder } from "./assetOrders";
import { stageLabel } from "./salesSettings";

/*
  WHAT SALES WRITES DOWN (the list Pavan approved, 2026-09-23). An event, not
  an edit: who is driving it, when it is planned, what is on it, what stage it
  is at. Tags, notes, PO numbers and contacts are edits and are not logged.
  "Order created" is written by `useLoggedRows` itself.
*/

const say = (out: string[], label: string, from: unknown, to: unknown) => {
  if (String(from ?? "") === String(to ?? "")) return;
  out.push(`${label}: ${from || "—"} → ${to || "—"}`);
};

export function diffFuelOrder(a: FuelOrder, b: FuelOrder): string[] {
  const out: string[] = [];
  /* A DRIVER PICK CAN MOVE THE STAGE (Requested ↔ Scheduled), so one line
     carries both. */
  if ((a.driver?.name ?? "") !== (b.driver?.name ?? ""))
    out.push(
      `Driver: ${a.driver?.name || "—"} → ${b.driver?.name || "—"}${
        a.status !== b.status ? ` (${stageLabel(b.status)})` : ""
      }`
    );
  else
    /* THE SHEET'S "MOVE TO …" (2026-10-07) changes the stage on its own —
       written under the stage's name as Sales Settings call it. */
    say(out, "Status", stageLabel(a.status), stageLabel(b.status));
  say(
    out,
    "Planned",
    a.planned ? `${a.planned.date} ${a.planned.time}` : "",
    b.planned ? `${b.planned.date} ${b.planned.time}` : ""
  );
  const products = (r: FuelOrder) => r.products.map((p) => `${p.name} ${p.gal} gal`).join(" · ");
  say(out, "Products", products(a), products(b));
  return out;
}

export function diffAssetOrder(a: AssetOrder, b: AssetOrder): string[] {
  const out: string[] = [];
  /* THE STAGE, set by hand — one of the five Sales stages (2026-10-07). */
  say(out, "Status", stageLabel(a.status), stageLabel(b.status));
  say(out, "Delivery date", a.date.title, b.date.title);
  return out;
}

