   quote and acknowledgement, work, complete — fully or partly. */

/* ───────────────────────────────────────────────────────────── the shell ── */

export function TechnicianMobile() {
  /* ITS OWN COPY OF THE JOBS. This app is a separate product and, in the real
     one, a separate client talking to the same API — so it keeps its own
     state rather than reaching into the dispatch screen's. What that costs is
     that changes here do not show up there, which is honest about what it is
     rather than pretending at a sync nothing behind this prototype does. */
  const cfg = useServiceSettings();
  const [tech, setTech] = React.useState(TECHNICIANS[0].id);
  /* THE SAME ORDERS AS THE DISPATCH BOARD (Pavan, 2026-09-24) — what the
     technician does here is what the dispatcher sees, and the other way
     round. Changes are logged under the technician's name. */
  const [orders, setShared] = useServiceOrders();
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [tab, setTab] = React.useState<HomeTab>("jobs");
  const [menuOpen, setMenuOpen] = React.useState(false);

  /* EVERY JOB ASSIGNED TO THEM (Pavan, 2026-09-23) — it used to stop at the
     first eight, a day's worth, which hid anything booked further out. The
     list screen sequences and filters them. */
  const jobs = React.useMemo(
    () => orders.filter((o) => o.technicianId === tech && o.status !== "Canceled"),
    [orders, tech]
  );

  const open = orders.find((j) => j.id === openId) ?? null;
  /* ONE ONGOING JOB AT A TIME (Pavan, 2026-09-24) — the other it blocks. */
  const ongoing = jobs.find((j) => j.status === "Ongoing" && j.id !== openId);
  const technician = TECHNICIANS.find((t) => t.id === tech)!;
  /** Every phone write goes to the shared orders, logged as this technician. */
  const setOrders = (fn: (prev: ServiceOrder[]) => ServiceOrder[]) => setShared(fn, technician.name);

  const patch = (id: string, p: Partial<ServiceOrder>) =>
    setOrders((prev) => prev.map((o) => (o.id === id ? { ...o, ...p } : o)));

  /**
   * PARTLY DONE — PARTS MISSING (Pavan, 2026-09-24). The same two outcomes the
   * dispatch screen has, chosen by the technician in the moment:
   *   continue  a LINKED order: this one stays open (Parts pending), carrying
   *             the fitted quantities, with nobody on it until the next visit
   *   neworder  this one is completed; what is owed becomes a NEW order,
   *             linked back, starting from nothing but the owed parts
   */
  /**
   * PARTLY DONE — PARTS MISSING. The same three outcomes the dispatch screen
   * has (`resolveShortfall`), chosen by the technician in the moment.
   */
  const split = (job: ServiceOrder, req: SplitRequest) => {
    let said = { title: "", description: "" };
    setOrders((prev) => {
      const out = resolveShortfall(prev, job.id, { parts: req.parts, note: req.note, mode: req.mode, nativeBilling: cfg.nativeBilling });
      said = out;
      return out.rows;
    });
    if (said.title) toast.success(said.title, { description: said.description });
  };

  const nextOrderNo = () =>
    `SO-${Math.max(...orders.map((r) => Number(r.orderNo.slice(3)) || 0)) + 3}`;

  const blank = React.useCallback(
    () =>
      blankServiceOrder({
        priceBook: cfg.priceBook,
        raisedBy: technician.name,
        /* THE PERSON RAISING IT IS THE ONE WHO WILL DO IT, unless they say
           otherwise — and what they found it on is an inspection. */
        technicianId: technician.id,
        source: "Flagged inspection",
      }),
    [cfg.priceBook, technician]
  );

  return (
    <div className="flex min-h-0 flex-1 flex-col items-center justify-center gap-4 p-6">
      {/* WHOSE PHONE THIS IS — a prototype affordance, not part of the app.
          It sits OUTSIDE the device frame so nobody mistakes it for a screen
          the technician would ever see. */}
      <div className="flex items-center gap-2">
        <span className="text-xs text-muted-foreground">Signed in as</span>
        {TECHNICIANS.filter((t) => t.active).map((t) => (
          <button
            key={t.id}
            type="button"
            onClick={() => {
              setTech(t.id);
              setOpenId(null);
            }}
            className={cn(
              "rounded-md px-2 py-1 text-xs transition-colors",
              t.id === tech
                ? "bg-chip text-foreground"
                : "text-muted-foreground hover:text-foreground"
            )}
          >
            {t.name.split(" ")[0]}
          </button>
        ))}
      </div>

      {/* THE DEVICE. 390×844 — an iPhone's points, which is the narrowest
          screen this has to work on and therefore the one to design at.
          `relative` because the menu and the bottom sheets overlay INSIDE it. */}
      <div className="relative flex h-[844px] max-h-[calc(var(--fp-vh)-180px)] w-[390px] shrink-0 flex-col overflow-hidden rounded-[2.25rem] border-[10px] border-fp-outline-2 bg-fp-surface-1b shadow-2xl">
        {open ? (
          <TechnicianJob
            key={open.id}
            job={open}
            onBack={() => setOpenId(null)}
            onPatch={(p) => patch(open.id, p)}
            onSplit={(req) => split(open, req)}
            busyWith={ongoing?.orderNo}
            onCreateTicket={(req) => {
              const no = nextOrderNo();
              setOrders((prev) => [ticketFrom(open, req, no, technician.name), ...prev]);
              return no;
            }}
          />
        ) : (
          <>
            {tab === "jobs" ? (
              <JobsScreen
                jobs={jobs}
                technician={technician}
                onOpen={setOpenId}
                onMenu={() => setMenuOpen(true)}
              />
            ) : (
              <NewOrderScreen
                key={tech}
                blank={blank}
                onMenu={() => setMenuOpen(true)}
                onCreateDraft={(d) => {
                  const no = nextOrderNo();
                  const row = {
                    ...d,
                    id: `so-m-${no}`,
                    orderNo: no,
                    status: "Drafted" as WorkStatus,
                    audit: [{ at: nowIso(), by: technician.name, changes: ["Order created as a draft"] }],
                  };
                  setOrders((prev) => [row, ...prev]);
                  return { id: row.id, orderNo: no };
                }}
                onUpdate={(d) => setOrders((prev) => prev.map((o) => (o.id === d.id ? { ...d } : o)))}
                onCommit={(d) => {
                  setOrders((prev) =>
                    prev.map((o) =>
                      o.id === d.id
                        ? {
                            ...d,
                            status: "Assigned" as WorkStatus,
                            audit: [...o.audit, { at: nowIso(), by: technician.name, changes: ["Status: Drafted → Assigned"] }],
                          }
                        : o
                    )
                  );
                  toast.success(`${d.orderNo} created and assigned`);
                  setTab("jobs");
                }}
              />
            )}
            <TabBar tab={tab} onTab={setTab} />
          </>
        )}
        <MenuDrawer
          open={menuOpen}
          onClose={() => setMenuOpen(false)}
          technician={technician}
          onTab={(t) => {
            setOpenId(null);
            setTab(t);
          }}
        />
      </div>
    </div>
  );
}

import * as React from "react";
import { HardHat } from "lucide-react";
import { Pill } from "@/components/ui/pill";
import { StatusChip } from "@/components/ui/status-chip";
import type { ListColumn } from "../ListTable";
import { ServiceListScreen } from "./ServiceListScreen";
import { TECHNICIANS, type ServiceOrder, type Technician } from "./work";
import { useServiceOrders } from "./store";
import { ACTIVE_KIND, kindTone } from "../statusKind";

/**
 * TECHNICIANS — who can take the work.
 *
 * A LIST, NOT A BOARD. A technician has no lifecycle; the questions asked of
 * this screen are "who covers meters", "who works out of Kern" and "how full
 * is somebody" — which are a filter, a filter and a number, all of them
 * columns.
 *
 * OPEN JOBS IS THE COLUMN THAT MAKES IT USEFUL. A roster with skills and a
 * phone number is a contact list; the count of work still on somebody is what
 * turns it into the thing you read before assigning the next job. It is
 * counted off the work orders rather than stored, because a stored count is a
 * number that goes stale the moment a job moves.
 *
 * NOT BUILT YET, named rather than faked: the technician's own day (their
 * jobs, in order, with travel between them), and adding or editing one.
 */

type TechColumnKey =
  | "name"
  | "base"
  | "skills"
  | "open"
  | "capacity"
  | "phone"
  | "status"
  | "actions";

const TECH_COLUMNS: ListColumn<TechColumnKey>[] = [
  { key: "name", label: "Technician", width: 130, sortable: true },
  { key: "base", label: "Base", width: 130, sortable: true },
  { key: "skills", label: "Skills", width: 220, sortable: true },
  /* COMPARED DOWN THE COLUMN, so right-aligned — these two are read against
     each other and against the rows above. */
  { key: "open", label: "Open Jobs", width: 110, sortable: true },
  { key: "capacity", label: "Jobs / Day", width: 110, sortable: true },
  { key: "phone", label: "Phone", width: 140, sortable: true },
  { key: "status", label: "Status", width: 100, sortable: true },
  { key: "actions", label: "", width: 44 },
];

/**
 * WORK STILL ON SOMEBODY.
 *
 * Assigned, under way, or stalled for a part — all three are jobs that are
 * still theirs. Anything past the visit belongs to a manager or to accounting,
 * and counting it here would make a technician look busy for work they
 * finished last week.
 */
function openJobsFor(rows: ServiceOrder[], id: string): number {
  return rows.filter(
    (r) =>
      r.technicianId === id &&
      (r.status === "Assigned" ||
        r.status === "Ongoing" ||
        r.status === "Parts pending")
  ).length;
}

/**
 * WHAT A COLUMN PRINTS, as text — what its filter box matches, because the
 * reader types what they read. Kept beside `renderCell` in meaning: change
 * what a cell shows and this follows.
 */
function techColumnText(t: Technician, key: TechColumnKey, openJobs: number): string {
  switch (key) {
    case "name":
      return t.name;
    case "base":
      return t.base;
    case "skills":
      return t.skills.join(" ");
    case "open":
      return String(openJobs);
    case "capacity":
      return String(t.dailyCapacity);
    case "phone":
      return t.phone;
    case "status":
      return t.active ? "Active" : "Inactive";
    default:
      return "";
  }
}

export function TechniciansScreen() {
  /* COUNTED OFF THE SHARED ORDERS (2026-09-24), so it moves as jobs move. */
  const [orders] = useServiceOrders();
  const open = React.useMemo(
    () => Object.fromEntries(TECHNICIANS.map((t) => [t.id, openJobsFor(orders, t.id)])),
    [orders]
  );

  const renderCell = (t: Technician, key: TechColumnKey): React.ReactNode => {
    switch (key) {
      case "name":
        return <span className="font-medium text-foreground">{t.name}</span>;
      case "base":
        return t.base;
      case "skills":
        /* CHIPS, BECAUSE THE QUESTION IS "CAN THEY DO X". A comma-joined
           sentence is read; a row of chips is scanned, which is what somebody
           picking a technician is doing. */
        return (
          <span className="flex flex-wrap items-center gap-1">
            {t.skills.map((s) => (
              <Pill key={s}>
                {s}
              </Pill>
            ))}
          </span>
        );
      case "open":
        return <span className="tabular-nums">{open[t.id] ?? 0}</span>;
      case "capacity":
        return <span className="tabular-nums">{t.dailyCapacity}</span>;
      case "phone":
        return <span className="tabular-nums text-muted-foreground">{t.phone}</span>;
      case "status":
        return (
          <StatusChip tone={kindTone(ACTIVE_KIND(t.active))}>
            {t.active ? "Active" : "Inactive"}
          </StatusChip>
        );
      default:
        return null;
    }
  };

  /* THE STANDARD LIST (Pavan, 2026-10-22) — views, Filters, chips, the view
     bar, like every table page. Skills filter by each skill. */
  return (
    <ServiceListScreen<Technician, TechColumnKey>
      rows={TECHNICIANS}
      columns={TECH_COLUMNS}
      rowId={(t) => t.id}
      renderCell={renderCell}
      sortValue={(t, key) =>
        key === "open" ? (open[t.id] ?? 0) : key === "capacity" ? t.dailyCapacity : key === "status" ? (t.active ? 0 : 1) : techColumnText(t, key, open[t.id] ?? 0)
      }
      valuesOf={(t, key) => (key === "skills" ? t.skills : undefined)}
      searchPlaceholder="Search technicians, bases, skills…"
      noun="technicians"
      icon={<HardHat />}
    />
  );
}

import { RENTAL_ASSETS } from "../threepl/directory";
import {
  FEE_BOOK,
  LABOR_RATE,
  WORK_TYPES,
  WORK_TYPE_CATEGORY,
  TASK_KIND_LABEL,
  type ServiceOrder,
} from "./work";

/*
  THE SERVICE PLATFORM'S REFERENCE SCREENS (Pavan and Deepika, 2026-09-24),
  after Anirudh's unified design: price book, parts, agreements, maintenance,
  compliance, performance.

  BUILT FROM WHAT THE MODULE ALREADY HOLDS where it can be — the price book
  IS `WORK_TYPES`, the parts are the parts it names, the assets and customers
  are the real rental fleet — so an order and these screens agree. What has
  no source yet is INVENTED and deterministic: stock levels, bins, vendors,
  plans, visit counts, certificate dates.
*/

const DAY = 86_400_000;
const today = () => {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  return d;
};
const addDays = (d: Date, n: number) => new Date(d.getTime() + n * DAY);
export const keyOf = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

/* ─────────────────────────────────────────────────────────── price book ── */

/** How long each job usually takes. INVENTED until the real book arrives. */
const LABOR_HOURS: Record<string, number> = {
  "Leak check": 2,
  "Hose swap": 1.5,
  "Pump replace": 3,
  "Nozzle replace": 1,
  "Monitor install": 2,
  "Tank swap": 4,
};

export interface PriceBookRow {
  code: string;
  job: string;
  category: string;
  laborHours: number;
  parts: string[];
  fee: number;
  /** Parts + fee + the usual hours at the standard rate — what the job comes to. */
  flatRate: number;
}

export const PRICE_BOOK: PriceBookRow[] = Object.entries(WORK_TYPES).map(([job, book]) => {
  const hours = LABOR_HOURS[job] ?? 1;
  const parts = book.parts.reduce((s, p) => s + p.cost * p.qty, 0);
  const fee = book.fees.reduce((s, f) => s + f.amount, 0);
  return {
    code: job
      .split(" ")
      .map((w) => w.slice(0, 3).toUpperCase())
      .join("-"),
    job,
    category: TASK_KIND_LABEL[WORK_TYPE_CATEGORY[job] ?? "Parts"],
    laborHours: hours,
    parts: book.parts.map((p) => (p.qty > 1 ? `${p.name} ×${p.qty}` : p.name)),
    fee,
    flatRate: Math.round(parts + fee + hours * LABOR_RATE),
  };
});

export { FEE_BOOK };

/* ──────────────────────────────────────────────────────────────── parts ── */

export interface InventoryRow {
  sku: string;
  part: string;
  bin: string;
  vendor: string;
  onHand: number;
  reorderAt: number;
  cost: number;
}

const VENDORS = ["GPI Direct", "OPW Supply", "Cim-Tek", "Fisher"];

/** Every part the price book names, plus the common consumables. */
export const INVENTORY: InventoryRow[] = (() => {
  const seen = new Map<string, number>();
  for (const b of Object.values(WORK_TYPES)) for (const p of b.parts) seen.set(p.name, p.cost);
  const extra: [string, number][] = [
    ["Spin-on filter", 30],
    ["Pump seal kit", 88],
    ["Regulator diaphragm", 64],
  ];
  for (const [n, c] of extra) if (!seen.has(n)) seen.set(n, c);
  return [...seen.entries()].map(([part, cost], i) => ({
    sku: part.replace(/[^A-Za-z]/g, "").slice(0, 3).toUpperCase() + "-" + String(100 + i * 7),
    part,
    bin: `${"ABCD"[i % 4]}-${String(3 + i * 4).padStart(2, "0")}`,
    vendor: VENDORS[i % VENDORS.length],
    onHand: [4, 11, 2, 26, 1, 6, 9, 3][i % 8],
    reorderAt: [2, 4, 3, 10, 3, 2, 4, 3][i % 8],
    cost,
  }));
})();

export const stockStatus = (r: InventoryRow) => (r.onHand <= r.reorderAt ? "Reorder" : "Stocked");

/* ─────────────────────────────────────────────────────────── agreements ── */

/** The fleet that sits at customers — where agreements and plans attach. */
const PLACED = RENTAL_ASSETS.filter((a) => a.customer && a.shipTo);

export type AgreementStatus = "Active" | "Renewal due" | "Lapsed";

export interface AgreementRow {
  no: string;
  kind: "Membership" | "MSA";
  customer: string;
  asset: string;
  plan: string;
  visitsUsed: number;
  visitsIncluded: number;
  monthly: number;
  renewsKey: string;
  autoRenew: boolean;
  status: AgreementStatus;
}

const PLANS = [
  { plan: "Basic", visits: 2, monthly: 40 },
  { plan: "Plus", visits: 4, monthly: 95 },
  { plan: "Premium", visits: 6, monthly: 160 },
];

export const AGREEMENTS: AgreementRow[] = PLACED.slice(0, 8).map((a, i) => {
  const p = PLANS[i % 3];
  const renews = addDays(today(), [160, 6, -105, 220, 45, -20, 300, 12][i]);
  const days = (renews.getTime() - today().getTime()) / DAY;
  const status: AgreementStatus = days < 0 ? "Lapsed" : days <= 30 ? "Renewal due" : "Active";
  /* AN MSA IS A YEAR'S FEE COVERING A SCHEDULE (Deepika, 2026-09-24). */
  const msa = i % 4 === 3;
  return {
    no: `SA-${1140 + i * 7}`,
    kind: msa ? "MSA" : "Membership",
    customer: a.customer!,
    asset: a.name,
    plan: msa ? "Master service agreement" : p.plan,
    visitsUsed: Math.min(p.visits, [2, 5, 2, 1, 3, 2, 0, 4][i]),
    visitsIncluded: msa ? 12 : p.visits,
    monthly: msa ? 450 : p.monthly,
    renewsKey: keyOf(renews),
    autoRenew: i % 3 !== 2,
    status,
  };
});

/* ─────────────────────────────────────────────────────────── maintenance ── */

export interface MaintenancePlan {
  id: string;
  no: string;
  asset: string;
  assetId: string;
  assetType: string;
  customer: string;
  shipTo: string;
  task: string;
  everyMonths: number;
  lastKey: string;
  nextKey: string;
}

export const MAINTENANCE_PLANS: MaintenancePlan[] = PLACED.slice(0, 7).map((a, i) => {
  const every = [6, 12, 3, 12, 18, 6, 3][i];
  const last = addDays(today(), -[50, 350, 80, 140, 100, 170, 95][i]);
  const next = new Date(last);
  next.setMonth(next.getMonth() + every);
  return {
    id: `mp-${i}`,
    no: `MP-${301 + i}`,
    asset: a.name,
    assetId: a.id,
    assetType: a.assetType,
    customer: a.customer!,
    shipTo: a.shipTo!,
    task: Object.keys(WORK_TYPES)[i % Object.keys(WORK_TYPES).length],
    everyMonths: every,
    lastKey: keyOf(last),
    nextKey: keyOf(next),
  };
});

/* ───────────────────────────────────────────────────────────── compliance ── */

export type ComplianceStatus = "OK" | "Due soon" | "Overdue";

export interface ComplianceItem {
  no: string;
  asset: string;
  customer: string;
  requirement: string;
  authority: string;
  lastKey: string;
  dueKey: string;
  status: ComplianceStatus;
}

/**
 * LONG-CYCLE COMPLIANCE (Deepika, 2026-09-24) — tests an asset needs because
 * it sits at a customer for years: a tank tightness test, a cargo tank
 * inspection, a regulator recertification.
 */
const REQUIREMENTS = [
  { requirement: "Tank tightness test", authority: "State EPA", years: 1 },
  { requirement: "DOT cargo tank inspection", authority: "FMCSA", years: 1 },
  { requirement: "Propane regulator recert", authority: "NFPA 58", years: 2 },
  { requirement: "Overfill prevention check", authority: "State EPA", years: 1 },
];

export const COMPLIANCE: ComplianceItem[] = PLACED.slice(2, 8).map((a, i) => {
  const r = REQUIREMENTS[i % REQUIREMENTS.length];
  const due = addDays(today(), [20, 310, -40, 220, 9, 150][i]);
  const last = new Date(due);
  last.setFullYear(last.getFullYear() - r.years);
  const days = (due.getTime() - today().getTime()) / DAY;
  return {
    no: `CP-${71 + i}`,
    asset: a.name,
    customer: a.customer!,
    requirement: r.requirement,
    authority: r.authority,
    lastKey: keyOf(last),
    dueKey: keyOf(due),
    status: days < 0 ? "Overdue" : days <= 30 ? "Due soon" : "OK",
  };
});

/* ─────────────────────────────────────────────────────────── performance ── */

/** Work still on the books — not yet finished. */
const OPEN = new Set(["Drafted", "Parts pending", "Linked order", "Assigned", "Yet to start", "Ongoing"]);

/**
 * THE NUMBERS, COUNTED OFF THE ORDERS — never stored, so they cannot go
 * stale. First-time fix: finished jobs that did not need a second visit.
 * Quote attach: finished jobs that carried a quote.
 */
export function performance(rows: ServiceOrder[]) {
  const finished = rows.filter((r) => r.completedAt && r.status !== "Canceled");
  const firstTime = finished.filter((r) => r.visits.length <= 1 && r.status !== "Completed — linked");
  const quoted = finished.filter((r) => r.quote);
  const invoiced = rows.filter((r) => r.invoiceCreated);
  const pct = (n: number, d: number) => (d === 0 ? 0 : Math.round((n / d) * 100));
  return {
    open: rows.filter((r) => OPEN.has(r.status)).length,
    firstTimeFix: pct(firstTime.length, finished.length),
    quoteAttach: pct(quoted.length, finished.length),
    invoicedCount: invoiced.length,
    synced: rows.filter((r) => r.synced).length,
    finished: finished.length,
  };
}

import { DATE_FMT } from "../data";
import {
  feesTotal,
  formatHours,
  jobsOf,
  money,
  partsTotal,
  technicianById,
  type ServiceOrder,
} from "./work";

/*
  A REAL INVOICE TO DOWNLOAD (Pavan, 2026-09-25).

  A one-page PDF written by hand — no library, so the single-file build stays
  self-contained. Text only, in the two standard PDF fonts, which every reader
  has. The figures come from the same helpers the order sheet's Summary uses,
  so the file and the screen cannot disagree.

  `partial` marks a rolled-over job's invoice: what was done on this visit,
  with the parts still owed listed and not charged.
*/

/** The standard fonts speak WinAnsi; keep to plain ASCII so nothing breaks. */
const ascii = (s: string) =>
  s
    .replace(/[—–]/g, "-")
    .replace(/×/g, "x")
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/·/g, "-")
    .replace(/[^\x20-\x7E]/g, "");

const esc = (s: string) => ascii(s).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");

type Op = { x: number; y: number; text: string; bold?: boolean; size?: number; right?: boolean };

/** Rough Helvetica width, good enough to right-align a column of figures. */
const widthOf = (text: string, size: number) => ascii(text).length * size * 0.52;

function pdfFrom(ops: Op[], rules: { x1: number; x2: number; y: number }[]): Blob {
  const stream = [
    ...rules.map((r) => `0.8 G ${r.x1} ${r.y} m ${r.x2} ${r.y} l S`),
    ...ops.map((o) => {
      const size = o.size ?? 10;
      const x = o.right ? o.x - widthOf(o.text, size) : o.x;
      return `BT /${o.bold ? "F2" : "F1"} ${size} Tf 0 g ${x.toFixed(1)} ${o.y} Td (${esc(o.text)}) Tj ET`;
    }),
  ].join("\n");

  const objects = [
    "<< /Type /Catalog /Pages 2 0 R >>",
    "<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
    "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
    "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>",
    `<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`,
  ];
  let out = "%PDF-1.4\n";
  const offsets: number[] = [];
  objects.forEach((body, i) => {
    offsets.push(out.length);
    out += `${i + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xref = out.length;
  out += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((o) => `${String(o).padStart(10, "0")} 00000 n \n`).join("");
  out += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
  return new Blob([out], { type: "application/pdf" });
}

export function invoicePdf(order: ServiceOrder, opts: { partial?: boolean } = {}): Blob {
  const ops: Op[] = [];
  const rules: { x1: number; x2: number; y: number }[] = [];
  const L = 56;
  const R = 556;
  let y = 740;
  const line = (text: string, o: Partial<Op> = {}) => ops.push({ x: L, y, text, ...o });

  const issued = DATE_FMT.format(new Date(order.invoicedAt ?? order.invoiceSentAt ?? new Date().toISOString()));
  line(opts.partial ? "PARTIAL INVOICE" : "INVOICE", { bold: true, size: 20 });
  ops.push({ x: R, y, text: "FleetPanda Service", bold: true, size: 12, right: true });
  y -= 18;
  line(`Invoice ${order.orderNo}-INV · Issued ${issued}`, { size: 10 });
  y -= 30;

  line("Bill to", { bold: true });
  ops.push({ x: 320, y, text: "Job", bold: true });
  y -= 15;
  const tech = technicianById(order.technicianId);
  const left = [order.customer, order.shipTo, order.poc ? `${order.poc.name} - ${order.poc.email}` : ""].filter(Boolean);
  const right = [
    `Order ${order.orderNo}`,
    order.scheduledAt ? `Date ${DATE_FMT.format(new Date(order.scheduledAt))}` : "",
    tech ? `Technician ${tech.name}` : "",
  ].filter(Boolean);
  for (let i = 0; i < Math.max(left.length, right.length); i++) {
    if (left[i]) line(left[i]);
    if (right[i]) ops.push({ x: 320, y, text: right[i] });
    y -= 14;
  }
  y -= 12;

  const work = order.assets.flatMap((a) => jobsOf(a).map((j) => ({ asset: a.assetName, ...j }))).filter((j) => j.workType);
  if (work.length) {
    line("Work done", { bold: true });
    y -= 15;
    for (const w of work) {
      line(w.asset ? `${w.workType} - ${w.asset}` : w.workType);
      y -= 14;
    }
    y -= 12;
  }

  /* THE CHARGES TABLE */
  line("Description", { bold: true });
  ops.push({ x: 380, y, text: "Qty", bold: true, right: true });
  ops.push({ x: 470, y, text: "Unit", bold: true, right: true });
  ops.push({ x: R, y, text: "Amount", bold: true, right: true });
  y -= 6;
  rules.push({ x1: L, x2: R, y });
  y -= 14;
  const row = (desc: string, qty: string, unit: string, amount: number) => {
    line(desc);
    if (qty) ops.push({ x: 380, y, text: qty, right: true });
    if (unit) ops.push({ x: 470, y, text: unit, right: true });
    ops.push({ x: R, y, text: money(amount), right: true });
    y -= 16;
  };
  for (const p of order.parts) row(p.name || "Part", String(p.qty), money(p.cost), p.cost * p.qty);
  if (order.labor > 0 || order.laborRate > 0)
    row(`Labor (${formatHours(order.labor)})`, "", `${money(order.laborRate)}/h`, order.labor * order.laborRate);
  for (const f of order.fees) row(f.name || "Fee", "", "", f.amount);
  for (const f of order.extraCharges) row(f.name || "Charge", "", "", f.amount);
  rules.push({ x1: L, x2: R, y: y + 8 });
  y -= 6;
  const total =
    partsTotal(order.parts) + order.labor * order.laborRate + feesTotal(order.fees) + feesTotal(order.extraCharges);
  line("Total due", { bold: true, size: 12 });
  ops.push({ x: R, y, text: money(total), bold: true, size: 12, right: true });
  y -= 28;

  const owed = (order.unavailableParts ?? []).filter((p) => p.name);
  if (owed.length) {
    line(opts.partial ? "Still to come (not charged on this invoice)" : "Not included - parts not available", { bold: true });
    y -= 15;
    for (const p of owed) {
      line(`${p.name} x ${p.qty}`);
      y -= 14;
    }
    y -= 12;
  }

  if (order.payment) {
    line("Payment", { bold: true });
    y -= 15;
    line(`Received ${money(order.payment.amount)} on ${DATE_FMT.format(new Date(order.payment.paidAt))} by ${order.payment.method} (${order.payment.reference})`);
    y -= 14;
  } else {
    line(`Status: ${order.status}`, { size: 9 });
  }

  return pdfFrom(ops, rules);
}

/** Save the invoice as a file. */
export function downloadInvoice(order: ServiceOrder, opts: { partial?: boolean } = {}) {
  const url = URL.createObjectURL(invoicePdf(order, opts));
  const a = document.createElement("a");
  a.href = url;
  a.download = `${order.orderNo}-${opts.partial ? "partial-" : ""}invoice.pdf`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

import * as React from "react";

/*
  THE SERVICE MODULE'S SWITCH POINTS.

  Eight of them, and between them they describe every customer this module has
  to fit. They are NOT preferences: each one turns a whole step of the flow on
  or off — whether a work type arrives with its parts priced, whether a manager
  signs it off, whether an invoice writes itself, what a stalled job does next.
  Two named profiles sit at the ends of the range, and everything in between is
  a real configuration somebody runs.

  THEY LIVE HERE, NOT IN THE GLOBAL SETTINGS PAGE. The app's Settings page will
  govern several modules and has been on hold pending that; these are this
  module's own, and putting them behind a rail item inside it is what lets them
  ship now without pre-empting that decision.

  A MODULE-LEVEL STORE RATHER THAN A PROVIDER. The rail's screens are siblings
  mounted one at a time by the shell, so a context would have to be threaded
  through the whole app to reach two of them. `useSyncExternalStore` gives the
  same thing — one value, every subscriber re-rendered — without the shell
  having to know this module has settings.
*/

/**
 * WHAT A PARTIAL VISIT DOES (Pavan, 2026-09-23).
 *
 * THE TRIGGER. Ten parts are needed, five are on the van. The technician fits
 * the five and marks the job partially completed. The work that happened is
 * recorded either way; what differs is where the REMAINING five live.
 *
 * `continue`  — **THE SAME ORDER, THE SAME NUMBER.** It goes back to OPEN,
 *               because a second visit needs a technician and a date and
 *               nobody has picked either yet. Its part list keeps the fitted
 *               quantities, so the order carries its own progress: five of
 *               ten, and it is not done until it is ten of ten. One fault,
 *               one number, however many visits it takes.
 * `neworder`  — **THIS ONE IS FINISHED; THE REST IS A NEW JOB.** The five
 *               fitted are complete and the order says so; the five owed
 *               become an order of their own, with its own number, linked
 *               back.
 *
 * THE DIFFERENCE IS WHETHER THE FAULT IS ONE PIECE OF WORK OR TWO — which is
 * a question about how the business invoices and talks to the customer, not
 * about the parts. That is why it is a setting and not a choice on the day.
 *
 * SUPERSEDES `suborder` (2026-09-23), which made a CHILD record `SO-1048-2`.
 * That was a third thing nobody asked for: it split one fault into two
 * records while pretending they were one, so the progress lived on neither.
 * And it supersedes `rollforward` before it, which just moved the whole order
 * to tomorrow and could not say that five of ten went on.
 */
/*
 * THREE OUTCOMES (Deepika and Pavan, 2026-09-24):
 *   `rollover`  the SAME order, pushed to the next day: details kept, same
 *               technician, still Assigned, with a Parts pending callout.
 *   `neworder`  this one is complete; a NEW Open order (no technician, no
 *               date) carries the rest, the notes and the jobs — linked both
 *               ways.
 *   `queue`     this one is complete; the rest waits in the dispatcher's
 *               queue as a Parts pending order — no link, no rollover.
 * Replaces `continue` (back to Open on the same number).
 */
export type ReturnMode = "rollover" | "neworder" | "queue";

export interface ServiceSettings {
  /**
   * ON: the invoice writes itself the moment a job is approved — parts, actual
   * labour, mileage and fees. OFF: the costs are still captured, but somebody
   * generates the invoice by hand. Either way it reaches accounting on a batch
   * schedule afterwards, not in real time.
   */
  nativeBilling: boolean;
  /** ON: what a job costs rolls into the asset's payback picture. */
  roiFeed: boolean;
  /**
   * ON: finished work waits in Needs approval for a service manager. OFF: it
   * approves itself the moment the technician submits.
   */
  managerApproval: boolean;
  /** Where the parts a visit could not fit go. See `ReturnMode`. */
  returnMode: ReturnMode;
  /** ON: a work type arrives with its usual parts and a suggested fee. */
  priceBook: boolean;
  /** ON: "Portal request" is offered as an intake source. */
  portalIntake: boolean;
  /**
   * ON: an assigned order flows to the TECHNICIAN'S OWN APP for on-site
   * completion — arrive, quote, then do it now or defer for a part. OFF: it is
   * handled by hand from the order sheet; dispatch records the completed work
   * and there is no on-site quote at all.
   *
   * RESTORED 2026-09-21, having been cut on 2026-09-18 on the grounds that the
   * field app is a separate mobile product. It is — and that is exactly why
   * the switch has to exist: whether it is in play changes what the DISPATCH
   * screens can do. With it on, the order sheet cannot complete a job, because
   * the person holding the job is standing in front of the asset.
   */
  techApp: boolean;
  /**
   * ON: before work starts the technician sends the customer a quote — parts
   * plus fees — for on-site approval. OFF: work starts straight from dispatch
   * and everything settles on the invoice afterwards.
   *
   * NESTED UNDER `techApp`, and dead without it: a quote can only be sent from
   * the field, so with no field app there is no moment at which to send one.
   */
  fieldQuote: boolean;
}

/** Everything on — the unified profile. */
export const DEFAULT_SETTINGS: ServiceSettings = {
  nativeBilling: true,
  roiFeed: true,
  managerApproval: true,
  returnMode: "rollover",
  priceBook: true,
  portalIntake: true,
  techApp: true,
  fieldQuote: true,
};

/**
 * THE TWO ENDS OF THE RANGE, named. A reader turning eight switches one at a
 * time has to know what they are aiming at; these are the two configurations
 * the module was shaped around, so they are offered as one click each.
 */
export const SETTINGS_PROFILES: {
  key: string;
  name: string;
  detail: string;
  settings: ServiceSettings;
}[] = [
  {
    key: "unified",
    name: "Unified",
    detail:
      "Everything in FleetPanda — price book, manager sign-off and invoicing.",
    settings: DEFAULT_SETTINGS,
  },
  {
    key: "dispatch",
    name: "Dispatch layer",
    detail:
      "FleetPanda dispatches and records; approval and billing happen elsewhere.",
    settings: {
      nativeBilling: false,
      roiFeed: false,
      managerApproval: false,
      returnMode: "neworder",
      priceBook: false,
      portalIntake: false,
      techApp: false,
      fieldQuote: false,
    },
  },
];

let current: ServiceSettings = { ...DEFAULT_SETTINGS };
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

export function setServiceSetting<K extends keyof ServiceSettings>(
  key: K,
  value: ServiceSettings[K]
) {
  current = { ...current, [key]: value };
  /* A NESTED SWITCH CANNOT OUTLIVE ITS PARENT. Field quoting means nothing
     without a field app, and leaving it ticked under a disabled parent is how
     a reader comes back later and believes a step is running that is not. */
  if (key === "techApp" && value === false) current.fieldQuote = false;
  emit();
}

export function applyServiceProfile(settings: ServiceSettings) {
  current = { ...settings };
  emit();
}

export function useServiceSettings(): ServiceSettings {
  return React.useSyncExternalStore(
    (onChange) => {
      listeners.add(onChange);
      return () => listeners.delete(onChange);
    },
    () => current,
    () => current
  );
}

/** For the seed and for pure helpers that cannot use a hook. */
export function readServiceSettings(): ServiceSettings {
  return current;
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { Slider } from "@/components/ui/slider";

/**
 * A SINGLE-HANDLE SLIDER FOR ONE MEASURE — hours on site, miles driven.
 *
 * SAME CONTROL AS THE DELIVERY WINDOW, minus one handle. Both answer "how
 * much", both are read far more often than they are typed, and both want the
 * figure PRINTED rather than estimated from where the handle sits — a slider
 * whose value can only be guessed is one nobody trusts for anything that ends
 * up on an invoice.
 *
 * ONE HANDLE BECAUSE IT IS NOT A RANGE. A delivery window is two facts, a
 * start and an end; four hours is one. Two handles would ask the reader which
 * of them was the answer.
 *
 * ONE FIELD, ONE HEIGHT — the label and the value share the label's line, and
 * the track plus its scale fill exactly the 36px a control occupies, so this
 * sits on the same baselines as the fields beside it.
 */
export function MeasureSlider({
  label,
  value,
  onChange,
  max,
  step,
  /** How the figure reads — "4 h", "16 mi". */
  format,
  /** Marks under the track, so the handle has something to mean. */
  ticks,
  trailing,
  tickLabel,
  className,
  "aria-label": ariaLabel,
}: {
  label: string;
  value: number;
  onChange: (v: number) => void;
  max: number;
  step: number;
  format: (v: number) => string;
  ticks: number[];
  /** What the figure costs, shown at the far edge of the label row. */
  trailing?: React.ReactNode;
  /** How a tick reads, when it is not just its own number. */
  tickLabel?: (v: number) => string;
  className?: string;
  "aria-label"?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      <div className="flex items-baseline justify-between gap-3">
        <span className="flex min-w-0 items-baseline gap-2">
          <span className="text-sm font-medium whitespace-nowrap text-foreground">
            {label}
          </span>
          <span className="truncate text-sm tabular-nums text-foreground">
            {format(value)}
          </span>
        </span>
        {/* WHAT IT COMES TO, at the other edge — the reason anybody moves this
            handle is the figure it puts on the bill, and having to look two
            sections down to see it is what makes a slider feel vague. */}
        {trailing && (
          <span className="shrink-0 text-xs tabular-nums text-muted-foreground">
            {trailing}
          </span>
        )}
      </div>

      <div className="relative h-9">
        <Slider
          className="absolute inset-x-0 top-1.5"
          aria-label={ariaLabel ?? label}
          min={0}
          max={max}
          step={step}
          value={[value]}
          onValueChange={([v]) => onChange(v)}
        />
        <div
          aria-hidden
          className="absolute inset-x-0 bottom-0 h-3 leading-none select-none"
        >
          {ticks.map((t, i) => {
            const first = i === 0;
            const last = i === ticks.length - 1;
            return (
              <span
                key={t}
                className={cn(
                  "absolute bottom-0 text-[11px] leading-none tabular-nums text-muted-foreground",
                  first && "left-0",
                  last && "right-0",
                  !first && !last && "-translate-x-1/2"
                )}
                style={first || last ? undefined : { left: `${(t / max) * 100}%` }}
              >
                {tickLabel ? tickLabel(t) : t}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}

/**
 * A CARD IN THE SHEET'S RIGHT-HAND RAIL.
 *
 * Copied verbatim from the 3PL order sheet, for the reason the rail exists
 * there: one rule decides which side a card is on — can you type into it? What
 * you fill in goes left, what the order HAS BECOME goes right. Once an
 * editable number and a computed one share a column they look identical, and
