/**
 * HOW LONG A RUNNING JOB HAS BEEN RUNNING — live.
 *
 * WHY A HOOK AND NOT A FIGURE. `computedLabor` needs two ends and a running
 * job only has one, so the second end is *now* and has to keep moving. A
 * dispatcher watching a job needs the number to change or they will assume
 * the screen is stale.
 *
 * FIFTEEN SECONDS, NOT ONE. Labour is billed in quarter hours and read in
 * minutes; a per-second tick would be a stopwatch offering a precision the
 * business does not use, and it would re-render the sheet sixty times a
 * minute to change nothing on screen. Fifteen is often enough that the
 * minutes never look stuck.
 *
 * It returns 0 when nothing is running, so a caller can render unconditionally
 * and decide by the timestamp rather than by the number.
 */
export function useElapsedHours(startedAt: string | null): number {
  const [, tick] = React.useReducer((n: number) => n + 1, 0);

  React.useEffect(() => {
    if (!startedAt) return undefined;
    const id = window.setInterval(tick, 15_000);
    return () => window.clearInterval(id);
  }, [startedAt]);

  if (!startedAt) return 0;
  const ms = Date.now() - new Date(startedAt).getTime();
  return ms > 0 ? ms / 3_600_000 : 0;
}

import * as React from "react";
import type { ReturnMode } from "./settings";
import {
  SERVICE_ORDERS,
  shortfallLabel,
  splitParts,
  type PartLine,
  type WorkStatus,
  TECHNICIANS,
  diffServiceOrder,
  type ServiceOrder,
} from "./work";

/*
  ONE LIST OF SERVICE ORDERS (Pavan, 2026-09-24).

  The dispatch board and the technician's phone read and write the SAME
  orders, so an outcome on one is an outcome on the other: a technician who
  arrives, starts, quotes or finishes moves the order on the board; a
  dispatcher who assigns, reschedules or edits changes the technician's job.

  THE CHANGE LOG IS WRITTEN HERE, round the only setter, so no path — the
  sheet's autosave, the board's acts, the phone's steps, a split, creation —
  can forget. Each write says who made it.
*/

/** An order put back to before anybody started it. */
const notStarted = (o: ServiceOrder): ServiceOrder => ({
  ...o,
  status: "Assigned",
  arrivedAt: null,
  startedAt: null,
  visits: [],
  completedAt: null,
  labor: 0,
  laborOverride: null,
  quote: null,
  assessment: null,
  assessmentLines: undefined,
  signed: false,
  invoiceCreated: false,
  invoicedAt: null,
  synced: false,
  partNeeded: null,
  parts: o.parts.map((p) => ({ ...p, fittedQty: undefined })),
});

/**
 * THE SHARED SEED, arranged for a technician's day (Pavan,
 * 2026-09-24): each technician's FIRST TWO jobs are Yet to start, and NOBODY
 * STARTS WITH AN ONGOING JOB — only one may be Ongoing at a time, so a
 * seeded one would block starting either of them. The first job started
 * becomes the one Ongoing.
 */
export function phoneSeed(all: ServiceOrder[]): ServiceOrder[] {
  const out = all.map((o) => ({ ...o }));
  for (const t of TECHNICIANS) {
    const mine = out
      .filter((o) => o.technicianId === t.id && o.status !== "Canceled")
      .sort((a, b) => (a.scheduledAt ?? "").localeCompare(b.scheduledAt ?? ""));
    const reset = new Set(mine.slice(0, 2).map((o) => o.id));
    for (const o of mine) if (o.status === "Ongoing") reset.add(o.id);
    reset.forEach((id) => {
      const i = out.findIndex((o) => o.id === id);
      out[i] = notStarted(out[i]);
    });
    /* THE FIRST JOB CARRIES SEVERAL TASKS, so the task cards can be seen as a
       list (2026-09-24) — most seeded orders have one. Dummy, and only in the
       phone's copy. */
    const first = mine[0] && out.findIndex((o) => o.id === mine[0].id);
    if (first !== undefined && first >= 0 && out[first].assets.length < 3) {
      const o = out[first];
      const extra = [
        { workType: "Leak check", fault: "Weeping at the bottom collar" },
        { workType: "Hose swap", fault: "Hose kinked and split" },
      ].map((x, k) => ({
        assetId: "",
        assetName: `${o.assetName || "Asset"} — ${k === 0 ? "fill line" : "dispenser"}`,
        assetType: o.assetType,
        ...x,
      }));
      out[first] = { ...o, assets: [...o.assets, ...extra].slice(0, 3) };
    }
  }
  return out;
}


let store: ServiceOrder[] = phoneSeed(SERVICE_ORDERS);
const listeners = new Set<() => void>();

/** Write the orders, logging what changed against `by`. */
export function setServiceOrders(
  fn: (prev: ServiceOrder[]) => ServiceOrder[],
  by: string = "Dana Whitfield"
) {
  const prev = store;
  const next = fn(prev);
  if (next === prev) return;
  const at = new Date().toISOString();
  store = next.map((r) => {
    const before = prev.find((x) => x.id === r.id);
    if (!before)
      return r.audit.length > 0
        ? r
        : {
            ...r,
            audit: [{ at, by, changes: [r.status === "Drafted" ? "Order created as a draft" : "Order created"] }],
          };
    if (before === r) return r;
    /* A DRAFT BEING FILLED IN WRITES NOTHING — the same rule 3PL follows.
       What gets logged is the commitment, not every field on the way. */
    if (before.status === "Drafted" && r.status === "Drafted") return r;
    const changes = diffServiceOrder(before, r);
    return changes.length > 0 ? { ...r, audit: [...r.audit, { at, by, changes }] } : r;
  });
  listeners.forEach((l) => l());
}

export function useServiceOrders(): [ServiceOrder[], typeof setServiceOrders] {
  const rows = React.useSyncExternalStore(
    (l) => {
      listeners.add(l);
      return () => listeners.delete(l);
    },
    () => store
  );
  return [rows, setServiceOrders];
}

/** The next free order number. */
export const nextServiceOrderNo = (rows: ServiceOrder[]) =>
  `SO-${Math.max(...rows.map((r) => Number(r.orderNo.slice(3)) || 0)) + 1}`;

const keyOfDay = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;

/**
 * PARTS MISSING — THE THREE OUTCOMES, in one place (2026-09-24). The board,
 * the order sheet and the phone all call this, so they cannot disagree about
 * what "the rest" becomes. The visit has already been closed by the caller.
 * Returns the new rows and what to tell the reader.
 */
export function resolveShortfall(
  rows: ServiceOrder[],
  id: string,
  data: { parts: PartLine[]; note?: string | null; mode: ReturnMode; nativeBilling: boolean }
): { rows: ServiceOrder[]; title: string; description: string } {
  const order = rows.find((r) => r.id === id);
  if (!order) return { rows, title: "", description: "" };
  const { owed } = splitParts(data.parts);
  const shortfall = shortfallLabel(data.parts);
  const at = new Date().toISOString();
  const note = data.note ?? order.techNotes;

  /* ROLLED OVER — the same order tomorrow, everything kept. */
  if (data.mode === "rollover") {
    /* THE DAY AFTER THE VISIT — tomorrow — at the booking's own time of day. */
    const next = new Date();
    next.setDate(next.getDate() + 1);
    if (order.scheduledAt) {
      const t = new Date(order.scheduledAt);
      next.setHours(t.getHours(), t.getMinutes(), 0, 0);
    }
    return {
      rows: rows.map((r) =>
        r.id === id
          ? {
              ...r,
              status: "Assigned" as WorkStatus,
              parts: data.parts,
              /* THE CALLOUT: an Assigned order that is not a normal one. */
              partNeeded: shortfall,
              techNotes: note,
              arrivedAt: null,
              completedAt: null,
              scheduledAt: next.toISOString(),
              dateKey: keyOfDay(next),
            }
          : r
      ),
      title: `${order.orderNo} rolled over to tomorrow`,
      description: `${shortfall} still owed · same technician.`,
    };
  }

  /* THE REST, AS ITS OWN ORDER — shared by the two outcomes that close this
     one. It starts from nothing but what is owed: labour, mileage and fees
     belong to the visit that happened. No technician and no date. */
  const no = nextServiceOrderNo(rows);
  const linked = data.mode === "neworder";
  const rest: ServiceOrder = {
    ...order,
    id: `so-owed-${no}`,
    orderNo: no,
    status: (linked ? "Linked order" : "Parts pending") as WorkStatus,
    audit: [],
    fault: `Awaiting parts — ${shortfall}`,
    assets: order.assets.map((a) => ({ ...a, fault: `Awaiting parts — ${shortfall}` })),
    parts: owed,
    arrivedAt: null,
    visits: [],
    startedAt: null,
    assessment: null,
    assessmentLines: undefined,
    siteAssessment: undefined,
    /* THE PREVIOUS TECHNICIAN'S NOTES GO WITH IT, so whoever takes it knows. */
    techNotes: note,
    labor: 0,
    laborOverride: null,
    fees: [],
    quote: null,
    extraCharges: [],
    invoiceCreated: false,
    invoicedAt: null,
    synced: false,
    partNeeded: shortfall,
    returnOf: linked ? order.orderNo : null,
    spawnedReturn: null,
    signed: false,
    completedAt: null,
    technicianId: null,
    scheduledAt: null,
    dateKey: keyOfDay(new Date()),
  };
  return {
    rows: [
      rest,
      ...rows.map((r) =>
        r.id === id
          ? {
              ...r,
              parts: data.parts,
              status: (linked ? "Completed — linked" : "Completed") as WorkStatus,
              completedAt: at,
              signed: true,
              partNeeded: null,
              techNotes: note,
              spawnedReturn: linked ? no : null,
              invoiceCreated: data.nativeBilling,
              invoicedAt: data.nativeBilling ? at : null,
            }
          : r
      ),
    ],
    title: `${order.orderNo} completed`,
    description: linked
      ? `New order ${no} carries ${shortfall}, linked back.`
      : `${no} waits in the queue as Parts pending — ${shortfall}.`,
  };
}

import { RENTAL_ASSETS, type RentalAsset } from "../threepl/directory";
import type { CodeDiscTone } from "@/components/ui/code-disc";
import type { LaneColor } from "../threepl/BrokerBoard";
import { statusTones, type StatusKind } from "../statusKind";
import { MONEY as money } from "../data";

/*
  SERVICE WORK — the model, the fixture and the invariants.

  WHAT THIS MODULE IS. Everything this business puts out on rent — tanks,
  pumps, monitors, nozzles — breaks, drifts out of spec, or needs swapping.
  A SERVICE ORDER is one job on one deployed asset: somebody reports it, a
  dispatcher books it, a technician does it, a manager signs it off, and it is
  billed. The asset is the subject, because the history hangs off the asset.

  THE MONEY RULE, WHICH IS THE SHARP EDGE OF THE WHOLE MODULE.

    A QUOTE is parts + the predefined fee, and it is sent and approved on site
    BEFORE the work starts. It cannot contain labour or mileage, because at the
    moment it is sent nobody knows how long the job took or how far the van
    went.

    AN INVOICE is raised AFTER the job and may be bigger: actual labour hours,
    mileage, and any extra parts the technician turned out to need. The gap
    between the two is not an error — it is the thing the customer has to be
    able to see, so both figures stay on the record.

  INVENTED, and flagged: the technicians, the fault text, the labour hours, the
  parts and their costs, the rates. Customers, ship-tos and assets are REUSED
  from the existing rental directory, because a tank being serviced is the tank
  on the rental list, not a second copy of it.
*/

/* ------------------------------------------------------------ the stages */

/**
 * EIGHT STAGES, and each is a different answer to "what is this job waiting
 * on".
 *
 *   Open            nobody is on it
 *   Assigned        a technician is, but they have not arrived
 *   In progress     they have arrived and are working
 *   Parts-pending   they stopped, and it is a part that stopped them
 *   Needs approval  the work is recorded and a manager has not signed it
 *   Approved        signed off; the invoice exists
 *   Completed       the invoice reached accounting and the job is closed
 *   Canceled       it is not happening
 *
 * OPEN AND ASSIGNED ARE TWO FACTS, NOT ONE. A job nobody is on and a job
 * somebody is on but has not started are different problems, and the gap
 * between them is the dispatcher's backlog.
 *
 * APPROVED AND COMPLETED ARE TWO FACTS TOO. Approved says a human agreed the
 * numbers; Completed says the money left the building. An invoice that has
 * been raised and an invoice that has landed in accounting are not the same
 * state, and only the second one means nobody has to look at this again.
 */
/*
  ═══════════════════════════════════════════════════════════════════════════
  THE LIFECYCLE — FIVE LANES, AND THE STATUSES INSIDE THEM
  ═══════════════════════════════════════════════════════════════════════════

  RESTRUCTURED 2026-09-23 (Pavan). It was eight flat statuses and eight lanes,
  one each, which made the board a row of narrow columns most of them empty —
  and made every status a peer of every other, so "waiting for a part" looked
  like the same KIND of thing as "approved".

  A LANE IS A PLACE IN THE WORK. A STATUS IS WHY IT IS THERE. The lane answers
  "whose problem is this now"; the status answers "what exactly". Five lanes,
  because there are five people-shaped answers to the first question:

    Open      nobody is on it            → dispatch has to assign somebody
    Assigned  somebody is on it, later   → nothing to do but wait for the day
    Working   it is in the field today   → the technician has it
    Completed the visit is over          → what is left is money
    Synced    the money has been checked → finished

  THE TWO OPEN STATUSES THAT ARE NOT "NEW" ARE THE POINT. A remainder from a
  partial visit and a spawned linked order are both WORK NOBODY IS ON, which
  is what Open means — filing them anywhere else hides outstanding work behind
  a word about how it arose.
*/

export type WorkLane =
  | "Open"
  | "Assigned"
  | "Working"
  | "Completed"
  | "Synced"
  | "Canceled";

export type WorkStatus =
  /* Open — nobody is on it */
  | "Drafted"
  | "Parts pending"
  | "Linked order"
  /* Assigned — somebody is, but not today */
  | "Assigned"
  /* Working — it is in the field */
  | "Yet to start"
  | "Ongoing"
  | "Needs approval"
  /* THE CUSTOMER HAS THE INVOICE and has not said yes yet (Pavan,
     2026-09-25 — the no-technician-app flow). */
  | "Awaiting approval"
  /* Completed — the visit is over */
  | "Completed"
  | "Completed — linked"
  /* Synced — the money has been looked at */
  | "Yet to be reviewed"
  | "Reviewed"
  /* PAYMENT, AS ACCOUNTING REPORTS IT (Pavan, 2026-09-25). Set by the
     accounting system, never pressed in the app. */
  | "Awaiting payment"
  | "Payment received"
  | "Payment delayed"
  | "Unpaid"
  | "Canceled";

export const WORK_STATUSES: WorkStatus[] = [
  "Drafted",
  "Parts pending",
  "Linked order",
  "Assigned",
  "Yet to start",
  "Ongoing",
  "Needs approval",
  "Awaiting approval",
  "Completed",
  "Completed — linked",
  "Yet to be reviewed",
  "Reviewed",
  "Awaiting payment",
  "Payment received",
  "Payment delayed",
  "Unpaid",
  "Canceled",
];

/** Lane order on the board. Canceled sits behind a rule — it is not a step. */
export const WORK_LANES: {
  key: WorkLane;
  statuses: WorkStatus[];
  apart?: boolean;
}[] = [
  { key: "Open", statuses: ["Drafted", "Parts pending", "Linked order"] },
  { key: "Assigned", statuses: ["Assigned"] },
  { key: "Working", statuses: ["Yet to start", "Ongoing", "Awaiting approval", "Needs approval"] },
  { key: "Completed", statuses: ["Completed", "Completed — linked"] },
  { key: "Synced", statuses: ["Awaiting payment", "Payment delayed", "Unpaid", "Payment received", "Yet to be reviewed", "Reviewed"] },
  { key: "Canceled", statuses: ["Canceled"], apart: true },
];

/** Which lane a status lives in. One place, so the board and the list agree. */
export const LANE_OF: Record<WorkStatus, WorkLane> = Object.fromEntries(
  WORK_LANES.flatMap((l) => l.statuses.map((st) => [st, l.key]))
) as Record<WorkStatus, WorkLane>;

/** Past this, the visit has happened and what is left is money. */
export function isRecorded(s: WorkStatus): boolean {
  return (
    s === "Needs approval" ||
    LANE_OF[s] === "Completed" ||
    LANE_OF[s] === "Synced"
  );
}

/**
 * The technician can still act on it.
 *
 * NOT "PARTS PENDING" ANY MORE. That status now belongs to the REMAINDER,
 * which is a separate order sitting in Open waiting for somebody to be put on
 * it — there is nothing for a technician to resume.
 */
export function isWorkable(s: WorkStatus): boolean {
  return s === "Assigned" || s === "Yet to start" || s === "Ongoing";
}

/** Work nobody is on. The lane's whole meaning, and the CTA follows it. */
export const isUnassigned = (s: WorkStatus) => LANE_OF[s] === "Open";

/**
 * THE DS SHIPS FOUR TONE CHANNELS and this lifecycle has twelve statuses, so
 * they share. The DS's own rule is that colour is never the only carrier of
 * meaning — the label always says which — so sharing is honest where two
 * statuses are the same KIND of state. The lane colours below do the
 * separating.
 */

/**
 * WHAT KIND OF STATE A STATUS IS — the badge's colour (Pavan, 2026-09-23).
 *
 * FIVE KINDS, AND THEY ARE ABOUT WHAT THE READER SHOULD DO, not about where
 * the status sits in the ladder:
 *
 *   caution   WAITING ON SOMEBODY — pending, awaiting, not yet looked at
 *   success   DONE — the thing it was for has happened
 *   info      SIMPLY TRUE — somebody is on it, it is under way. Asks nothing
 *   critical  A WARNING, or a state important enough to change a plan
 *   neutral   NEITHER — a record that exists and is not yet a state
 *
 * A DISPATCHER SCANS A BOARD FOR THE YELLOW ONES. That is the whole argument
 * for colouring these: every badge grey made the column the only thing
 * carrying meaning, and a column is a place, not a state — a Parts-pending
 * remainder and a brand-new job sat in Open looking identical.
 *
 * NOTHING IS CRITICAL YET, and that is deliberate rather than an oversight:
 * no status in this lifecycle is a warning. Red stays for the priority badge
 * and for a state that genuinely goes wrong, so that when it does appear it
 * is worth looking at.
 */
export const WORK_STATUS_KIND: Record<WorkStatus, StatusKind> = {
  /* A record that exists. Nothing has happened to it yet. */
  Drafted: "neutral",
  /* Waiting on parts, and on somebody to take the next trip. */
  "Parts pending": "caution",
  /* Work spun off another job and waiting for an owner. */
  "Linked order": "caution",
  /* Somebody is on it. Both are facts, neither asks anything. */
  Assigned: "info",
  "Yet to start": "info",
  Ongoing: "info",
  /* Sitting on a manager's desk. */
  "Needs approval": "caution",
  /* Waiting on the customer to accept the invoice. */
  "Awaiting approval": "caution",
  Completed: "success",
  "Completed — linked": "success",
  /* An invoice nobody has checked. */
  "Yet to be reviewed": "caution",
  Reviewed: "success",
  /* PAYMENT — waiting is caution; late is still somebody else's move;
     UNPAID is the severe case and the only red on the board. */
  "Awaiting payment": "caution",
  "Payment received": "success",
  "Payment delayed": "caution",
  Unpaid: "critical",
  /* NOT RED. Canceled is a terminal non-event, not a problem to solve — and
     a red badge on a lane of them would be the loudest thing on the board
     saying the least. */
  Canceled: "neutral",
};

/** The same kinds as `StatusChip` tones — the table's and the sheet's chip. */
export const WORK_STATUS_TONE = statusTones(WORK_STATUS_KIND);

/** The DS's `--fp-lane-*` set, the same tokens the 3PL board draws from. */
export const WORK_LANE_COLOR: Record<WorkStatus, LaneColor> = {
  Drafted: "grey",
  "Parts pending": "yellow",
  "Linked order": "yellow",
  Assigned: "blue",
  "Yet to start": "blue",
  Ongoing: "cyan",
  "Needs approval": "violet",
  "Awaiting approval": "violet",
  Completed: "green",
  "Completed — linked": "green",
  "Yet to be reviewed": "violet",
  Reviewed: "purple",
  "Awaiting payment": "purple",
  "Payment received": "purple",
  "Payment delayed": "purple",
  Unpaid: "purple",
  /* CANCELLED IS NOT RED (DS ui §10b) — a terminal non-event, grey. */
  Canceled: "grey",
};

