                                placeholder="Add vendor"
                                disabled={draft.status === "Blocked"}
                                autoFocus={focusPartner?.row === i}
                                aria-label={`Vendor for row ${i + 1}`}
                                /* NO REACHABILITY TAG. "Emails off" and "Link
                                   only" described how the invitation would
