import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { DateRangePopover, formatDateRange, type DateRange } from "@/components/ui/date-picker";
import { dateKeyOf, startOfDay } from "../data";

export type { DateRange };

const DAY = 86_400_000;

/**
 * The toolbar control: a window you can step, and the picker behind its label.
 *
 * 3PL ONLY, and deliberately: a fuel dispatcher works one day and steps through
 * days, but a broker's orders sit against a delivery window that routinely runs
 * over a weekend, and a one-day view of those is a lane that keeps looking
 * empty. The arrows move by the length of the window you are on — a week steps
 * a week — so stepping never silently changes how much you are looking at.
 */
export function DateRangeFilter({
  value,
  onChange,
  fullWidth = false,
  all,
  count,
  noun,
}: {
  value: DateRange;
  onChange: (next: DateRange) => void;
  /**
   * Stretch the control to its container, the LABEL taking the slack.
   *
   * On the toolbar it sits in a row of controls and is as wide as the date it
   * prints. Given a row of its own — the export sheet's Date line — that left
   * it huddled against one edge under a full-width heading. The arrows keep
   * their 32px either way: they are the same act at any width, and a stepper
   * that grows with the panel stops reading as one.
   */
  fullWidth?: boolean;
  /** "All dates" and the span it means here — the screen's records. */
  all?: DateRange;
  /** Live "N orders match" in the picker's footer. */
  count?: (r: DateRange) => number;
  noun?: string;
}) {
  const days = Math.round((value.to.getTime() - value.from.getTime()) / DAY) + 1;

  const step = (dir: -1 | 1) => {
    const shift = dir * days * DAY;
    onChange({
      from: startOfDay(new Date(value.from.getTime() + shift)),
      to: startOfDay(new Date(value.to.getTime() + shift)),
    });
  };

  /* ONE DAY READS AS ONE DAY. "Sep 7 – Sep 7" is a range only a computer would
     write, so a single-day window prints as a date. Everything reads as
     "All dates", and has no next or previous. */
  const isAll =
    !!all && dateKeyOf(all.from) === dateKeyOf(value.from) && dateKeyOf(all.to) === dateKeyOf(value.to);
  const label = isAll ? "All dates" : formatDateRange(value);

  return (
    <div className={cn("flex items-center gap-1", fullWidth && "w-full")}>
      <Button
        variant="outline"
        size="icon-sm"
        aria-label={days === 1 ? "Previous day" : `Previous ${days} days`}
        disabled={isAll}
        onClick={() => step(-1)}
      >
        <ChevronLeft />
      </Button>

      {/* THE SHARED PICKER (DS ui §10p) — presets, two months, typed dates,
          a live count; nothing changes until Apply. */}
      <DateRangePopover
        value={value}
        onChange={onChange}
        all={all}
        count={count}
        noun={noun}
        resetTo={(() => {
          const t = startOfDay(new Date());
          return { from: t, to: t };
        })()}
      >
        <Button
          variant="outline"
          size="sm"
          className={cn(fullWidth && "h-8 flex-1")}
          aria-label={`Delivery dates: ${label}. Pick a date or range`}
        >
          {label}
        </Button>
      </DateRangePopover>

      <Button
        variant="outline"
        size="icon-sm"
        aria-label={days === 1 ? "Next day" : `Next ${days} days`}
        disabled={isAll}
        onClick={() => step(1)}
      >
        <ChevronRight />
      </Button>
    </div>
  );
}

import * as React from "react";
import { toast } from "sonner";
import { Archive, CheckCircle2, Download, MoreHorizontal, Tag, XCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import type { BulkAction } from "@/components/tables-layout";
import { DirectoryList, type DirectoryColumn, type DirectoryFacet } from "./DirectoryList";
import {
  DirectoryRecordSheet,
  type RecordReadSection,
} from "./DirectoryRecordSheet";
import type { FormSectionDef } from "./directoryFormTypes";
import { writeUrl } from "./directoryUrl";
import type { AuditEvent, RecordStatus } from "./directoryCore";
import type { GroupDim } from "@/components/tables-layout";

/*
  A list, and a sheet over it. For one entity.

  THE DS'S RECORD INTERACTION IS THE SIDE SHEET — `RecordSheet`, as
  `CustomerSheet` uses it. The record IS the form: `mode` decides whether the
  header reads Edit or Create, the body carries the fields, and the footer
  carries Save Changes. There is no separate full-page detail and no separate
  editor, because that would be a second pattern doing the same job, and the
  list would stop being visible behind the thing you opened from it.

  WHY THIS IS ONE COMPONENT AND NOT FOUR. The traffic is identical on every
  entity: a row opens the sheet, saving closes it, creating prepends a record,
  archiving flips a status. Written four times, the fourth copy is the one
  where a canceled create leaves a half-made record in the list.

  WHAT AN ENTITY STILL SUPPLIES is everything genuinely about ITS records —
  columns, cells, facets, the form's fields, what the sheet shows below them,
  and what "archive" means for it.

  STATE LIVES HERE, at the top of the entity. A saved edit has to be visible on
  the list behind the sheet, and the only way to make that true without a store
  is to own the array in one place. Real screens would refetch; this prototype
  mutates its own copy and keeps the audit trail honest about it.

  BACK BEHAVES. Opening a record pushes a history entry, so the browser's Back
  closes the sheet — the one navigation people try without being told.
*/

export interface EntityConfig<Row, K extends string> {
  /** `customers`, `vendors` — the URL's `entity`, and the params namespace. */
  urlKey: string;
  /** Breadcrumb and heading: "Customers". */
  parentLabel: string;
  /** One record: "customer", "vendor", "product", "asset". */
  noun: string;
  nounPlural?: string;
  rowId: (row: Row) => string;
  nameOf: (row: Row) => string;

  columns: DirectoryColumn<K>[];
  renderCell: (row: Row, key: K) => React.ReactNode;
  matches: (row: Row, q: string) => boolean;
  searchFields: { key: string; label: string; text: (row: Row) => string }[];
  searchPlaceholder: string;
  sortRows: (rows: Row[], sort: { key: K; dir: "asc" | "desc" } | null) => Row[];
  dimensions: GroupDim<Row>[];
  facets: DirectoryFacet<Row>[];
  measureOf?: (row: Row) => number;
  measureUnit?: string;
  formatTotal?: (total: number) => string;
  emptyIcon: React.ReactNode;
  exportRow: (row: Row) => Record<string, string | number>;

  /* ── the sheet ── */
  /** The chips beside the sheet's title — status, and what blocks this record. */
  headerAsideOf: (row: Row) => React.ReactNode;
  /** Everything the sheet shows but does not edit, below the form's sections. */
  readSectionsOf: (row: Row, go: Navigator) => RecordReadSection[];

  /* ── the form ── */
  formSections: FormSectionDef<Row>[];
  /** A blank record, for Create. Given a fresh id. */
  blank: (id: string) => Row;
  /** Reads and writes the shared lifecycle field, whatever it is called here. */
  statusField: {
    get: (row: Row) => RecordStatus;
    set: (row: Row, next: RecordStatus) => Row;
  };
  /** The record's edit history — shown in the header's drawer, not the body. */
  auditOf: (row: Row) => AuditEvent[];
  withAudit: (row: Row, entry: AuditEvent) => Row;
  /** An alternative rendering of the same rows — vendors only, for now. */
  renderMap?: (rows: Row[], open: (row: Row) => void) => React.ReactNode;
  /** Verbs beyond archive that this entity's selection supports. */
  extraBulkActions?: (
    selected: Row[],
    apply: (fn: (row: Row) => Row, message: string) => void
  ) => BulkAction[];
}

/** Cross-entity jumps a record page can make. */
export interface Navigator {
  openCustomer: (id: string) => void;
  openVendor: (id: string) => void;
  openProduct: (id: string) => void;
  openAsset: (id: string) => void;
}

/** The sheet is open on a record, open on a new one, or closed. */
type Sheet = { kind: "record"; id: string } | { kind: "create" } | null;

export interface DirectoryEntityScreenProps<Row, K extends string> {
  config: EntityConfig<Row, K>;
  rows: Row[];
  onRowsChange: (next: Row[]) => void;
  navigate: Navigator;
  /** Open this record on mount — a jump from another entity, or a deep link. */
  focusId?: string | null;
  onFocusHandled?: () => void;
  canWrite?: boolean;
  /** The list's total, for the page header. */
  onTotalChange?: (label: string | null) => void;
}

/** The audit entry a save writes. One per save, listing what actually moved. */
function auditFor<Row>(
  before: Row,
  after: Row,
  sections: FormSectionDef<Row>[],
  actor: string
): AuditEvent | null {
  const changes: string[] = [];
  sections.forEach((s) =>
    s.fields.forEach((f) => {
      const a = f.get(before);
      const b = f.get(after);
      if (a === b) return;
      const show = (v: unknown) =>
        v === null || v === undefined || v === "" ? "empty" : String(v);
      changes.push(`${f.label}: ${show(a)} → ${show(b)}`);
    })
  );
  if (changes.length === 0) return null;
  return {
    id: `au-${Date.now().toString(36)}`,
    at: new Date().toISOString(),
    by: actor,
    action: "Updated",
    changes,
  };
}

export function DirectoryEntityScreen<Row, K extends string>({
  config,
  rows,
  onRowsChange,
  navigate,
  focusId,
  onFocusHandled,
  canWrite = true,
  onTotalChange,
}: DirectoryEntityScreenProps<Row, K>) {
  const [sheet, setSheet] = React.useState<Sheet>(null);
  const seq = React.useRef(0);

  /* A jump from another entity's sheet opens this entity's sheet on that
     record — the list is behind it either way, which is the point. */
  React.useEffect(() => {
    if (!focusId) return;
    setSheet({ kind: "record", id: focusId });
    onFocusHandled?.();
  }, [focusId, onFocusHandled]);

  const record =
    sheet?.kind === "record" ? rows.find((r) => config.rowId(r) === sheet.id) ?? null : null;

  /* A BLANK RECORD IS MADE ONCE PER OPEN, not on every render — remade each
     time, the sheet's draft would reset under the reader's hands. */
  const blank = React.useMemo(
    () => (sheet?.kind === "create" ? config.blank(`${config.urlKey.slice(0, 2)}-new-${(seq.current += 1)}`) : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [sheet?.kind === "create"]
  );

  const openRecord = (row: Row) => {
    const id = config.rowId(row);
    setSheet({ kind: "record", id });
    /* PUSH, not replace: Back should close the sheet, and that is the one
       navigation nobody has to be told about. */
    writeUrl({ entity: config.urlKey, record: id }, { push: true });
  };

  const closeSheet = () => {
    setSheet(null);
    writeUrl({ record: null });
  };

  const replaceRow = (id: string, fn: (row: Row) => Row) =>
    onRowsChange(rows.map((r) => (config.rowId(r) === id ? fn(r) : r)));

  const applyToMany = (ids: string[], fn: (row: Row) => Row, message: string) => {
    const set = new Set(ids);
    onRowsChange(rows.map((r) => (set.has(config.rowId(r)) ? fn(r) : r)));
    toast.success(message);
  };

  const plural = config.nounPlural ?? `${config.noun}s`;
  const Noun = config.noun[0].toUpperCase() + config.noun.slice(1);

  /* THE RECORD AS IT WAS WHEN OPENED (Pavan, 2026-10-07). Autosave writes as
     the reader types; the audit entry is one per visit, against this. */
  const opened = React.useRef<Row | null>(null);
  const openedId = sheet?.kind === "record" ? sheet.id : null;
  React.useEffect(() => {
    opened.current = openedId
      ? rows.find((r) => config.rowId(r) === openedId) ?? null
      : null;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openedId]);

  const autosave = (draft: Row) => replaceRow(config.rowId(draft), () => draft);

  /** Ends an edit visit: one audit entry for everything that moved. */
  const finish = (draft: Row) => {
    const before = opened.current;
    opened.current = null;
    if (!before) return null;
    const entry = auditFor(before, draft, config.formSections, "Dana Whitfield");
    const next = entry ? config.withAudit(draft, entry) : draft;
    replaceRow(config.rowId(next), () => next);
    return entry;
  };

  /* Archive / Restore from the ⋯ — one write with the visit's audit, then
     back to the list. */
  const setStatusFromSheet = (row: Row, status: RecordStatus, message: string) => {
    const before = opened.current;
    opened.current = null;
    const after = config.statusField.set(row, status);
    const entry = before ? auditFor(before, after, config.formSections, "Dana Whitfield") : null;
    const next = entry ? config.withAudit(after, entry) : after;
    replaceRow(config.rowId(next), () => next);
    toast.success(message);
    closeSheet();
  };

  const submit = (draft: Row) => {
    if (sheet?.kind === "create") {
      onRowsChange([draft, ...rows]);
      toast.success(`${Noun} created`);
      closeSheet();
      return;
    }
    if (!record) return;
    const entry = finish(draft);
    /* A save that changed nothing says so rather than claiming a save — the
       audit trail stays clean and nobody goes looking for the diff. */
    if (entry) {
      toast.success("Changes saved");
    } else {
      toast.info("Nothing to save");
    }
    closeSheet();
  };

  const initial = sheet?.kind === "create" ? blank : record;

  return (
    <>
      <DirectoryList<Row, K>
        rows={rows}
        columns={config.columns}
        rowId={config.rowId}
        renderCell={config.renderCell}
        matches={config.matches}
        searchFields={config.searchFields}
        searchPlaceholder={config.searchPlaceholder}
        sortRows={config.sortRows}
        dimensions={config.dimensions}
        facets={config.facets}
        noun={config.noun}
        nounPlural={config.nounPlural}
        measureOf={config.measureOf}
        measureUnit={config.measureUnit}
        formatTotal={config.formatTotal}
        emptyIcon={config.emptyIcon}
        onOpenRow={openRecord}
        openLabel={(r) => `Open ${config.noun} ${config.nameOf(r)}`}
        urlKey={config.urlKey}
        canWrite={canWrite}
        onTotalChange={onTotalChange}
        renderMap={
          config.renderMap ? (rows) => config.renderMap!(rows, openRecord) : undefined
        }
        exportRow={config.exportRow}
        onCreate={() => setSheet({ kind: "create" })}
        createLabel={`Add New ${Noun}`}
        bulkActions={(selected, clear) => {
          const ids = selected.map(config.rowId);
          const allArchived = selected.every((r) => config.statusField.get(r) === "archived");
          return [
            {
              key: "export",
              label: "Export selection",
              icon: <Download />,
              onSelect: () => {
                toast.success(
                  `${selected.length} ${selected.length === 1 ? config.noun : plural} exported`
                );
                clear();
              },
            },
            ...(config.extraBulkActions?.(selected, (fn, message) => {
              applyToMany(ids, fn, message);
              clear();
            }) ?? []),
            {
              key: "archive",
              label: allArchived ? "Restore" : "Archive",
              icon: allArchived ? <CheckCircle2 /> : <Archive />,
              destructive: !allArchived,
              disabled: !canWrite,
              title: canWrite ? undefined : "You do not have permission to archive records",
              onSelect: () => {
                applyToMany(
                  ids,
                  (r) => config.statusField.set(r, allArchived ? "active" : "archived"),
                  `${ids.length} ${ids.length === 1 ? config.noun : plural} ${allArchived ? "restored" : "archived"}`
                );
                clear();
              },
            },
          ];
        }}
      />

      {initial && (
        <DirectoryRecordSheet<Row>
          open
          onOpenChange={(next) => {
            if (!next) closeSheet();
          }}
          /* Close keeps the latest valid draft and writes its audit entry. */
          onClose={(latest) => {
            if (!record) return;
            const entry = finish(latest ?? record);
            if (entry)
              toast.success("Changes saved");
          }}
          recordKey={config.rowId(initial)}
          onAutosave={autosave}
          headerMenu={
            sheet?.kind === "create" || !record ? undefined : (
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button variant="ghost" size="icon-sm" aria-label={`More ${config.noun} actions`}>
                    <MoreHorizontal />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-52">
                  {config.statusField.get(record) === "archived" ? (
                    <DropdownMenuItem
                      disabled={!canWrite}
                      onSelect={() => setStatusFromSheet(record, "active", `${Noun} restored`)}
                    >
                      <CheckCircle2 />
                      Restore
                    </DropdownMenuItem>
                  ) : (
                    <DropdownMenuItem
                      variant="destructive"
                      disabled={!canWrite}
                      onSelect={() => setStatusFromSheet(record, "archived", `${Noun} archived`)}
                    >
                      <Archive />
                      Archive
                    </DropdownMenuItem>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            )
          }
          mode={sheet?.kind === "create" ? "create" : "edit"}
          noun={Noun}
          title={config.nameOf(initial)}
          headerAside={sheet?.kind === "create" ? undefined : config.headerAsideOf(initial)}
          initial={initial}
          sections={config.formSections}
          readSections={
            sheet?.kind === "create" ? [] : config.readSectionsOf(initial, navigate)
          }
          /* A record being created has no history — the icon would open an
             empty drawer, so it is not drawn at all. */
          audit={sheet?.kind === "create" ? undefined : config.auditOf(initial)}
          onSubmit={submit}
        />
      )}
    </>
  );
}

/** A bulk verb that sets a tag on everything selected. Shared by all four. */
export function tagBulkAction<Row>(
  apply: (fn: (row: Row) => Row, message: string) => void,
  addTag: (row: Row, tag: string) => Row,
  count: number
): BulkAction {
  return {
    key: "tag",
    label: "Add “Watch List” tag",
    icon: <Tag />,
    onSelect: () =>
      apply(
        (r) => addTag(r, "Watch List"),
        `Tagged ${count} ${count === 1 ? "record" : "records"}`
      ),
  };
}

/** Deactivate / reactivate, for the two entities that have an `active` flag. */
export function activeBulkAction<Row>(
  apply: (fn: (row: Row) => Row, message: string) => void,
  isActive: (row: Row) => boolean,
  setActive: (row: Row, next: boolean) => Row,
  selected: Row[]
): BulkAction {
  const allOff = selected.every((r) => !isActive(r));
  return {
    key: "active",
    label: allOff ? "Reactivate" : "Deactivate",
    icon: allOff ? <CheckCircle2 /> : <XCircle />,
    onSelect: () =>
      apply(
        (r) => setActive(r, allOff),
        `${selected.length} ${selected.length === 1 ? "record" : "records"} ${allOff ? "reactivated" : "deactivated"}`
      ),
  };
}

import * as React from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { Plus, SearchX } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/components/ui/empty";
import { TooltipProvider } from "@/components/ui/tooltip";
import {
  BulkActionBar,
  GroupedListFooter,
  TablePagination,
  useGrouping,
  type BulkAction,
  type GroupDim,
} from "@/components/tables-layout";
import { toast } from "sonner";
import { FuelOrdersViewBar } from "../FuelOrdersViewBar";
import { ListToolbar, ColumnSearchChip, FilterChips, type ListView, useViewBar, ViewStatement } from "../ListToolbar";
import { ListFilters } from "../ListFilters";
import { ExportSheet, type ExportFilterRow } from "../ExportSheet";
import { ListTable } from "../ListTable";
import { useSavedViews } from "../useSavedViews";
import { packList, readUrl, unpackList, writeUrl } from "./directoryUrl";
import { downloadCsv } from "../csv";

/*
  The Directory's list shell — Customers, Vendors, Products, Rental Assets.

  ONE COMPONENT, FOUR SCREENS. The four share a shape exactly: a record list
  with no date scope, a facet panel, grouping, selection, pagination and a
  footer that counts. Four copies of that would have drifted within a release —
  and the drift would have been in the parts nobody looks at twice, like which
  screens suspend pagination while grouped.

  WHAT EACH SCREEN STILL OWNS is what is genuinely its own: its records, its
  columns and how their cells render, what it can be grouped and filtered by,
  what can be DONE to a selection of them, and whether anything about it SUMS.
  Everything below that line is the same everywhere, so it lives here.

  NOT DATE-SCOPED, deliberately. A carrier, an account, a product and a tank
  carry no date, so the toolbar's date stepper is omitted rather than shown with
  nothing to scope — the same call Sales' Customers screen makes.

  PAGINATION AND GROUPING ARE EXCLUSIVE. At 30 rows a page a group straddles
  the boundary and its header claims a count for records that are not on
  screen, so while grouped the list scrolls whole and reports its shape
  instead. That is `GroupedListFooter`'s entire reason for existing, and the
  two footers keep the same skeleton so the bottom of the screen does not jump.
*/

/** Mirrors `TablePagination`'s own default set — used only to validate a URL. */
const DS_PAGE_SIZES = [10, 25, 50, 100];

/*
  WHAT A CELL PRINTS, as text — what the header row's "Filter…" boxes match.

  The boxes promise to search the column you are looking at, so they have to
  match the words in it: "$12,400" not 12400, "Expiring" not a date, the
  status chip's label not its enum. The four screens only describe their cells
  as React, so the cell is rendered here, off screen, and its text read back —
  one definition of the column, not a second text-only copy of it to drift.
  Tooltip bodies are closed in a static render, so hover text does not match;
  that is the same line the eye draws.

  A cell that will not render outside the page falls back to the strings in
  its tree, which is most of them.
*/
function textOfNode(node: React.ReactNode): string {
  if (node === null || node === undefined || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(textOfNode).join(" ");
  if (React.isValidElement(node)) {
    const props = node.props as Record<string, unknown>;
    return ["title", "description", "label", "value", "children"]
      .map((k) => textOfNode(props[k] as React.ReactNode))
      .join(" ");
  }
  return "";
}

function cellText(node: React.ReactNode): string {
  let text: string;
  try {
    /* Spaces between tags, so a two-line cell reads "Acme Fuels 1042", not
       "Acme Fuels1042". */
    const html = renderToStaticMarkup(<TooltipProvider>{node}</TooltipProvider>).replace(/></g, "> <");
    text = new DOMParser().parseFromString(html, "text/html").body.textContent ?? "";
  } catch {
    text = textOfNode(node);
  }
  return text.replace(/\s+/g, " ").trim().toLowerCase();
}

/** Empty boxes are no filter — typing then clearing one is not a change. */
const liveColFilters = (f: Record<string, string> | undefined) =>
  Object.entries(f ?? {})
    .filter(([, v]) => v.trim() !== "")
    .sort(([a], [b]) => a.localeCompare(b));

function readColFilters(raw: string | undefined): Record<string, string> {
  if (!raw) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return {};
    return Object.fromEntries(
      Object.entries(parsed as Record<string, unknown>).filter(
        (e): e is [string, string] => typeof e[1] === "string"
      )
    );
  } catch {
    return {};
  }
}

export interface DirectoryFacet<Row> {
  key: string;
  label: string;
  options: string[];
  /** The value a row presents to this facet. Must match an option exactly. */
  valueOf: (row: Row) => string | string[];
  searchable?: boolean;
}

export interface DirectoryColumn<K extends string> {
  key: K;
  label: string;
  width: number;
  sortable?: boolean;
  align?: "right" | "center";
}

export interface DirectoryListProps<Row, K extends string> {
  rows: Row[];
  columns: DirectoryColumn<K>[];
  rowId: (row: Row) => string;
  renderCell: (row: Row, key: K) => React.ReactNode;
  /** Free-text across everything the record is findable by. */
  matches: (row: Row, q: string) => boolean;
  searchFields: { key: string; label: string; text: (row: Row) => string }[];
  searchPlaceholder: string;
  sortRows: (rows: Row[], sort: { key: K; dir: "asc" | "desc" } | null) => Row[];
  dimensions: GroupDim<Row>[];
  facets?: DirectoryFacet<Row>[];
  /** What one record is called — "vendor", "account", "product", "asset". */
  noun: string;
  /** Plural of `noun` where it is not just `+s`. */
  nounPlural?: string;
  /** The column that sums to something true. OMIT where none does. */
  measureOf?: (row: Row) => number;
  /** Unit for that measure. */
  measureUnit?: string;
  /** Formats the footer's total — for currency, where a unit suffix is wrong. */
  formatTotal?: (total: number) => string;
  emptyIcon: React.ReactNode;
  /** Row click opens the record. */
  onOpenRow?: (row: Row) => void;
  openLabel: (row: Row) => string;
  /** Header CTA. Omitted, no button is drawn — no dead controls. */
  onCreate?: () => void;
  createLabel?: string;
  /** One CSV row per record, in the order the columns are declared. */
  exportRow?: (row: Row) => Record<string, string | number>;
  /** What can be done to a selection. Omitted, the checkbox column is absent. */
  bulkActions?: (selected: Row[], clear: () => void) => BulkAction[];
  /** Namespaces this list's URL params so four screens can share one address. */
  urlKey: string;
  /**
   * THE LIST'S TOTAL GOES TO THE PAGE HEADER, not under the footer.
   *
   * It is a fact about the whole list — "these 150 accounts are owed
   * $9.7m" — and the footer is where the page position lives. Sat down
   * there it read as a property of page 1 of 5, and it was the last thing on
   * a screen somebody has to scroll to reach. Beside the title it is the
   * first, which is where a headline number belongs.
   */
  onTotalChange?: (label: string | null) => void;
  /** Whether the reader may create, edit or archive here. */
  canWrite?: boolean;
  /**
   * An alternative rendering of the SAME filtered, searched, sorted rows — the
   * vendor map. It replaces the table only, so the toolbar, the facets and the
   * chips keep working and the two views can never disagree about what is on
   * screen.
   */
  renderMap?: (rows: Row[]) => React.ReactNode;
}

interface ViewState {
  /** THE DISPLAY IT OPENS IN — table, board or map (Pavan, 2026-10-21). */
  mode?: ListView;
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  pageSize: number;
  colScope: string;
  colQuery: string;
  filters: string[];
  /** The header row's boxes, by column key. Optional so a view saved before
   *  them still applies. */
  colFilters?: Record<string, string>;
  /* A SAVED VIEW KEEPS THE COLUMNS' ORDER AND WIDTHS (Pavan, 2026-10-07), as
     Delivery Orders does. Optional so an older view still applies. */
  columnOrder?: string[];
  columnWidths?: Record<string, number>;
}

const keyOf = (s: ViewState) =>
  JSON.stringify({
    ...s,
    mode: s.mode ?? "table",
    hidden: [...s.hidden].sort(),
    filters: [...s.filters].sort(),
    colFilters: Object.fromEntries(liveColFilters(s.colFilters)),
    columnOrder: s.columnOrder ?? [],
    columnWidths: s.columnWidths ?? {},
  });

export function DirectoryList<Row, K extends string>({
  rows,
  columns,
  rowId,
  renderCell,
  matches,
  searchFields,
  searchPlaceholder,
  sortRows,
  dimensions,
  facets = [],
  noun,
  nounPlural,
  measureOf,
  measureUnit,
  formatTotal,
  emptyIcon,
  onOpenRow,
  openLabel,
  onCreate,
  createLabel,
  exportRow,
  bulkActions,
  urlKey,
  canWrite = true,
  onTotalChange,
  renderMap,
}: DirectoryListProps<Row, K>) {
  const toggleColumns = React.useMemo(
    () => columns.filter((c) => c.label).map((c) => ({ key: c.key, label: c.label })),
    [columns]
  );
  const firstScope = searchFields[0]?.key ?? "";

  /* ── initial state, from the URL if it carries any ────────────────────── */
  const boot = React.useMemo(() => {
    const u = readUrl();
    /* Params belong to whichever entity the address names. Landing on Vendors
       with the Customers list's page number would be worse than ignoring it. */
    return u.entity === urlKey ? u : {};
  }, [urlKey]);

  const [search, setSearch] = React.useState(boot.q ?? "");
  const [sort, setSort] = React.useState<{ key: K; dir: "asc" | "desc" } | null>(
    boot.sortBy ? { key: boot.sortBy as K, dir: boot.sortDir === "desc" ? "desc" : "asc" } : null
  );
  const [page, setPage] = React.useState(Number(boot.page) > 0 ? Number(boot.page) : 1);
  /* THE DS'S PAGINATION, unchanged. `TablePagination` ships its own page-size
     set and its own footer copy, and both are already documented; a second set
     of sizes here would make this list the one screen that counts differently
     from every other. The URL may name a size, but only one the DS offers. */
  const [pageSize, setPageSize] = React.useState(() =>
    DS_PAGE_SIZES.includes(Number(boot.pageSize)) ? Number(boot.pageSize) : 25
  );
  const [hidden, setHidden] = React.useState<Set<K>>(new Set(unpackList(boot.cols) as K[]));
  const [colScope, setColScope] = React.useState(boot.colScope ?? firstScope);
  const [colQuery, setColQuery] = React.useState(boot.colQuery ?? "");
  const [view, setView] = React.useState<ListView>("table");
  /** Applied facet ids, `facetKey:option`. Empty = everything. */
  const [applied, setApplied] = React.useState<string[]>(unpackList(boot.filters));
  const [selected, setSelected] = React.useState<Set<string>>(new Set());
  /** One box per column, under the headers — see `ListTableProps.columnFilters`. */
  const [colFilters, setColFilters] = React.useState<Record<string, string>>(() =>
    readColFilters(boot.colFilters)
  );
  /* The row opens when the address arrives with something typed in it. */
  const [colFiltersOpen, setColFiltersOpen] = React.useState(
    () => liveColFilters(readColFilters(boot.colFilters)).length > 0
  );
  const activeColFilters = React.useMemo(() => liveColFilters(colFilters), [colFilters]);
  /* Columns move and resize, lifted so a view keeps them (Pavan, 2026-10-07). */
  const [columnOrder, setColumnOrder] = React.useState<string[]>([]);
  const [columnWidths, setColumnWidths] = React.useState<Record<string, number>>({});
  const [exporting, setExporting] = React.useState(false);

  /*
    THE LOADING STATE IS REAL, not a toggle in a demo.

    Changing the page, the page size or the sort is the moment a real list goes
    back to the server, and the skeleton is what the reader sees while it does.
    Showing it for one frame on those three transitions is the honest amount:
    long enough that the state exists and is designed, short enough that it is
    never in the way.
  */
  const [loading, setLoading] = React.useState(false);
  const settle = React.useRef<number | undefined>(undefined);
  const reload = React.useCallback(() => {
    setLoading(true);
    window.clearTimeout(settle.current);
    settle.current = window.setTimeout(() => setLoading(false), 260);
  }, []);
  React.useEffect(() => () => window.clearTimeout(settle.current), []);

  const current: ViewState = {

    mode: view,
    search,
    sortKey: sort?.key ?? null,
    sortDir: sort?.dir ?? null,
    hidden: [...hidden],
    pageSize,
    colScope,
    colQuery,
    filters: applied,
    colFilters,
    columnOrder,
    columnWidths,
  };
  const defaultState: ViewState = React.useMemo(
    () => ({
    mode: "table",
      search: "",
      sortKey: null,
      sortDir: null,
      hidden: [],
      pageSize: 25,
      colScope: firstScope,
      colQuery: "",
      filters: [],
      colFilters: {},
      columnOrder: [],
      columnWidths: {},
    }),
    [firstScope]
  );
  const applyState = (s: ViewState) => {
    setView(s.mode ?? "table");
    setSearch(s.search);
    setSort(s.sortKey && s.sortDir ? { key: s.sortKey as K, dir: s.sortDir } : null);
    setHidden(new Set(s.hidden as K[]));
    setPageSize(s.pageSize);
    setColScope(s.colScope);
    setColQuery(s.colQuery);
    setApplied(s.filters);
    const filters = s.colFilters ?? {};
    setColFilters(filters);
    /* The row opens when the view has something typed in it. */
    setColFiltersOpen(liveColFilters(filters).length > 0);
    setColumnOrder(s.columnOrder ?? []);
    setColumnWidths(s.columnWidths ?? {});
    setPage(1);
    reload();
  };
  const savedViews = useSavedViews({ current, defaultState, keyOf, apply: applyState, storageKey: `3pl-directory-${nounPlural}` });

  const q = search.trim().toLowerCase();
  const cq = colQuery.trim().toLowerCase();

  /* Rendered once per row and column, then kept until the row itself changes
     — an edit replaces the row object, so the cache cannot go stale. */
  const textCache = React.useMemo(
    () => new WeakMap<object, Map<string, string>>(),
    [renderCell]
  );
  const textOf = React.useCallback(
    (row: Row, key: K) => {
      const obj = row as unknown as object;
      let byKey = textCache.get(obj);
      if (!byKey) textCache.set(obj, (byKey = new Map()));
      let t = byKey.get(key);
      if (t === undefined) byKey.set(key, (t = cellText(renderCell(row, key))));
      return t;
    },
    [textCache, renderCell]
  );

  /* The whole narrowing for any facet set, so the filter panel can count a
     selection that is ticked but not yet applied with the very same rules. */
  const narrow = React.useCallback((ids: Iterable<string>) => {
    const picked = [...ids];
    const scoped = searchFields.find((f) => f.key === colScope);
    /* Options picked WITHIN one facet are OR; the facets are AND. That is the
       reading everyone already has of a filter panel, and a facet with nothing
       picked narrows nothing rather than narrowing to nothing. */
    const picks = facets
      .map((f) => ({
        f,
        chosen: picked
          .filter((id) => id.startsWith(`${f.key}:`))
          .map((id) => id.slice(f.key.length + 1)),
      }))
      .filter((p) => p.chosen.length > 0);

    return rows.filter((r) => {
      if (q && !matches(r, q)) return false;
      if (cq && scoped && !scoped.text(r).toLowerCase().includes(cq)) return false;
      /* AND, because that is what typing in two boxes looks like it should
         do. Each box matches the text its own column PRINTS — see `cellText`. */
      if (
        !activeColFilters.every(([key, value]) =>
          textOf(r, key as K).includes(value.trim().toLowerCase())
        )
      )
        return false;
      return picks.every(({ f, chosen }) => {
        const v = f.valueOf(r);
        return Array.isArray(v) ? v.some((x) => chosen.includes(x)) : chosen.includes(v);
      });
    });
  }, [rows, q, cq, colScope, facets, searchFields, matches, activeColFilters, textOf]);

  const filtered = React.useMemo(() => narrow(applied), [narrow, applied]);

  /* THE VIEW BAR — the table's and the board's tools render into it. */
  const bar = useViewBar();
  const sorted = React.useMemo(() => sortRows(filtered, sort), [filtered, sort, sortRows]);

  const g = useGrouping<Row, K>({
    dimensions,
    rows: sorted,
    rowId,
    measureOf,
    hiddenColumns: hidden,
    page,
    pageSize,
  });

  /* The URL trails the state rather than driving it: one writer, no loop. */
  React.useEffect(() => {
    writeUrl({
      entity: urlKey,
      q: search || null,
      page: page > 1 ? page : null,
      pageSize: pageSize === 25 ? null : pageSize,
      sortBy: sort?.key ?? null,
      sortDir: sort?.dir ?? null,
      cols: packList([...hidden]) || null,
      colScope: colQuery ? colScope : null,
      colQuery: colQuery || null,
      filters: packList(applied) || null,
      colFilters: activeColFilters.length
        ? JSON.stringify(Object.fromEntries(activeColFilters))
        : null,
      group: packList(g.groupBy) || null,
    });
  }, [urlKey, search, page, pageSize, sort, hidden, colScope, colQuery, applied, activeColFilters, g.groupBy]);

  /* The header's number follows the FILTERED list, so narrowing the list
     narrows the total with it — a total that ignored the filters would be a
     different number from the rows underneath it. */
  React.useEffect(() => {
    if (!onTotalChange) return undefined;
    onTotalChange(
      measureOf === undefined
        ? null
        : formatTotal
          ? formatTotal(g.total ?? 0)
          : `${(g.total ?? 0).toLocaleString()}${measureUnit ? ` ${measureUnit}` : ""}`
    );
    return () => onTotalChange(null);
  }, [onTotalChange, measureOf, formatTotal, measureUnit, g.total]);

  /* A page that no longer exists — the last row on it was filtered away. */
  const totalPages = Math.max(1, Math.ceil(sorted.length / pageSize));
  React.useEffect(() => {
    if (page > totalPages) setPage(totalPages);
  }, [page, totalPages]);

  const onSort = (key: K) => {
    setSort((prev) => {
      if (prev?.key !== key) return { key, dir: "asc" };
      if (prev.dir === "asc") return { key, dir: "desc" };
      return null;
    });
    setPage(1);
    reload();
  };

  const plural = nounPlural ?? `${noun}s`;
  const count = sorted.length;

  /* SELECTION IS SCOPED TO WHAT IS ON SCREEN. "Select all" on a filtered list
     of 3,000 that silently picks up rows nobody has seen is how people delete
     the wrong thing; the header checkbox takes the visible page and no more. */
  const pageIds = g.visibleRows.map(rowId);
  const selectedRows = sorted.filter((r) => selected.has(rowId(r)));
  const clearSelection = () => setSelected(new Set());
  const actions = bulkActions?.(selectedRows, clearSelection) ?? [];

  const appliedSet = React.useMemo(() => new Set(applied), [applied]);
  /** Anything typed — the search, the column search, or a header box. */
  const typed = Boolean(q || cq || activeColFilters.length > 0);
  const typedText = (search || colQuery).trim() || activeColFilters[0]?.[1].trim() || "";

  /* EXPORT ASKS FIRST (Pavan, 2026-10-07) — the same sheet as Delivery
     Orders, listing every narrowing that shapes the file. */
  const exportFilters: ExportFilterRow[] = [
    {
      key: "search",
      label: "Search",
      values: search.trim()
        ? [{ value: search.trim(), onRemove: () => { setSearch(""); setPage(1); } }]
        : [],
    },
    {
      key: "colSearch",
      label: searchFields.find((f) => f.key === colScope)?.label ?? "Column",
      values: colQuery.trim()
        ? [{ value: colQuery.trim(), onRemove: () => { setColQuery(""); setPage(1); } }]
        : [],
    },
    ...activeColFilters.map(([key, value]) => ({
      key: `col:${key}`,
      label: columns.find((c) => c.key === key)?.label ?? key,
      values: [
        {
          value: value.trim(),
          onRemove: () => {
            setColFilters((prev) => ({ ...prev, [key]: "" }));
            setPage(1);
          },
        },
      ],
    })),
    ...facets.map((f) => {
      const mine = applied.filter((id) => id.startsWith(`${f.key}:`));
      const drop = (ids: string[]) => {
        setApplied((prev) => prev.filter((id) => !ids.includes(id)));
        setPage(1);
      };
      return {
        key: f.key,
        label: f.label,
        values: mine.map((id) => ({
          value: id.slice(f.key.length + 1),
          onRemove: () => drop([id]),
        })),
        onRemoveAll: () => drop(mine),
      };
    }),
  ];

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <FuelOrdersViewBar
        {...savedViews}
        onExport={exportRow ? () => setExporting(true) : undefined}
      />

      <div className="mt-4 flex shrink-0 items-center gap-2">
        <div className="min-w-0 flex-1">
          <ListToolbar
            viewToolsInto={bar.into}
            viewStatement={<ViewStatement count={sorted.length} one={noun} many={plural} />}
            searchValue={search}
            onSearchChange={(v) => {
              setSearch(v);
              setPage(1);
            }}
            searchPlaceholder={searchPlaceholder}
            filters={
              facets.length > 0 ? (
                <ListFilters
                  facets={facets.map((f) => ({
                    key: f.key,
                    label: f.label,
                    options: f.options,
                    searchable: f.searchable,
                  }))}
                  value={appliedSet}
                  countFor={(sel) => narrow(sel).length}
                  onApply={(ids) => {
                    setApplied([...ids]);
                    setPage(1);
                    reload();
                  }}
                />
              ) : undefined
            }
            groupBy={{
              dimensions: g.menuDimensions,
              value: g.groupBy,
              onChange: (next) => {
                g.setGrouping(next);
                setPage(1);
              },
            }}
            columns={toggleColumns}
            hiddenColumns={hidden}
            columnOrder={columnOrder}
            onReorderColumns={setColumnOrder}
            onToggleColumn={(k) =>
              setHidden((prev) => {
                const next = new Set(prev);
                if (next.has(k)) next.delete(k);
                else next.add(k);
                return next;
              })
            }
            onShowAllColumns={() => setHidden(new Set())}
            searchFields={searchFields}
            colScope={colScope}
            onColScopeChange={(v) => {
              setColScope(v);
              setPage(1);
            }}
            colQuery={colQuery}
            onColQueryChange={(v) => {
              setColQuery(v);
              setPage(1);
            }}
            /* THE ROW, NOT THE POPOVER. It only makes sense over a table, so
               the map keeps the button pointed at nothing rather than opening
               a row of boxes above pins that have no columns. */
            columnFiltersOpen={view === "table" && colFiltersOpen}
            onToggleColumnFilters={
              view === "table"
                ? () =>
                    setColFiltersOpen((open) => {
                      /* CLOSING THE ROW PUTS THE LIST BACK. Leaving what was
                         typed applying after the boxes have gone would be a
                         narrowing with nothing on screen saying so. */
                      if (open) {
                        setColFilters({});
                        setPage(1);
                      }
                      return !open;
                    })
                : undefined
            }
            columnFilterCount={activeColFilters.length}
            view={view}
            onViewChange={setView}
            mapView={Boolean(renderMap)}
          />
        </div>

        {onCreate && (
          <Button
            size="sm"
            className="shrink-0"
            disabled={!canWrite}
            /* A DEAD CONTROL MUST SAY WHY. Hiding it would leave someone
               without the permission wondering where the button went. */
            title={canWrite ? undefined : `You do not have permission to add a ${noun}`}
            onClick={onCreate}
          >
            <Plus />
            {createLabel ?? `Add New ${noun[0].toUpperCase()}${noun.slice(1)}`}
          </Button>
        )}
      </div>

      {/* ACTIVE FILTERS, SAID OUT LOUD, on the same shelf as the column
          search. The facet panel remembers what was picked, but it is closed —
          and a list that is quietly narrowed is the single most common way
          people conclude their data is missing. Shared with the orders board,
          because a chip row that behaved differently on two lists would be two
          things to learn for one idea. */}
      <FilterChips
        facets={facets}
        selected={appliedSet}
        onChange={(next) => {
          setApplied([...next]);
          setPage(1);
          reload();
        }}
      >
        <ColumnSearchChip
          className=""
          searchFields={searchFields}
          colScope={colScope}
          colQuery={colQuery}
          onClear={() => {
            setColQuery("");
            setPage(1);
          }}
        />
        {/* One chip per header box that has something typed in it — the same
            chip as the column search, because it is the same question. */}
        {activeColFilters.map(([key, value]) => (
          <ColumnSearchChip
            key={key}
            className=""
            searchFields={columns.map((c) => ({ key: c.key, label: c.label }))}
            colScope={key}
            colQuery={value.trim()}
            onClear={() => {
              setColFilters((prev) => ({ ...prev, [key]: "" }));
              setPage(1);
            }}
          />
        ))}
      </FilterChips>

      <div className="relative mt-4 min-h-0 flex-1">
        <div className="h-full min-h-0">
          {renderMap && view === "map" ? (
            /* THE MAP TAKES THE SORTED ROWS, not the page. A map paginated to
               25 pins is a map of a page, which is not a thing anybody wants —
               and the footer switches to a plain count to match. */
            renderMap(sorted)
          ) : count === 0 && !loading && !colFiltersOpen ? (
            /* NOT WHILE THE ROW IS OPEN: the boxes live in the table's header,
               so swapping the table for an empty state would take away the box
               being typed in at the moment it matched nothing. */
            <Empty className="h-full">
              <EmptyHeader>
                <EmptyMedia variant="icon">
                  {typed || applied.length > 0 ? <SearchX /> : emptyIcon}
                </EmptyMedia>
                {/* THREE EMPTY STATES, NOT ONE. Nothing here yet, nothing
                    matches what you typed, and nothing matches the filters are
                    three different situations with three different next
                    actions, and one shared sentence would fit none of them. */}
                <EmptyTitle>
                  {typed
                    ? `No ${plural} match your search`
                    : applied.length > 0
                      ? `No ${plural} match these filters`
                      : `No ${plural} yet`}
                </EmptyTitle>
                <EmptyDescription>
                  {typed
                    ? `Nothing found for “${typedText}”. Check the spelling, or search a different column.`
                    : applied.length > 0
                      ? "Try removing a filter — the chips above show what is applied."
                      : `Add your first ${noun} to get started.`}
                </EmptyDescription>
              </EmptyHeader>
              {applied.length > 0 && (
                <Button variant="outline" size="sm" onClick={() => setApplied([])}>
                  Clear all filters
                </Button>
              )}
              {applied.length === 0 && !typed && onCreate && canWrite && (
                <Button size="sm" onClick={onCreate}>
                  <Plus />
                  {createLabel ?? `Add New ${noun[0].toUpperCase()}${noun.slice(1)}`}
                </Button>
              )}
            </Empty>
          ) : (
            <ListTable
              topBar={bar.slot}
              rows={g.visibleRows}
              nodes={g.grouped ? g.groups.nodes : undefined}
              collapsedGroups={g.collapsed}
              onToggleGroupCollapse={g.toggleGroupCollapse}
              groupNoun={noun}
              groupUnit={measureUnit}
              columns={columns}
              hidden={g.effectiveHidden}
              sort={sort}
              onSort={onSort}
              rowId={rowId}
              renderCell={renderCell}
              actionsKey={"actions" as K}
              columnOrder={columnOrder}
              onReorderColumns={setColumnOrder}
              columnWidths={columnWidths}
              onResizeColumns={setColumnWidths}
              openLabel={openLabel}
              onOpenRow={onOpenRow}
              showColumnFilters={colFiltersOpen}
              columnFilters={colFilters}
              onColumnFilterChange={(key, value) => {
                setColFilters((prev) => ({ ...prev, [key]: value }));
                setPage(1);
              }}
              loading={loading}
              skeletonRows={Math.min(pageSize, 12)}
              selectedIds={bulkActions ? selected : undefined}
              onToggleRow={
                bulkActions
                  ? (id) =>
                      setSelected((prev) => {
                        const next = new Set(prev);
                        if (next.has(id)) next.delete(id);
                        else next.add(id);
                        return next;
                      })
                  : undefined
              }
              onToggleAll={
                bulkActions
                  ? (next) =>
                      setSelected((prev) => {
                        const out = new Set(prev);
                        pageIds.forEach((id) => (next ? out.add(id) : out.delete(id)));
                        return out;
                      })
                  : undefined
              }
            />
          )}
        </div>

        {selected.size > 0 && actions.length > 0 && (
          <div className="pointer-events-none absolute inset-x-0 bottom-4 flex justify-center">
            <div className="pointer-events-auto">
              <BulkActionBar
                count={selected.size}
                noun={noun}
                actions={actions}
                tools={false}
                onClear={clearSelection}
              />
            </div>
          </div>
        )}
      </div>

      {/* Grouped, the footer reports the shape of the list; flat, it reports
          the page position — the one number a paged list owes the reader. */}
      <div className="mt-4 shrink-0">
        {renderMap && view === "map" ? (
          <div className="text-sm tabular-nums text-muted-foreground">
            {count} {count === 1 ? noun : plural} on the map
          </div>
        ) : g.grouped ? (
          <GroupedListFooter
            groupCount={g.groups.groupCount}
            rowCount={g.groups.rowCount}
            noun={noun}
            total={g.total}
            unit={measureUnit}
            overCounts={g.groups.overCounts}
            allCollapsed={g.allCollapsed}
            onExpandAll={g.expandAll}
            onCollapseAll={g.collapseAll}
          />
        ) : (
          <TablePagination
            page={page}
            pageSize={pageSize}
            total={count}
            onPageChange={(p) => {
              setPage(p);
              reload();
            }}
            onPageSizeChange={(s) => {
              setPageSize(s);
              setPage(1);
              reload();
            }}
          />
        )}
      </div>

      {exportRow && (
        <ExportSheet
          open={exporting}
          onOpenChange={setExporting}
          title={`Export ${plural[0].toUpperCase()}${plural.slice(1)}`}
          noun={plural}
          nounOne={noun}
          count={count}
          filtersControl={
            facets.length > 0 ? (
              <ListFilters
                facets={facets.map((f) => ({
                  key: f.key,
                  label: f.label,
                  options: f.options,
                  searchable: f.searchable,
                }))}
                value={appliedSet}
                countFor={(sel) => narrow(sel).length}
                onApply={(ids) => {
                  setApplied([...ids]);
                  setPage(1);
                }}
                fullWidth
              />
            ) : undefined
          }
          filters={exportFilters}
          onExport={(format) => {
            setExporting(false);
            if (format === "csv") {
              downloadCsv(`${urlKey}-${new Date().toISOString().slice(0, 10)}`,
                sorted.map(exportRow));
              toast.success(`Exported ${count.toLocaleString()} ${count === 1 ? noun : plural}`);
            } else {
              toast.success(
                `Exporting ${count.toLocaleString()} ${count === 1 ? noun : plural} as .${format}`
              );
            }
          }}
        />
      )}
    </div>
  );
}

import * as React from "react";
import { FormStepsContext } from "@/components/side-sheet/form-steps-context";
import { Download, FileText, History, Image as ImageIcon, Sheet as SheetIcon, X } from "lucide-react";
import { Pill } from "@/components/ui/pill";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Combobox } from "@/components/ui/combobox";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { StatusChip, type StatusTone } from "@/components/ui/status-chip";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import {
  Sheet,
  SheetContent,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { SheetField, SheetSection, SheetSectionNote } from "@/components/side-sheet/parts";
import { cn } from "@/lib/utils";
import { DraftStatusChip, RecordSheet, useDraftSaveState } from "../RecordSheet";
import type { PendingItem } from "../PendingStrip";
import { DASH, formatDate, formatStamp, type Attachment, type AuditEvent } from "./directoryCore";
import type { FieldKind, FormFieldDef, FormSectionDef } from "./directoryFormTypes";
import { kindTone } from "../statusKind";

/*
  The Directory's record sheet.

  ONE SHEET, NOT A PAGE AND A FORM. The DS's rule for a record is the side
  sheet — `CustomerSheet` is the precedent, and `RecordSheet` is the component:
  the record IS the form, `mode` decides whether the header says Edit or
  Create, and the footer carries Save Changes. A full-page detail with a
  separate edit screen was a second interaction pattern for the same job, and
  the sheet keeps the list behind it, which is the point of a sheet.

  READ-ONLY CONTENT LIVES IN THE SAME SCROLL. A record's related lists —
  orders against an account, a vendor's rate card, an asset's billing history —
  are `SheetSection`s like any other, below the editable ones. Section rhythm
  is the DS's 40 / 16 throughout, owned by the sheet body.

  WIDTH IS `wide`, not `narrow`. 560px is right for stacked fields and wrong
  for the tables these records carry: at 560 their columns have to be scrolled
  sideways, and a table you scroll to read is a table you cannot compare rows
  in. That is the DS's own reason for the size, quoted in `RecordSheet`.

  VALIDATION KEEPS THE FORM'S CONTRACT. Nothing is red until you have left the
  field; after a failed submit everything validates live; a failed submit keeps
  every character. `canSubmit` gates the footer, so an incomplete record cannot
  be saved from a sheet any more than from a page.
*/

export interface RecordReadSection {
  key: string;
  title: string;
  /** Count on the heading note — "6 locations". Omit where none applies. */
  count?: number;
  note?: string;
  /** Its table's columns as `CELL` widths — the sheet is as wide as the
      widest section's table (Pavan, 2026-10-15: each record its own width). */
  columns?: number[];
  render: () => React.ReactNode;
}

export interface DirectoryRecordSheetProps<T> {
  /**
   * The record's edit history.
   *
   * NOT A SECTION. It is the longest block on the record and the one people
   * read least often, and at the bottom of the body it pushed everything
   * anyone opens the sheet FOR — the related records — behind a wall of "field
   * changed" lines. It gets an icon in the header instead, which also makes it
   * reachable without scrolling at all.
   */
  audit?: AuditEvent[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "edit" | "create";
  /** "Customer", "Vendor" — the sheet's own noun. */
  noun: string;
  /** The record's name, for the edit header. */
  title: string;
  /** The record's identity — the draft resets only when this changes, so an
   *  autosaved edit coming back as `initial` does not reset the form. */
  recordKey: string;
  /* AUTOSAVE (Pavan, 2026-10-07). An existing record writes each valid change
     as it settles; Confirm and Close finish the visit. */
  onAutosave?: (draft: T) => void;
  /** Closing hands back the latest draft (null while it is invalid), so a
   *  change still settling is not lost. */
  onClose?: (latest: T | null) => void;
  /** The ⋯ menu — acts on the record that are not part of filling it in. */
  headerMenu?: React.ReactNode;
  headerAside?: React.ReactNode;
  initial: T;
  sections: FormSectionDef<T>[];
  /** Everything the record shows but does not edit, under the editable blocks. */
  readSections?: RecordReadSection[];
  onSubmit: (draft: T) => void;
}

/*
  A FIELD STARTS WITH A CAPITAL, and this is the layer that can safely say so.

  `Input` sets `autoCapitalize`, which only reaches a soft keyboard; on a
  desktop nothing capitalises anything. So the form normalises the first
  character on BLUR — after the reader has finished the word, never while they
  are typing it, because a field that rewrites itself mid-keystroke is a field
  people fight.

  WHAT IS EXEMPT, and why each one:
    · email, url  — case-carrying. "Ray.obuya@…" is a different string, and
      capitalising it is the kind of silent edit that produces a bounced
      invoice.
    · number, money, date — no letters to capitalise.
    · select, combobox, switch, checkbox — the value is chosen, not typed.

  AND IT ONLY TOUCHES THE FIRST CHARACTER. `text-transform: capitalize`
  uppercases every word, which turns "Bray, Raymond and Marks" into "Bray,
  Raymond And Marks" and a street into title case. One character, once.
*/
const TYPED_TEXT: FieldKind[] = ["text", "tel", "textarea"];

const sentenceCase = (v: string): string =>
  v.length === 0 ? v : v[0].toUpperCase() + v.slice(1);

/**
 * The label an option shows. The VALUE is untouched — a record status stays
 * the lowercase `active` the model stores, and only the word on screen is
 * capitalised. Values that already start with a capital ("Net 30") pass
 * straight through.
 */
const optionLabel = (v: string): string => sentenceCase(v);

function isBlank(v: string | number | boolean | null): boolean {
  return v === null || v === undefined || v === "" || (typeof v === "number" && Number.isNaN(v));
}

export function DirectoryRecordSheet<T>({
  open,
  onOpenChange,
  mode,
  noun,
  title,
  recordKey,
  onAutosave,
  onClose,
  headerMenu,
  headerAside,
  initial,
  sections,
  readSections = [],
  audit,
  onSubmit,
}: DirectoryRecordSheetProps<T>) {
  const [historyOpen, setHistoryOpen] = React.useState(false);
  const [draft, setDraft] = React.useState<T>(initial);
  const [touched, setTouched] = React.useState<Set<string>>(new Set());
  const [submitted, setSubmitted] = React.useState(false);
  /* The same header feedback the order sheets give. A record sheet holds a
     draft exactly as they do, and silence about it reads the same way. */
  const saveState = useDraftSaveState(draft, open);

  /* A sheet is reused across records, so the draft resets when the record it
     is showing changes — not when the component happens to remount. */
  React.useEffect(() => {
    setDraft(initial);
    setTouched(new Set());
    setSubmitted(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [recordKey, mode]);

  const visibleSections = React.useMemo(
    () =>
      sections.map((s) => ({ ...s, fields: s.fields.filter((f) => f.visible?.(draft) ?? true) })),
    [sections, draft]
  );

  const errors = React.useMemo(() => {
    const out: Record<string, string> = {};
    visibleSections.forEach((s) =>
      s.fields.forEach((f) => {
        if (f.required && isBlank(f.get(draft))) out[f.key] = `${f.label} is required`;
        else {
          const e = f.validate?.(draft);
          if (e) out[f.key] = e;
        }
      })
    );
    return out;
  }, [visibleSections, draft]);

  const errorCount = Object.keys(errors).length;

  /* AUTOSAVE (Pavan, 2026-10-07) — the draft chip's promise kept: a valid
     change on an existing record is written once typing settles. */
  const latestInitial = React.useRef(initial);
  latestInitial.current = initial;
  React.useEffect(() => {
    if (mode !== "edit" || !onAutosave || !open) return undefined;
    if (draft === latestInitial.current || errorCount > 0) return undefined;
    const t = window.setTimeout(() => onAutosave(draft), 600);
    return () => window.clearTimeout(t);
  }, [draft, errorCount, mode, onAutosave, open]);

  /* WHAT THE PRIMARY IS WAITING ON (Pavan, 2026-10-07 — G25). The button stays
     pressable; a press names the gap and goes to its section. */
  const pending: PendingItem[] = visibleSections.flatMap((s) =>
    s.fields
      .filter((f) => errors[f.key])
      .map((f) => ({
        key: f.key,
        label: f.required && isBlank(f.get(draft)) ? `Add ${f.label.toLowerCase()}` : errors[f.key],
        target: `dir-sec-${s.key}`,
      }))
  );
  const showError = (key: string) => Boolean(errors[key]) && (submitted || touched.has(key));

  const set = (f: FormFieldDef<T>, v: string | number | boolean | null) =>
    setDraft((d) => f.set(d, v));

  const control = (f: FormFieldDef<T>) => {
    const v = f.get(draft);
    const bad = showError(f.key);
    const blur = () => {
      setTouched((t) => new Set(t).add(f.key));
      if (!TYPED_TEXT.includes(f.kind)) return;
      const current = f.get(draft);
      if (typeof current !== "string" || current.length === 0) return;
      const next = sentenceCase(current);
      if (next !== current) setDraft((d) => f.set(d, next));
    };

    switch (f.kind) {
      case "select":
        return (
          <Select
            value={typeof v === "string" && v !== "" ? v : undefined}
            onValueChange={(next) => {
              set(f, next);
              blur();
            }}
          >
            <SelectTrigger
              id={f.key}
              aria-invalid={bad || undefined}
              /* `capitalize` on the TRIGGER only. Radix renders the chosen
                 item's raw text here and there is no slot to relabel it, so
                 the CSS does what `optionLabel` does in the list — and a
                 value like "Net 30" is unaffected either way. */
              className={cn("w-full capitalize", bad && "border-destructive")}
            >
              <SelectValue placeholder={f.placeholder ?? "Select…"} />
            </SelectTrigger>
            <SelectContent>
              {(f.options ?? []).map((o) => (
                <SelectItem key={o} value={o}>
                  {optionLabel(o)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        );
      case "combobox":
        return (
          <Combobox
            id={f.key}
            value={typeof v === "string" ? v : ""}
            options={(f.options ?? []).map((o) => ({ value: o, label: optionLabel(o) }))}
            placeholder={f.placeholder ?? "Select…"}
            allowCreate={f.allowCreate}
            aria-label={f.label}
            className={cn("w-full", bad && "border-destructive")}
            onValueChange={(next) => {
              set(f, next);
              blur();
            }}
          />
        );

      case "textarea":
        return (
          <Textarea
            id={f.key}
            rows={3}
            value={typeof v === "string" ? v : ""}
            placeholder={f.placeholder}
            aria-invalid={bad || undefined}
            className={cn(bad && "border-destructive")}
            onBlur={blur}
            onChange={(e) => set(f, e.target.value)}
          />
        );
      default: {
        const numeric = f.kind === "number" || f.kind === "money";
        return (
          <Input
            id={f.key}
            type={f.kind === "date" ? "date" : numeric ? "text" : f.kind}
            inputMode={numeric ? "decimal" : undefined}
            value={v === null || v === false ? "" : String(v)}
            placeholder={f.placeholder}
            aria-invalid={bad || undefined}
            className={cn(bad && "border-destructive")}
            onBlur={blur}
            onChange={(e) => {
              const raw = e.target.value;
              if (!numeric) return set(f, raw);
              /* Money accepts what people type — commas, a dollar sign — and
                 stores a number. Rejecting keystrokes is how a field ends up
                 impossible to correct once it is wrong. */
              const cleaned = raw.replace(/[^0-9.-]/g, "");
              return set(f, cleaned === "" ? null : Number(cleaned));
            }}
          />
        );
      }
    }
  };

  const data = readSections.length > 0;
  return (
    <RecordSheet
      /* WIDTH FROM ITS TABLES, PER RECORD (Pavan, 2026-10-15): each read
         section names its table's columns; the widest decides. A create (no
         read sections) is a form, 600. */
      /* AN EXISTING RECORD IS DATA-INTENSIVE (Pavan, 2026-10-15 — "cramped"):
         1200 at least, fields three across. A create stays a 600 form. */
      {...(readSections.length > 0 ? { size: "data" as const } : {})}
      fit={{ tables: readSections.map((r) => r.columns ?? []) }}
      open={open}
      onOpenChange={(o) => {
        if (!o) onClose?.(errorCount === 0 ? draft : null);
        onOpenChange(o);
      }}
      mode={mode}
      editTitle={title}
      createTitle={`Create New ${noun}`}
      createAction={`Create ${noun}`}
      /* NO CANCEL — this sheet autosaves its draft (`useDraftSaveState`
         above), and "Cancel" promises to undo something that has already been
         kept. Close is the honest exit. (DS ux rules, side-sheet anatomy.) */
      showCancel={false}
      headerMenu={headerMenu}
      headerAside={
        <span className="flex items-center gap-2">
          {headerAside}
          {saveState !== "idle" && (
            <DraftStatusChip tone="neutral" label="Draft" saveState={saveState} />
          )}
        </span>
      }
      headerActions={
        audit && audit.length > 0 ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={`Audit history (${audit.length} ${audit.length === 1 ? "entry" : "entries"})`}
                onClick={() => setHistoryOpen(true)}
              >
                <History />
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              Audit history · {audit.length} {audit.length === 1 ? "entry" : "entries"}
            </TooltipContent>
          </Tooltip>
        ) : undefined
      }
      canSubmit={errorCount === 0}
      pending={pending}
      onSubmit={() => {
        setSubmitted(true);
        if (errorCount > 0) return;
        onSubmit(draft);
      }}
    >
      {visibleSections.map((s) => (
        <SheetSection
          key={s.key}
          id={`dir-sec-${s.key}`}
          title={s.title}
          note={s.note ? <SheetSectionNote>{s.note}</SheetSectionNote> : undefined}
        >
          {/* THREE UP ON A RECORD (the data width, 1200 — Pavan, 2026-10-15),
              two up while creating (600). */}
          <div className={cn("grid gap-4", data ? "grid-cols-3" : "grid-cols-2")}>
            {s.fields.map((f) =>
              /*
                A TOGGLE IS NOT A FIELD WITH A CONTROL UNDER IT.

                Stacked like every other field, a switch put its label on one
                line and a 20px control alone on the next, leaving a hole
                beside it and reading as if something were missing. A toggle is
                a statement and an answer: the statement goes on the left,
                aligned with every other label, the answer sits at the far
                right of the row, and the helper text runs under the statement
                where it explains what turning it on does. That is the row
                `CustomerSheet` already uses for Active.

                Always full width, so the two edges the reader's eye follows —
                the left edge of the labels and the right edge of the sheet —
                are the two things the row is pinned to.
              */
              f.kind === "switch" || f.kind === "checkbox" ? (
                <div
                  key={f.key}
                  className="col-span-full flex items-start justify-between gap-4"
                >
                  <div className="flex min-w-0 flex-col gap-1">
                    <label
                      htmlFor={f.key}
                      className="text-sm font-medium text-foreground"
                    >
                      {f.label}
                      {f.required && <span className="text-destructive"> *</span>}
                    </label>
                    {(showError(f.key) || f.description) && (
                      <span
                        className={cn(
                          "text-xs",
                          showError(f.key) ? "text-destructive" : "text-muted-foreground"
                        )}
                      >
                        {showError(f.key) ? errors[f.key] : f.description}
                      </span>
                    )}
                  </div>
                  <div className="shrink-0 pt-0.5">
                    {f.kind === "switch" ? (
                      <Switch
                        id={f.key}
                        checked={Boolean(f.get(draft))}
                        onCheckedChange={(on) => set(f, on)}
                      />
                    ) : (
                      <Checkbox
                        id={f.key}
                        checked={Boolean(f.get(draft))}
                        onCheckedChange={(on) => set(f, on === true)}
                      />
                    )}
                  </div>
                </div>
              ) : (
                <SheetField
                  key={f.key}
                  label={f.label}
                  required={f.required}
                  description={showError(f.key) ? undefined : f.description}
                  className={f.wide ? "col-span-full" : undefined}
                >
                  {control(f)}
                  {showError(f.key) && (
                    <p className="text-xs text-destructive">{errors[f.key]}</p>
                  )}
                </SheetField>
              )
            )}
          </div>
        </SheetSection>
      ))}

      {audit && (
        <AuditDrawer
          open={historyOpen}
          onOpenChange={setHistoryOpen}
          title={title}
          events={audit}
        />
      )}

      {readSections.map((s) => {
        /* A TABLE TAKES THE CARD'S OWN EDGES. Decided here from what the
           section actually renders rather than from a flag on every section,
           so a new table cannot be added with the gap left in by accident. */
        const body = s.render();
        return (
          <SheetSection
            key={s.key}
            title={s.title}
            flush={fillsSection(body)}
            note={
              s.note || s.count !== undefined ? (
                <SheetSectionNote>
                  {s.note ?? `${s.count} ${s.count === 1 ? "entry" : "entries"}`}
                </SheetSectionNote>
              ) : undefined
            }
          >
            {body}
          </SheetSection>
        );
      })}
    </RecordSheet>
  );
}

/* ═══════════════════════════════════════════════ read-only building blocks ═ */

/**
 * A labelled fact.
 *
 * `-` and `N/A` are both real values, printed muted, never suppressed. A field
 * that vanishes when it is empty makes an incomplete record look complete, and
 * the reason to open a record is to find out what is missing from it.
 */
export function ReadField({
  label,
  value,
  wide = false,
}: {
  label: string;
  value: React.ReactNode;
  wide?: boolean;
}) {
  const empty =
    value === null || value === undefined || value === "" || value === DASH || value === "N/A";
  return (
    <div className={cn(wide && "col-span-full")}>
      <dt className="text-xs font-medium text-muted-foreground">{label}</dt>
      <dd
        className={cn(
          "mt-0.5 text-sm break-words",
          empty ? "text-muted-foreground/70" : "text-foreground"
        )}
      >
        {empty ? DASH : value}
      </dd>
    </div>
  );
}

export function ReadGrid({ children }: { children: React.ReactNode }) {
  /* Three across — the record's data width (Pavan, 2026-10-15). */
  return <dl className="grid grid-cols-3 gap-x-6 gap-y-4">{children}</dl>;
}

/** The widest related-records table any directory record shows (a customer's
 *  assets) — what `DirectoryRecordSheet` sizes itself by. */

/** A related-records table that says something useful when it is empty. */
export function SheetTable<T>({
  rows,
  columns,
  emptyBody,
  onOpenRow,
  rowKey,
  max = 25,
}: {
  rows: T[];
  columns: { key: string; label: string; align?: "right"; render: (row: T) => React.ReactNode }[];
  emptyBody: string;
  onOpenRow?: (row: T) => void;
  rowKey: (row: T) => string;
  max?: number;
}) {
  /* THE CARD IS THE BOX. A table in a boxed unit runs to the unit's edges and
     borrows its border — so the empty state is padded text, not a second
     dashed box inside the first. */
  if (rows.length === 0) {
    return (
      <p className="px-4 py-6 text-center text-sm text-muted-foreground">
        {emptyBody}
      </p>
    );
  }
  const shown = rows.slice(0, max);
  return (
    <div className="overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full min-w-max text-sm">
          <thead>
            <tr className="border-b border-fp-outline-1 bg-fp-table-header">
              {columns.map((c) => (
                <th
                  key={c.key}
                  className={cn(
                    "h-9 whitespace-nowrap px-3 text-left text-xs font-medium text-muted-foreground",
                    c.align === "right" && "text-right"
                  )}
                >
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {shown.map((row) => (
              <tr
                key={rowKey(row)}
                className={cn(
                  "border-b border-fp-outline-1 last:border-0",
                  onOpenRow && "cursor-pointer hover:bg-fp-row-hover"
                )}
                onClick={onOpenRow ? () => onOpenRow(row) : undefined}
              >
                {columns.map((c) => (
                  <td
                    key={c.key}
                    className={cn(
                      "h-10 whitespace-nowrap px-3 align-middle text-foreground",
                      c.align === "right" && "text-right tabular-nums"
                    )}
                  >
                    {c.render(row)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {rows.length > shown.length && (
        <p className="border-t border-fp-outline-1 px-3 py-2 text-xs text-muted-foreground">
          Showing {shown.length} of {rows.length}. Open the list to see them all.
        </p>
      )}
    </div>
  );
}

/**
 * IT FILLS ITS SECTION. A section whose body is one of these is rendered
 * flush, so the table's edges are the card's edges and there is one border
 * where there used to be two. The flag is on the component rather than on
 * every call site, because a rule nobody has to remember is a rule that holds.
 */
SheetTable.fillsSection = true;

/** Whether a section's body is a table that wants the card's own edges. */
function fillsSection(body: React.ReactNode): boolean {
  return (
    React.isValidElement(body) &&
    (body.type as { fillsSection?: boolean })?.fillsSection === true
  );
}

const FILE_ICON: Record<string, React.ReactNode> = {
  pdf: <FileText className="size-4" />,
  png: <ImageIcon className="size-4" />,
  xlsx: <SheetIcon className="size-4" />,
  csv: <SheetIcon className="size-4" />,
};

/**
 * Files on a record.
 *
 * EXPIRY IS THE POINT for half of these. A certificate that lapsed in June is
 * the most consequential fact a vendor record holds, so it is stated on the
 * row and coloured, not left for somebody to work out from a date.
 */
export function AttachmentTable({ files }: { files: Attachment[] }) {
  const today = new Date();
  return (
    <SheetTable
      rows={files}
      rowKey={(f) => f.id}
      emptyBody="Nothing attached yet."
      columns={[
        {
          key: "name",
          label: "File",
          render: (f) => (
            <span className="flex items-center gap-2">
              <span className="text-muted-foreground">
                {FILE_ICON[f.kind] ?? <FileText className="size-4" />}
              </span>
              {f.name}
            </span>
          ),
        },
        {
          key: "expires",
          label: "Expires",
          render: (f) => {
            if (!f.expiresOn) return <span className="text-muted-foreground/70">{DASH}</span>;
            const gone = new Date(`${f.expiresOn}T00:00:00Z`) < today;
            /* A DATE IS NOT A STATUS (Pavan, 2026-10-09). Now that a status is
               a pill, a grey pill round every date would read as one; only the
               expired date — the warning — takes the pill. */
            return gone ? (
              <StatusChip tone={kindTone("critical")}>Expired {formatDate(f.expiresOn)}</StatusChip>
            ) : (
              <span className="text-sm tabular-nums">{formatDate(f.expiresOn)}</span>
            );
          },
        },
        { key: "size", label: "Size", render: (f) => `${f.sizeKb.toLocaleString()} KB` },
        { key: "by", label: "Uploaded by", render: (f) => f.uploadedBy },
        {
          key: "dl",
          label: "",
          render: () => (
            <Button variant="ghost" size="icon-sm" aria-label="Download file">
              <Download />
            </Button>
          ),
        },
      ]}
    />
  );
}

/** It is a `SheetTable`, so it fills its section for the same reason. */
AttachmentTable.fillsSection = true;

/**
 * The record's history — the same treatment the order sheet's Activity uses.
 *
 * NEWEST FIRST, and every entry names its fields. "Updated" tells you somebody
 * was here; "Credit limit: 120000 → 200000" tells you what to look at.
 */
export function AuditList({ events }: { events: AuditEvent[] }) {
  if (events.length === 0) {
    return (
      <p className="rounded-md border border-dashed border-fp-outline-1 px-4 py-6 text-center text-sm text-muted-foreground">
        Edits to this record will be listed here with who made them and when.
      </p>
    );
  }
  const sorted = [...events].sort((a, b) => (a.at < b.at ? 1 : -1));
  return (
    <ol className="flex flex-col gap-4">
      {sorted.map((e) => (
        <li key={e.id} className="border-l-2 border-fp-outline-1 pl-3">
          <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
            <span className="text-sm font-medium text-foreground">{e.action}</span>
            <span className="text-sm text-muted-foreground">by {e.by}</span>
            <span className="text-xs tabular-nums text-muted-foreground/80">
              {formatStamp(e.at)}
            </span>
          </div>
          {e.changes.length > 0 && (
            <ul className="mt-0.5 flex flex-col gap-0.5">
              {e.changes.map((c, i) => (
                <li key={i} className="text-sm text-muted-foreground">
                  {c}
                </li>
              ))}
            </ul>
          )}
        </li>
      ))}
    </ol>
  );
}

/**
 * A READ-ONLY DRAWER — one thing, looked at, closed.
 *
 * NARROW AND OVER THE TOP. What goes in here is a column of short content —
 * 420px is as wide as it ever needs — and it opens ON whatever is behind it
 * rather than replacing it, so closing puts the reader back exactly where they
 * were with nothing re-rendered underneath.
 *
 * NO FOOTER, deliberately. There is nothing to save: reading is not editing.
 * The moment something in here needs a Save it belongs in the record sheet
 * instead, which is the form.
 *
 * It stacks a layer above the record sheet so the two coexist rather than
 * fighting for the same one — and it opens straight off a LIST row too, where
 * there is no record sheet underneath at all.
 */
export function ReadDrawer({
  open,
  onOpenChange,
  title,
  subtitle,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    /* A picker over a stepped form is not part of it. */
    <FormStepsContext.Provider value={false}>
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        showCloseButton={false}
        className="z-[60] w-[min(420px,calc(var(--fp-vw)-56px))] gap-0 p-0 sm:max-w-[min(420px,calc(var(--fp-vw)-56px))]"
      >
        <div className="flex items-start justify-between gap-4 border-b border-border p-4">
          <div className="flex min-w-0 flex-col gap-0.5">
            <SheetTitle className="text-base">{title}</SheetTitle>
            {subtitle && (
              <span className="truncate text-xs text-muted-foreground">{subtitle}</span>
            )}
          </div>
          <button
            type="button"
            aria-label={`Close ${title.toLowerCase()}`}
            onClick={() => onOpenChange(false)}
            className="shrink-0 rounded-sm p-1 text-muted-foreground opacity-70 outline-none transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            <X className="size-4" />
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-auto p-4">{children}</div>
      </SheetContent>
    </Sheet>
    </FormStepsContext.Provider>
  );
}

/**
 * `ReadDrawer` with a footer — for a small edit that belongs to a record you
 * reached from somewhere else.
 *
 * IT IS NOT THE RECORD SHEET, and must not grow into one. This is for the two
 * or three fields somebody noticed were wrong while doing something else — a
 * stale phone number found halfway through raising an order. The full record
 * still lives in its own sheet; this is the shortcut that stops a wrong number
 * costing somebody their draft.
 */
export function EditDrawer({
  open,
  onOpenChange,
  title,
  subtitle,
  onSave,
  canSave = true,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  subtitle?: string;
  onSave: () => void;
  canSave?: boolean;
  children: React.ReactNode;
}) {
  /* ON RECORDSHEET (Pavan, 2026-10-07 — G21/G23). A second-level sheet over
     the one it was opened from: no Cancel (Close is the exit), and the
     primary is the sheet's own edit word, not Save Changes. */
  return (
    <RecordSheet
      level={2}
      size="form"
      stepNav={false}
      open={open}
      onOpenChange={onOpenChange}
      mode="edit"
      editTitle={title}
      createTitle={title}
      createAction="Confirm"
      headerSubtitle={
        subtitle ? (
          <span className="truncate text-xs text-muted-foreground">{subtitle}</span>
        ) : undefined
      }
      showCancel={false}
      canSubmit={canSave}
      onSubmit={onSave}
    >
      <div className="flex flex-col gap-4">{children}</div>
    </RecordSheet>
  );
}

/** The record's history, in a `ReadDrawer`. */
export function AuditDrawer({
  open,
  onOpenChange,
  title,
  events,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  events: AuditEvent[];
}) {
  return (
    <ReadDrawer
      open={open}
      onOpenChange={onOpenChange}
      title="Audit history"
      subtitle={`${title} · ${events.length} ${events.length === 1 ? "entry" : "entries"}`}
    >
      <AuditList events={events} />
    </ReadDrawer>
  );
}

/** Tag pills, or an honest blank. */
export function TagRow({ tags }: { tags: string[] }) {
  if (tags.length === 0) return <span className="text-muted-foreground/70">{DASH}</span>;
  return (
    <span className="flex flex-wrap gap-1">
      {tags.map((t) => (
        <Pill key={t}>
          {t}
        </Pill>
      ))}
    </span>
  );
}

/** Free text a record carries — dispatch instructions, internal notes. */
export function NoteBlock({ body, hint }: { body: string | null; hint: string }) {
  return body ? (
    <p className="text-sm whitespace-pre-wrap text-foreground">{body}</p>
  ) : (
    <p className="text-sm text-muted-foreground/70">{hint}</p>
  );
}

