export function assetConfig(
  onOpenNote: (a: RentalAsset) => void
): EntityConfig<RentalAsset, RentalAssetColumnKey> {
  return {
    urlKey: "assets",
    parentLabel: "Rental Assets",
    noun: "asset",
    rowId: (a) => a.id,
    nameOf: (a) => a.name,
    columns: RENTAL_ASSET_COLUMNS,
    matches: matchesAsset,
    searchFields: RENTAL_ASSET_SEARCH_FIELDS,
    searchPlaceholder: "Search by asset, serial, customer or location",
    sortRows: sortAssets,
    dimensions: RENTAL_ASSET_GROUP_DIMS,
    emptyIcon: <Boxes />,
    /* ONLY WHAT IS OUT EARNS. Capacity would be the obvious measure and is
       wrong — a group's tanks do not pool into one tank. */
    measureOf: (a) => (a.availabilityStatus === "On rent" ? a.rentalRate : 0),
    formatTotal: (n) => `${money(n)} / mo on rent`,

    renderCell: (a, key) => {
      switch (key) {
        case "name":
          /* One line: the serial moved into its own column, where it leads. */
          return <span className="text-sm font-medium text-foreground">{a.name}</span>;
        case "asset":
          /* SERIAL OVER TYPE. A Bulk Tank is a category — there are 30 of them
             — and FP-TK-0180 is the tank. The thing that identifies one row
             takes the prominent line. */
          return (
            <TwoLineCell
              title={a.serialNumber ?? DASH}
              description={a.assetType}
            />
          );
        case "rental": {
          /*
            A RENTAL IS A PERIOD, NOT TWO DATES, and its availability is what
            the period MEANS. An asset out Feb-to-Feb and one sitting free are
            the same two dates apart and completely different facts, so the
            state belongs under the dates rather than four columns away.
          */
          const period = a.rentalStartDate
            ? `${formatDate(a.rentalStartDate)} – ${
                a.rentalEndDate ? formatDate(a.rentalEndDate) : "Open ended"
              }`
            : null;
          const tone =
            a.availabilityStatus === "Available"
              ? "text-status-success"
              : a.availabilityStatus === "On rent"
                ? "text-fp-banner-accent-caution"
                : a.availabilityStatus === "In maintenance"
                  ? "text-status-failed"
                  : "text-muted-foreground";
          return (
            <div className="flex min-w-0 flex-col gap-0.5">
              <span className="flex min-w-0 items-center gap-1.5">
                {period ? (
                  <span className="truncate text-sm tabular-nums text-foreground">{period}</span>
                ) : (
                  /* NOT ON RENT HAS NO PERIOD — `N/A`, not a blank and not a
                     date range invented to fill the line. */
                  <span className="text-sm text-muted-foreground/70">N/A</span>
                )}
                {endingSoon(a) && (
                  <Pill className="shrink-0">
                    Soon
                  </Pill>
                )}
              </span>
              <span className={cn("truncate text-xs font-medium", tone)}>
                {a.availabilityStatus}
              </span>
            </div>
          );
        }
        case "customer":
          return a.customer ? (
            <span className="text-sm">{a.customer}</span>
          ) : (
            <Muted>At the yard</Muted>
          );
        case "shipTo":
          return a.shipTo ? <span className="text-sm">{a.shipTo}</span> : <Muted />;
        case "address":
          if (!a.addressLine1 && !a.city && !a.state && !a.zip) return <Muted />;
          return (
            <TwoLineCell
              title={a.addressLine1 ?? DASH}
              description={
                [a.city, [a.state, a.zip].filter(Boolean).join(" ")]
                  .filter(Boolean)
                  .join(", ") || DASH
              }
            />
          );
        case "status":
          return <RecordStatusChip status={a.status} />;
        case "rate":
          return <Money value={a.rentalRate} />;
        case "product": {
          const p = BROKER_PRODUCTS.find((x) => x.id === a.associatedProductId);
          return p ? <span className="text-sm">{p.name}</span> : <Muted>N/A</Muted>;
        }
        case "maintenance":
          return (
            <StatusChip
              tone={kindTone(
                /* OK is the normal state, not an achievement — it says nothing,
                   so the exceptions are what carry colour. */
                a.maintenanceStatus === "OK"
                  ? "neutral"
                  : a.maintenanceStatus === "Service due"
                    ? "caution"
                    : "critical",
              )}
              variant="text"
            >
              {a.maintenanceStatus}
            </StatusChip>
          );
        case "notes":
          return a.notes ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label={`Read notes for ${a.name}`}
                  onClick={() => onOpenNote(a)}
                >
                  <NotebookPen />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Read asset notes</TooltipContent>
            </Tooltip>
          ) : (
            <Muted />
          );
        default:
          return null;
      }
    },

    facets: [
      { key: "status", label: "Record Status", options: ["active", "inactive", "archived"], valueOf: (a) => a.status },
      { key: "availability", label: "Availability", options: [...RENTAL_STATUSES], valueOf: (a) => a.availabilityStatus },
      { key: "type", label: "Asset Type", options: [...RENTAL_TYPES], valueOf: (a) => a.assetType },
      { key: "maintenance", label: "Maintenance", options: [...MAINTENANCE_STATUSES], valueOf: (a) => a.maintenanceStatus },
      {
        key: "customer",
        label: "Customer",
        searchable: true,
        options: [...new Set(RENTAL_ASSETS.map((a) => a.customer).filter((x): x is string => Boolean(x)))].sort(),
        valueOf: (a) => a.customer ?? "",
      },
      { key: "state", label: "State", options: STATE_CODES, searchable: true, valueOf: (a) => a.state ?? "" },
      {
        key: "flags",
        label: "Flags",
        options: ["Rental ending soon", "Compliance risk", "Under maintenance", "Linked to recurring", "Unassigned"],
        valueOf: (a) => {
          const out: string[] = [];
          if (endingSoon(a)) out.push("Rental ending soon");
          if (a.complianceStatus === "Expired" || a.complianceStatus === "Expiring") out.push("Compliance risk");
          if (a.availabilityStatus === "In maintenance") out.push("Under maintenance");
          if (BROKER_ORDERS.some((o) => o.kind === "Recurring" && o.lines.some((l) => l.asset === a.name))) {
            out.push("Linked to recurring");
          }
          if (!a.customerId) out.push("Unassigned");
          return out;
