      "Next Service Due": blank(a.nextServiceDue),
    }),

    headerAsideOf: assetHeaderAside,
    readSectionsOf: (a, go) => assetReadSections(a, go),

    formSections: assetFormSections(),
    blank: (id) => ({
      id,
      name: "",
      assetType: "Bulk Tank",
      tankType: null,
      serialNumber: null,
      qrCode: null,
      externalAssetId: null,
      ownershipType: "owned",
      status: "active",
      customerId: null,
      customer: null,
      shipToId: null,
      shipTo: null,
      addressLine1: null,
      addressLine2: null,
      city: null,
      state: null,
      zip: null,
      country: "USA",
      latitude: null,
      longitude: null,
      installedDate: null,
      removalDate: null,
      availabilityStatus: "Available",
      rentalStartDate: null,
      rentalEndDate: null,
      contractId: null,
      billingFrequency: "Monthly",
      rentalRate: 0,
      depositAmount: null,
      autoRenew: false,
      associatedProductId: null,
      capacityGal: 0,
      unit: "gal",
      fillThreshold: null,
      reorderPoint: null,
      topOffRelevant: false,
      assignedVendorId: null,
      lastServiceDate: null,
      nextServiceDue: null,
      maintenanceStatus: "OK",
      complianceStatus: "Not required",
      assetPhoto: null,
      documents: [],
      inspectionFiles: [],
      installationRecords: [],
      tags: [],
      notes: null,
