import * as React from "react";
import { Image as ImageIcon, Send, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { SheetField, SheetSection } from "@/components/side-sheet/parts";
import { RecordSheet } from "../RecordSheet";
import { DATE_FMT } from "../data";
import type { OrderLine } from "./orders";

/*
  INVITING A PARTNER IS SENDING THEM AN EMAIL, so the sheet is the email.

  WHY IT IS NOT A CONFIRM DIALOG. What goes out carries the whole order — the
  site, the window, the assets and the gallons — and it is the only thing the
  partner will ever see of it. A dialog saying "Invite Redline Carriers?" asks
  somebody to vouch for a message they have not read.

  TWO COLUMNS, WHICH IS WHY IT IS `xxwide`: what you write on the left, what
  they receive on the right. The same rule the order sheet follows — editable
  left, derived right — and the preview is derived in the strictest sense,
  because every line of it comes off the order rather than out of this form.

  THE PREVIEW IS NOT A MOCK. It is built from the same draft the sheet was
  opened on, so a wrong address here is a wrong address in the inbox, and it
  can be caught before the send rather than after.
*/

export interface InviteTarget {
  id: string;
  name: string;
  /** Where the invitation goes. Seeded from the partner's dispatch address. */
  email: string;
}

export interface InviteOrderFacts {
  orderNo: string;
  customer: string;
  shipTo: string;
  address: string;
  dateKey: string;
  window: { start: string; end: string };
  lines: OrderLine[];
}

/* ---------------------------------------------------------------------------
 * Email addresses, as chips
 * ------------------------------------------------------------------------ */

/**
 * A LIST OF ADDRESSES IS NOT A LINE OF TEXT. Comma-separated in one field,
 * a single typo takes the whole send down and nothing says which address was
 * wrong. As chips each address is its own object: added on Enter or a comma,
 * removed on its own ×, and one bad one is visibly one bad one.
 */
export function EmailChips({
  value,
  onChange,
  placeholder,
  id,
}: {
  value: string[];
  onChange: (next: string[]) => void;
  placeholder: string;
  id: string;
}) {
  const [text, setText] = React.useState("");

  const commit = () => {
    const parts = text
      .split(/[,;\s]+/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (parts.length === 0) return;
    onChange([...new Set([...value, ...parts])]);
    setText("");
  };

  return (
    <div className="flex min-h-9 flex-wrap items-center gap-1.5 rounded-md border border-input px-2 py-1.5">
      {value.map((addr) => (
        <span
          key={addr}
          className={cn(
            "inline-flex items-center gap-1 rounded-md bg-fp-surface-1b py-0.5 pr-1 pl-2 text-sm",
            /* A ROUGH SHAPE CHECK, NOT VALIDATION. It cannot know whether an
               address exists; it can say that this one has no @ in it, which
               is the typo people actually make. */
            !addr.includes("@") && "text-status-failed"
          )}
        >
          {addr}
          <button
            type="button"
            aria-label={`Remove ${addr}`}
            onClick={() => onChange(value.filter((a) => a !== addr))}
            className="flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:text-foreground"
          >
            <X className="size-3.5" />
          </button>
        </span>
      ))}
      <input
        id={id}
        value={text}
        placeholder={value.length === 0 ? placeholder : undefined}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === ",") {
            e.preventDefault();
            commit();
          }
          if (e.key === "Backspace" && text === "" && value.length > 0) {
            onChange(value.slice(0, -1));
          }
        }}
        /* ON BLUR TOO. A half-typed address left in the box and a press of
           Send is the one way to lose a recipient silently. */
        onBlur={commit}
        className="min-w-[10ch] flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
      />
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * What is attached
 * ------------------------------------------------------------------------ */

/**
 * THE EMAIL BODY IS NOT DESIGNED HERE. (Pavan, 2026-09-22.) The order summary
 * that reaches the partner is rendered by another system and goes out as an
 * image; this sheet composes the message around it. Redrawing that layout in
 * the app would be a second copy of somebody else's design, wrong the first
 * time it changed and nobody's job to keep right.
 *
 * SO THIS PANE SHOWS THE ATTACHMENT, not a replica of it — its name, what it
 * carries, and the fact that it is generated rather than written. What the
 * broker is responsible for is on the left.
 */
function AttachedSummary({
  facts,
  partnerName,
}: {
  facts: InviteOrderFacts;
  partnerName: string;
}) {
  const when = (() => {
    const [y, m, d] = facts.dateKey.split("-").map(Number);
    if (!y) return "—";
    return `${DATE_FMT.format(new Date(y, m - 1, d))}, ${facts.window.start} – ${facts.window.end}`;
  })();
  const lines = facts.lines.filter((l) => l.asset);

  return (
    <div className="flex flex-col gap-4 p-4">
      <div className="flex items-start gap-3 rounded-md border border-fp-outline-1 bg-fp-card-1 p-3">
        <ImageIcon className="mt-0.5 size-5 shrink-0 text-muted-foreground" />
        <span className="flex min-w-0 flex-col gap-0.5">
          <span className="truncate text-sm font-medium text-foreground">
            {facts.orderNo}-order-summary.png
          </span>
          <span className="text-xs text-muted-foreground">
            Generated when the invitation is sent · goes out in the message body
          </span>
        </span>
      </div>

      {/* WHAT IS IN IT, IN WORDS. Not a picture of the picture: a list of what
          the partner will be able to read, so a missing asset or a wrong
          window is catchable from here even though the layout is not ours. */}
      <div className="flex flex-col gap-1.5 text-sm">
        <span className="font-medium text-foreground">It will show</span>
        <ul className="flex flex-col gap-1 text-muted-foreground">
          <li>
            Order <span className="text-foreground">{facts.orderNo}</span> for{" "}
            <span className="text-foreground">{facts.customer}</span>
          </li>
          <li>
            <span className="text-foreground">{facts.shipTo}</span> —{" "}
            {facts.address}
          </li>
          <li>
            Delivery <span className="text-foreground">{when}</span>
          </li>
          <li>
            {lines.length === 0 ? (
              <span className="text-status-failed">
                No assets on the order — {partnerName} would be asked to price
                nothing
              </span>
            ) : (
              <>
                <span className="text-foreground">
                  {lines.length} {lines.length === 1 ? "line" : "lines"}
                </span>
                {" — "}
                {lines
                  .map(
                    (l) =>
                      `${l.asset} · ${l.product} · ${
                        l.topOff ? "top off" : `${(l.gal ?? 0).toLocaleString()} gal`
                      }`
                  )
                  .join("; ")}
              </>
            )}
          </li>
          <li>A link back to submit their pricing</li>
        </ul>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * The sheet
 * ------------------------------------------------------------------------ */

export function InvitePartnerSheet({
  open,
  onOpenChange,
  targets,
  facts,
  resend = false,
  onSend,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  /** One partner, or everything ticked for a bulk send. */
  targets: InviteTarget[];
  facts: InviteOrderFacts;
  /** A second invitation to somebody already asked — the wording differs. */
  resend?: boolean;
  onSend: (ids: string[]) => void;
}) {
  const one = targets.length === 1 ? targets[0] : null;

  const [to, setTo] = React.useState<string[]>([]);
  const [cc, setCc] = React.useState<string[]>([]);
  const [bcc, setBcc] = React.useState<string[]>([]);
  const [subject, setSubject] = React.useState("");
  const [message, setMessage] = React.useState("");

  /* SEEDED ONCE PER OPEN, so a broker who edits the subject and closes by
     accident does not get their wording back — and one who opens it on a
     different partner does not get the last one's. */
  React.useEffect(() => {
    if (!open) return;
    setTo(targets.map((t) => t.email));
    setCc([]);
    setBcc([]);
    setSubject(
      `${facts.orderNo} · ${facts.shipTo} · ${facts.customer}`
    );
    setMessage(
      resend
        ? `A reminder about order ${facts.orderNo}. We have not had your pricing yet — please acknowledge and submit it when you can.`
        : `We have a delivery to cover and would like you to quote for it. Please acknowledge the order and submit your pricing.`
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, targets.map((t) => t.id).join(","), resend]);

  const nothingToSend = to.length === 0 || subject.trim() === "";

  return (
    <RecordSheet
      /* ONE COLUMN (Pavan, 2026-10-20) — recipients, then the message, then
         what's attached, read top to bottom as the email is. */
      fit={{ tables: [[560]] }}
      /* OVER THE ORDER SHEET — see `level` on `RecordSheet`. */
      level={2}
      open={open}
      onOpenChange={onOpenChange}
      mode="create"
      editTitle=""
      createTitle={
        one
          ? `${resend ? "Resend to" : "Invite"} ${one.name}`
          : `Invite ${targets.length} partners`
      }
      createAction={resend ? "Resend invitation" : "Send invitation"}
      showCancel={false}
      canSubmit={!nothingToSend}
      onSubmit={() => onSend(targets.map((t) => t.id))}
      footerPrimary={
        <Button
          disabled={nothingToSend}
          onClick={() => {
            onSend(targets.map((t) => t.id));
            onOpenChange(false);
          }}
        >
          <Send />
          {targets.length > 1
            ? `Send ${targets.length} invitations`
            : resend
              ? "Resend invitation"
              : "Send invitation"}
        </Button>
      }
    >
      <div className="flex min-w-0 flex-col gap-10">
          <SheetSection title="Recipients">
            <SheetField label="To">
              <EmailChips
                id="invite-to"
                value={to}
                onChange={setTo}
                placeholder="name@partner.com"
              />
            </SheetField>
            <div className="grid grid-cols-2 gap-4">
              <SheetField label="Cc">
                <EmailChips
                  id="invite-cc"
                  value={cc}
                  onChange={setCc}
                  placeholder="Optional"
                />
              </SheetField>
              <SheetField label="Bcc">
                <EmailChips
                  id="invite-bcc"
                  value={bcc}
                  onChange={setBcc}
                  placeholder="Optional"
                />
              </SheetField>
            </div>
            {targets.length > 1 && (
              /* A BULK SEND IS N EMAILS, NOT ONE WITH N NAMES ON IT. Partners
                 bidding against each other must not see the list they are
                 bidding against. */
              <p className="text-xs text-muted-foreground">
                One message each — no partner sees the others.
              </p>
            )}
          </SheetSection>

          {/* THE MESSAGE RUNS TO THE BOTTOM. It is the only thing on this
              sheet the broker actually writes, and a seven-line box under
              two short fields made the writing feel like an afterthought to
              the addressing. Everything above it is fixed; this takes what
              is left. */}
          <SheetSection title="Message">
            <SheetField label="Subject">
              <Input
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="What the order is"
              />
            </SheetField>
            {/* THE BOX IS THE REST OF THE CARD.
                TWO THINGS HAD TO GIVE. `SheetField` wraps its control in a
                second div for the helper-text rhythm, so the growth has to be
                passed through it as well as to the field itself; and the DS
                textarea is `field-sizing-content`, which sizes to what is
                typed and would shrink a deliberately tall box back to three
                lines. Fixed sizing plus `flex-1` is what makes it fill. */}
            <SheetField label="Your note">
              <Textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Anything this partner needs to know."
                className="min-h-[160px] resize-y [field-sizing:fixed]"
              />
            </SheetField>
          </SheetSection>

          {/* WHAT THEY GET, UNDER WHAT YOU WRITE. */}
          <SheetSection
            title="Attached"
            flush
            action={
              <span className="text-xs text-muted-foreground">
                {one ? one.name : `${targets.length} partners`}
              </span>
            }
          >
            <AttachedSummary
              facts={facts}
              partnerName={one?.name ?? "the partner"}
            />
          </SheetSection>
      </div>
    </RecordSheet>
  );
}

import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCellSelect, TableRequiredLabel } from "@/components/form-layout";
import { loadOptions } from "./orders";

/** One product on the load order, and where it loads from. */
export interface LoadOrderRow {
  product: string;
  terminal?: string;
  supplier?: string;
  loadingAccount?: string;
  /**
   * Set aside, not deleted. The product is still on the order, so a deleted
   * row would come back blank on the next render.
   */
  excluded?: boolean;
}

/**
 * THE LOAD ORDER TABLE — one row per product, then Terminal, Supplier and
 * Loading Account, each narrowed by the one before it.
 *
 * The delivery order's load order, drawn per product. The Create recurring
 * rule sheet draws its load order BY ACCOUNT instead (Pavan, 2026-09-25) —
 * an account carries several products — so it has its own table. Flush (T1):
 * the card it sits in draws the rim.
 */
export function LoadOrderTable({
  rows,
  onChange,
}: {
  rows: LoadOrderRow[];
  onChange: (product: string, patch: Partial<LoadOrderRow>) => void;
}) {
  return (
    <table className="w-full table-fixed border-collapse">
      <colgroup>
        <col className="w-[44px]" />
        <col className="w-[26%]" />
        <col />
        <col />
        <col />
      </colgroup>
      <thead>
        <tr className="border-b border-border bg-fp-table-header">
          {/* No label: what the tick means is stated by the rows it dims, and
              a header for it would name the exception. */}
          <th aria-hidden />
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel>Product</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel required>Terminal</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel required>Supplier</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel required>Loading Account</TableRequiredLabel>
          </th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => {
          /* Narrowed by THIS product, then by what is chosen to its left. */
          const opts = loadOptions([row.product], row.terminal, row.supplier);
          const on = !row.excluded;
          return (
            <tr
              key={row.product}
              className="h-11 border-b border-border last:border-b-0"
            >
              {/* SET ASIDE, NOT DELETED. Unticking dims the row and disables
                  its cells, keeping whatever was chosen for the moment someone
                  ticks it again. */}
              <td className="px-3">
                <Checkbox
                  checked={on}
                  onCheckedChange={(c) =>
                    onChange(row.product, { excluded: c !== true })
                  }
                  aria-label={`Include ${row.product} in the load order`}
                />
              </td>
              <td
                className={cn(
                  "truncate px-3 text-sm",
                  on ? "text-foreground" : "text-muted-foreground line-through"
                )}
              >
                {row.product}
              </td>
              <td className="relative p-0">
                <TableCellSelect
                  value={row.terminal ?? ""}
                  options={opts.terminals}
                  placeholder="Terminal"
                  disabled={!on}
                  aria-label={`Terminal for ${row.product}`}
                  onChange={(v) =>
                    onChange(row.product, {
                      terminal: v,
                      supplier: undefined,
                      loadingAccount: undefined,
                    })
                  }
                />
              </td>
              <td className="relative p-0">
                <TableCellSelect
                  value={row.supplier ?? ""}
                  options={opts.suppliers}
                  placeholder="Supplier"
                  disabled={!on}
                  aria-label={`Supplier for ${row.product}`}
                  onChange={(v) =>
                    onChange(row.product, {
                      supplier: v,
                      loadingAccount: undefined,
                    })
                  }
                />
              </td>
              <td className="relative p-0">
                <TableCellSelect
                  value={row.loadingAccount ?? ""}
                  options={opts.accounts}
                  placeholder="Account"
                  disabled={!on}
                  aria-label={`Loading account for ${row.product}`}
                  onChange={(v) => onChange(row.product, { loadingAccount: v })}
                />
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

import { CELL } from "../RecordSheet";
import { StatusChip } from "@/components/ui/status-chip";
import {
  AttachmentTable,
  NoteBlock,
  ReadField,
  ReadGrid,
  SheetTable,
  TagRow,
  type RecordReadSection,
} from "./DirectoryRecordSheet";
import { DASH, formatDate, money } from "./directoryCore";
import {
  BROKER_CUSTOMERS,
  PRODUCT_CATEGORIES,
  UNITS_OF_MEASURE,
  customerReach,
  type BrokerProduct,
} from "./directory";
import { ordersForProduct, vendorsForProduct } from "./directoryLinks";
import { BROKER_STATUS_TONE } from "./orders";
import type { FormSectionDef } from "./directoryFormTypes";
import { ACTIVE_KIND, kindTone } from "../statusKind";

/*
  What a product record shows in the sheet, beyond the fields it edits.

  A PRODUCT IS A SET OF RULES, not a thing. Everything here constrains an order
  line: what it can be measured in, how much may be ordered, whether "top off"
  is even offerable, who may buy it, and who can deliver it.

  TWO NUMBERS ARE COMPUTED, NEVER STORED — how many customers may buy it and
  how many vendors can fulfil it. Both answer "why is this product not on the
  picker", and a stored count would be wrong the first time a vendor was
  edited.
*/

const Muted = () => <span className="text-muted-foreground/70">{DASH}</span>;

export function productHeaderAside(p: BrokerProduct) {
  const vendors = vendorsForProduct(p).length;
  return (
    <span className="flex items-center gap-1.5">
      <StatusChip tone={kindTone(ACTIVE_KIND(p.status === "active"))} variant="soft">
        <span className="capitalize">{p.status}</span>
      </StatusChip>
      {p.topOffSupported && (
        <StatusChip tone={kindTone("info")} variant="soft">
          Top-off
        </StatusChip>
      )}
      {p.taxable && !p.taxCode && (
        <StatusChip tone={kindTone("critical")} variant="soft">
          No tax code
        </StatusChip>
      )}
      {vendors === 0 && (
        <StatusChip tone={kindTone("critical")} variant="soft">
          No vendor can fulfil
        </StatusChip>
      )}
    </span>
  );
}

export function productReadSections(
  p: BrokerProduct,
  go: { openVendor: (id: string) => void; openCustomer: (id: string) => void }
): RecordReadSection[] {
  const vendors = vendorsForProduct(p);
  const orders = ordersForProduct(p.name);
  const recurring = orders.filter((o) => o.kind === "Recurring");
  const allowed = p.availableToAllCustomers
    ? BROKER_CUSTOMERS.filter((c) => !p.blockedCustomerIds.includes(c.id))
    : BROKER_CUSTOMERS.filter((c) => p.allowedCustomerIds.includes(c.id));

  return [
    {
      key: "reach",
      title: "Reach",
      note: `${customerReach(p)} customers · ${vendors.length} vendors`,
      render: () => (
        <ReadGrid>
          <ReadField label="Base price" value={`${money(p.basePrice)} per ${p.unit}`} />
          <ReadField
            label="Top-off"
            value={p.topOffSupported ? "A line may be a top-off" : "Every line needs a quantity"}
          />
          <ReadField
            label="Quantity"
            value={
              p.minimumQuantity === null && p.maximumQuantity === null
                ? null
                : `${p.minimumQuantity?.toLocaleString() ?? "—"} – ${p.maximumQuantity?.toLocaleString() ?? "no max"} ${p.unit}`
            }
          />
          <ReadField label="Default quantity" value={p.defaultQuantity === null ? null : `${p.defaultQuantity.toLocaleString()} ${p.unit}`} />
          <ReadField label="Hazard flags" value={p.hazardFlags.length > 0 ? <TagRow tags={p.hazardFlags} /> : null} />
          <ReadField label="Tags" value={<TagRow tags={p.tags} />} />
          <ReadField
            label="Geography restrictions"
            value={p.geographyRestrictions.length > 0 ? <TagRow tags={p.geographyRestrictions} /> : "None"}
            wide
          />
          <ReadField label="Last updated" value={formatDate(p.updatedAt.slice(0, 10))} />
          <ReadField label="Created" value={formatDate(p.createdAt.slice(0, 10))} />
        </ReadGrid>
      ),
    },
    {
      key: "vendors",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.name, CELL.pick, CELL.text, CELL.flag, CELL.status],
      title: "Vendors who can fulfill this",
      count: vendors.length,
      render: () => (
        <SheetTable
          rows={vendors}
          rowKey={(v) => v.id}
          onOpenRow={(v) => go.openVendor(v.id)}
          emptyBody="No carrier's business lines cover this product, so an order naming it cannot be assigned."
          columns={[
            { key: "name", label: "Vendor", render: (v) => v.name },
            { key: "base", label: "Base", render: (v) => v.base },
            { key: "lines", label: "Business lines", render: (v) => v.businessLines.join(", ") },
            {
              key: "default",
              label: "Default",
              render: (v) => (p.defaultVendorIds.includes(v.id) ? "Yes" : <Muted />),
            },
            {
              key: "status",
              label: "Status",
              render: (v) => (
                <StatusChip tone={kindTone(ACTIVE_KIND(v.active))} variant="text">
                  {v.active ? "Active" : "Inactive"}
                </StatusChip>
              ),
            },
          ]}
        />
      ),
    },
    {
      key: "customers",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.name, CELL.pick, CELL.pick, CELL.pick],
      title: "Eligible accounts",
      count: allowed.length,
      note: p.availableToAllCustomers ? "Available to all customers" : "Restricted list",
      render: () => (
        <SheetTable
          rows={allowed}
          rowKey={(c) => c.id}
          onOpenRow={(c) => go.openCustomer(c.id)}
          emptyBody="Nobody can order this product. Check the availability rules above."
          columns={[
            { key: "name", label: "Customer", render: (c) => c.name },
            { key: "erp", label: "ERP ID", render: (c) => c.erpId },
            { key: "credit", label: "Credit", render: (c) => c.creditStatus },
            { key: "state", label: "State", render: (c) => c.state ?? <Muted /> },
          ]}
        />
      ),
    },
    {
      key: "usage",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.pick, CELL.name, CELL.date, CELL.number, CELL.status],
      title: "Order usage",
      note: `${orders.length} orders · ${recurring.length} recurring`,
      render: () => (
        <SheetTable
          rows={orders}
          rowKey={(o) => o.id}
          emptyBody="No order line has named this product."
          columns={[
            { key: "no", label: "Order", render: (o) => o.orderNo },
            { key: "cust", label: "Customer", render: (o) => o.customer.title },
            { key: "date", label: "Date", render: (o) => o.date.title },
            {
              key: "qty",
              label: "Quantity",
              render: (o) => {
                const line = o.lines.find((l) => l.product === p.name);
                if (!line) return <Muted />;
                return line.topOff ? "Top-off" : `${(line.gal ?? 0).toLocaleString()} ${p.unit}`;
              },
            },
            {
              key: "status",
              label: "Status",
              render: (o) => (
                <StatusChip tone={BROKER_STATUS_TONE[o.status]} variant="text">
                  {o.status}
                </StatusChip>
              ),
            },
          ]}
        />
      ),
    },
    {
      key: "sds",
      title: "Safety data sheets",
      count: p.sdsAttachments.length,
      render: () => <AttachmentTable files={p.sdsAttachments} />,
    },
    {
      key: "attachments",
      title: "Attachments",
      count: p.attachments.length,
      render: () => <AttachmentTable files={p.attachments} />,
    },
    {
      key: "notes",
      title: "Product notes",
      render: () => <NoteBlock body={p.notes} hint="No notes recorded." />,
    },
  ];
}

