                      a padded cell drew a second grid over the table's. */}
                  <td className="relative p-0">
                    {editable && !l.topOff ? (
                      <TableCellInput
                        numeric
                        placeholder="0"
                        value={l.gal == null ? "" : String(l.gal)}
                        aria-label={`Quantity for ${l.product}`}
