/**
 * A RULE, BACK INTO THE FORM'S SHAPE. Rules made in the form keep the form's
 * own frequency; the seeded ones are rebuilt from their schedule.
 */
function draftOf(p: RecurringProgram): ProgramDraft {
  const days = p.schedule.days;
  return {
    name: p.programNo,
    jobType: p.jobType,
    vendorIds: p.vendorIds,
    products: p.products,
    winterProducts: p.winterProducts,
    frequency: p.frequency ?? {
      ...blankFrequency(),
      dayMode: days.length === 7 ? "daily" : "specific",
      days,
      repeat: /month/i.test(p.schedule.cadence) ? "monthly" : "weekly",
      endKey: p.endKey,
    },
    loadOrder: p.loadOrder,
    loadRows: p.loadRows.map((l) => ({ loadingAccount: l.loadingAccount })),
    startKey: p.startKey,
    signatureOnDelivery: p.signatureOnDelivery,
    targets: p.targets,
  };
}

export function RecurringProgramsScreen({
  onOpenArchive,
}: {
  /** The old versions (V1, V2), kept for reference — see the footer. */
  onOpenArchive?: () => void;
} = {}) {
  /* THE SHARED LIST — Delivery Orders cuts its recurring orders from it. */
  const [programs, setPrograms] = usePrograms();
  const [openId, setOpenId] = React.useState<string | null>(null);
  const [creating, setCreating] = React.useState(false);
  /** A rule started from a recommendation — see `RuleRecommendations`. */
  const [seed, setSeed] = React.useState<{
    frequency: RuleFrequency;
    products: string[];
    vendorIds: string[];
    loadOrder: boolean;
    loadingAccounts: string[];
    targets: { customer: { title: string; description: string }; shipTo: string }[];
  } | null>(null);
  /* THE RULE BEING EDITED in the create form — only one that has made no
     order yet (see the sheet's Edit rule). */
  const [editingId, setEditingId] = React.useState<string | null>(null);
  const [search, setSearch] = React.useState("");
  const [applied, setApplied] = React.useState<ReadonlySet<string>>(new Set());
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set());
  const [view, setView] = React.useState<ListView>("table");
  const [colScope, setColScope] = React.useState(PROGRAM_SEARCH_FIELDS[0].key);
  const [colQuery, setColQuery] = React.useState("");
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(25);

  /* THE COLUMNS ARE THE READER'S — order, widths and the sort, the same
     `useTableColumns` call every flat table here makes. */
  /* SEARCH BY COLUMN IS A ROW OF BOXES UNDER THE HEADER — the Delivery
     Orders behaviour, and the rule for every table (`2-rules.md` §10g). */
  const [colFilters, setColFilters] = React.useState<Record<string, string>>({});
  const [colFiltersOpen, setColFiltersOpen] = React.useState(false);
  const activeColFilters = React.useMemo(
    () => Object.entries(colFilters).filter(([, v]) => v.trim() !== ""),
    [colFilters]
  );
  const [colOrder, setColOrder] = React.useState<string[]>(COL_KEYS);
  const [widths, setWidths] = React.useState<Record<string, number>>({});
  const [exporting, setExporting] = React.useState(false);
  const [sort, setSort] = React.useState<{
    key: string;
    dir: "asc" | "desc";
  } | null>(null);
  const cols = useTableColumns({
    keys: COL_KEYS,
    order: colOrder,
    onOrderChange: setColOrder,
    widths,
    onWidthsChange: setWidths,
  });
  /* ASC → DESC → UNSORTED, the three-press cycle every table uses. */
  const onSort = (key: string) =>
    setSort((prev) =>
      !prev || prev.key !== key
        ? { key, dir: "asc" }
        : prev.dir === "asc"
          ? { key, dir: "desc" }
          : null
    );

  const savedViews = useSavedViews<{
    search: string;
    applied: string[];
    hidden: string[];
    colScope: string;
    colQuery: string;
    colFilters: Record<string, string>;
    colOrder: string[];
    widths: Record<string, number>;
    sort: { key: string; dir: "asc" | "desc" } | null;
  }>({
    current: {
      search,
      applied: [...applied],
      hidden: [...hidden],
      colScope,
      colQuery,
      colFilters: Object.fromEntries(activeColFilters),
      colOrder,
      widths,
      sort,
    },
    defaultState: {
      search: "",
      applied: [],
      hidden: [],
      colScope: PROGRAM_SEARCH_FIELDS[0].key,
      colQuery: "",
      colFilters: {},
      colOrder: COL_KEYS,
      widths: {},
      sort: null,
    },
    keyOf: (v) =>
      JSON.stringify({
        ...v,
        applied: [...v.applied].sort(),
        hidden: [...v.hidden].sort(),
        colFilters: Object.fromEntries(
          Object.entries(v.colFilters ?? {})
            .filter(([, x]) => x.trim() !== "")
            .sort(([a], [b]) => a.localeCompare(b))
        ),
      }),
    apply: (v) => {
      setSearch(v.search);
      setColFilters(v.colFilters ?? {});
      /* A view that narrows by column opens on its boxes — a narrowing with
         nothing on screen saying so is the one thing the row exists to avoid. */
      setColFiltersOpen(Object.values(v.colFilters ?? {}).some((x) => x.trim()));
      setApplied(new Set(v.applied));
      setHidden(new Set(v.hidden));
      setColScope(v.colScope);
      setColQuery(v.colQuery);
      setColOrder(v.colOrder ?? COL_KEYS);
      setWidths(v.widths ?? {});
      setSort(v.sort ?? null);
      setPage(1);
    },
    /* REMEMBERED ACROSS VISITS (Pavan, 2026-10-09). */
    storageKey: "3pl-recurring-programs",
  });

  /* THE NARROWING, FOR ANY SET OF FACET TICKS — the list uses the applied
     set; the filter panel asks it of the ticks it holds, to count them. */
  const narrow = React.useCallback((facetSel: ReadonlySet<string>) => {
    const cq = colQuery.trim().toLowerCase();
    const field = PROGRAM_SEARCH_FIELDS.find((f) => f.key === colScope);
    const byFacet = [...facetSel].reduce<Record<string, string[]>>((acc, id) => {
      const at = id.indexOf(":");
      (acc[id.slice(0, at)] ??= []).push(id.slice(at + 1));
      return acc;
    }, {});
    return programs.filter((p) => {
      if (!matchesProgram(p, search)) return false;
      if (cq && field && !field.text(p).toLowerCase().includes(cq)) return false;
      /* AND, because that is what typing in two boxes looks like it does. */
      if (
        !activeColFilters.every(([k, v]) =>
          columnText(p, k).toLowerCase().includes(v.trim().toLowerCase())
        )
      )
        return false;
      return Object.entries(byFacet).every(([k, wanted]) => {
        const facet = PROGRAM_FACETS.find((f) => f.key === k);
        if (!facet) return true;
        const mine = facet.valuesOf?.(p) ?? [facet.valueOf(p)];
        return mine.some((x) => wanted.includes(x));
      });
    });
  }, [programs, search, colScope, colQuery, activeColFilters]);

  const rows = React.useMemo(() => {
    const kept = narrow(applied);
    /* SORTING IS THE LAST STEP. Unsorted returns the list's own order. */
    const col = sort && COLUMNS.find((c) => c.key === sort.key);
    if (!sort || !col) return kept;
    const dir = sort.dir === "asc" ? 1 : -1;
    return [...kept].sort((a, b) => {
      const av = col.sort(a);
      const bv = col.sort(b);
      if (typeof av === "number" && typeof bv === "number")
        return (av - bv) * dir;
      return String(av).localeCompare(String(bv)) * dir;
    });
  }, [narrow, applied, sort]);

  /* THE VIEW BAR — the table's tools render into it. */
  const bar = useViewBar();
  const total = rows.length;
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(page, pageCount);
  const pageRows = rows.slice((safePage - 1) * pageSize, safePage * pageSize);
  React.useEffect(() => {
    setPage(1);
  }, [search, applied, colQuery, colScope, activeColFilters]);

  const openProgram = programs.find((p) => p.id === openId) ?? null;
  const editing = programs.find((p) => p.id === editingId) ?? null;
  const editingDraft = React.useMemo<ProgramDraft | null>(
    () => (editing ? draftOf(editing) : null),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editingId]
  );
  const filtered =
    search.trim().length > 0 ||
    applied.size > 0 ||
    colQuery.trim().length > 0 ||
    activeColFilters.length > 0;
  const clearAll = () => {
    setSearch("");
    setApplied(new Set());
    setColQuery("");
    setColFilters({});
  };

  const visibleCols = React.useMemo(
    () => cols.arrange(COLUMNS.filter((c) => !hidden.has(c.key))),
    [cols, hidden]
  );

  /* EXPORT ASKS FIRST (Pavan, 2026-10-07) — the Delivery Orders sheet, with
     every narrowing that shapes the file listed. */
  const exportFilters: ExportFilterRow[] = [
    {
      key: "search",
      label: "Search",
      values: search.trim() ? [{ value: search.trim(), onRemove: () => setSearch("") }] : [],
    },
    {
      key: "colSearch",
      label: PROGRAM_SEARCH_FIELDS.find((f) => f.key === colScope)?.label ?? "Column",
      values: colQuery.trim() ? [{ value: colQuery.trim(), onRemove: () => setColQuery("") }] : [],
    },
    ...activeColFilters.map(([key, value]) => ({
      key: `col:${key}`,
      label: COLUMNS.find((c) => c.key === key)?.label ?? key,
      values: [
        {
          value: value.trim(),
          onRemove: () => setColFilters((prev) => ({ ...prev, [key]: "" })),
        },
      ],
    })),
    ...PROGRAM_FACETS.map((f) => {
      const mine = [...applied].filter((id) => id.startsWith(`${f.key}:`));
      const drop = (ids: string[]) =>
        setApplied((prev) => new Set([...prev].filter((id) => !ids.includes(id))));
      return {
        key: f.key,
        label: f.label,
        values: mine.map((id) => ({
          value: id.slice(f.key.length + 1),
          onRemove: () => drop([id]),
        })),
        onRemoveAll: () => drop(mine),
      };
    }),
  ];

  const exportCsv = () => {
    downloadCsv(
      `recurring-programs-${new Date().toISOString().slice(0, 10)}`,
      rows.flatMap((p) =>
        /* ONE CSV ROW PER LANE, not per programme. A spreadsheet of
           programmes with a "12 sites" cell is a spreadsheet nobody can
           pivot; the lane is the unit anybody exporting this wants. */
        p.targets.map((t) => ({
          "Program #": p.programNo,
          Partner: programVendors(p).map((v) => v.name).join(" / "),
          Product: p.products.join(" + "),
          Frequency: p.schedule.label,
          Customer: t.customer.title,
          "Ship to": t.shipTo,
          City: t.city,
          State: t.state,
          Window: `${t.window.start} – ${t.window.end}`,
          Lane: t.state_,
          Serviceable: t.serviceable ? "Yes" : "No",
          "Partner price": t.vendorPrice ?? "",
          "Customer price": t.customerPrice ?? "",
        }))
      )
    );
    toast.success(
      `Exported ${rows.reduce((s, p) => s + p.targets.length, 0)} lanes`
    );
  };

  const cell = (p: RecurringProgram, key: string): React.ReactNode => {
    const live = liveTargets(p);
    const waiting = waitingTargets(p);
    const money = programMoney(p);

    switch (key) {
      case "programNo":
        return (
          <div className="flex min-w-0 items-start gap-2">
            <Network className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
            <div className="flex min-w-0 flex-col leading-tight">
              <span className="truncate text-sm tabular-nums text-foreground">
                {p.programNo}
              </span>
              <span className="truncate text-xs text-muted-foreground">
                {DATE_FMT.format(new Date(p.createdAt))}
              </span>
            </div>
          </div>
        );
      case "schedule":
        return <ScheduleCell schedule={p.schedule} roomy />;
      case "product":
        /* SEVERAL PRODUCTS: the first, and +N for the rest on hover — the
           idiom every list here uses. */
        return <OverflowList values={p.products} label="products" />;
      case "status":
        return (
          <StatusChip tone={SERIES_TONE[p.status]} variant="soft">
            {p.status}
          </StatusChip>
        );
      case "vendor":
        return (
          <span className="truncate text-sm text-foreground">
            {programPartnerLabel(p)}
          </span>
        );
      case "loadOrder":
        return (
          <span
            className={cn(
              "text-sm",
              p.loadOrder ? "text-foreground" : "text-muted-foreground"
            )}
          >
            {p.loadOrder ? "Yes" : "No"}
          </span>
        );
      case "terminal":
        return p.loadOrder ? (
          <span className="truncate text-sm text-foreground">
            {[...new Set(p.loadRows.map((l) => l.terminal))].join(" / ")}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground/70">
            Partner supplies
          </span>
        );
      case "account":
        return p.loadOrder ? (
          <span className="truncate text-sm text-foreground">
            {[...new Set(p.loadRows.map((l) => l.loadingAccount))].join(" / ")}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground/70">{DASH}</span>
        );
      case "sites":
        return (
          <span className="text-sm tabular-nums text-foreground">
            {p.targets.length}
          </span>
        );
      case "customers":
        return (
          <span className="text-sm tabular-nums text-foreground">
            {new Set(p.targets.map((t) => t.customer.title)).size}
          </span>
        );
      case "liveness":
        /* HOW MUCH OF THE BOOK IS ACTUALLY RUNNING. A programme is rarely all
           on or all off, and a bare count of sites hides the difference
           between twelve delivering and twelve waiting to be priced. */
        return (
          <div className="flex min-w-0 flex-col gap-0.5 leading-tight">
            <span className="text-sm tabular-nums text-foreground">
              {live.length} of {p.targets.length}
            </span>
            {waiting.length > 0 && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span className="cursor-default truncate text-xs text-muted-foreground">
                    {waiting.length} waiting on the partner
                  </span>
                </TooltipTrigger>
                <TooltipContent>
                  {waiting
                    .map((t) => `${t.shipTo} — ${t.serviceable ? t.state_ : "out of area"}`)
                    .join(" · ")}
                </TooltipContent>
              </Tooltip>
            )}
          </div>
        );
      case "cost":
        return money.cost > 0 ? (
          <span className="text-sm tabular-nums text-foreground">
            {MONEY(money.cost)}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground">Not priced</span>
        );
      case "revenue":
        return money.revenue > 0 ? (
          <span className="text-sm tabular-nums text-foreground">
            {MONEY(money.revenue)}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground">Not priced</span>
        );
      case "margin":
        return money.revenue > 0 ? (
          <span
            className={cn(
              "text-sm font-medium tabular-nums",
              money.margin < 0 ? "text-status-failed" : "text-foreground"
            )}
          >
            {MONEY(money.margin)}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground">{DASH}</span>
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <FuelOrdersViewBar
        {...savedViews}
        /* CREATE RULE, NOT CREATE ORDER — and it opens HERE rather than
           sending the reader to the delivery-order form. V1 and V2 make a
           recurring order by ticking a box on an order, so their CTA goes
           there; a programme is its own record with its own two-step form,
           so it has its own act. */
        ctaLabel="Create Rule"
        onCreateOrder={() => {
          setSeed(null);
          setCreating(true);
        }}
        onExport={() => setExporting(true)}
      />

      <div className="mt-4 shrink-0">
        <ListToolbar
          viewToolsInto={bar.into}
          viewStatement={<ViewStatement count={total} one="program" many="programs" />}
          /* RECOMMENDATIONS ON THE LIST TOO (Pavan, 2026-10-06) — a rule's
             frequency and the ship-tos it fits, across customers; Review and
             Create Rule opens the form with both filled in. Next to the Filters button. */
          afterFilters={
            <RuleRecommendations
              buttonVariant="outline"
              applyLabel="Review and Create Rule"
              onApply={(r) => {
                setSeed({
                  frequency: r.frequency,
                  products: [r.product],
                  vendorIds: recommendedVendors(r).map((v) => v.id),
                  loadOrder: r.loadOrder,
                  loadingAccounts: r.loadingAccounts,
                  targets: r.targets.map((t) => ({
                    customer: { title: t.customer.name, description: t.customer.erpId },
                    shipTo: t.shipTo,
                  })),
                });
                setCreating(true);
              }}
            />
          }
          searchValue={search}
          onSearchChange={setSearch}
          searchPlaceholder="Search programs, partners, products, sites…"
          filters={
            <ListFilters
              facets={PROGRAM_FACETS.map((f) => ({
                key: f.key,
                label: f.label,
                options: f.options,
                searchable: f.searchable,
              }))}
              value={applied}
              onApply={setApplied}
              countFor={(sel) => narrow(sel).length}
            />
          }
          showGroupBy={false}
          boardView={false}
          columns={ALL_COLS.map((c) => ({ key: c.key, label: c.label }))}
          /* The column menu reorders too (Pavan, 2026-10-07). */
          columnOrder={colOrder}
          onReorderColumns={setColOrder}
          hiddenColumns={hidden as Set<string>}
          onToggleColumn={(k) =>
            setHidden((prev) => {
              const next = new Set(prev);
              if (next.has(k)) next.delete(k);
              else next.add(k);
              return next;
            })
          }
          onShowAllColumns={() => setHidden(new Set())}
          searchFields={PROGRAM_SEARCH_FIELDS.map((f) => ({
            key: f.key,
            label: f.label,
          }))}
          colScope={colScope}
          onColScopeChange={setColScope}
          colQuery={colQuery}
          onColQueryChange={setColQuery}
          columnFiltersOpen={view === "table" && colFiltersOpen}
          onToggleColumnFilters={
            view === "table"
              ? () =>
                  setColFiltersOpen((open) => {
                    /* CLOSING THE ROW PUTS THE TABLE BACK — boxes that are
                       gone must not go on narrowing. */
                    if (open) setColFilters({});
                    return !open;
                  })
              : undefined
          }
          columnFilterCount={activeColFilters.length}
          view={view}
          onViewChange={setView}
        />

        <FilterChips
          facets={PROGRAM_FACETS.map((f) => ({ key: f.key, label: f.label }))}
          selected={applied}
          onChange={setApplied}
        >
          <ColumnSearchChip
            searchFields={PROGRAM_SEARCH_FIELDS.map((f) => ({
              key: f.key,
              label: f.label,
            }))}
            colScope={colScope}
            colQuery={colQuery}
            onClear={() => setColQuery("")}
          />
        </FilterChips>
      </div>

      <div className="relative mt-4 min-h-0 flex-1">
        {/* THE ROW STAYS WHEN NOTHING MATCHES. Swapping the table for an
            empty state would take away the very boxes the reader has to
            change to get the rows back. */}
        {rows.length === 0 && !colFiltersOpen ? (
          <Empty className="h-full">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                {filtered ? <SearchX /> : <Network />}
              </EmptyMedia>
              <EmptyTitle>
                {filtered ? "No programs match" : "No programs yet"}
              </EmptyTitle>
              <EmptyDescription>
                {filtered
                  ? "Nothing found. Check the spelling, or clear the filters above."
                  : "A program starts with a partner — pick one, and the sites they can reach become the book you build from."}
              </EmptyDescription>
            </EmptyHeader>
            {filtered && (
              <Button variant="outline" size="sm" onClick={clearAll}>
                Clear search and filters
              </Button>
            )}
          </Empty>
        ) : (
          <div className="flex h-full flex-col overflow-hidden rounded-md border border-border">
            <div className="shrink-0 border-b border-fp-outline-1 bg-fp-surface-1b">{bar.slot}</div>
            <div className="min-h-0 flex-1 overflow-auto [&_[data-slot=table-container]]:overflow-visible">
            {/* Separated borders — see `docs/ds/ui/2-rules.md` §10d. */}
            <Table
              style={{ tableLayout: "fixed" }}
              className="border-separate border-spacing-0"
            >
              <colgroup>
                {visibleCols.map((c) => (
                  <col key={c.key} style={{ width: `${cols.widthOf(c)}px` }} />
                ))}
              </colgroup>
              <TableHeader className="bg-fp-table-header">
                <TableRow className="h-10 bg-fp-table-header hover:bg-transparent">
                  {visibleCols.map((c) => {
                    const active = sort?.key === c.key;
                    const SortIcon = !active
                      ? ChevronsUpDown
                      : sort?.dir === "asc"
                        ? ArrowUp
                        : ArrowDown;
                    return (
                      <TableColumnHeader
                        key={c.key}
                        cols={cols}
                        col={c}
                        aria-sort={
                          active
                            ? sort?.dir === "asc"
                              ? "ascending"
                              : "descending"
                            : undefined
                        }
                        className={cn(
                          "sticky top-0 z-20 whitespace-nowrap border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                          c.align === "right" && "text-right"
                        )}
                      >
                        <button
                          type="button"
                          onClick={() => onSort(c.key)}
                          aria-label={`Sort by ${c.label}`}
                          className={cn(
                            "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                            active && "text-foreground"
                          )}
                        >
                          {c.label}
                          <SortIcon
                            className={cn(
                              "size-3.5",
                              active ? "opacity-100" : "opacity-70"
                            )}
                          />
                        </button>
                      </TableColumnHeader>
                    );
                  })}
                </TableRow>
                {colFiltersOpen && (
                  /* THE SECOND HEADER ROW — the same band ListTable draws. */
                  <TableRow className="h-11 hover:bg-transparent">
                    {visibleCols.map((c) => (
                      <TableHead
                        key={c.key}
                        className="sticky top-10 z-20 border-b border-fp-outline-1 bg-fp-surface-1b px-2"
                      >
                        <Input
                          value={colFilters[c.key] ?? ""}
                          onChange={(e) =>
                            setColFilters((prev) => ({
                              ...prev,
                              [c.key]: e.target.value,
                            }))
                          }
                          placeholder={cols.widthOf(c) >= 96 ? "Filter…" : ""}
                          aria-label={`Filter by ${c.label}`}
                          className="h-7 rounded-md px-2.5 text-xs shadow-none"
                        />
                      </TableHead>
                    ))}
                  </TableRow>
                )}
              </TableHeader>
              <TableBody>
                {pageRows.map((p) => (
                  <TableRow
                    key={p.id}
                    className="group/row h-16 cursor-pointer [&>td]:border-b [&>td]:border-fp-outline-1"
                    onClick={(e) => {
                      const t = e.target as HTMLElement | null;
                      if (t?.closest("button,a,input,label")) return;
                      if (window.getSelection()?.toString()) return;
                      setOpenId(p.id);
                    }}
                  >
                    {visibleCols.map((c) => (
                      <TableCell
                        key={c.key}
                        className={cn("px-3", c.align === "right" && "text-right")}
                      >
                        {cell(p, c.key)}
                      </TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
          </div>
        )}
      </div>

      <div className="mt-4 flex shrink-0 flex-wrap items-center justify-between gap-3">
        <span className="flex items-center gap-2 text-sm text-muted-foreground">
          <Pill className="tabular-nums">
            {rows.reduce((s, p) => s + liveTargets(p).length, 0)} live lanes
          </Pill>
          across {rows.length} {rows.length === 1 ? "program" : "programs"}
          {/* THE ARCHIVE IS TUCKED AWAY ON PURPOSE (Pavan, 2026-09-23). V1
              and V2 are kept to refer back to until they are kept or deleted
              for good — so the way in is the quietest thing on the screen,
              not a place in the navigation. */}
          {onOpenArchive && (
            <button
              type="button"
              onClick={onOpenArchive}
              className="ml-2 flex items-center gap-1 rounded-sm text-xs text-muted-foreground/60 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <Archive className="size-3" />
              Archive
            </button>
          )}
        </span>
        <TablePagination
          page={safePage}
          pageSize={pageSize}
          total={total}
          onPageChange={setPage}
          onPageSizeChange={(n) => {
            setPageSize(n);
            setPage(1);
          }}
        />
      </div>

      <ExportSheet
        open={exporting}
        onOpenChange={setExporting}
        title="Export Programs"
        noun="programs"
        nounOne="program"
        count={rows.length}
        filtersControl={
          <ListFilters
            facets={PROGRAM_FACETS.map((f) => ({
              key: f.key,
              label: f.label,
              options: f.options,
              searchable: f.searchable,
            }))}
            value={applied}
            onApply={setApplied}
            countFor={(sel) => narrow(sel).length}
            fullWidth
          />
        }
        filters={exportFilters}
        onExport={(format) => {
          setExporting(false);
          if (format === "csv") exportCsv();
          else
            toast.success(
              `Exporting ${rows.length} ${rows.length === 1 ? "program" : "programs"} as .${format}`
            );
        }}
      />

      <RecurringProgramCreate
        open={creating || editing !== null}
        onOpenChange={(v) => {
          if (v) return;
          setCreating(false);
          setEditingId(null);
          setSeed(null);
        }}
        /* A rule never clashes with itself. */
        all={editing ? programs.filter((p) => p.id !== editing.id) : programs}
        initial={editingDraft}
        seed={editing ? null : seed}
        onCreate={(d: ProgramDraft) => {
          const schedule = toSchedule(d.frequency);
          const partners = d.vendorIds
            .map((id) => VENDORS.find((v) => v.id === id)?.name)
            .filter(Boolean);
          const next: RecurringProgram = {
            id: `prog-new-${Date.now()}`,
            programNo: d.name.trim() || `P-${2140 + programs.length * 7}`,
            createdAt: new Date().toISOString(),
            vendorIds: d.vendorIds,
            jobType: d.jobType,
            loadOrder: d.loadOrder,
            /* A row per account; the stored rule keeps the account's
               products that are on the rule, and all its terminals and
               suppliers. */
            loadRows: d.loadOrder
              ? d.loadRows.flatMap((r) => {
                  const a = LOADING_ACCOUNTS.find((x) => x.name === r.loadingAccount);
                  return a
                    ? [
                        {
                          products: a.products.filter((p) => d.products.includes(p)),
                          terminal: terminalsOf(a).join(" / "),
                          supplier: suppliersOf(a).join(" / "),
                          loadingAccount: a.name,
                        },
                      ]
                    : [];
                })
              : [],
            products: d.products,
            winterProducts: d.winterProducts,
            /* Under "All" the program takes its first product's line. */
            serviceLine: lineOfProduct(d.products[0] ?? ""),
            business: LINE_BUSINESSES[lineOfProduct(d.products[0] ?? "")][0] ?? null,
            orderType: "Core",
            signatureOnDelivery: d.signatureOnDelivery,
            schedule,
            frequency: d.frequency,
            startKey: d.startKey,
            endKey: d.frequency.endKey,
            tags: [],
            internalNote: "",
            /* EVERY LANE STARTS AS A DRAFT. Creating the rule does not start
               a truck — the partner has to price and accept each lane, and
               the sheet lists them all under Waiting until they do. */
            targets: d.targets,
            status:
              d.startKey > dateKeyOf(startOfDay(new Date()))
                ? "Upcoming"
                : "Active",
          };
          /* "STOP THE OTHER RULE HERE" — written onto those rules' ship-tos
             now that this rule exists. They keep running everywhere else. */
          const asks = d.targets.flatMap((t) =>
            (t.othersSkip ?? []).map((o) => ({ ...o, shipTo: t.shipTo }))
          );
          next.targets = next.targets.map((t) => ({ ...t, othersSkip: undefined }));
          if (asks.length)
            setPrograms((prev) =>
              prev.map((p) => {
                const mine = asks.filter((a) => a.programId === p.id);
                if (!mine.length) return p;
                return {
                  ...p,
                  targets: p.targets.map((t) => {
                    const a = mine.find((x) => x.shipTo === t.shipTo);
                    if (!a) return t;
                    return {
                      ...t,
                      skip: {
                        weekdays: [...new Set([...(t.skip?.weekdays ?? []), ...a.weekdays])],
                        monthDays: [...new Set([...(t.skip?.monthDays ?? []), ...a.monthDays])],
                      },
                    };
                  }),
                };
              })
            );
          if (editing) {
            /* SAVING REPLACES THE RULE IN PLACE — same record, same row. */
            const saved: RecurringProgram = {
              ...next,
              id: editing.id,
              createdAt: editing.createdAt,
              serviceLine: editing.serviceLine,
              business: editing.business,
              orderType: editing.orderType,
              tags: editing.tags,
              internalNote: editing.internalNote,
            };
            setPrograms((prev) => prev.map((p) => (p.id === saved.id ? saved : p)));
            setEditingId(null);
            setOpenId(saved.id);
            toast.success(`${saved.programNo} saved`);
            return;
          }
          setPrograms((prev) => [next, ...prev]);
          setOpenId(next.id);
          toast.success(`${next.programNo} created`, {
            description: `${d.targets.length} draft ${d.targets.length === 1 ? "lane" : "lanes"} waiting on ${partners.join(", ") || "the partner"} to price.`,
          });
        }}
      />

      <RecurringProgramSheet
        program={openProgram}
        all={programs}
        open={openProgram !== null}
        onOpenChange={(v) => !v && setOpenId(null)}
        onChange={(next) =>
          setPrograms((prev) => prev.map((p) => (p.id === next.id ? next : p)))
        }
        onEdit={(p) => {
          setOpenId(null);
          setEditingId(p.id);
        }}
      />
    </div>
  );
}

import * as React from "react";
import { ChevronLeft, ChevronRight, Info } from "lucide-react";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Pill } from "@/components/ui/pill";
import { Button } from "@/components/ui/button";
import { StatusChip } from "@/components/ui/status-chip";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { CELL, RecordSheet } from "../RecordSheet";
import { DATE_FMT, MONEY, dateKeyOf, startOfDay } from "../data";
import { BROKER_STATUS_TONE } from "./orders";
import { VENDORS } from "./vendors";
import {
  editDelivery,
  monthGrid,
  ruleGallons,
  ruleSentence,
  type DeliveryPatch,
  type DeliveryState,
  type RecurringRule,
  type RuleDelivery,
} from "./recurringRules";
import { RecurringDeliverySheet } from "./RecurringDeliverySheet";
import { SERIES_STATUS_MEANING, type SeriesStatus } from "./recurring";
import { statusTones } from "../statusKind";

/*
  THE RULE SHEET — V1's record, opened from the Recurring Orders list.

  THE CALENDAR IS THE FIRST CARD, and that ordering is the argument. A rule is a
  claim about DATES, and every question anyone brings to one is a date question:
  when is the next drop, did last Thursday go out, why is there nothing in the
  first week of November. A stack of field cards answers none of those; a month
  grid answers all three at a glance.

  FOUR STATES, AND THE FOURTH IS THE POINT.

    Delivered   it ran. Carries its order number and where the money got to.
    Created     an order exists and the work is ahead of us.
    Scheduled   THE RULE WANTS THIS DATE AND NOBODY HAS CUT AN ORDER FOR IT.
    Skipped     the rule wanted it; something stopped it.

  Only a rule can draw `scheduled`. In the parent/child model a date with no
  order behind it does not exist anywhere — the calendar would simply end a
  month out, and a broker asking "does this run through December" would have no
  way to find out but arithmetic. That is the clearest single thing this sheet
  shows that V2 cannot.

  TWEAKED IS A LABEL, NOT A STATE. A delivery can be created AND edited, or
  delivered AND edited. It is orthogonal, so it renders as a badge on the cell
  rather than as a fifth colour — and it is worth showing at all because a
  delivery that no longer matches the rule that made it is exactly the thing
  somebody is about to be surprised by.

  NO SAVE, NO CANCEL. Side sheets autosave, creating or editing, everywhere in
  this app.
*/

const WEEKDAY_HEADS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

const MONTH_FMT = new Intl.DateTimeFormat("en-US", {
  month: "long",
  year: "numeric",
});



const DASH = "—";

/** Four tones, four states — and unlike the series words, these map cleanly. */
const STATE_TONE = statusTones<DeliveryState>({
  delivered: "success",
  /* The order exists and is on its way through. */
  created: "info",
  /* "Not created yet" — a date on a plan, not yet a state. */
  scheduled: "neutral",
  /* Skipped by decision. An absence, not a fault. */
  skipped: "neutral",
});

const STATE_LABEL: Record<DeliveryState, string> = {
  delivered: "Delivered",
  created: "Order created",
  scheduled: "Not created yet",
  skipped: "Skipped",
};

const SERIES_TONE = statusTones<SeriesStatus>({
  /* Set up, not yet running. True, and asks nothing. */
  Upcoming: "info",
  /* Running. Asks nothing — a series being live is not an achievement. */
  Active: "info",
  /* Waiting on somebody to resume it. NOT red: pausing is a decision. */
  Paused: "caution",
  Canceled: "neutral",
  Ended: "neutral",
  Expired: "neutral",
});

/**
 * The seam between what has run and what is coming — four behind, eight ahead.
 * A rule holds a year of dates, so both "oldest first" and "newest first" open
 * on a screenful of rows where nothing has happened.
 */
function aroundToday(
  deliveries: RuleDelivery[],
  todayKey: string
): RuleDelivery[] {
  const i = deliveries.findIndex((d) => d.dateKey >= todayKey);
  const at = i === -1 ? deliveries.length : i;
  return deliveries.slice(Math.max(0, at - 4), at + 8);
}

/* ---------------------------------------------------------------------------
 * Card chrome — shared by every card in the sheet
 * ------------------------------------------------------------------------ */

function Card({
  title,
  aside,
  flush,
  children,
}: {
  title: string;
  aside?: React.ReactNode;
  /**
   * DROPS THE BODY'S PADDING so the content runs to the card's own edges.
   *
   * For content that is ITSELF a bordered grid — the calendar. Nesting one
   * bordered box 16px inside another draws two lines to say one thing, and the
   * gap between them belongs to neither: the card's edge is already the
   * calendar's edge, so the calendar should use it.
   */
  flush?: boolean;
  children: React.ReactNode;
}) {
  /*
    SHRINK-0, AND IT IS NOT COSMETIC. The sheet body is a flex column, so a card
    with no explicit basis is free to be squeezed below its content height. It
    used to overflow visibly and read as correct; the moment `overflow-hidden`
    arrived — needed so the flush calendar clips to the card's rounded corners —
    the squeeze started clipping instead, and four cards rendered as headers
    with nothing under them.
  */
  return (
    <section className="shrink-0 overflow-hidden rounded-md border border-fp-outline-1">
      <header className="flex items-center justify-between gap-3 border-b border-fp-outline-1 px-4 py-3">
        <h3 className="text-sm font-medium text-foreground">{title}</h3>
        {aside}
      </header>
      <div className={flush ? undefined : "p-4"}>{children}</div>
    </section>
  );
}

function Field({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-1">
      <dt className="text-xs font-medium text-muted-foreground">{label}</dt>
      <dd className="text-sm text-foreground">{children}</dd>
    </div>
  );
}

function Fields({ children }: { children: React.ReactNode }) {
  return <dl className="grid grid-cols-3 gap-x-6 gap-y-4">{children}</dl>;
}

/* ---------------------------------------------------------------------------
 * The calendar
 * ------------------------------------------------------------------------ */

function DayCell({
  day,
  inMonth,
  isToday,
  delivery,
  onOpen,
}: {
  day: number;
  inMonth: boolean;
  isToday: boolean;
  delivery: RuleDelivery | null;
  onOpen?: () => void;
}) {
  /* A CELL WITH A DELIVERY IS A CONTROL; an empty one is not. The whole grid
     being clickable would promise a sheet behind every square, and five of
     seven squares in a week have nothing to open. */
  const pressable = Boolean(delivery && inMonth && onOpen);

  const body = (
    <div
      className={cn(
        "flex h-[92px] min-w-0 flex-col gap-1 border-b border-r border-fp-outline-1 p-2 text-left",
        !inMonth && "bg-fp-surface-1b/40",
        delivery && inMonth && "bg-fp-surface-1b",
        pressable && "transition-colors hover:bg-fp-row-hover"
      )}
    >
      <div className="flex items-center justify-between gap-1">
        <span
          className={cn(
            "flex size-5 items-center justify-center rounded-full text-xs tabular-nums",
            inMonth ? "text-foreground" : "text-muted-foreground/50",
            /* TODAY IS A RING, NOT A FILL. A filled day competes with the
               delivery states for the same square inch, and the question
               "what is on this date" beats "which date is it". */
            isToday && "bg-primary text-primary-foreground"
          )}
        >
          {day}
        </span>
        {delivery && inMonth && (
          <span
            aria-hidden
            className={cn(
              "size-1.5 rounded-full",
              delivery.state === "delivered" && "bg-status-success",
              delivery.state === "created" && "bg-status-processing",
              delivery.state === "scheduled" && "bg-muted-foreground",
              delivery.state === "skipped" && "bg-status-failed"
            )}
          />
        )}
      </div>

      {delivery && inMonth && (
        <div className="flex min-w-0 flex-col gap-0.5 leading-tight">
          {/* THE ORDER NUMBER IS THE CELL'S CONTENT. It is what a broker reads
              a date to find — the thing they will paste into a search box or
              read down a phone.

              A DATE WITH NO NUMBER GETS ONE LINE, NOT TWO. "Not created yet"
              IS the whole answer for that cell, and printing it as both the
              number and the state said the same thing twice in a 92px box. */}
          {delivery.orderNo ? (
            <>
              <span className="truncate text-xs tabular-nums text-foreground">
                {delivery.orderNo}
              </span>
              <span className="truncate text-[11px] text-muted-foreground">
                {STATE_LABEL[delivery.state]}
              </span>
            </>
          ) : (
            <span className="truncate text-xs text-muted-foreground">
              {STATE_LABEL[delivery.state]}
            </span>
          )}
          {delivery.tweak && (
            <Badge
              variant="secondary"
              className="mt-0.5 h-4 w-fit px-1 text-[10px] font-normal"
            >
              Tweaked
            </Badge>
          )}
        </div>
      )}
    </div>
  );

  const shell = pressable ? (
    <button
      type="button"
      onClick={onOpen}
      aria-label={
        delivery?.orderNo
          ? `Open order ${delivery.orderNo}`
          : `Open the delivery scheduled for day ${day}`
      }
      className="block w-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      {body}
    </button>
  ) : (
    body
  );

  /* The tweak's DETAIL lives on hover. The cell has room for the fact that
     something changed, not for what; and "what" is a sentence, not a chip. */
  if (delivery?.tweak && inMonth) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <div className={cn(!pressable && "cursor-default")}>{shell}</div>
        </TooltipTrigger>
        <TooltipContent>{delivery.tweak}</TooltipContent>
      </Tooltip>
    );
  }
  return shell;
}

function CalendarCard({
  rule,
  onOpenDelivery,
}: {
  rule: RecurringRule;
  onOpenDelivery: (dateKey: string) => void;
}) {
  const today = React.useMemo(() => startOfDay(new Date()), []);
  const todayKey = dateKeyOf(today);

  /* Opens on the month the next delivery is in — which is the month somebody
     opening a rule is nearly always asking about. */
  const firstNext = rule.nextKey ?? rule.deliveries[0]?.dateKey ?? todayKey;
  const [cursor, setCursor] = React.useState(() => {
    const [y, m] = firstNext.split("-").map(Number);
    return { year: y, month: m - 1 };
  });

  const cells = React.useMemo(
    () => monthGrid(rule, cursor.year, cursor.month),
    [rule, cursor]
  );

  const step = (n: number) =>
    setCursor((c) => {
      const d = new Date(c.year, c.month + n, 1);
      return { year: d.getFullYear(), month: d.getMonth() };
    });

  const inMonth = cells.filter((c) => c.inMonth && c.delivery);
  const created = inMonth.filter((c) => c.delivery?.orderNo).length;

  return (
    <Card
      title="Schedule"
      flush
      aside={
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Previous month"
            onClick={() => step(-1)}
          >
            <ChevronLeft />
          </Button>
          <span className="min-w-[128px] text-center text-sm font-medium tabular-nums text-foreground">
            {MONTH_FMT.format(new Date(cursor.year, cursor.month, 1))}
          </span>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Next month"
            onClick={() => step(1)}
          >
            <ChevronRight />
          </Button>
        </div>
      }
    >
      {/* THE CARD'S BORDER IS THE CALENDAR'S BORDER. The grid used to sit in a
          second bordered box inset 16px inside this one — two lines saying one
          thing, with a strip of nothing between them. The cells keep their own
          right and bottom hairlines; the Saturday column drops its right one so
          it does not double the card's edge, and the last row's bottom hairline
          becomes the rule above the legend. */}
      <div className="grid grid-cols-7 [&>*:nth-child(7n)]:border-r-0">
          {WEEKDAY_HEADS.map((w) => (
            <div
              key={w}
              className="border-b border-r border-fp-outline-1 bg-fp-table-header px-2 py-1.5 text-xs font-medium text-muted-foreground"
            >
              {w}
            </div>
          ))}
          {cells.map((c) => (
            <DayCell
              key={c.dateKey}
              day={c.date.getDate()}
              inMonth={c.inMonth}
              isToday={c.dateKey === todayKey}
              delivery={c.delivery}
              onOpen={() => onOpenDelivery(c.dateKey)}
            />
          ))}
      </div>

      {/* THE LEGEND SAYS WHAT THE COLOURS MEAN AND THE LINE UNDER IT SAYS WHAT
          THE MONTH ADDS UP TO. Four dots with no count is a key to a chart
          nobody has read yet. It carries the padding the card body gave up. */}
      <div className="flex flex-wrap items-center gap-x-5 gap-y-2 px-4 pt-3">
        {(
          ["delivered", "created", "scheduled", "skipped"] as DeliveryState[]
        ).map((s) => (
          <span
            key={s}
            className="flex items-center gap-1.5 text-xs text-muted-foreground"
          >
            <span
              aria-hidden
              className={cn(
                "size-1.5 rounded-full",
                s === "delivered" && "bg-status-success",
                s === "created" && "bg-status-processing",
                s === "scheduled" && "bg-muted-foreground",
                s === "skipped" && "bg-status-failed"
              )}
            />
            {STATE_LABEL[s]}
          </span>
        ))}
      </div>
      <p className="px-4 pb-4 pt-2 text-xs text-muted-foreground">
        {inMonth.length} {inMonth.length === 1 ? "delivery" : "deliveries"} this
        month · {created} with an order cut
      </p>
    </Card>
  );
}

