/*
  RECURRING ORDERS — V1, the rule-based list.

  ONE ROW PER RULE, AND A RULE IS NOT AN ORDER. There is no order number in the
  identity column and no parent to expand: the row IS the standing arrangement,
  and its deliveries live in the sheet's calendar rather than nested under it.
  That is the whole difference from V2, and it is why this list can carry the
  commercial terms — partner, load-order responsibility, both sides of the
  price — where V2's row had to spend its width on an order's own fields.

  SEVENTEEN COLUMNS, FLAT AND ALL EQUAL. They were grouped under Rule /
  Customer details / Delivery details / Vendor details / Pricing, which read
  well and cost the reader everything else: a column could only move inside
  its own group, the header was two rows tall on every screen, and the groups
  asserted a relationship the reader is not obliged to accept. Flat, every
  column sorts, resizes and goes anywhere — which is what `useTableColumns`
  gives for free, and could not while the header had two tiers.

  THE TABLE IS WIDE AND SCROLLS SIDEWAYS. That is the honest consequence of
  putting the terms on the row; the answer is the column menu and the reader's
  own ordering, not a second header row.

  THE LOAD-ORDER COLUMNS ARE EMPTY FOR HALF THE ROWS on purpose. Terminal,
  supplier and loading account only mean something when we buy the product; on
  a partner-supplied rule there is no value to show, and inventing one would be
  worse than the em-dash.
*/



const DASH = "—";

const SERIES_TONE = statusTones<SeriesStatus>({
  /* Set up, not yet running. True, and asks nothing. */
  Upcoming: "info",
  /* Running. Asks nothing — a series being live is not an achievement. */
  Active: "info",
  /* Waiting on somebody to resume it. NOT red: pausing is a decision. */
  Paused: "caution",
  Canceled: "neutral",
  Ended: "neutral",
  Expired: "neutral",
});

interface Col {
  key: string;
  label: string;
  width: number;
  align?: "right";
  /** What it sorts BY. Omit and the column does not sort. */
  sort?: (r: RecurringRule) => string | number;
}

/**
 * THE COLUMNS, FLAT.
 *
 * They were grouped under Rule / Customer details / Delivery details / Vendor
 * details / Pricing, which read well on a 2,400px table and cost the reader
 * everything else: a column could only move inside its own group, the header
 * was two rows tall on every screen, and the groups claimed a relationship
 * between columns that the reader is not obliged to accept. Flat, every column
 * is a peer — it sorts, it resizes, and it goes anywhere.
 *
 * WIDTHS STILL MATCH `BROKER_COLUMNS` wherever the same fact appears on the
 * orders table. Losing the groups does not licence losing that.
 */
const COLUMNS: Col[] = [
  {
    key: "ruleNo",
    label: "Rule # / Created",
    width: 170,
    sort: (r) => r.ruleNo,
  },
  { key: "schedule", label: "Schedule", width: 270, sort: (r) => r.schedule.label },
  {
    key: "next",
    label: "Next Delivery",
    /* A NULL NEXT DATE SORTS LAST, not first. A rule with nothing coming is
       not the most imminent thing on the list. */
    width: 150,
    sort: (r) => r.nextKey ?? "9999",
  },
  { key: "status", label: "Status", width: 190, sort: (r) => r.status },
  { key: "customer", label: "Customer", width: 230, sort: (r) => r.customer.title },
  { key: "shipTo", label: "Ship To", width: 170, sort: (r) => r.shipTo },
  {
    key: "assets",
    label: "Assets",
    width: 170,
    sort: (r) => r.assets[0] ?? "",
  },
  {
    key: "products",
    label: "Products",
    width: 230,
    sort: (r) => r.lines[0]?.product ?? "",
  },
  {
    key: "qty",
    label: "Qty (Gal)",
    width: 110,
    sort: (r) => ruleGallons(r),
  },
  {
    key: "vendor",
    label: "Partner",
    width: 190,
    sort: (r) => VENDORS.find((v) => v.id === r.vendorId)?.name ?? "",
  },
  { key: "poc", label: "POC", width: 170, sort: (r) => r.vendorPoc ?? "" },
  {
    key: "loadOrder",
    label: "Load Order",
    width: 110,
    sort: (r) => (r.loadOrder?.length ? "Yes" : "No"),
  },
  {
    key: "terminal",
    label: "Terminal",
    width: 160,
    sort: (r) => r.loadOrder?.[0]?.terminal ?? "",
  },
  {
    key: "supplier",
    label: "Supplier",
    width: 160,
    sort: (r) => r.loadOrder?.[0]?.supplier ?? "",
  },
  {
    key: "account",
    label: "Loading Account",
    width: 170,
    sort: (r) => r.loadOrder?.[0]?.loadingAccount ?? "",
  },
  {
    key: "vendorPrice",
    /* THE PRICING PAIR HAS TO NAME ITSELF NOW. Under a "Pricing" heading
       "Vendor" and "Customer" were unambiguous; flat, "Customer" already
       means the customer's NAME three columns to the left. A group heading
       that was carrying meaning has to hand it back to the labels. */
    label: "Vendor Price",
    width: 130,
    /* NOT PRICED SORTS LAST on a money column, for the same reason a missing
       date does: an absent number is not the smallest one. */
    sort: (r) => r.vendorPrice ?? Number.MAX_SAFE_INTEGER,
  },
  {
    key: "customerPrice",
    label: "Customer Price",
    width: 140,
    sort: (r) => r.customerPrice ?? Number.MAX_SAFE_INTEGER,
  },
];

const ALL_COLS: Col[] = COLUMNS;
const COL_KEYS: string[] = COLUMNS.map((c) => c.key);

/**
 * WHAT THE LIST CAN BE NARROWED BY. Three, and each one is a question somebody
 * actually walks up to this screen with: which of these are running, who hauls
 * them, and how often. Every other column is findable through the column
 * search rather than through a facet — a panel with fifteen sections is a
 * panel nobody opens twice.
 */
const RULE_FACETS: {
  key: string;
  label: string;
  options: string[];
  valueOf: (r: RecurringRule) => string;
  searchable?: boolean;
}[] = [
  /* LINE OF SERVICE AND BUSINESS ARE FILTERS (Pavan, 2026-10-21) — not a
     segment and preset tabs above the list. */
  {
    key: "serviceLine",
    label: "Line of Service",
    options: [...SERVICE_LINES],
    valueOf: (r) => r.serviceLine,
  },
  {
    key: "business",
    label: "Business",
    options: businessesOf("All"),
    valueOf: (r) => r.business ?? "",
  },
  {
    key: "status",
    label: "Status",
    options: SERIES_STATUSES,
    valueOf: (r) => r.status,
  },
  {
    key: "partner",
    label: "Partner",
    options: [...new Set(VENDORS.map((v) => v.name))].sort(),
    valueOf: (r) => VENDORS.find((v) => v.id === r.vendorId)?.name ?? "",
    searchable: true,
  },
  {
    key: "frequency",
    label: "Frequency",
    options: [...new Set(RECURRING_RULES.map((r) => r.schedule.label))].sort(),
    valueOf: (r) => r.schedule.label,
  },
];

/**
 * THE ONE SPLIT WORTH A CONTROL RATHER THAN A FACET.
 *
 * Who runs the work is the question a reader flips between several times a
 * session — the brokerage book and the own-fleet book are two different jobs
 * with two different people worrying about them. A facet you open, tick and
 * close is the wrong amount of work for something changed that often.
 *
 * THREE SEGMENTS, EXHAUSTIVE AND SHORT, which is the bar for putting a split
 * here at all. Everything else stays in the panel.
 */
const OPERATIONS = [
  { key: "all", label: "All" },
  { key: "first", label: "First party operations" },
  { key: "third", label: "Third party operations" },
] as const;

type Operations = (typeof OPERATIONS)[number]["key"];

/** The columns the column-search row can ask a question OF. */
const RULE_SEARCH_FIELDS: {
  key: string;
  label: string;
  text: (r: RecurringRule) => string;
}[] = [
  { key: "ruleNo", label: "Rule #", text: (r) => r.ruleNo },
  {
    key: "customer",
    label: "Customer",
    text: (r) => `${r.customer.title} ${r.customer.description}`,
  },
  { key: "shipTo", label: "Ship To", text: (r) => r.shipTo },
  { key: "schedule", label: "Schedule", text: (r) => r.schedule.label },
  {
    key: "products",
    label: "Products",
    text: (r) => r.lines.map((l) => l.product).join(" "),
  },
  {
    key: "vendor",
    label: "Partner",
    text: (r) => VENDORS.find((v) => v.id === r.vendorId)?.name ?? "",
  },
  { key: "poc", label: "POC", text: (r) => r.vendorPoc ?? "" },
];

function vendorName(id: string | null): string | null {
  if (!id) return null;
  return VENDORS.find((v) => v.id === id)?.name ?? null;
}

/* WHAT A CELL PRINTS, as text — what the filter row's boxes match
   (Pavan, 2026-10-07), the same idea as Programs' `columnText`. */
function ruleColumnText(r: RecurringRule, key: string): string {
  const load = (pick: (l: NonNullable<RecurringRule["loadOrder"]>[number]) => string) =>
    [...new Set(r.loadOrder?.map(pick) ?? [])].join(" ");
  switch (key) {
    case "ruleNo":
      return `${r.ruleNo} ${DATE_FMT.format(new Date(r.createdAt))}`;
    case "schedule":
      return r.schedule.label;
    case "next":
      return r.nextKey ? DATE_FMT.format(new Date(`${r.nextKey}T00:00:00`)) : "";
    case "status":
      return `${r.status} ${r.stalledReason ?? ""}`;
    case "customer":
      return `${r.customer.title} ${r.customer.description}`;
    case "shipTo":
      return r.shipTo;
    case "assets":
      return r.assets.length > 0 ? r.assets.join(" ") : "Any";
    case "products":
      return r.lines.map((l) => l.product).join(" ");
    case "qty": {
      const gal = ruleGallons(r);
      return gal > 0 ? gal.toLocaleString() : "Top off";
    }
    case "vendor":
      return vendorName(r.vendorId) ?? "Not assigned";
    case "poc":
      return r.vendorPoc ?? "";
    case "loadOrder":
      return r.loadOrder?.length ? "Yes" : "No";
    case "terminal":
      return r.loadOrder?.length ? load((l) => l.terminal) : "Partner supplies";
    case "supplier":
      return load((l) => l.supplier);
    case "account":
      return load((l) => l.loadingAccount);
    case "vendorPrice":
      return r.vendorPrice !== null ? MONEY(r.vendorPrice) : "Not priced";
    case "customerPrice":
      return r.customerPrice !== null ? MONEY(r.customerPrice) : "Not priced";
    default:
      return "";
  }
}

/**
 * A load-order field, which is a LIST per product rather than one value. The
 * first is shown and the rest are counted, which is the same call the orders
 * table's Products cell makes — a cell that stacked four terminals would set
 * the row height for every row in the table.
 */
/* "+N" OPENS THE REST, on click — the shared chip and card (Pavan,
   2026-10-14: one way everywhere). */
function LoadField({ values, empty, label = "values" }: { values: string[]; empty: string; label?: string }) {
  const unique = [...new Set(values)];
  if (unique.length === 0)
    return <span className="text-sm text-muted-foreground/70">{empty}</span>;
  return (
    <span className="flex min-w-0 items-center gap-1.5">
      <span className="truncate text-sm text-foreground">{unique[0]}</span>
      {unique.length > 1 && (
        <OverflowChip
          count={unique.length - 1}
          label={`Show all ${unique.length} ${label}`}
          card={{ title: `All ${label} (${unique.length})`, rows: unique.map((v) => ({ label: v })) }}
        />
      )}
    </span>
  );
}

export function RecurringRulesScreen({
  onCreateRule,
}: {
  /**
   * THE CTA GOES WHERE CREATION ACTUALLY HAPPENS. A rule is not created on
   * this screen — it is created by ticking Recurring on a delivery order and
   * giving it a frequency, which is the flow that already exists. A second
   * create form here would be a second way to make the same record, and the
   * two would drift.
   */
  onCreateRule?: () => void;
} = {}) {
  const today = React.useMemo(() => startOfDay(new Date()), []);
  const todayKey = dateKeyOf(today);

  const [search, setSearch] = React.useState("");
  const [applied, setApplied] = React.useState<ReadonlySet<string>>(new Set());
  const [hidden, setHidden] = React.useState<ReadonlySet<string>>(new Set());
  const [view, setView] = React.useState<ListView>("table");
  const [colScope, setColScope] = React.useState(RULE_SEARCH_FIELDS[0].key);
  const [colQuery, setColQuery] = React.useState("");
  const [ops, setOps] = React.useState<Operations>("all");
  const [page, setPage] = React.useState(1);
  const [pageSize, setPageSize] = React.useState(25);
  /* THE SCOPE SHELF — the line, and the business inside it. Not a filter: a
     filter narrows the list you are looking at, and this says WHICH LIST. It
     is the same pair the orders board carries, in the same place. */
  /* THE RULES LIVE IN STATE, not straight off the fixture, because a delivery
     edited in the sheet has to survive closing it. The seed is the starting
     point and nothing writes back to it. */
  const [rules, setRules] = React.useState<RecurringRule[]>(RECURRING_RULES);
  const [openId, setOpenId] = React.useState<string | null>(null);

  /* ── THE COLUMNS ARE THE READER'S ──────────────────────────────────────
     `useTableColumns` is the DS's one call for all three behaviours — order,
     widths, and the guard that stops a resize press starting a drag. It was
     unusable while the header had two tiers, because a grouped column could
     only move inside its group and the hook knows nothing about groups.
     Flat, it is exactly the right thing and there is nothing to wire. */
  const [colOrder, setColOrder] = React.useState<string[]>(COL_KEYS);
  const [widths, setWidths] = React.useState<Record<string, number>>({});
  /* SEARCH BY COLUMN IS A ROW OF BOXES UNDER THE HEADER (Pavan, 2026-10-07)
     — the Delivery Orders behaviour, as Programs already has it. */
  const [colFilters, setColFilters] = React.useState<Record<string, string>>({});
  const [colFiltersOpen, setColFiltersOpen] = React.useState(false);
  const activeColFilters = React.useMemo(
    () => Object.entries(colFilters).filter(([, v]) => v.trim() !== ""),
    [colFilters]
  );
  const [exporting, setExporting] = React.useState(false);
  const [sort, setSort] = React.useState<{
    key: string;
    dir: "asc" | "desc";
  } | null>(null);

  const cols = useTableColumns({
    keys: COL_KEYS,
    order: colOrder,
    onOrderChange: setColOrder,
    widths,
    onWidthsChange: setWidths,
  });

  /* ASC → DESC → UNSORTED, the same three-press cycle every other table here
     uses. The third press matters: a reader who sorted by accident needs the
     way back to the list's own order. */
  const onSort = (key: string) =>
    setSort((prev) =>
      !prev || prev.key !== key
        ? { key, dir: "asc" }
        : prev.dir === "asc"
          ? { key, dir: "desc" }
          : null
    );

  const visibleCols = React.useMemo(
    () => cols.arrange(COLUMNS.filter((c) => !hidden.has(c.key))),
    [cols, hidden]
  );

  /* SAVED VIEWS remember everything the reader arranged and nothing the app
     decided — the narrowing, the sort, the column order, widths and what is
     hidden. Not the scope shelf: Default means "nothing applied". */
  type ViewState = {
    search: string;
    applied: string[];
    hidden: string[];
    colScope: string;
    colQuery: string;
    colOrder: string[];
    widths: Record<string, number>;
    sort: { key: string; dir: "asc" | "desc" } | null;
    /** Optional so a view saved before the filter row still applies. */
    colFilters?: Record<string, string>;
  };
  const savedViews = useSavedViews<ViewState>({
    current: {
      search,
      applied: [...applied],
      hidden: [...hidden],
      colScope,
      colQuery,
      colOrder,
      widths,
      sort,
      colFilters: Object.fromEntries(activeColFilters),
    },
    defaultState: {
      search: "",
      applied: [],
      hidden: [],
      colScope: RULE_SEARCH_FIELDS[0].key,
      colQuery: "",
      colOrder: COL_KEYS,
      widths: {},
      sort: null,
      colFilters: {},
    },
    keyOf: (v) =>
      JSON.stringify({
        ...v,
        applied: [...v.applied].sort(),
        hidden: [...v.hidden].sort(),
        colFilters: Object.fromEntries(
          Object.entries(v.colFilters ?? {})
            .filter(([, x]) => x.trim() !== "")
            .sort(([a], [b]) => a.localeCompare(b))
        ),
      }),
    apply: (v) => {
      setSearch(v.search);
      setApplied(new Set(v.applied));
      setHidden(new Set(v.hidden));
      setColScope(v.colScope);
      setColQuery(v.colQuery);
      setColOrder(v.colOrder);
      setWidths(v.widths);
      setSort(v.sort);
      setColFilters(v.colFilters ?? {});
      setColFiltersOpen(Object.values(v.colFilters ?? {}).some((x) => x.trim()));
      setPage(1);
    },
    /* REMEMBERED ACROSS VISITS (Pavan, 2026-10-09). */
    storageKey: "3pl-recurring-rules",
  });

  /* THREE NARROWINGS, AND-ED. Free text across the whole record, the facet
     panel, and a question asked OF one column — they answer different
     questions and a reader uses them together, so none of them replaces
     another. */
  const narrow = React.useCallback((sel: ReadonlySet<string>) => {
    const cq = colQuery.trim().toLowerCase();
    const field = RULE_SEARCH_FIELDS.find((f) => f.key === colScope);
    const byFacet = [...sel].reduce<Record<string, string[]>>((acc, id) => {
      const at = id.indexOf(":");
      const k = id.slice(0, at);
      (acc[k] ??= []).push(id.slice(at + 1));
      return acc;
    }, {});
    return rules.filter((r) => {
      /* THE SCOPE COMES FIRST, because it is not a narrowing of the list — it
         IS the list. A rule on another line is not a hidden row, it is a row
         that belongs to a different screenful. */
      if (ops === "first" && r.jobType !== "Transportation") return false;
      if (ops === "third" && r.jobType !== "Brokerage") return false;
      if (!matchesRule(r, search)) return false;
      if (cq && field && !field.text(r).toLowerCase().includes(cq))
        return false;
      if (
        !activeColFilters.every(([k, v]) =>
          ruleColumnText(r, k).toLowerCase().includes(v.trim().toLowerCase())
        )
      )
        return false;
      /* WITHIN a facet the options are OR-ed — picking two partners means
         either — and BETWEEN facets they are AND-ed, which is what ticking
         boxes in two different sections looks like it should do. */
      return Object.entries(byFacet).every(([k, wanted]) => {
        const facet = RULE_FACETS.find((f) => f.key === k);
        return !facet || wanted.includes(facet.valueOf(r));
      });
    });
  }, [rules, search, colScope, colQuery, ops, activeColFilters]);

  const rows = React.useMemo(() => {
    const kept = narrow(applied);

    /* SORTING IS THE LAST STEP, over what survived the narrowing — sorting
       first and filtering after would do the same work and throw most of it
       away. Unsorted returns the fixture's own order, which is what the third
       press of a header goes back to. */
    const col = sort && COLUMNS.find((c) => c.key === sort.key);
    if (!sort || !col?.sort) return kept;
    const dir = sort.dir === "asc" ? 1 : -1;
    const of = col.sort;
    return [...kept].sort((a, b) => {
      const av = of(a);
      const bv = of(b);
      if (typeof av === "number" && typeof bv === "number")
        return (av - bv) * dir;
      return String(av).localeCompare(String(bv)) * dir;
    });
  }, [narrow, applied, sort]);

  /* PAGINATION IS OVER THE NARROWED LIST, and the page resets whenever the
     narrowing changes — page 4 of a list that just became one page long is a
     screen that reads as empty. */
  /* THE VIEW BAR — the table's tools render into it. */
  const bar = useViewBar();
  const total = rows.length;
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  const safePage = Math.min(page, pageCount);
  const pageRows = React.useMemo(
    () => rows.slice((safePage - 1) * pageSize, safePage * pageSize),
    [rows, safePage, pageSize],
  );
  React.useEffect(() => {
    setPage(1);
  }, [search, applied, colQuery, colScope, ops, activeColFilters]);

  /* READ THE OPEN RULE OUT OF STATE EVERY RENDER. Holding the rule object
     itself would leave the sheet showing the version it was opened with, so
     an edit made inside it would not appear on the calendar behind it. */
  const openRule = rules.find((r) => r.id === openId) ?? null;

  const filtered =
    search.trim().length > 0 ||
    applied.size > 0 ||
    colQuery.trim().length > 0 ||
    activeColFilters.length > 0;

  const clearAll = () => {
    setSearch("");
    setApplied(new Set());
    setColQuery("");
    setColFilters({});
  };

  /* EXPORT ASKS FIRST (Pavan, 2026-10-07) — the Delivery Orders sheet, with
     every narrowing that shapes the file listed. */
  const exportFilters: ExportFilterRow[] = [
    {
      key: "search",
      label: "Search",
      values: search.trim() ? [{ value: search.trim(), onRemove: () => setSearch("") }] : [],
    },
    {
      key: "colSearch",
      label: RULE_SEARCH_FIELDS.find((f) => f.key === colScope)?.label ?? "Column",
      values: colQuery.trim() ? [{ value: colQuery.trim(), onRemove: () => setColQuery("") }] : [],
    },
    ...activeColFilters.map(([key, value]) => ({
      key: `col:${key}`,
      label: COLUMNS.find((c) => c.key === key)?.label ?? key,
      values: [
        {
          value: value.trim(),
          onRemove: () => setColFilters((prev) => ({ ...prev, [key]: "" })),
        },
      ],
    })),
    ...RULE_FACETS.map((f) => {
      const mine = [...applied].filter((id) => id.startsWith(`${f.key}:`));
      const drop = (ids: string[]) =>
        setApplied((prev) => new Set([...prev].filter((id) => !ids.includes(id))));
      return {
        key: f.key,
        label: f.label,
        values: mine.map((id) => ({
          value: id.slice(f.key.length + 1),
          onRemove: () => drop([id]),
        })),
        onRemoveAll: () => drop(mine),
      };
    }),
  ];

  const exportCsv = () => {
    downloadCsv(
      `recurring-rules-${new Date().toISOString().slice(0, 10)}`,
      rows.map((r) => ({
        "Rule #": r.ruleNo,
        Schedule: r.schedule.label,
        Status: r.status,
        "Next delivery": r.nextKey ?? "",
        Customer: r.customer.title,
        "Ship to": r.shipTo,
        Assets: r.assets.join(" / ") || "Any",
        Products: r.lines.map((l) => l.product).join(" / "),
        "Qty (gal)": ruleGallons(r),
        Partner: vendorName(r.vendorId) ?? "",
        POC: r.vendorPoc ?? "",
        "Load order": r.loadOrder?.length ? "Yes" : "No",
        Terminal: r.loadOrder?.map((l) => l.terminal).join(" / ") ?? "",
        Supplier: r.loadOrder?.map((l) => l.supplier).join(" / ") ?? "",
        "Loading account":
          r.loadOrder?.map((l) => l.loadingAccount).join(" / ") ?? "",
        "Vendor price": r.vendorPrice ?? "",
        "Customer price": r.customerPrice ?? "",
      })),
    );
    toast.success(
      `Exported ${rows.length} ${rows.length === 1 ? "rule" : "rules"}`,
    );
  };

  const cell = (r: RecurringRule, key: string): React.ReactNode => {
    switch (key) {
      case "ruleNo":
        return (
          <div className="flex min-w-0 items-start gap-2">
            <Repeat className="mt-0.5 size-3.5 shrink-0 text-muted-foreground" />
            <div className="flex min-w-0 flex-col leading-tight">
              <span className="truncate text-sm tabular-nums text-foreground">
                {r.ruleNo}
              </span>
              {/* WHEN IT WAS SET UP, under the number it belongs to. A rule
                  made in March to start in September is a booked arrangement;
                  one made today to start today is somebody reacting. */}
              <span className="truncate text-xs text-muted-foreground">
                {DATE_FMT.format(new Date(r.createdAt))}
              </span>
            </div>
          </div>
        );
      case "schedule":
        return <ScheduleCell schedule={r.schedule} />;
      case "next": {
        const ahead = ruleUpcoming(r, todayKey);
        return r.nextKey ? (
          <div className="flex min-w-0 flex-col leading-tight">
            <span className="truncate text-sm tabular-nums text-foreground">
              {DATE_FMT.format(new Date(`${r.nextKey}T00:00:00`))}
            </span>
            <span className="truncate text-xs text-muted-foreground">
              {ahead} cut so far
            </span>
          </div>
        ) : (
          <span className="text-sm text-muted-foreground">{DASH}</span>
        );
      }
      case "status":
        return (
          <div className="flex min-w-0 flex-col gap-0.5 leading-tight">
            <StatusChip
              tone={SERIES_TONE[r.status]}
              variant="soft"
              className="self-start"
            >
              {r.status}
            </StatusChip>
            {r.stalledReason && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span className="cursor-default truncate text-xs text-muted-foreground">
                    {r.stalledReason}
                  </span>
                </TooltipTrigger>
                <TooltipContent>{r.stalledReason}</TooltipContent>
              </Tooltip>
            )}
          </div>
        );
      case "customer":
        return (
          <div className="flex min-w-0 flex-col leading-tight">
            <span className="truncate text-sm text-foreground">
              {r.customer.title}
            </span>
            <span className="truncate text-xs text-muted-foreground">
              {r.customer.description}
            </span>
          </div>
        );
      case "shipTo":
        return (
          <span className="truncate text-sm text-foreground">{r.shipTo}</span>
        );
      case "assets":
        /* NOT MANDATORY. "Any" is the rule's real answer; an em-dash would
           read as a field somebody forgot. */
        return r.assets.length > 0 ? (
          <LoadField values={r.assets} empty="Any" label="assets" />
        ) : (
          <span className="text-sm text-muted-foreground">Any</span>
        );
      case "products":
        return (
          <LoadField values={r.lines.map((l) => l.product)} empty={DASH} label="products" />
        );
      case "qty": {
        const gal = ruleGallons(r);
        return gal > 0 ? (
          <span className="text-sm tabular-nums text-foreground">
            {gal.toLocaleString()}
          </span>
        ) : (
          <Pill>Top off</Pill>
        );
      }
      case "vendor": {
        const name = vendorName(r.vendorId);
        return name ? (
          <span className="truncate text-sm text-foreground">{name}</span>
        ) : (
          <span className="text-sm text-muted-foreground">Not assigned</span>
        );
      }
      case "poc":
        return r.vendorPoc ? (
          <span className="truncate text-sm text-foreground">
            {r.vendorPoc}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground/70">{DASH}</span>
        );
      case "loadOrder":
        /* THE ANSWER IS WHO BUYS THE PRODUCT, so the word is Yes or No and the
           three columns after it are the detail of a Yes. */
        return (
          <span
            className={cn(
              "text-sm",
              r.loadOrder?.length ? "text-foreground" : "text-muted-foreground",
            )}
          >
            {r.loadOrder?.length ? "Yes" : "No"}
          </span>
        );
      case "terminal":
        return (
          <LoadField
            values={r.loadOrder?.map((l) => l.terminal) ?? []}
            label="terminals"
            empty="Partner supplies"
          />
        );
      case "supplier":
        return (
          <LoadField
            values={r.loadOrder?.map((l) => l.supplier) ?? []}
            label="suppliers"
            empty={DASH}
          />
        );
      case "account":
        return (
          <LoadField
            values={r.loadOrder?.map((l) => l.loadingAccount) ?? []}
            label="accounts"
            empty={DASH}
          />
        );
      case "vendorPrice":
        return r.vendorPrice !== null ? (
          <span className="text-sm tabular-nums text-foreground">
            {MONEY(r.vendorPrice)}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground">Not priced</span>
        );
      case "customerPrice":
        return r.customerPrice !== null ? (
          <span className="text-sm tabular-nums text-foreground">
            {MONEY(r.customerPrice)}
          </span>
        ) : (
          <span className="text-sm text-muted-foreground">Not priced</span>
        );
      default:
        return null;
    }
  };

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      {/* THE SCOPE SHELF — preset views, the line and the business inside it,
          Export and the CTA. It is the top half of the action unit and it is
          the SAME BAR the orders board carries, because a reader who has
          learnt one list has learnt this one. See `docs/ds/ui/2-rules.md`
          §10c. */}
      <FuelOrdersViewBar
        {...savedViews}
        ctaLabel="Create Order"
        onCreateOrder={onCreateRule}
        onExport={() => setExporting(true)}
      />

      {/* THE TOOLBAR AND THE CHIPS ARE ONE SHELF, and the shelf is spaced
          off the bar above it — `mt-4`, the same step the orders board and
          the directory lists use. Dropped in without it, the view bar and
          the toolbar sat flush and read as one crowded band. */}
      <div className="mt-4 shrink-0">
        {/* THE ACTION UNIT. Every list in this app carries it, and it carries the
          same controls in the same order — search, filters, the view switch,
          the column tools. A list that grew its own two-control bar was a list
          people had to learn separately for no reason.

          NO BOARD, NO MAP, NO GROUP BY. Standing arrangements have no lanes to
          sit in and no pins to drop, and row grouping would fight the column
          groups this table already has for the word "group". Each is switched
            off at the toolbar rather than drawn dead. */}
        <ListToolbar
          viewToolsInto={bar.into}
          viewStatement={<ViewStatement count={total} one="rule" many="rules" />}
          searchValue={search}
          onSearchChange={setSearch}
          searchPlaceholder="Search rules, customers, sites, partners…"
          filters={
            <ListFilters
              facets={RULE_FACETS.map((f) => ({
                key: f.key,
                label: f.label,
                options: f.options,
                searchable: f.searchable,
              }))}
              value={applied}
              onApply={setApplied}
            />
          }
          /* THE SEGMENTS SIT WITH SEARCH AND FILTERS, because they narrow the
             list — which is what everything on that side of the toolbar does.
             `h-8` matches the search field and the Filters button exactly; a
             control a pixel off on a row of three reads as a mistake. */
          quickFilters={
            /* OUTLINE + SPACING 0 — the DS's own joined segmented control.
               It draws the box round the set and the hairlines between the
               segments, which is what says these three are one choice rather
               than three buttons that happen to sit together. */
            <ToggleGroup
              type="single"
              variant="outline"
              value={ops}
              onValueChange={(v) => v && setOps(v as Operations)}
              className="h-8 shrink-0"
            >
              {OPERATIONS.map((o) => (
                <ToggleGroupItem
                  key={o.key}
                  value={o.key}
                  className="h-8 px-3 text-sm"
                >
                  {o.label}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
          }
          showGroupBy={false}
          boardView={false}
          columns={ALL_COLS.map((c) => ({ key: c.key, label: c.label }))}
          columnOrder={colOrder}
          onReorderColumns={setColOrder}
          hiddenColumns={hidden as Set<string>}
          onToggleColumn={(k) =>
            setHidden((prev) => {
              const next = new Set(prev);
              if (next.has(k)) next.delete(k);
              else next.add(k);
              return next;
            })
          }
          onShowAllColumns={() => setHidden(new Set())}
          searchFields={RULE_SEARCH_FIELDS.map((f) => ({
            key: f.key,
            label: f.label,
          }))}
          colScope={colScope}
          onColScopeChange={setColScope}
          colQuery={colQuery}
          onColQueryChange={setColQuery}
          columnFiltersOpen={view === "table" && colFiltersOpen}
          onToggleColumnFilters={
            view === "table"
              ? () =>
                  setColFiltersOpen((open) => {
                    /* Closing the row puts the table back. */
                    if (open) setColFilters({});
                    return !open;
                  })
              : undefined
          }
          columnFilterCount={activeColFilters.length}
          view={view}
          onViewChange={setView}
        />

        {/* NARROWED IS SAID OUT LOUD. The facet panel remembers what was picked
            and then closes, and a list quietly narrowed is the commonest way
            somebody concludes their data has gone missing. */}
        <FilterChips
          facets={RULE_FACETS.map((f) => ({ key: f.key, label: f.label }))}
          selected={applied}
          onChange={setApplied}
        >
          <ColumnSearchChip
            searchFields={RULE_SEARCH_FIELDS.map((f) => ({
              key: f.key,
              label: f.label,
            }))}
            colScope={colScope}
            colQuery={colQuery}
            onClear={() => setColQuery("")}
          />
          {activeColFilters.map(([key, value]) => (
            <ColumnSearchChip
              key={key}
              searchFields={COLUMNS.map((c) => ({ key: c.key, label: c.label }))}
              colScope={key}
              colQuery={value.trim()}
              onClear={() => setColFilters((prev) => ({ ...prev, [key]: "" }))}
            />
          ))}
        </FilterChips>
      </div>

      <div className="relative mt-4 min-h-0 flex-1">
        {rows.length === 0 && !colFiltersOpen ? (
          <Empty className="h-full">
            <EmptyHeader>
              <EmptyMedia variant="icon">
                {filtered ? <SearchX /> : <Repeat />}
              </EmptyMedia>
              <EmptyTitle>
                {filtered ? "No rules match" : "No recurring rules yet"}
              </EmptyTitle>
              <EmptyDescription>
                {filtered
                  ? "Nothing found. Check the spelling, or clear the filters above."
                  : "Tick Recurring on a delivery order and give it a frequency — the rule appears here."}
              </EmptyDescription>
            </EmptyHeader>
            {filtered && (
              <Button variant="outline" size="sm" onClick={clearAll}>
                Clear search and filters
              </Button>
            )}
          </Empty>
        ) : (
          <div className="flex h-full flex-col overflow-hidden rounded-md border border-border">
            <div className="shrink-0 border-b border-fp-outline-1 bg-fp-surface-1b">{bar.slot}</div>
            <div className="min-h-0 flex-1 overflow-auto [&_[data-slot=table-container]]:overflow-visible">
            {/* BORDER-SEPARATE, AND IT IS THE WHOLE FIX.

                Chrome will not honour `position: sticky` on a table CELL while
                the table's borders are collapsed, and it ignores z-index on
                `<thead>` in that mode too — so a collapsed table can hold its
                header still (sticky on the header) or paint it above the body
                (sticky on the cells), but never both. That is why a scrolled
                row could be read straight through the header.

                Separating the borders lets the cells stick properly and
                respect z-index. The cost is that a border on a `<tr>` stops
                painting, so the row rule moves onto the cells — which is where
                the header's own borders already were. */}
              <Table
                style={{ tableLayout: "fixed" }}
                className="border-separate border-spacing-0"
              >
              <colgroup>
                {visibleCols.map((c) => (
                  <col key={c.key} style={{ width: `${cols.widthOf(c)}px` }} />
                ))}
              </colgroup>
              {/* THE CELLS STICK, NOT THE HEADER — a collapsed-border table
                  ignores z-index on `<thead>`, so the table separates its
                  borders and each header cell sticks on its own. See
                  `docs/ds/ui/2-rules.md` §10d. */}
              <TableHeader className="bg-fp-table-header">
                <TableRow className="h-10 bg-fp-table-header hover:bg-transparent">
                  {visibleCols.map((c) => {
                    const active = sort?.key === c.key;
                    const SortIcon = !active
                      ? ChevronsUpDown
                      : sort?.dir === "asc"
                        ? ArrowUp
                        : ArrowDown;
                    return (
                      <TableColumnHeader
                        key={c.key}
                        cols={cols}
                        col={c}
                        aria-sort={
                          active
                            ? sort?.dir === "asc"
                              ? "ascending"
                              : "descending"
                            : undefined
                        }
                        className={cn(
                          "sticky top-0 z-20 whitespace-nowrap border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                          c.align === "right" && "text-right"
                        )}
                      >
                        {/* EVERY COLUMN SORTS, which is a rule rather than a
                            taste: a header that sorts on one column and not
                            the next teaches the reader to stop trying, and
                            the ones left out are always the text columns —
                            exactly where "show me these together" is asked
                            most. */}
                        <button
                          type="button"
                          onClick={() => onSort(c.key)}
                          aria-label={`Sort by ${c.label}`}
                          className={cn(
                            "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                            active && "text-foreground"
                          )}
                        >
                          {c.label}
                          <SortIcon
                            className={cn(
                              "size-3.5",
                              active ? "opacity-100" : "opacity-70"
                            )}
                          />
                        </button>
                      </TableColumnHeader>
                    );
                  })}
                </TableRow>
                {colFiltersOpen && (
                  /* THE SECOND HEADER ROW — the same band ListTable draws. */
                  <TableRow className="h-11 hover:bg-transparent">
                    {visibleCols.map((c) => (
                      <TableHead
                        key={c.key}
                        className="sticky top-10 z-20 border-b border-fp-outline-1 bg-fp-surface-1b px-2"
                      >
                        <Input
                          value={colFilters[c.key] ?? ""}
                          onChange={(e) =>
                            setColFilters((prev) => ({
                              ...prev,
                              [c.key]: e.target.value,
                            }))
                          }
                          placeholder={cols.widthOf(c) >= 96 ? "Filter…" : ""}
                          aria-label={`Filter by ${c.label}`}
                          className="h-7 rounded-md px-2.5 text-xs shadow-none"
                        />
                      </TableHead>
                    ))}
                  </TableRow>
                )}
              </TableHeader>
              <TableBody>
                {pageRows.map((r) => (
                  <TableRow
                    key={r.id}
                    /* THE ROW RULE LIVES ON THE CELLS, because a border on a
                       `<tr>` does not paint once the table's borders are
                       separated. */
                    className="group/row h-14 cursor-pointer [&>td]:border-b [&>td]:border-fp-outline-1"
                    onClick={(e) => {
                      const t = e.target as HTMLElement | null;
                      if (t?.closest("button,a,input,label,[role='checkbox']"))
                        return;
                      if (window.getSelection()?.toString()) return;
                      setOpenId(r.id);
                    }}
                  >
                    {visibleCols.map((c) => (
                      <TableCell
                        key={c.key}
                        className={cn("px-3", c.align === "right" && "text-right")}
                      >
                        {cell(r, c.key)}
                      </TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
          </div>
        )}
      </div>

      {/* THE PAGE POSITION IS THE FOOTER'S JOB, and it is the one number a
          paged list owes the reader: which of how many, and how to get to the
          next. It is the same control every other list in the app ends with. */}
      <div className="mt-4 shrink-0">
        <TablePagination
          page={safePage}
          pageSize={pageSize}
          total={total}
          onPageChange={setPage}
          onPageSizeChange={(n) => {
            setPageSize(n);
            setPage(1);
          }}
        />
      </div>

      <ExportSheet
        open={exporting}
        onOpenChange={setExporting}
        title="Export Rules"
        noun="rules"
        nounOne="rule"
        count={rows.length}
        filtersControl={
          <ListFilters
            facets={RULE_FACETS.map((f) => ({
              key: f.key,
              label: f.label,
              options: f.options,
              searchable: f.searchable,
            }))}
            value={applied}
            onApply={setApplied}
            countFor={(sel) => narrow(sel).length}
            fullWidth
          />
        }
        filters={exportFilters}
        onExport={(format) => {
          setExporting(false);
          if (format === "csv") exportCsv();
          else
            toast.success(
              `Exporting ${rows.length} ${rows.length === 1 ? "rule" : "rules"} as .${format}`
            );
        }}
      />

      <RecurringRuleSheet
        rule={openRule}
        open={openRule !== null}
        onOpenChange={(v) => !v && setOpenId(null)}
        onChange={(next) =>
          setRules((prev) => prev.map((r) => (r.id === next.id ? next : r)))
        }
      />
    </div>
  );
}

import * as React from "react";
import { DateKeyField } from "@/components/ui/date-picker";
import { ChevronDown, Plus, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { selectTriggerClasses } from "@/components/ui/select";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { DATE_FMT, dateKeyOf, relativeLabel, startOfDay } from "../data";
import type { Schedule } from "./recurring";

/*
  HOW OFTEN — the frequency a rule is built from.

  TWO QUESTIONS, NOT ONE, and keeping them apart is the whole design.

    WHICH DAYS   Sunday through Saturday, as badges. Daily lights all seven;
                 otherwise the reader picks.
    HOW IT REPEATS  weekly, monthly or yearly — and what that means differs
                 enough per choice that each gets its own follow-up rather
                 than one list of twenty phrases.

  A SINGLE DROPDOWN OF PHRASES CANNOT DO THIS. "Monthly On First Thursday" is
  one entry in a list that would need a hundred to cover the real range, and
  every one of them has to be read to be understood. Two badges lit and the
  word "monthly" is understood before it is read.

  THE BADGES ARE THE SAME SEVEN THE LIST SHOWS. A reader who picks S–M–T–W–T
  here sees exactly that shape back in the Frequency column, which is what
  makes the column readable at all.

  EVERY SHAPE STILL COMES OUT AS A `Schedule`, so the list cell, the calendar
  and the generator are untouched by any of this — `toSchedule` is the whole
  seam.
*/

export const WEEKDAYS = [
  { letter: "S", name: "Sunday" },
  { letter: "M", name: "Monday" },
  { letter: "T", name: "Tuesday" },
  { letter: "W", name: "Wednesday" },
  { letter: "T", name: "Thursday" },
  { letter: "F", name: "Friday" },
  { letter: "S", name: "Saturday" },
];

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

export type Repeat = "weekly" | "monthly" | "yearly" | "cycle";

/** CUSTOM CYCLE (Pavan, 2026-10-06) — 2 to 4 weeks, each with its own days. */
export const CYCLE_LENGTHS = [2, 3, 4];
const DAY_MS = 86_400_000;
/** The Sunday that starts `d`'s week, at midnight. */
const weekStart = (d: Date) => {
  const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  x.setDate(x.getDate() - x.getDay());
  return x;
};
const keyToDate = (k: string) =>
  new Date(Number(k.slice(0, 4)), Number(k.slice(5, 7)) - 1, Number(k.slice(8, 10)));
/** Which week of the cycle `d` falls in, or -1 before the cycle starts. */
export const cycleWeekOf = (d: Date, startKey: string, length: number) => {
  const n = Math.round((weekStart(d).getTime() - weekStart(keyToDate(startKey)).getTime()) / (7 * DAY_MS));
  return n < 0 ? -1 : n % length;
};
/**
 * DAYS OR DATES (Pavan, 2026-10-01) — the two ways a rule says when. Days is
 * weekdays and how they repeat; Date is dates picked on a calendar and how
 * often that set comes round.
 */
export type FrequencyBasis = "days" | "date";

/** How often the picked dates come round: every N months, 0 = only once. */
export const DATE_REPEATS = [
  { n: 1, label: "Every month" },
  { n: 2, label: "Every 2 months" },
  { n: 3, label: "Every 3 months" },
  { n: 6, label: "Every 6 months" },
  { n: 12, label: "Every year" },
  { n: 0, label: "Does not repeat" },
];

/** 0 = every week (the fifth, partial one included); 1–4 = that week. */
export const MONTH_WEEKS = [
  { n: 0, label: "Every week" },
  { n: 1, label: "First week" },
  { n: 2, label: "Second week" },
  { n: 3, label: "Third week" },
  { n: 4, label: "Fourth week" },
];
export type YearlyMode = "firstMonth" | "specificMonths";

export interface RuleFrequency {
  basis: FrequencyBasis;
  /** DATE basis — the picked calendar dates, as `yyyy-mm-dd`. */
  dates: string[];
  /** DATE basis — every N months; 0 is just the picked dates. */
  dateRepeat: number;
  /** `daily` lights all seven and cannot be unpicked one at a time. */
  dayMode: "daily" | "specific";
  /** 0 = Sunday … 6 = Saturday. */
  days: number[];
  repeat: Repeat;
  /**
   * WEEKLY ONLY — how many drops a week, and a time of day for each.
   *
   * The days say WHEN IN THE WEEK; this says how many runs and at what hour,
   * because two drops on a Monday is a real arrangement and the days alone
   * cannot express it.
   */
  times: string[];
  /**
   * WHICH WEEKS OF THE MONTH (Pavan, 2026-10-01) — checkboxes, one or several.
   * `[0]` is every week and stands alone; ticking a single week drops it.
   */
  monthWeeks: number[];
  yearlyMode: YearlyMode;
  /** 0-based, for `specificMonths`. */
  months: number[];
  /** `null` is "no end date", and it is the default. */
  endKey: string | null;
  /** CYCLE ONLY — one list of weekdays per week of the cycle. */
  cycleWeeks?: number[][];
  /** CYCLE ONLY — a day in the week the cycle's Week 1 is, as `yyyy-mm-dd`. */
  cycleStartKey?: string;
}

export function blankFrequency(): RuleFrequency {
  return {
    dayMode: "specific",
    days: [2],
    repeat: "weekly",
    times: ["08:00"],
    basis: "days",
    dates: [],
    dateRepeat: 1,
    monthWeeks: [1],
    yearlyMode: "firstMonth",
    months: [0],
    endKey: null,
  };
}

/** 1st, 2nd, 3rd, 4th… */
const ordinal = (n: number) =>
  `${n}${n % 10 === 1 && n !== 11 ? "st" : n % 10 === 2 && n !== 12 ? "nd" : n % 10 === 3 && n !== 13 ? "rd" : "th"}`;

const nthWeekdayOfMonth = (d: Date) => Math.floor((d.getDate() - 1) / 7) + 1;

const listNames = (xs: string[]) =>
  xs.length <= 1
    ? (xs[0] ?? "")
    : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`;

/**
 * THE SEAM. Everything downstream — the list's Frequency cell, the calendar,
 * the generator — takes a `Schedule`, so the picker's richer shape is turned
 * into one here and nothing else has to know it exists.
 */
export function toSchedule(f: RuleFrequency): Schedule {
  if (f.basis === "date") {
    /* THE PICKED DATES, AND HOW OFTEN THEY COME ROUND. No weekday pattern,
       so one badge instead of the row. Repeating keeps each date's day of
       the month; one past a month's end (the 31st in April) falls on its
       last day, so no month is skipped. */
    const keys = [...(f.dates ?? [])].sort();
    const every = f.dateRepeat ?? 1;
    const dom = [...new Set(keys.map((k) => Number(k.slice(8, 10))))].sort(
      (a, b) => a - b
    );
    const first = keys[0];
    const monthIndex = (d: Date) => d.getFullYear() * 12 + d.getMonth();
    const firstMonth = first
      ? Number(first.slice(0, 4)) * 12 + Number(first.slice(5, 7)) - 1
      : 0;
    return {
      raw: `date:${every}:${keys.join(",")}`,
      label:
        keys.length === 0
          ? "No dates picked"
          : every === 0
            ? `On ${keys.length} ${keys.length === 1 ? "date" : "dates"}`
            : `${every === 1 ? "Every month" : `Every ${every} months`} on the ${listNames(dom.map(ordinal))}`,
      days: [],
      badge: every === 0 ? "Dates" : "Monthly",
      cadence:
        every === 0
          ? `${keys.length} ${keys.length === 1 ? "date" : "dates"}, no repeat`
          : `${dom.length} ${dom.length === 1 ? "date" : "dates"} ${every === 1 ? "every month" : `every ${every} months`}`,
      hits: (d) => {
        if (keys.length === 0) return false;
        const key = dateKeyOf(d);
        if (every === 0) return keys.includes(key);
        if (key < first) return false;
        if ((monthIndex(d) - firstMonth) % every !== 0) return false;
        const last = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
        return dom.some((x) => Math.min(x, last) === d.getDate());
      },
    };
  }
  if (f.repeat === "cycle") {
    const weeks = f.cycleWeeks ?? [f.days, []];
    const start = f.cycleStartKey ?? dateKeyOf(weekStart(new Date()));
    const short = (ds: number[]) =>
      ds.length === 0 ? "none" : ds.map((x) => WEEKDAYS[x].name.slice(0, 3)).join(", ");
    return {
      raw: `cycle:${start}:${weeks.map((w) => w.join(",")).join("|")}`,
      label: weeks.map((w, i) => `Week ${i + 1}: ${short(w)}`).join(" · "),
      days: [...new Set(weeks.flat())].sort((a, b) => a - b),
      cycle: weeks,
      badge: null,
      cadence: `${weeks.length}-week cycle`,
      hits: (d) => {
        const i = cycleWeekOf(d, start, weeks.length);
        return i >= 0 && weeks[i].includes(d.getDay());
      },
    };
  }
  const days = f.dayMode === "daily" ? [0, 1, 2, 3, 4, 5, 6] : [...f.days];
  const onDay = (d: Date) => days.includes(d.getDay());
  const dayNames = days.map((d) => WEEKDAYS[d].name);

  if (f.repeat === "weekly") {
    const perWeek =
      f.times.length > 1 ? `, ${f.times.length}× a day` : "";
    return {
      raw: `weekly:${days.join(",")}`,
      label:
        f.dayMode === "daily" ? "Every day" : `Every ${listNames(dayNames)}`,
      days,
      badge: f.dayMode === "daily" ? "Daily" : null,
      cadence: `Every week${perWeek}`,
      hits: onDay,
    };
  }

  if (f.repeat === "monthly") {
    const weeks = [...(f.monthWeeks ?? [1])].sort((a, b) => a - b);
    const every = weeks.length === 0 || weeks.includes(0);
    const weekWords = weeks.map((n) => ["", "first", "second", "third", "fourth"][n]);
    const capital = (x: string) => x.charAt(0).toUpperCase() + x.slice(1);
    return {
      raw: `monthly:weeks:${weeks.join(",")}:${days.join(",")}`,
      label: every
        ? `Every ${listNames(dayNames)}`
        : `${capital(listNames(weekWords))} ${listNames(dayNames)} of the month`,
      days,
      badge: null,
      cadence: every
        ? "Every week of the month"
        : `${capital(weekWords.join(", "))} ${weeks.length === 1 ? "week" : "weeks"} of every month`,
      hits: (d) => onDay(d) && (every || weeks.includes(nthWeekdayOfMonth(d))),
    };
  }

  const months = f.yearlyMode === "firstMonth" ? [0] : [...f.months];
  const monthNames = months.map((m) => MONTHS[m]);
  return {
    raw: `yearly:${f.yearlyMode}:${months.join(",")}`,
    label:
      f.yearlyMode === "firstMonth"
        ? "Every January"
        : `Every ${listNames(monthNames)}`,
    days,
    badge: "Yearly",
    cadence:
      f.yearlyMode === "firstMonth"
        ? "First month of every year"
        : `${months.length} ${months.length === 1 ? "month" : "months"} a year`,
    hits: (d) => months.includes(d.getMonth()) && onDay(d),
  };
}

/* ---------------------------------------------------------------------------
 * The picker
 * ------------------------------------------------------------------------ */

function DayBadges({
  value,
  onChange,
  stretch,
}: {
  value: number[];
  onChange: (next: number[]) => void;
  /** Fill the row — the frequency unit is wider (Pavan, 2026-10-16). */
  stretch?: boolean;
}) {
  return (
    <div className={cn("flex gap-1", stretch && "w-full")}>
      {WEEKDAYS.map((d, i) => {
        const on = value.includes(i);
        return (
          <button
            key={i}
            type="button"
            aria-pressed={on}
            aria-label={d.name}
            onClick={() =>
              onChange(
                on ? value.filter((x) => x !== i) : [...value, i].sort()
              )
            }
            className={cn(
              "flex h-8 items-center justify-center rounded-md text-sm font-medium transition-colors",
              stretch ? "min-w-8 flex-1" : "w-8",
              on
                ? "bg-accent-violet text-accent-violet-foreground"
                : "bg-fp-card-1 text-muted-foreground hover:text-foreground"
            )}
          >
            {d.letter}
          </button>
        );
      })}
    </div>
  );
}

function Row({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <span className="text-sm font-medium text-foreground">{label}</span>
      {children}
      {hint && <span className="text-xs text-muted-foreground">{hint}</span>}
    </div>
  );
}

/**
 * WHICH WEEKS, AS CHECKBOXES IN A DROPDOWN (Pavan, 2026-10-01). One or several
 * weeks; "of the month" is said once, beside the field, not in every option.
 * Every week stands alone — it is all of them, the partial fifth included —
 * so ticking it clears the single weeks and ticking a single week clears it.
 * Picking dates instead is the Date tab, not an option here.
 */
function MonthPartPicker({
  value,
  onChange,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
}) {
  const weeks = value.monthWeeks ?? [1];
  const toggleWeek = (n: number) => {
    let next: number[];
    if (n === 0) next = weeks.includes(0) ? [] : [0];
    else {
      const singles = weeks.filter((x) => x !== 0);
      next = singles.includes(n)
        ? singles.filter((x) => x !== n)
        : [...singles, n].sort((a, b) => a - b);
    }
    onChange({ ...value, monthWeeks: next });
  };
  const summary = weeks.includes(0)
      ? "Every week"
      : weeks.length === 0
        ? "Pick weeks"
        : weeks.length === 1
          ? `${["", "First", "Second", "Third", "Fourth"][weeks[0]]} week`
          : /* SHORT WHEN SEVERAL, so the field never cuts the answer off. */
            `${weeks.map((n) => ["", "1st", "2nd", "3rd", "4th"][n]).join(", ")} weeks`;

  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <div className="flex min-w-0 items-center gap-2">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              aria-label="Which weeks of the month"
              className={cn(selectTriggerClasses, "w-full min-w-0")}
            >
              <span
                className={cn(
                  "truncate",
                  weeks.length === 0 && "text-muted-foreground"
                )}
              >
                {summary}
              </span>
              <ChevronDown className="size-4 shrink-0 opacity-50" />
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="start"
            className="w-(--radix-dropdown-menu-trigger-width) min-w-56"
          >
            {MONTH_WEEKS.map((w) => (
              <DropdownMenuCheckboxItem
                key={w.n}
                checked={weeks.includes(w.n)}
                /* Stays open — several weeks are picked in one visit. */
                onSelect={(e) => e.preventDefault()}
                onCheckedChange={() => toggleWeek(w.n)}
              >
                {w.label}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        <span className="shrink-0 text-sm text-muted-foreground">
          of the month
        </span>
      </div>
      {weeks.length === 0 && (
        <p className="text-xs text-status-failed">Pick at least one week.</p>
      )}
    </div>
  );
}

/**
 * THE DATE TAB — dates picked from a strip, and how often that set comes
 * round. Picking the 5th and the 20th with Every month is twice a month.
 *
 * A STRIP, NOT A CALENDAR GRID (Pavan, 2026-10-01). The month runs left to
 * right across the whole width of the unit, as many dates to a line as fit,
 * and wraps; Repeat sits under it, because it is asked after the dates.
 * Each date carries its weekday letter so the strip still reads as a week.
 */
function DatePart({
  value,
  onChange,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
}) {
  /* DATES OF THE MONTH, NOT OF A MONTH (Pavan, 2026-10-20) — 1 to 31, no
     month to step through: the dates repeat every month, or every N. Each
     pick is kept as that date's next turn from today (this month if it's
     still ahead, else next month), which is where the repeat starts. */
  const today = new Date();
  const picked = new Set((value.dates ?? []).map((k) => Number(k.slice(8, 10))));
  const keyOf = (dom: number) => {
    const ahead = dom >= today.getDate();
    const m = new Date(today.getFullYear(), today.getMonth() + (ahead ? 0 : 1), 1);
    return `${m.getFullYear()}-${String(m.getMonth() + 1).padStart(2, "0")}-${String(dom).padStart(2, "0")}`;
  };
  const toggle = (dom: number) => {
    const next = new Set(picked);
    if (next.has(dom)) next.delete(dom);
    else next.add(dom);
    onChange({ ...value, dates: [...next].sort((x, y) => x - y).map(keyOf).sort() });
  };

  return (
    /* THE DATES TAKE THE ROW; REPEAT SITS AT ITS RIGHT EDGE, well apart. */
    <div className="flex items-start gap-12">
      <div className="flex min-w-0 flex-1 flex-col gap-1.5">
        <span className="text-sm font-medium text-foreground">Select dates</span>
        <div className="grid grid-cols-[repeat(auto-fill,minmax(2.5rem,1fr))] gap-1">
          {Array.from({ length: 31 }, (_, i) => {
            const dom = i + 1;
            const on = picked.has(dom);
            return (
              <button
                key={dom}
                type="button"
                aria-pressed={on}
                aria-label={`The ${ordinal(dom)}`}
                onClick={() => toggle(dom)}
                className={cn(
                  "flex h-9 items-center justify-center rounded-md text-sm font-medium tabular-nums outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
                  on
                    ? "bg-accent-violet text-accent-violet-foreground"
                    : "bg-fp-card-1 text-foreground hover:bg-accent"
                )}
              >
                {dom}
              </button>
            );
          })}
        </div>
        {picked.size === 0 && (
          <p className="text-xs text-status-failed">Pick at least one date.</p>
        )}
      </div>

      <div className="w-62 shrink-0">
        <Row label="Repeat">
          <Select
            value={String(value.dateRepeat ?? 1)}
            onValueChange={(v) => onChange({ ...value, dateRepeat: Number(v) })}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {DATE_REPEATS.map((r) => (
                <SelectItem key={r.n} value={String(r.n)}>
                  {r.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Row>
      </div>
    </div>
  );
}

/** Switching Repeat; into a cycle, the days already picked become Week 1. */
function withRepeat(value: RuleFrequency, repeat: Repeat): RuleFrequency {
  if (repeat !== "cycle" || value.cycleWeeks) return { ...value, repeat };
  const days = value.dayMode === "daily" ? [0, 1, 2, 3, 4, 5, 6] : value.days;
  return {
    ...value,
    repeat,
    cycleWeeks: [days, []],
    cycleStartKey: value.cycleStartKey ?? dateKeyOf(weekStart(new Date())),
  };
}

/**
 * CUSTOM CYCLE (Pavan, 2026-10-06) — Repeat, how many weeks, when Week 1
 * starts, then one row of day badges per week, and the next four weeks as
 * they will run. A week with no days is a week with no delivery.
 */
function CyclePart({
  value,
  onChange,
  part,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
  /* IN THREE PLACES (Pavan, 2026-10-16): the weeks where the day badges
     are, the settings where Repeat is, the preview under both. */
  part: "weeks" | "settings" | "preview";
}) {
  const weeks = value.cycleWeeks ?? [value.days, []];
  const startKey = value.cycleStartKey ?? dateKeyOf(weekStart(new Date()));
  const setWeeks = (next: number[][]) => onChange({ ...value, cycleWeeks: next });
  const fmt = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });
  const first = weekStart(keyToDate(startKey));
  const preview = Array.from({ length: 4 }, (_, k) => {
    const from = new Date(first.getTime() + k * 7 * DAY_MS);
    const ds = weeks[k % weeks.length];
    return {
      label: fmt.format(from),
      days: ds.length === 0 ? "No delivery" : ds.map((x) => WEEKDAYS[x].name.slice(0, 3)).join(", "),
    };
  });
  if (part === "settings")
    return (
      <div className="grid grid-cols-2 content-start gap-6">
        <Row label="Cycle length">
          <Select
            value={String(weeks.length)}
            onValueChange={(v) => {
              const n = Number(v);
              setWeeks(Array.from({ length: n }, (_, i) => weeks[i] ?? []));
            }}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {CYCLE_LENGTHS.map((n) => (
                <SelectItem key={n} value={String(n)}>
                  {n} weeks
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Row>
        <Row label="Week 1 starts">
          <DateKeyField
            value={startKey}
            onChange={(key) => onChange({ ...value, cycleStartKey: key })}
          />
        </Row>
      </div>
    );
  if (part === "weeks")
    return (
      <div className="flex flex-col gap-2">
        {weeks.map((w, i) => (
          <div key={i} className="flex items-center gap-3">
            <span className="w-14 shrink-0 text-sm font-medium text-foreground">
              Week {i + 1}
            </span>
            <DayBadges
              stretch
              value={w}
              onChange={(next) => setWeeks(weeks.map((x, j) => (j === i ? next : x)))}
            />
          </div>
        ))}
        {weeks.every((w) => w.length === 0) && (
          <p className="text-xs text-status-failed">Pick at least one day.</p>
        )}
      </div>
    );
  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-sm font-medium text-foreground">Next 4 weeks</span>
      <div className="grid grid-cols-4 gap-2">
        {preview.map((p) => (
          <div
            key={p.label}
            className="flex flex-col rounded-md border border-fp-outline-1 px-3 py-2"
          >
            <span className="text-xs text-muted-foreground">Week of {p.label}</span>
            <span className="truncate text-sm text-foreground">{p.days}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

export function RuleFrequencyPicker({
  value,
  onChange,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
}) {
  const set = <K extends keyof RuleFrequency>(k: K, v: RuleFrequency[K]) =>
    onChange({ ...value, [k]: v });

  /* WHAT THEY HAD BEFORE DAILY. Ticking Daily fills all seven; going back to
     Specific with all seven still lit is a "specific days" answer that reads
     as daily, and leaves the reader unpicking six badges to get back to where
     they were. The set they came in with is remembered and handed back. */
  const beforeDaily = React.useRef<number[]>(value.days);

  const days = value.dayMode === "daily" ? [0, 1, 2, 3, 4, 5, 6] : value.days;
  const cycle = value.repeat === "cycle";

  return (
    <div className="flex flex-col gap-5">
      {/* DAYS OR DATE (Pavan, 2026-10-01) — THE DS SEGMENT CONTROL (Pavan,
          2026-10-16), the one the lists use for All / Fuel / Lubricants. */}
      <ToggleGroup
        type="single"
        variant="outline"
        size="sm"
        value={value.basis ?? "days"}
        onValueChange={(v) => v && set("basis", v as FrequencyBasis)}
        aria-label="Days or date"
        className="h-7 w-fit"
      >
        {(["days", "date"] as const).map((k) => (
          <ToggleGroupItem
            key={k}
            value={k}
            /* Greyscale — the DS segment control's own selection. */
            className="h-7 px-2.5 text-xs font-normal data-[state=on]:font-medium"
          >
            {k === "days" ? "Days" : "Date"}
          </ToggleGroupItem>
        ))}
      </ToggleGroup>

      {(value.basis ?? "days") === "date" ? (
        <DatePart value={value} onChange={onChange} />
      ) : (
      <>
      {/* THE DAYS UNIT WIDER, REPEAT NARROWER (Pavan, 2026-10-16). A custom
          cycle swaps its week rows into the same place, and its settings
          into Repeat's — on and off look the same, only the content moves. */}
      <div className="flex items-start gap-15">
        <div className="flex w-[360px] shrink-0 flex-col gap-3">
          {cycle ? (
            <CyclePart part="weeks" value={value} onChange={onChange} />
          ) : (
            <div className="flex flex-col gap-1.5">
              <span className="text-sm font-medium text-foreground">Select day/s</span>
              <DayBadges
                stretch
                value={days}
                onChange={(next) => {
                  if (value.dayMode === "daily") beforeDaily.current = next;
                  onChange({
                    ...value,
                    dayMode: next.length === 7 ? "daily" : "specific",
                    days: next,
                  });
                }}
              />
            </div>
          )}
          {/* DAILY AND CUSTOM CYCLE, SIDE BY SIDE — the word, then its switch
              (Pavan, 2026-10-16). Daily means nothing inside a cycle. */}
          <div className="flex items-center gap-6">
            <label
              className={cn(
                "flex w-fit cursor-pointer items-center gap-2.5 text-sm text-foreground",
                cycle && "cursor-not-allowed opacity-50"
              )}
            >
              Daily
              <Switch
                checked={!cycle && value.dayMode === "daily"}
                disabled={cycle}
                onCheckedChange={(on) => {
                  if (on) beforeDaily.current = value.days;
                  const back = beforeDaily.current;
                  onChange({
                    ...value,
                    dayMode: on ? "daily" : "specific",
                    days: on
                      ? [0, 1, 2, 3, 4, 5, 6]
                      : back.length > 0 && back.length < 7
                        ? back
                        : [],
                  });
                }}
              />
            </label>
            <label className="flex w-fit cursor-pointer items-center gap-2.5 text-sm text-foreground">
              Custom cycle
              <Switch
                checked={cycle}
                onCheckedChange={(on) =>
                  onChange(on ? withRepeat(value, "cycle") : { ...value, repeat: "weekly" })
                }
              />
            </label>
          </div>
          {!cycle && value.dayMode === "specific" && value.days.length === 0 && (
            <p className="text-xs text-status-failed">Pick at least one day.</p>
          )}
        </div>

      {/* THE REST OF THE ROW, FILLED (Pavan, 2026-10-16 — DS ui "A row of
          fields fills its row"): the two fields share it equally, 24px apart. */}
      <div className="flex min-w-0 flex-1 flex-col gap-4">
      {cycle ? (
        <CyclePart part="settings" value={value} onChange={onChange} />
      ) : (
      <div className="grid grid-cols-2 content-start gap-6">
        <Row label="Repeat">
          <Select
            value={value.repeat}
            onValueChange={(v) => onChange(withRepeat(value, v as Repeat))}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="weekly">Weekly</SelectItem>
              <SelectItem value="monthly">Monthly</SelectItem>
              <SelectItem value="yearly">Yearly</SelectItem>
            </SelectContent>
          </Select>
        </Row>
        {value.repeat === "weekly" && (
          <Row label="Times a day">
            <Select
              value={String(value.times.length)}
              onValueChange={(v) => {
                const n = Number(v);
                const next = Array.from(
                  { length: n },
                  (_, i) => value.times[i] ?? ["08:00", "14:00", "18:00"][i % 3]
                );
                set("times", next);
              }}
            >
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {[1, 2, 3].map((n) => (
                  <SelectItem key={n} value={String(n)}>
                    {n} {n === 1 ? "time" : "times"}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Row>
        )}

        {value.repeat === "monthly" && (
          <Row label="Which part of the month">
            <MonthPartPicker value={value} onChange={onChange} />
          </Row>
        )}

        {value.repeat === "yearly" && (
          <Row label="Which part of the year">
            <Select
              value={value.yearlyMode}
              onValueChange={(v) => set("yearlyMode", v as YearlyMode)}
            >
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="firstMonth">
                  First month of every year
                </SelectItem>
                <SelectItem value="specificMonths">
                  Specific months of the year
                </SelectItem>
              </SelectContent>
            </Select>
          </Row>
        )}
      </div>
      )}
      {/* WEEKLY, MORE THAN ONCE — a time per drop, under Repeat so it reads
          as part of it (Pavan, 2026-09-25). Two deliveries on one day
          is a real arrangement and the day badges cannot say it. */}
      {value.repeat === "weekly" && value.times.length > 1 && (
        <div className="flex flex-wrap gap-3">
          {value.times.map((t, i) => (
            <div key={i} className="flex min-w-0 flex-col gap-1.5">
              <span className="text-xs font-medium text-muted-foreground">
                Drop {i + 1}
              </span>
              <Input
                type="time"
                className="w-[130px]"
                value={t}
                aria-label={`Time for drop ${i + 1}`}
                onChange={(e) =>
                  set(
                    "times",
                    value.times.map((x, j) => (j === i ? e.target.value : x))
                  )
                }
              />
            </div>
          ))}
        </div>
      )}
      </div>
      </div>

      {cycle && <CyclePart part="preview" value={value} onChange={onChange} />}

      {value.repeat === "yearly" && value.yearlyMode === "specificMonths" && (
        <div className="flex flex-wrap gap-1.5">
          {MONTHS.map((m, i) => {
            const on = value.months.includes(i);
            return (
              <button
                key={m}
                type="button"
                aria-pressed={on}
                onClick={() =>
                  set(
                    "months",
                    on
                      ? value.months.filter((x) => x !== i)
                      : [...value.months, i].sort((a, b) => a - b)
                  )
                }
                className={cn(
                  "rounded-md px-2.5 py-1 text-xs font-medium transition-colors",
                  on
                    ? "bg-accent-violet text-accent-violet-foreground"
                    : "bg-fp-card-1 text-muted-foreground hover:text-foreground"
                )}
              >
                {m.slice(0, 3)}
              </button>
            );
          })}
        </div>
      )}

      </>
      )}

      {/* NO END DATE IS THE DEFAULT, so there is nothing to say until
          somebody wants one — the offer to add one is the whole control. */}
      <div className="flex flex-wrap items-center gap-3">
        {value.endKey === null ? (
          <Button
            variant="ghost"
            size="sm"
            className="-ml-2"
            onClick={() => {
              const d = new Date();
              d.setFullYear(d.getFullYear() + 1);
              set("endKey", d.toISOString().slice(0, 10));
            }}
          >
            <Plus />
            Add an end date
          </Button>
        ) : (
          <div className="flex items-center gap-2">
            {/* AS WIDE AS THE DAY BUTTONS ABOVE — seven 32px buttons and six
                4px gaps, 248px (Pavan, 2026-09-25). */}
            <div className="w-62">
              <DateKeyField value={value.endKey} placeholder="End date" onChange={(key) => set("endKey", key)} />
            </div>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Remove the end date"
              className="text-muted-foreground hover:text-destructive"
              onClick={() => set("endKey", null)}
            >
              <Trash2 />
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * THE NEXT DELIVERIES A FREQUENCY MAKES — from today, up to its end date.
 * Shared by every Create recurring rule (3PL, Customer Portal).
 */
export function nextHits(f: RuleFrequency, count = 4, from = startOfDay(new Date())): string[] {
  const sched = toSchedule(f);
  const end = f.endKey ? new Date(`${f.endKey}T00:00`) : null;
  const out: string[] = [];
  for (let i = 0; i < 400 && out.length < count; i++) {
    const d = new Date(from);
    d.setDate(d.getDate() + i);
    if (end && d > end) break;
    if (sched.hits(d)) out.push(dateKeyOf(d));
  }
  return out;
}

/**
 * NEXT 4 DELIVERIES — the strip pinned above a rule form's Create button
 * (Pavan, 2026-10-16), so what the rule will make is always in view.
 */
export function NextDeliveries({ keys }: { keys: string[] }) {
  const today = startOfDay(new Date());
  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-sm font-medium text-foreground">Next 4 deliveries</span>
      <div className="grid grid-cols-4 gap-2">
        {keys.length === 0 ? (
          <span className="col-span-4 text-sm text-muted-foreground">—</span>
        ) : (
          keys.map((k) => {
            const d = new Date(`${k}T00:00`);
            return (
              <div key={k} className="flex flex-col rounded-md border border-fp-outline-1 px-3 py-1.5">
                <span className="text-sm text-foreground">{DATE_FMT.format(d)}</span>
                <span className="text-xs text-muted-foreground">
                  {relativeLabel(Math.round((d.getTime() - today.getTime()) / 86_400_000), d)}
                </span>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

/* THE FREQUENCY UNIT IN ONE LINE (Pavan, 2026-10-20) — for the list's
   Repeats column and anywhere an order's repeat is named. */
const DAY_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
export function scheduleSummary(f: RuleFrequency): string {
  if (f.basis === "date") {
    if (!f.dates.length) return "";
    const th = (n: number) => `${n}${n % 10 === 1 && n !== 11 ? "st" : n % 10 === 2 && n !== 12 ? "nd" : n % 10 === 3 && n !== 13 ? "rd" : "th"}`;
    const doms = [...new Set(f.dates.map((k) => Number(k.slice(8, 10))))].sort((a, b) => a - b).map(th).join(", ");
    const every = f.dateRepeat ?? 1;
    return `${every === 0 ? "Once" : every === 1 ? "Every month" : `Every ${every} months`} · ${doms}`;
  }
  if (f.repeat === "cycle") return `Every ${(f.cycleWeeks ?? []).length || 2} weeks`;
  const days = f.dayMode === "daily" ? "Every day" : f.days.slice().sort().map((d) => DAY_SHORT[d]).join(", ");
  if (!days) return "";
  return f.repeat === "weekly" || f.dayMode === "daily" ? (f.dayMode === "daily" ? days : `Weekly · ${days}`) : `${f.repeat[0].toUpperCase()}${f.repeat.slice(1)} · ${days}`;
}

/** A FREQUENCY CARRIED AS TEXT — an order's `recurrence.frequency`, which
    `parseSchedule` reads back (Pavan, 2026-10-20: the order sheet now uses
    the rule's frequency unit). */
export const encodeFrequency = (f: RuleFrequency) => `rf:${JSON.stringify(f)}`;
export const decodeFrequency = (raw: string): RuleFrequency | null => {
  if (!raw.startsWith("rf:")) return null;
  try {
    return JSON.parse(raw.slice(3)) as RuleFrequency;
  } catch {
    return null;
  }
};

/** AN OLD CADENCE AS THE UNIT (Pavan, 2026-10-20) — orders saved with the
    former frequency list open on what they said. "Custom" and anything else
    unknown start blank. */
const DAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
export function frequencyFromLegacy(raw: string): RuleFrequency | null {
  const base = blankFrequency();
  if (raw === "Daily") return { ...base, dayMode: "daily", days: [0, 1, 2, 3, 4, 5, 6] };
  if (raw === "Every Weekday (Monday To Friday)") return { ...base, days: [1, 2, 3, 4, 5] };
  const w = /^Weekly On (\w+)$/.exec(raw);
  if (w && DAY_NAMES.includes(w[1])) return { ...base, days: [DAY_NAMES.indexOf(w[1])] };
  const m = /^Monthly On (\w+) (\w+)$/.exec(raw);
  if (m && DAY_NAMES.includes(m[2])) {
    const nth = ["First", "Second", "Third", "Fourth"].indexOf(m[1]) + 1;
    return { ...base, repeat: "monthly", monthWeeks: [nth || 1], days: [DAY_NAMES.indexOf(m[2])] };
  }
  const y = /^Annually On (\w+) (\d+)$/.exec(raw);
  if (y && MONTH_NAMES.includes(y[1])) {
    const mo = MONTH_NAMES.indexOf(y[1]);
    const now = new Date();
    const key = `${now.getFullYear()}-${String(mo + 1).padStart(2, "0")}-${String(Number(y[2])).padStart(2, "0")}`;
    return { ...base, basis: "date", dates: [key], dateRepeat: 12 };
  }
  return null;
}

