import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import type { Schedule } from "./recurring";

/*
  A SCHEDULE, AS A SHAPE RATHER THAN A SENTENCE.

  "Monthly On First Thursday" is precise and unreadable at a glance, and a
  reader scanning twenty rules is not reading — they are COMPARING. Seven
  letters with the live ones lit compare instantly: three rules that all run on
  Thursday look alike down the column, and the one that runs Monday to Friday
  does not.

  THE LETTERS SAY WHICH DAYS, THE LINE UNDER THEM SAYS HOW OFTEN. They are two
  different facts and neither can carry the other: the same lit Thursday is
  every week, every second week, or the first week of the month, and that is
  the whole difference between three schedules. The row alone would make them
  identical.

  SUNDAY FIRST, because the rule sheet's calendar is Sunday-first, and a week
  that starts on a different day in two places on one screen is two weeks.

  TWO LETTERS REPEAT — T for Tuesday and Thursday, S for Saturday and Sunday —
  which is what every calendar does and what position resolves. The full day
  name is the accessible name and the tooltip, so the ambiguity never reaches
  anyone who needs it resolved.

  A PATTERN THAT IS NOT A WEEKDAY HABIT GETS ONE WORD INSTEAD. Daily would
  light all seven, which is a row nobody needs to read; a yearly date lights
  none, which is a row that says nothing. Both are clearer as a single badge.
*/

const DAYS = [
  { letter: "S", name: "Sunday" },
  { letter: "M", name: "Monday" },
  { letter: "T", name: "Tuesday" },
  { letter: "W", name: "Wednesday" },
  { letter: "T", name: "Thursday" },
  { letter: "F", name: "Friday" },
  { letter: "S", name: "Saturday" },
];

export function ScheduleCell({
  schedule,
  className,
  roomy = false,
  emphasis = false,
}: {
  schedule: Schedule;
  className?: string;
  /** Bigger day badges and more air — the Recurring Orders list (Pavan,
      2026-10-01: "too tight"). */
  roomy?: boolean;
  /** LIFTED (Pavan, 2026-10-07 — "very dull") for a recommendation, where the
      frequency is the headline: larger badges in the info hue, and a cycle's
      weeks set apart as their own labelled rows. */
  emphasis?: boolean;
}) {
  if (emphasis) roomy = true;
  /* A LIT DAY IS THE ACCENT (Pavan, 2026-10-16) — the same violet the
     frequency picker marks a picked day with, so the list and the form say
     the same thing the same way (DS ui/2-rules "The accent"). */
  const lit = "bg-accent-violet text-accent-violet-foreground";
  /* A CUSTOM CYCLE IS ONE ROW PER WEEK (Pavan, 2026-10-06), each led by
     its week — W1, W2 — so the shape still compares down the column. */
  if (schedule.cycle) {
    return (
      <div className={cn("flex min-w-0 flex-col", roomy ? "gap-1.5" : "gap-1", className)}>
        <Tooltip>
          <TooltipTrigger asChild>
            <div
              className={cn(
                "flex w-fit cursor-default flex-col",
                emphasis ? "divide-y divide-border" : "gap-0.5"
              )}
              role="img"
              aria-label={schedule.label}
            >
              {schedule.cycle.map((week, w) => (
                <div
                  key={w}
                  className={cn(
                    "flex items-center",
                    roomy ? "gap-1" : "gap-0.5",
                    emphasis && "py-1.5 first:pt-0 last:pb-0"
                  )}
                >
                  <span
                    aria-hidden
                    className={cn(
                      "text-muted-foreground",
                      emphasis ? "w-14 text-xs font-medium text-foreground" : "w-6",
                      !emphasis && (roomy ? "text-xs" : "text-[11px]")
                    )}
                  >
                    {emphasis ? `Week ${w + 1}` : `W${w + 1}`}
                  </span>
                  {DAYS.map((d, i) => (
                    <span
                      key={i}
                      aria-hidden
                      className={cn(
                        "flex items-center justify-center rounded-sm font-medium tabular-nums",
                        roomy ? "size-6 text-xs" : "size-5 text-[11px]",
                        week.includes(i) ? lit : "text-muted-foreground/50"
                      )}
                    >
                      {d.letter}
                    </span>
                  ))}
                </div>
              ))}
            </div>
          </TooltipTrigger>
          <TooltipContent>{schedule.label}</TooltipContent>
        </Tooltip>
        <span className={cn("truncate", emphasis ? "text-sm font-medium text-foreground" : "text-xs text-muted-foreground")}>
          {schedule.cadence}
        </span>
      </div>
    );
  }
  const on = new Set(schedule.days);
  const live = DAYS.filter((_, i) => on.has(i)).map((d) => d.name);

  return (
    <div className={cn("flex min-w-0 flex-col", roomy ? "gap-1.5" : "gap-1", className)}>
      {schedule.badge ? (
        /* ONE WORD IN PLACE OF THE ROW. Sized to match a lit day badge so the
           column keeps one rhythm whichever shape a row takes. */
        <span
          className={cn(
            "inline-flex w-fit items-center rounded-sm px-1.5 font-medium",
            lit,
            roomy ? "h-6 text-xs" : "h-5 text-[11px]"
          )}
        >
          {schedule.badge}
        </span>
      ) : (
        <Tooltip>
          <TooltipTrigger asChild>
            <div
              className={cn("flex w-fit cursor-default", roomy ? "gap-1" : "gap-0.5")}
              role="img"
              aria-label={
                live.length > 0
                  ? `Runs on ${live.join(", ")}`
                  : "No weekday pattern"
              }
            >
              {DAYS.map((d, i) => (
                <span
                  key={i}
                  aria-hidden
                  className={cn(
                    "flex items-center justify-center rounded-sm font-medium tabular-nums",
                    roomy ? "size-6 text-xs" : "size-5 text-[11px]",
                    on.has(i)
                      ? /* QUIETER (Pavan, 2026-10-05): a soft grey square and
                           dark ink, not a solid black one — the column was
                           taking the whole row's attention. */
                        lit
                      : /* AN UNLIT DAY IS STILL A DAY. Dropping it would make
                           the row a different width per rule and destroy the
                           comparison the row exists for; so it stays, as a faint
                           letter with no square. */
                        "text-muted-foreground/50"
                  )}
                >
                  {d.letter}
                </span>
              ))}
            </div>
          </TooltipTrigger>
          <TooltipContent>{schedule.label}</TooltipContent>
        </Tooltip>
      )}
      <span className={cn("truncate", emphasis ? "text-sm font-medium text-foreground" : "text-xs text-muted-foreground")}>
        {schedule.cadence}
      </span>
    </div>
  );
}

import { cn } from "@/lib/utils";
import * as React from "react";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { StatusChip } from "@/components/ui/status-chip";
import { dateKeyOf, startOfDay } from "../data";
import { BarColumns, BarList, Panel, StatTile, DASHBOARD_GROUND } from "../DashboardParts";
import { DateRangeFilter, type DateRange } from "./DateRangeFilter";
import {
  BROKER_ORDERS,
  BROKER_STATUSES,
  BROKER_STATUS_TONE,
  ORDER_TYPE_FILTERS,
  customerTotal,
  quoteTotal,
  type BrokerOrder,
  type BrokerStatus,
  LINE_SCOPES,
  inLineScope,
  type LineScope,
} from "./orders";
import { vendorName } from "./vendors";
import { cuttableDays, ordersFromPrograms } from "./recurringOrders";
import { usePrograms } from "./recurringPrograms";

/*
  3PL DASHBOARD (Pavan, 2026-10-05) — the module's overview and its landing
  page. Read from the same orders the board shows (the seed plus what the
  recurring rules cut for the range), in the same line and date range, so
  every number here is the number the list opens on.

  WHAT IT ASKS, top to bottom: how much is live and what it is worth · where
  the work is sitting · when it lands · what kind it is · who it is for and
  who carries it · what needs somebody now.
*/

export interface ThreePLDrill {
  line: LineScope;
  range: DateRange;
  facets: string[];
}

const MONEY = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
});
const DAY_FMT = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });

/** The status filter's word for a lane — Draft is "Created / Draft" there. */
const statusFacet = (s: BrokerStatus) =>
  `status:${s === "Draft" ? "Created / Draft" : s}`;

/** Live = still being worked: not settled, not canceled. */
const LIVE: BrokerStatus[] = BROKER_STATUSES.filter(
  (s) => s !== "Synced" && s !== "Canceled"
);
/** Needs somebody now: not yet out, stuck, held, or a failed sync. */
const NEEDS_ACTION: BrokerStatus[] = ["Draft", "Blocked", "Review", "Partially Synced"];

/** What the held partner charges, when one holds it — the board's own sum. */
function costOf(r: BrokerOrder): number | null {
  if (!r.vendorId) return null;
  const q = r.quotes.find((x) => x.vendorId === r.vendorId);
  return q ? quoteTotal(q, r.lines, !r.loadOrder) : null;
}

export function ThreePLDashboard({
  onDrill,
  onOpenOrder,
}: {
  /** Open Delivery Orders narrowed to these rows. */
  onDrill: (d: ThreePLDrill) => void;
  /** Open one order's sheet. */
  onOpenOrder: (id: string) => void;
}) {
  const [line, setLine] = React.useState<LineScope>("All");
  const [range, setRange] = React.useState<DateRange>(() => {
    const today = startOfDay(new Date());
    const to = new Date(today);
    to.setDate(to.getDate() + 6);
    return { from: today, to };
  });
  const [programs] = usePrograms();

  const rows = React.useMemo(() => {
    const cut = ordersFromPrograms(
      programs,
      cuttableDays(range.from, range.to),
      new Set(BROKER_ORDERS.map((r) => r.id)),
      Math.max(...BROKER_ORDERS.map((r) => Number(r.orderNo.slice(2)) || 0)) + 1
    );
    const from = dateKeyOf(range.from);
    const to = dateKeyOf(range.to);
    return [...cut, ...BROKER_ORDERS].filter(
      (r) => inLineScope(line, r.serviceLine) && r.dateKey >= from && r.dateKey <= to
    );
  }, [programs, range, line]);

  const drill = (facets: string[], at: DateRange = range) =>
    onDrill({ line, range: at, facets });

  const live = rows.filter((r) => LIVE.includes(r.status));
  const priced = live
    .map((r) => ({ r, cost: costOf(r) }))
    .filter((x): x is { r: BrokerOrder; cost: number } => x.cost !== null);
  const cost = priced.reduce((s, x) => s + x.cost, 0);
  const revenue = priced.reduce((s, x) => s + customerTotal(x.r.lines, x.r.orderFees), 0);
  const margin = revenue - cost;
  const needs = rows.filter((r) => NEEDS_ACTION.includes(r.status));

  /* Where the work is sitting — the board's lanes, in its order. */
  const byLane = BROKER_STATUSES.filter((s) => s !== "Canceled").map((s) => {
    const n = rows.filter((r) => r.status === s).length;
    return {
      key: s,
      label: s === "Draft" ? "Orders" : s,
      value: n,
      detail: `${n} ${n === 1 ? "order" : "orders"}`,
      onOpen: n ? () => drill([statusFacet(s)]) : undefined,
    };
  });

  /* When it lands — one bar per day of the range. */
  const days: Date[] = [];
  for (let d = new Date(range.from); d <= range.to; d.setDate(d.getDate() + 1))
    days.push(new Date(d));
  const byDay = days.map((d) => {
    const key = dateKeyOf(d);
    const n = rows.filter((r) => r.dateKey === key).length;
    return {
      key,
      label: DAY_FMT.format(d),
      value: n,
      detail: `${n} ${n === 1 ? "order" : "orders"}`,
      onOpen: n ? () => drill([], { from: d, to: d }) : undefined,
    };
  });

  /* What kind of work — the Order Types facet's own words. */
  const typeOf = (r: BrokerOrder) =>
    r.orderType === "Asset Movement" ? "Movement" : r.orderType;
  const byType = [...new Set(rows.map(typeOf))]
    .map((t) => {
      const n = rows.filter((r) => typeOf(r) === t).length;
      const facet = (ORDER_TYPE_FILTERS as readonly string[]).includes(t);
      return {
        key: t,
        label: t,
        value: n,
        detail: `${n} ${n === 1 ? "order" : "orders"}`,
        onOpen: facet ? () => drill([`orderTypes:${t}`]) : undefined,
      };
    })
    .sort((a, b) => b.value - a.value);

  /* Who it is for — billed to the customer, priced orders only. */
  const byCustomer = [...new Set(priced.map((x) => x.r.customer.title))]
    .map((c) => {
      const mine = priced.filter((x) => x.r.customer.title === c);
      const v = mine.reduce((s, x) => s + customerTotal(x.r.lines, x.r.orderFees), 0);
      return {
        key: c,
        label: c,
        value: v,
        detail: `${MONEY.format(v)} · ${mine.length} priced ${mine.length === 1 ? "order" : "orders"}`,
        onOpen: () => drill([`customer:${c}`]),
      };
    })
    .sort((a, b) => b.value - a.value)
    .slice(0, 6);

  /* Who carries it — what each partner is paid, on the orders they hold. */
  const byPartner = [...new Set(priced.map((x) => x.r.vendorId as string))]
    .map((id) => {
      const mine = priced.filter((x) => x.r.vendorId === id);
      const v = mine.reduce((s, x) => s + x.cost, 0);
      return { id, name: vendorName(id), loads: mine.length, cost: v };
    })
    .sort((a, b) => b.cost - a.cost);

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto">
      {/* THE SCOPE, THE BOARD'S OWN — the line and the date range. */}
      <div className="flex shrink-0 flex-wrap items-center justify-between gap-3">
        <ToggleGroup
          type="single"
          size="sm"
          variant="outline"
          value={line}
          onValueChange={(v) => v && setLine(v as LineScope)}
        >
          {LINE_SCOPES.map((l) => (
            <ToggleGroupItem key={l} value={l} className="px-3">
              {l}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
        <DateRangeFilter value={range} onChange={setRange} />
      </div>

      {/* WHITE CARDS ON THEIR GROUND — see DashboardParts. */}
      <div className={cn("flex shrink-0 flex-col gap-3", DASHBOARD_GROUND)}>
      <div className="grid shrink-0 grid-cols-2 gap-3 lg:grid-cols-4">
        <StatTile
          label="Live orders"
          value={live.length.toLocaleString()}
          note={`${priced.length} priced · ${live.length - priced.length} unpriced`}
          onOpen={() => drill(LIVE.map(statusFacet))}
        />
        <StatTile
          label="Estimated partner cost"
          value={MONEY.format(cost)}
          note={`${priced.length} orders a partner holds`}
          onOpen={() =>
            drill([...new Set(priced.map((x) => x.r.status))].map(statusFacet))
          }
        />
        <StatTile
          label="Estimated margin"
          value={MONEY.format(margin)}
          note={revenue ? `${((margin / revenue) * 100).toFixed(1)}% of revenue` : "Nothing priced yet"}
        />
        <StatTile
          label="Needs action"
          value={needs.length.toLocaleString()}
          note="Draft · Blocked · Review · Partially Synced"
          onOpen={() => drill(NEEDS_ACTION.map(statusFacet))}
        />
      </div>

      <div className="grid shrink-0 gap-3 lg:grid-cols-2">
        <Panel title="Orders by lane" aside={`${rows.length} orders`}>
          <BarColumns data={byLane} />
        </Panel>
        <Panel title="Orders by delivery date" aside={`${days.length} days`}>
          <BarColumns data={byDay} />
        </Panel>
      </div>

      <div className="grid shrink-0 gap-3 lg:grid-cols-2">
        <Panel title="Order types" aside="share of orders">
          <BarList data={byType} share />
        </Panel>
        <Panel title="Top customers" aside="estimated customer price">
          <BarList data={byCustomer} format={(n) => MONEY.format(n)} />
        </Panel>
      </div>

      <div className="grid shrink-0 gap-3 lg:grid-cols-2">
        <Panel title="Partner spend" aside={`${byPartner.length} partners holding orders`}>
          {byPartner.length === 0 ? (
            <p className="py-6 text-center text-sm text-muted-foreground">
              No partner holds an order in this range.
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow className="hover:bg-transparent">
                  <TableHead className="px-2 text-xs">Partner</TableHead>
                  <TableHead className="px-2 text-xs">Loads</TableHead>
                  <TableHead className="px-2 text-xs">Cost</TableHead>
                  <TableHead className="px-2 text-xs">Share</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {byPartner.map((p) => (
                  <TableRow
                    key={p.id}
                    className="cursor-pointer"
                    onClick={() => drill([`vendor:${p.name}`])}
                  >
                    <TableCell className="px-2">{p.name}</TableCell>
                    <TableCell className="px-2 tabular-nums">{p.loads}</TableCell>
                    <TableCell className="px-2 tabular-nums">{MONEY.format(p.cost)}</TableCell>
                    <TableCell className="px-2 tabular-nums text-muted-foreground">
                      {cost ? `${Math.round((p.cost / cost) * 100)}%` : "—"}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </Panel>

        <Panel title="Needs attention" aside={`${needs.length} orders`}>
          {needs.length === 0 ? (
            <p className="py-6 text-center text-sm text-muted-foreground">
              Nothing waiting on anybody.
            </p>
          ) : (
            <Table>
              <TableHeader>
                <TableRow className="hover:bg-transparent">
                  <TableHead className="px-2 text-xs">Order</TableHead>
                  <TableHead className="px-2 text-xs">Customer</TableHead>
                  <TableHead className="px-2 text-xs">Status</TableHead>
                  <TableHead className="px-2 text-xs">Date</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {needs.slice(0, 8).map((r) => (
                  <TableRow
                    key={r.id}
                    className="cursor-pointer"
                    onClick={() => {
                      /* ON ITS OWN DAY, so the board has it loaded. */
                      const [y, m, d] = r.dateKey.split("-").map(Number);
                      const day = new Date(y, m - 1, d);
                      drill([], { from: day, to: day });
                      onOpenOrder(r.id);
                    }}
                  >
                    <TableCell className="px-2 tabular-nums">{r.orderNo}</TableCell>
                    <TableCell className="max-w-40 truncate px-2">{r.customer.title}</TableCell>
                    <TableCell className="px-2">
                      <StatusChip tone={BROKER_STATUS_TONE[r.status]} variant="soft">
                        {r.status}
                      </StatusChip>
                    </TableCell>
                    <TableCell className="px-2 tabular-nums text-muted-foreground">
                      {r.date.title}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </Panel>
      </div>
      </div>
    </div>
  );
}

import * as React from "react";
import { MapPin } from "lucide-react";
import { StatusChip } from "@/components/ui/status-chip";
import { cn } from "@/lib/utils";
import { PLACES, daysFromToday } from "./directoryCore";
import type { Vendor } from "./vendors";
import type { StatusKind } from "../statusKind";

/*
  Vendors on a map — list left, plot right.

  WHY A MAP AT ALL. Every other question about a vendor is answered by a
  column; "who is near this job" is not, because near is a relationship between
  two places and a table can only sort by one of them. A dispatcher looking for
  cover in Bakersfield is doing geometry, and a list of eighty rows sorted by
  name is the wrong instrument for it.

  IT IS NOT A REAL MAP, and it does not pretend to be. There is no tile
  provider in this prototype and adding one would put a network dependency and
  an API key into a file that is meant to open from disk. What this draws is
  the geography the data actually has: the seed's `PLACES` are real cities with
  real coordinates, so the plot is a true relative arrangement of the west
  coast — Fresno is south of Sacramento and inland of Salinas here, because it
  is. Swap the backdrop for tiles and the pins do not move.

  THE TWO HALVES ARE ONE SELECTION. Hovering a row lights its pin and hovering
  a pin lights its row; clicking either opens the vendor. A map beside a list
  that do not know about each other are two things on a screen, not a view.
*/

/** Latitude/longitude bounds of the seeded geography, with a little air. */
const BOUNDS = (() => {
  const lats = PLACES.map((p) => p.lat);
  const lngs = PLACES.map((p) => p.lng);
  const pad = 1.2;
  return {
    minLat: Math.min(...lats) - pad,
    maxLat: Math.max(...lats) + pad,
    minLng: Math.min(...lngs) - pad,
    maxLng: Math.max(...lngs) + pad,
  };
})();

/** A vendor's own city, from the `City, ST` its record carries. */
function placeOf(v: Vendor) {
  const city = (v.city ?? v.base.split(",")[0] ?? "").trim();
  return PLACES.find((p) => p.city === city) ?? null;
}

/** Percent from the left / top of the plot. Latitude runs the other way. */
function project(lat: number, lng: number) {
  return {
    left: ((lng - BOUNDS.minLng) / (BOUNDS.maxLng - BOUNDS.minLng)) * 100,
    top: ((BOUNDS.maxLat - lat) / (BOUNDS.maxLat - BOUNDS.minLat)) * 100,
  };
}

/**
 * A pin's colour says whether the vendor is USABLE, which is the only thing
 * worth colouring on a map somebody opens to find cover: inactive or lapsed is
 * the answer that changes what they do next.
 */
function toneOf(v: Vendor): StatusKind {
  if (!v.active) return "neutral";
  const days = daysFromToday(v.complianceValidTo);
  if (days !== null && days < 0) return "critical";
  if (v.availabilityStatus !== "Available") return "caution";
  return "success";
}

const PIN_FILL: Record<string, string> = {
  success: "bg-status-success",
  caution: "bg-fp-banner-accent-caution",
  critical: "bg-status-failed",
  neutral: "bg-muted-foreground",
};

export function VendorMapView({
  vendors,
  onOpenVendor,
}: {
  vendors: Vendor[];
  onOpenVendor: (v: Vendor) => void;
}) {
  const [hovered, setHovered] = React.useState<string | null>(null);

  /* Several vendors share a city, so pins are grouped by place and fanned —
     one dot per city with eight carriers under it is a map that hides the
     thing it was opened to show. */
  const groups = React.useMemo(() => {
    const by = new Map<string, { lat: number; lng: number; city: string; rows: Vendor[] }>();
    vendors.forEach((v) => {
      const p = placeOf(v);
      if (!p) return;
      const key = p.city;
      const g = by.get(key) ?? { lat: p.lat, lng: p.lng, city: p.city, rows: [] };
      g.rows.push(v);
      by.set(key, g);
    });
    return [...by.values()];
  }, [vendors]);

  const plotted = groups.reduce((n, g) => n + g.rows.length, 0);

  return (
    <div className="flex h-full min-h-0 gap-4">
      {/* ── the list ─────────────────────────────────────────────────── */}
      <div className="flex min-h-0 w-[340px] shrink-0 flex-col overflow-hidden rounded-md border border-fp-outline-1">
        <div className="shrink-0 border-b border-fp-outline-1 bg-fp-table-header px-3 py-2 text-xs font-medium text-muted-foreground">
          {vendors.length} {vendors.length === 1 ? "vendor" : "vendors"}
          {plotted < vendors.length && ` · ${vendors.length - plotted} without a mapped city`}
        </div>
        <ul className="min-h-0 flex-1 overflow-auto">
          {vendors.map((v) => {
            const p = placeOf(v);
            return (
              <li key={v.id}>
                <button
                  type="button"
                  onMouseEnter={() => setHovered(v.id)}
                  onMouseLeave={() => setHovered(null)}
                  onFocus={() => setHovered(v.id)}
                  onBlur={() => setHovered(null)}
                  onClick={() => onOpenVendor(v)}
                  className={cn(
                    "flex w-full flex-col gap-0.5 border-b border-fp-outline-1 px-3 py-2.5 text-left outline-none transition-colors last:border-b-0",
                    "hover:bg-fp-row-hover focus-visible:bg-fp-row-hover",
                    hovered === v.id && "bg-fp-row-hover"
                  )}
                >
                  <span className="flex items-center gap-2">
                    <span
                      aria-hidden
                      className={cn("size-2 shrink-0 rounded-full", PIN_FILL[toneOf(v)])}
                    />
                    <span className="truncate text-sm font-medium text-foreground">
                      {v.name}
                    </span>
                  </span>
                  <span className="truncate pl-4 text-xs text-muted-foreground">
                    {p ? v.base : `${v.base} · not on the map`} ·{" "}
                    {v.businessLines.join(", ") || "no business lines"}
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      </div>

      {/* ── the plot ─────────────────────────────────────────────────── */}
      <div className="relative min-h-0 flex-1 overflow-hidden rounded-md border border-fp-outline-1 bg-fp-board-lane">
        {/* A GRATICULE, NOT A DECORATION. Evenly spaced lines are what tells
            the eye this is a coordinate space rather than a diagram; without
            them the pins read as an arbitrary scatter. */}
        <svg aria-hidden className="absolute inset-0 size-full">
          <defs>
            <pattern id="fp-map-grid" width="48" height="48" patternUnits="userSpaceOnUse">
              <path
                d="M 48 0 L 0 0 0 48"
                fill="none"
                stroke="currentColor"
                strokeWidth="1"
                className="text-fp-outline-1"
              />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#fp-map-grid)" />
        </svg>

        {groups.map((g) => {
          const pos = project(g.lat, g.lng);
          return (
            <div
              key={g.city}
              className="absolute -translate-x-1/2 -translate-y-full"
              style={{ left: `${pos.left}%`, top: `${pos.top}%` }}
            >
              <div className="flex flex-col items-center gap-1">
                {/* The carriers in this city, fanned so each is its own target. */}
                <div className="flex max-w-[168px] flex-wrap justify-center gap-1">
                  {g.rows.map((v) => (
                    <button
                      key={v.id}
                      type="button"
                      title={`${v.name} — ${v.base}`}
                      aria-label={`${v.name}, ${v.base}`}
                      onMouseEnter={() => setHovered(v.id)}
                      onMouseLeave={() => setHovered(null)}
                      onFocus={() => setHovered(v.id)}
                      onBlur={() => setHovered(null)}
                      onClick={() => onOpenVendor(v)}
                      className={cn(
                        "grid size-5 place-items-center rounded-full border-2 border-fp-surface-1b outline-none transition-transform",
                        PIN_FILL[toneOf(v)],
                        "hover:scale-125 focus-visible:scale-125 focus-visible:ring-2 focus-visible:ring-ring/50",
                        hovered === v.id && "scale-150 ring-2 ring-ring/50"
                      )}
                    >
                      <MapPin className="size-2.5 text-fp-surface-1b" />
                    </button>
                  ))}
                </div>
                <span className="rounded-sm bg-fp-surface-1b/90 px-1.5 text-[11px] font-medium text-foreground">
                  {g.city}
                  <span className="ml-1 text-muted-foreground">{g.rows.length}</span>
                </span>
              </div>
            </div>
          );
        })}

        {/* THE KEY IS PART OF THE MAP. Four colours with no legend is a puzzle. */}
        <div className="absolute bottom-3 left-3 flex flex-wrap items-center gap-x-3 gap-y-1 rounded-md border border-fp-outline-1 bg-fp-surface-1b/95 px-3 py-2">
          {(
            [
              ["success", "Available"],
              ["caution", "Limited or unavailable"],
              ["critical", "Compliance expired"],
              ["neutral", "Inactive"],
            ] as const
          ).map(([tone, label]) => (
            <span key={tone} className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <span aria-hidden className={cn("size-2 rounded-full", PIN_FILL[tone])} />
              {label}
            </span>
          ))}
        </div>

        {vendors.length === 0 && (
          <div className="absolute inset-0 grid place-items-center">
            <StatusChip tone="neutral" variant="soft">
              No vendors match the filters applied
            </StatusChip>
          </div>
        )}
      </div>
    </div>
  );
}

import { Check, FileText, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { SheetSection } from "@/components/side-sheet/parts";
import { MONEY } from "../data";
import {
  TableCellInput,
  TableRequiredLabel,
} from "@/components/form-layout/table-cells";
import { FileUpload } from "@/components/form-layout/FileUpload";
import { CELL, RecordSheet } from "../RecordSheet";
import {
  billableGal,
  quoteLineTotal,
  quoteLineChargeRate,
  quoteTotal,
  type OrderLine,
  type QuoteLine,
  type VendorQuote,
} from "./orders";

/**
 * ONE PARTNER'S QUOTE, IN FULL — the working behind the TLC on its row.
 *
 * The vendor table gives every partner one number, which is the right amount to
 * compare on and not enough to decide on: a quote is a rate and a margin on
 * every line, plus the charges that ride on the run, plus whatever the partner
 * attached and said. That belongs somewhere you go to deliberately, not in a
 * column, so it is a second sheet over the order.
 *
 * TWO MODES, ONE LAYOUT.
 *
 * `review` is a quote the partner sent: every figure is theirs, so nothing is
 * editable and the decision is the only thing on offer — Accept or Reject.
 *
 * `draft` is the broker writing one down on the partner's behalf, which is what
 * happens when the price was agreed on a call. The same cells, editable. There
 * is no Reject: you cannot turn down a quote you are still typing.
 *
 * THE CELLS ARE THE ORDER SHEET'S CELLS. Same `TableCellInput`, same A / B / C
 * lettering, same `TLC = A×(B+C)` in the header — a reader who has seen Vendor
 * Pricing downstairs has already learnt this table. It prices on REQUESTED
 * gallons, where Vendor Pricing prices on delivered: at quote time nothing has
 * been delivered, and a quote against a number that does not exist yet would be
 * a quote about nothing.
 */

/**
 * WHAT RIDES ON THE RUN AND NOT ON THE PRODUCT — which is freight alone.
 *
 * Fees and taxes used to be here beside it, one figure each for the whole
 * quote. They are charged on what is in the tank, so they moved onto the lines
 * as (D) and (E) and a quote can now say that the tax on the dyed diesel is
 * not the tax on the DEF next to it. Freight stays: it is the truck, not the
 * cargo. (Pavan, 2026-09-22.)
 */
const ORDER_CHARGES = [
  { key: "freight", label: "Freight" },
] as const satisfies readonly {
  key: keyof Pick<VendorQuote, "freight">;
  label: string;
}[];

/** One helper, app-wide — `MONEY` in `../data`. */
const money = MONEY;

const num = (v: string) => {
  const n = Number(v.replace(/[^0-9.-]/g, ""));
  return Number.isFinite(n) ? n : 0;
};

/** A stand-in for what the partner attached. Read-only in `review`. */
export interface QuoteAttachment {
  name: string;
}

export function VendorQuoteSheet({
  open,
  onOpenChange,
  vendorName,
  mode,
  lines,
  quote,
  onQuoteChange,
  /**
   * Whether the partner is supplying the product as well as hauling it — the
   * order sheet's `chargesBase`. With a load order the product is already the
   * broker's, so the base price is struck and only the run's charges stand.
   */
  chargesBase = true,
  notes,
  onNotesChange,
  attachments = [],
  onAccept,
  onReject,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  vendorName: string;
  mode: "review" | "draft";
  lines: OrderLine[];
  quote: VendorQuote | null;
  onQuoteChange?: (next: VendorQuote) => void;
  chargesBase?: boolean;
  notes?: string;
  onNotesChange?: (v: string) => void;
  attachments?: QuoteAttachment[];
  onAccept: () => void;
  onReject?: () => void;
}) {
  const editable = mode === "draft";

  /** Every line the order has, with the partner's price on it where there is one. */
  const priced = lines.map((l) => ({
    line: l,
    ql: quote?.lines.find((x) => x.asset === l.asset) ?? null,
  }));

  const total = quote ? quoteTotal(quote, lines, chargesBase) : 0;

  const putLine = (asset: string, patch: Partial<QuoteLine>) => {
    if (!quote || !onQuoteChange) return;
    const has = quote.lines.some((x) => x.asset === asset);
    onQuoteChange({
      ...quote,
      lines: has
        ? quote.lines.map((x) => (x.asset === asset ? { ...x, ...patch } : x))
        : [...quote.lines, { asset, ratePerGal: 0, rates: {}, ...patch }],
    });
  };

  const putCharge = (key: (typeof ORDER_CHARGES)[number]["key"], v: number) => {
    if (!quote || !onQuoteChange) return;
    onQuoteChange({ ...quote, [key]: v });
  };

  return (
    <RecordSheet
      /* WIDTH FROM ITS TABLES (Pavan, 2026-10-15): pricing table = asset name,
         product pick, four figures (req. gal, rate, adds, TLC). */
      fit={{ tables: [[CELL.name, CELL.pick, CELL.number, CELL.number, CELL.number, CELL.number]] }}
      /* OVER THE ORDER SHEET — see `level` on `RecordSheet`. */
      level={2}
      open={open}
      onOpenChange={onOpenChange}
      mode="create"
      editTitle={`${vendorName} · Pricing`}
      createTitle={`${vendorName} · Pricing`}
      createAction="Accept"
      showCancel={false}
      footerAside={
        <span className="text-sm text-foreground">
          <span className="text-muted-foreground">Total landing cost</span>{" "}
          <span className="font-medium tabular-nums">{money(total)}</span>
        </span>
      }
      /* REJECT IS ONLY A REVIEW'S BUSINESS. You cannot turn down a quote you
         are still typing, so `draft` gets Accept alone. */
      /* THE TWO ANSWERS, COLOURED AS ANSWERS.

         This pair is the one place in the product where a decision is the whole
         of the screen — the sheet exists to be said yes or no to — so the two
         buttons carry the outcome rather than the usual primary/secondary
         weight. Accept fills green; Reject stays outlined and takes the
         destructive colour on its label and rim only, which is the DS's rule
         for a destructive act (`docs/ds/ui/2-rules.md` §9).

         IT USES THE STATUS TOKEN, not a raw green: `--status-success` with its
         own foreground. NOTE FOR THE DS — §9 reserves fills for brand and gives
         status colours no usage rule, so this is the first fill outside that.
         The rule needs amending or this pair needs a token of its own. */
      footerPrimary={
        <div className="flex items-center gap-3">
          {mode === "review" && onReject && (
            <Button
              variant="outline"
              className="border-destructive/50 text-destructive hover:bg-destructive/5 hover:text-destructive"
              onClick={onReject}
            >
              <X /> Reject
            </Button>
          )}
          <Button
            className="bg-status-success text-status-success-foreground hover:bg-status-success/90"
            onClick={onAccept}
          >
            <Check /> Accept
          </Button>
        </div>
      }
      onSubmit={onAccept}
    >
      <SheetSection title="Pricing" flush>
        <table className="w-full table-fixed border-collapse">
          {/* EIGHT COLUMNS, NOT SIX. The partner's fee and tax are per gallon
              and per product now, so they are cells on the row like the rate
              and the margin beside them — and the four narrow money columns
              are all one width, because they hold the same kind of figure. */}
          <colgroup>
            <col />
            <col className="w-[22%]" />
            <col className="w-[112px]" />
            <col className="w-[128px]" />
            <col className="w-[128px]" />
            <col className="w-[144px]" />
          </colgroup>
          <thead>
            <tr className="border-b border-border bg-fp-table-header">
              <th className="px-3 py-2.5 text-left">
                <TableRequiredLabel>Asset name</TableRequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <TableRequiredLabel>Product</TableRequiredLabel>
              </th>
              <th className="px-3 py-2.5">
                <TableRequiredLabel>Req. gal (A)</TableRequiredLabel>
              </th>
              <th className="px-3 py-2.5">
                <TableRequiredLabel>Rate/gal (B)</TableRequiredLabel>
              </th>
              {/* ONE COLUMN FOR EVERYTHING ON TOP OF THE RATE, and it is read
                  back rather than typed (Pavan, 2026-09-22). A product can
                  carry several margins, several taxes and several fees now, so
                  three fixed columns could hold the first of each and nothing
                  after it. They are typed where they are compared — the order
                  sheet's Pricing unit, which lays the partner's figure beside
                  the broker's row for row. */}
              <th className="px-3 py-2.5">
                <TableRequiredLabel>Adds/gal (C)</TableRequiredLabel>
              </th>
              <th
                className="px-3 py-2.5"
                title="Total landing cost — requested gallons x (rate + everything added)"
              >
                <TableRequiredLabel>TLC A×(B+C)</TableRequiredLabel>
              </th>
            </tr>
          </thead>
          <tbody>
            {priced.map(({ line, ql }, i) => (
              <tr key={i} className="h-12 border-b border-border">
                <td className="truncate px-3 text-sm text-foreground">
                  {line.asset || "—"}
                </td>
                <td className="truncate px-3 text-sm text-muted-foreground">
                  {line.product}
                </td>
                <td className="px-3 text-sm tabular-nums text-muted-foreground">
                  {line.topOff ? "Top-off" : billableGal(line).toLocaleString()}
                </td>
                {editable ? (
                  <>
                    <td className="relative p-0">
                      <TableCellInput
                        value={ql ? String(ql.ratePerGal) : ""}
                        placeholder="0.000"
                        numeric
                        prefix="$"
                        aria-label={`Rate per gallon for line ${i + 1}`}
                        onChange={(v) =>
                          putLine(line.asset, { ratePerGal: num(v) })
                        }
                      />
                    </td>
                    <td className="px-3 text-sm tabular-nums text-muted-foreground">
                      {ql
                        ? `$${quoteLineChargeRate(ql, line).toFixed(4)}`
                        : "—"}
                    </td>
                  </>
                ) : (
                  <>
                    <td className="px-3 text-sm tabular-nums text-muted-foreground">
                      {ql ? `$${ql.ratePerGal.toFixed(4)}` : "—"}
                    </td>
                    <td className="px-3 text-sm tabular-nums text-muted-foreground">
                      {ql
                        ? `$${quoteLineChargeRate(ql, line).toFixed(4)}`
                        : "—"}
                    </td>
                  </>
                )}
                <td className="px-3 text-sm font-medium tabular-nums text-foreground">
                  {ql ? money(quoteLineTotal(ql, line)) : money(0)}
                </td>
              </tr>
            ))}
          </tbody>
          {/* WHAT RIDES ON THE RUN, THEN THE TOTAL.

              NO BASE-PRICE ROW. It was the sum of the TLC column directly
              above it — the same figure twice, one line apart, with the second
              one named something the first is not called. The lines add up in
              plain sight; a subtotal of three rows you can already see is a row
              that only makes the reader check the addition. */}
          <tfoot>
            {ORDER_CHARGES.map((c) => (
              <tr key={c.key} className="h-11 border-b border-border">
                <td colSpan={5} className="px-3 text-sm text-muted-foreground">
                  {c.label}
                </td>
                {editable ? (
                  <td className="relative p-0">
                    <TableCellInput
                      value={quote ? String(quote[c.key]) : ""}
                      placeholder="0"
                      numeric
                      prefix="$"
                      aria-label={c.label}
                      onChange={(v) => putCharge(c.key, num(v))}
                    />
                  </td>
                ) : (
                  <td className="px-3 text-sm tabular-nums text-muted-foreground">
                    {money(quote ? quote[c.key] : 0)}
                  </td>
                )}
              </tr>
            ))}
            <tr className="h-12">
              <td colSpan={5} className="px-3 text-sm font-medium text-foreground">
                Total landing cost
              </td>
              <td className="px-3 text-sm font-semibold tabular-nums text-foreground">
                {money(total)}
              </td>
            </tr>
          </tfoot>
        </table>
      </SheetSection>

      {/* WHAT THEY SENT WITH IT. A quote arrives with a rate sheet or a signed
          agreement behind it as often as not, and the broker accepting the
          price is the person who has to have read them.

          NOTHING EXTRA IS ONE FACT, NOT TWO. Most quotes are numbers alone, and
          two headed sections each reporting their own absence took a third of
          the sheet to say the partner sent nothing else. One line says it. The
          sections come back the moment either has something in it, and in
          `draft` they are always there — they are fields to fill. */}
      {!editable && attachments.length === 0 && !notes?.trim() ? (
        <p className="text-sm text-muted-foreground">
          Vendor has not added additional supporting docs or notes.
        </p>
      ) : (
        /* ONE GROUP, NOT TWO. A rate sheet and the sentence explaining it are
           the same thing — everything the partner sent WITH the price — and
           two headed cards said that twice, at the cost of a second heading
           and 40px of gap between two halves of one thought. */
        <SheetSection title="Supporting documents and notes">
          {editable ? (
            <FileUpload variant="field" label="Attach a document" note="" />
          ) : attachments.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              No documents attached
            </p>
          ) : (
            <ul className="grid grid-cols-3 gap-3">
              {attachments.map((a) => (
                <li
                  key={a.name}
                  className="flex items-center gap-2 rounded-lg border border-border px-3 py-2.5"
                >
                  <FileText className="size-4 shrink-0 text-muted-foreground" />
                  <span className="truncate text-sm text-foreground">
                    {a.name}
                  </span>
                </li>
              ))}
            </ul>
          )}

          {editable ? (
            <Textarea
              value={notes ?? ""}
              onChange={(e) => onNotesChange?.(e.target.value)}
              placeholder="Anything the price depends on — a wait-time cap, a fuel index, a date it expires."
              className="min-h-24"
            />
          ) : notes?.trim() ? (
            <p className="text-sm text-foreground">{notes}</p>
          ) : (
            <p className="text-sm text-muted-foreground">No note</p>
          )}
        </SheetSection>
      )}
    </RecordSheet>
  );
}

import { CELL } from "../RecordSheet";
import { Pill } from "@/components/ui/pill";
import { StatusChip } from "@/components/ui/status-chip";
import {
  AttachmentTable,
  NoteBlock,
  ReadField,
  ReadGrid,
  SheetTable,
  TagRow,
  type RecordReadSection,
} from "./DirectoryRecordSheet";
import { DASH, daysFromToday, formatDate, money } from "./directoryCore";
import { BROKER_PRODUCTS } from "./directory";
import { ordersForVendor } from "./directoryLinks";
import { BROKER_STATUS_TONE } from "./orders";
import {
  AVAILABILITY_STATUSES,
  BUSINESS_LINES,
  SERVICE_AREA_TYPES,
  VENDOR_TYPES,
  assignedOrderCount,
  type Vendor,
} from "./vendors";
import type { FormSectionDef } from "./directoryFormTypes";
import { ACTIVE_KIND, kindTone } from "../statusKind";

/*
  What a vendor record shows in the sheet, beyond the fields it edits.

  ELIGIBILITY IS THE HEADLINE, and it is four independent answers: are they
  switched on, are they approved, is the paperwork current, and are they free.
  Four chips, because collapsing them into one "eligible / not eligible"
  destroys the only useful part — WHICH of the four is the problem.

  COMPLIANCE IS COUNTED IN DAYS, not shown as a date. "Expires 2026-11-30" is a
  date somebody has to subtract today from; "84 days left" is the answer they
  were doing the subtraction to get.
*/

const Muted = () => <span className="text-muted-foreground/70">{DASH}</span>;

export function vendorHeaderAside(v: Vendor) {
  const days = daysFromToday(v.complianceValidTo);
  return (
    <span className="flex items-center gap-1.5">
      <StatusChip tone={kindTone(ACTIVE_KIND(v.active))} variant="soft">
        {v.active ? "Active" : "Inactive"}
      </StatusChip>
      <StatusChip
        tone={
          kindTone(
            v.complianceStatus === "Valid"
              ? "success"
              : v.complianceStatus === "Expiring"
                ? "caution"
                : "critical",
          )
        }
        variant="soft"
      >
        {days !== null && days < 0
          ? `Compliance expired`
          : days !== null && days < 60
            ? `Compliance ${days}d`
            : "Compliance valid"}
      </StatusChip>
      {!v.approvedForAssignment && (
        <StatusChip tone={kindTone("critical")} variant="soft">
          Not approved
        </StatusChip>
      )}
      {v.availabilityStatus !== "Available" && (
        <StatusChip tone={kindTone("caution")} variant="soft">
          {v.availabilityStatus}
        </StatusChip>
      )}
    </span>
  );
}

export function vendorReadSections(v: Vendor): RecordReadSection[] {
  const orders = ordersForVendor(v.id);
  const live = orders.filter(
    (o) => !["Completed", "Synced", "Canceled"].includes(o.status)
  );
  const history = orders.filter((o) =>
    ["Completed", "Synced", "Canceled"].includes(o.status)
  );
  const products = BROKER_PRODUCTS.filter((p) => v.supportedProductIds.includes(p.id));
  const days = daysFromToday(v.complianceValidTo);

  return [
    {
      key: "standing",
      title: "Standing",
      note:
        days === null
          ? undefined
          : days < 0
            ? `Lapsed ${Math.abs(days)} days ago`
            : `${days} days of cover left`,
      render: () => (
        <ReadGrid>
          <ReadField label="Compliance status" value={v.complianceStatus} />
          <ReadField label="Valid until" value={formatDate(v.complianceValidTo)} />
          <ReadField label="Insurance expiry" value={formatDate(v.insuranceExpiry)} />
          <ReadField label="Licences" value={<TagRow tags={v.licenseNumbers} />} />
          <ReadField label="Live orders" value={assignedOrderCount(v.id)} />
          <ReadField label="Safety score" value={`${v.safetyScore} / 100`} />
          <ReadField label="Distance from yard" value={`${v.distanceMi} mi`} />
          <ReadField label="Legal business name" value={v.legalBusinessName} />
          <ReadField label="Vendor type" value={v.vendorType} />
          {/* THE COMMS SETTINGS LIVE HERE NOW. Both left the table — real,
              rarely looked at, never the reason somebody opens the list — so
              the record is where they have to be readable. */}
          <ReadField
            label="Email invitations"
            value={v.emailsEnabled ? "Enabled" : "Disabled — this vendor is not emailed"}
          />
          <ReadField
            label="Vendor app"
            value={v.hasAccount ? "Has an account" : "Email link only"}
          />
          <ReadField
            label="Approved for assignment"
            value={v.approvedForAssignment ? "Yes" : "No — withheld"}
          />
          <ReadField
            label="Blackout dates"
            value={
              v.blackoutDates.length > 0 ? (
                <TagRow tags={v.blackoutDates.map((d) => formatDate(d))} />
              ) : (
                "None"
              )
            }
            wide
          />
          <ReadField label="Tags" value={<TagRow tags={v.tags} />} wide />
        </ReadGrid>
      ),
    },
    {
      /* NOT "Service coverage" — that heading is already the editable section
         above, and two blocks with one name is how somebody edits the wrong
         one. This is the part of coverage the form does not ask for. */
      key: "coverage-detail",
      title: "Coverage detail",
      note: "Derived from the service area above",
      render: () => (
        <ReadGrid>
          <ReadField
            label="Cities covered"
            value={v.coveredCities.length > 0 ? <TagRow tags={v.coveredCities} /> : null}
            wide
          />
          <ReadField
            label="ZIPs covered"
            value={v.coveredZips.length > 0 ? <TagRow tags={v.coveredZips} /> : null}
            wide
          />
          <ReadField label="Order types" value={<TagRow tags={v.supportedOrderTypes} />} wide />
        </ReadGrid>
      ),
    },
    {
      key: "contacts",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.name, CELL.pick, CELL.pick, CELL.text],
      title: "Contacts",
      count: v.contacts.length,
      render: () => (
        <SheetTable
          rows={v.contacts}
          rowKey={(p) => p.id}
          emptyBody="Nobody is recorded here. Dispatch has no one to call."
          columns={[
            {
              key: "name",
              label: "Name",
              render: (p) => (
                <span className="flex items-center gap-2">
                  {p.name}
                  {p.isPrimary && (
                    <Pill>
                      Primary
                    </Pill>
                  )}
                </span>
              ),
            },
            { key: "role", label: "Role", render: (p) => p.role },
            { key: "phone", label: "Phone", render: (p) => p.phone ?? <Muted /> },
            { key: "email", label: "Email", render: (p) => p.email ?? <Muted /> },
          ]}
        />
      ),
    },
    {
      key: "rates",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.name, CELL.number, CELL.number, CELL.number],
      title: "Rate card",
      count: v.rateCard.length,
      render: () => (
        <SheetTable
          rows={v.rateCard}
          rowKey={(l) => l.id}
          emptyBody="No rate card. Quotes from this vendor cannot be checked against anything."
          columns={[
            {
              key: "label",
              label: "Tier",
              render: (l) => (
                <span className="flex items-center gap-2">
                  {l.label}
                  {l.id === v.defaultRateCardId && (
                    <Pill>
                      Default
                    </Pill>
                  )}
                </span>
              ),
            },
            {
              key: "min",
              label: "From",
              render: (l) => (l.minGallons ? `${l.minGallons.toLocaleString()} gal` : <Muted />),
            },
            {
              key: "rate",
              label: "Rate",
              render: (l) => `${money(l.rate)} ${l.unit}`,
            },
            {
              key: "fsc",
              label: "Surcharge",
              render: (l) => (l.fuelSurcharge === null ? <Muted /> : money(l.fuelSurcharge)),
            },
          ]}
        />
      ),
    },
    {
      key: "products",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.name, CELL.pick, CELL.pick, CELL.pick],
      title: "Supported products",
      count: products.length,
      render: () => (
        <SheetTable
          rows={products}
          rowKey={(p) => p.id}
          emptyBody="This vendor's business lines cover nothing in the catalog."
          columns={[
            { key: "name", label: "Product", render: (p) => p.name },
            { key: "code", label: "Code", render: (p) => p.productCode },
            { key: "cat", label: "Category", render: (p) => p.category },
            { key: "unit", label: "UOM", render: (p) => p.unit },
          ]}
        />
      ),
    },
    {
      key: "assignments",
      /* ITS TABLE'S COLUMNS — the sheet's width (DS ui/7-variants §1). */
      columns: [CELL.pick, CELL.name, CELL.date, CELL.status],
      title: "Assignments",
      note: `${live.length} live · ${history.length} closed`,
      render: () => (
        <SheetTable
          rows={[...live, ...history]}
          rowKey={(o) => o.id}
          emptyBody="This vendor has never been given work."
          columns={[
            { key: "no", label: "Order", render: (o) => o.orderNo },
            { key: "cust", label: "Customer", render: (o) => o.customer.title },
            { key: "date", label: "Date", render: (o) => o.date.title },
            {
              key: "status",
              label: "Status",
              render: (o) => (
                <StatusChip tone={BROKER_STATUS_TONE[o.status]} variant="text">
                  {o.status}
                </StatusChip>
              ),
            },
          ]}
        />
      ),
    },
    {
      key: "documents",
      title: "Compliance documents",
      count: v.documents.length,
      render: () => <AttachmentTable files={v.documents} />,
    },
    {
