import * as React from "react";

/**
 * Saved-view state for a list screen, generic over what a view captures.
 *
 * The interaction is the DS's finalized one (`data-action-control/
 * DataActionControl.tsx`): a Default tab plus saved tabs, a dirty dot when the
 * live state has drifted from the active view, and rename / update / delete on
 * each saved tab. Fuel Orders proved it; this hook is what lets Asset Orders and
 * Customers have the same thing without a third and fourth copy of the state.
 *
 * `keyOf` exists so drift detection cannot be fooled by key order — each screen
 * serialises its own state deterministically.
 */
/*
  A LIST REMEMBERS WHERE IT WAS LEFT (Pavan, 2026-10-09). Leaving a page and
  coming back finds the same filters, search, sort and view — still dirty if
  they were, still savable as a view, still clearable — until Clear all (or
  the view's own reset) takes them off. Kept for the session in memory, one
  entry per list (`storageKey`); a page reload starts clean.
*/
type Kept<S> = {
  views: { id: string; name: string; state: S }[];
  activeId: string | null;
  working: Record<string, S>;
  current: S;
  seq: number;
};
const KEPT = new Map<string, Kept<unknown>>();

export function useSavedViews<S>({
  current,
  defaultState,
  keyOf,
  apply,
  storageKey,
  restore = true,
}: {
  current: S;
  defaultState: S;
  keyOf: (s: S) => string;
  apply: (s: S) => void;
  /** Remembers this list across leaving and coming back — see `KEPT`. */
  storageKey?: string;
  /** False when the visit arrives with its own narrowing (a dashboard drill),
      which then wins over what was left. */
  restore?: boolean;
}) {
  const kept = storageKey ? (KEPT.get(storageKey) as Kept<S> | undefined) : undefined;
  const [views, setViews] = React.useState<{ id: string; name: string; state: S }[]>(
    () => kept?.views ?? []
  );
  const [activeId, setActiveId] = React.useState<string | null>(() => kept?.activeId ?? null);
  const seq = React.useRef(kept?.seq ?? 0);
  /* ON RETURN, PUT THE LIST BACK as it was left — once, after mount. */
  React.useEffect(() => {
    if (kept && restore && keyOf(kept.current) !== keyOf(current)) apply(kept.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  /* EACH VIEW KEEPS ITS UNSAVED CHANGES (Pavan, 2026-09-24) — leaving a view
     and coming back finds it as it was left, dirty dot and all. Keyed by view
     id, "" for Default. Saving or updating the view clears its entry. */
  const working = React.useRef<Record<string, S>>(kept?.working ?? {});
  /* KEEP EVERYTHING ON EVERY CHANGE, so leaving at any moment loses nothing. */
  React.useEffect(() => {
    if (!storageKey) return;
    KEPT.set(storageKey, {
      views,
      activeId,
      working: working.current,
      current,
      seq: seq.current,
    } as Kept<unknown>);
  });
  const DEFAULT_KEY = "";

  const activeView = views.find((v) => v.id === activeId) ?? null;
  const dirty = keyOf(current) !== keyOf(activeView ? activeView.state : defaultState);

  /** Park what is on screen against the view being left. */
  const park = () => {
    const key = activeId ?? DEFAULT_KEY;
    if (dirty) working.current[key] = current;
    else delete working.current[key];
  };

  return {
    views,
    activeId,
    dirty,
    /* PRESSING THE TAB YOU ARE ON puts it back to its saved state — the one
       way to drop what was changed. Pressing another tab keeps both. */
    onApply: (id: string) => {
      const v = views.find((x) => x.id === id);
      if (!v) return;
      if (id === activeId) {
        delete working.current[id];
        apply(v.state);
        return;
      }
      park();
      apply(working.current[id] ?? v.state);
      setActiveId(id);
    },
    onResetToDefault: () => {
      if (activeId === null) {
        delete working.current[DEFAULT_KEY];
        apply(defaultState);
        return;
      }
      park();
      apply(working.current[DEFAULT_KEY] ?? defaultState);
      setActiveId(null);
    },
    onCreate: (name: string) => {
      const id = `v-${++seq.current}`;
      /* The changes move INTO the new view, so the view left is clean again. */
      delete working.current[activeId ?? DEFAULT_KEY];
      setViews((prev) => [...prev, { id, name, state: current }]);
      setActiveId(id);
    },
    onRename: (id: string, name: string) =>
      setViews((prev) => prev.map((v) => (v.id === id ? { ...v, name } : v))),
    onUpdate: (id: string) => {
      delete working.current[id];
      setViews((prev) =>
        prev.map((v) => (v.id === id ? { ...v, state: current } : v))
      );
    },
    onDelete: (id: string) => {
      delete working.current[id];
      setViews((prev) => prev.filter((v) => v.id !== id));
      if (activeId === id) setActiveId(null);
    },
  };
}

import * as React from "react";
import { cn } from "@/lib/utils";

export interface AppShellProps {
  /** Global top bar — a full-width chrome band above the rail + content. Optional. */
  topBar?: React.ReactNode;
  /** Tier-1 icon rail (52px, flush, full height). Self-contained (owns its surface). */
  rail?: React.ReactNode;
  /** Tier-2 contextual sidebar (256px). Optional. Self-contained. */
  sidebar?: React.ReactNode;
  /**
   * THE TIER-2 DRAWER IS NOT THERE UNTIL THE RAIL IS TOUCHED.
   *
   * A second nav level is READ ONCE — you pick the list you are working in and
   * then you work in it — and it charges 264px of every screen after that for
   * having been read. On a table that is two columns; on a board it is most of
   * a lane. It does not earn a resting footprint either: a 52px strip of
   * unlabelled icons beside a 52px strip of unlabelled icons is two things to
   * read where the rail is already the one you aim at.
   *
   * ONE DRAWER AT A TIME (Pavan, 2026-10-01). Hovering the rail opens the
   * rail ONLY — the second drawer stays away, so the menu items can be read
   * and clicked with nothing sliding out beside them. CLICKING a menu item is
   * what brings the second drawer out, and the rail collapses back to 52px in
   * the same moment (NavRail's own "picking is finishing"). Hover the rail
   * again and the second drawer goes away: you are choosing again.
   *
   * IT FLOATS RATHER THAN PUSHES. Reflowing the content layer every time the
   * pointer crossed the rail would make the thing you are reading move while
   * you read it, and the drawer's whole argument is that the content should
   * have the width. The same call the rail already makes one level up.
   *
   * IT LEAVES ON ITS OWN, and not the instant you step off: a pointer on its
   * way to a row crosses the drawer, and one that shut on that would be a
   * drawer you had to chase. See `PEEK_HIDE_MS`.
   *
   * A PRESS OUTSIDE BOTH PANELS CLOSES THEM AT ONCE. The clock is grace for a
   * pointer that may come back; pressing on the work behind the panels is not
   * wandering past, it is saying the nav is finished with. Waiting the second
   * out there would leave two panels sitting over the thing the reader just
   * pressed.
   */
  sidebarPeek?: boolean;
  /**
   * Fixed page header at the top of the content layer — the name of the selected
   * menu (from the sub-nav drawer or the main nav). A string renders the 24px
   * semibold title; pass a node for custom header content.
   */
  title?: React.ReactNode;
  /**
   * Optional breadcrumb (the nav path). Rendered **inside the header, directly
   * below the title text** (above the header's bottom divider). Omit it (e.g. via
   * the Settings toggle) and the header collapses to the title row.
   * See `docs/content-layer.md`.
   */
  breadcrumb?: React.ReactNode;
  /** Optional right-aligned controls in the page header (e.g. theme toggle). */
  headerAction?: React.ReactNode;
  /** Content layer body. Rendered with the 16px inset unless `inset={false}`. */
  children: React.ReactNode;
  /** The 16px content-layer inset is a hard layout rule — on by default. */
  inset?: boolean;
  /** Tighter page header (less vertical padding) for dense, ClickUp-style tops. */
  compactHeader?: boolean;
  /** Bottom hairline under the (non-compact) header. On by default. */
  headerDivider?: boolean;
  className?: string;
}

/**
 * Canonical FleetPanda app shell — Figma "Layout Structure & Spacing"
 * (node 27634:21171). Encodes the two spacing laws:
 *   • 8px gap between panels (rail ↔ sidebar ↔ content) + 8px outer margin.
 *   • 16px inset on all four sides inside the content layer.
 *
 * Geometry: 52px rail (flush, full height) · 8px gap · 256px sidebar · 8px gap ·
 * fluid content · 8px right/top/bottom margin. The Content Layer (27634:23034)
 * is a distinct FP/Surface-1b panel (#1b2028, rounded-md) with a fixed 48px
 * page-header at its top (1px #363c45 bottom divider) showing the selected menu.
 */
/**
 * How long the drawer stays out after the pointer leaves both it and the rail.
 *
 * 500ms, down from a second in two steps (2026-09-17). The delay exists only
 * to forgive the gap a pointer crosses on its way somewhere else — long enough
 * to cover the trip, short enough that a drawer you have finished with is gone
 * before you notice it is still sitting on your table. A full second was well
 * on the wrong side of that: the trip takes a fraction of it, and the rest was
 * the panel hanging about over work the reader had already turned back to.
 */
const PEEK_HIDE_MS = 500;

export function AppShell({
  topBar,
  rail,
  sidebar,
  sidebarPeek = false,
  title,
  breadcrumb,
  headerAction,
  children,
  inset = true,
  compactHeader = false,
  headerDivider = true,
  className,
}: AppShellProps) {
  const titleEl =
    typeof title === "string" || typeof title === "number" ? (
      <h1 className="truncate text-xl font-semibold leading-none text-foreground">
        {title}
      </h1>
    ) : (
      title
    );
  const hasHeader = title != null || headerAction != null || breadcrumb != null;

  const peeking = sidebarPeek && sidebar != null;
  const [expanded, setExpanded] = React.useState(false);
  const railBox = React.useRef<HTMLDivElement>(null);
  const drawerBox = React.useRef<HTMLDivElement>(null);
  const hideAt = React.useRef<number | undefined>(undefined);
  /* TRUE FROM A CLICK ON A RAIL ITEM UNTIL THE POINTER LEAVES THE RAIL.
     The pointer is still on the rail just after the click, and without this
     the next move would read as "hovering the rail" and put the drawer away
     again. */
  const picked = React.useRef(false);

  const open = React.useCallback(() => {
    window.clearTimeout(hideAt.current);
    hideAt.current = undefined;
    setExpanded(true);
  }, []);

  /**
   * WHICH PANEL IS OUT IS DECIDED BY WHERE THE POINTER IS, NOT BY EVENTS THAT
   * WERE SUPPOSED TO FIRE.
   *
   * `mouseenter`/`mouseleave` are the obvious way to write this and they are
   * not dependable here. Both panels MOVE under the pointer — the rail grows
   * to 256, the drawer slides in from off-canvas — and a browser fires no
   * enter for an element that arrives under a cursor that is not moving, so it
   * owes no leave for it either. Hung on those, the drawer sometimes never
   * came out and, once out, sometimes never went back.
   *
   * Asking "what is under the pointer" on every move has no such hole: the
   * answer is the truth at that instant, however the pixels got there. On the
   * rail, the drawer comes out. On the drawer, it stays. On neither, ONE clock
   * starts — and is not restarted by further movement, or a pointer crossing
   * the table would keep postponing a retreat it is plainly not interested in.
   */
  React.useEffect(() => {
    if (!peeking) return;
    const arm = () => {
      if (hideAt.current !== undefined) return;
      hideAt.current = window.setTimeout(() => {
        hideAt.current = undefined;
        setExpanded(false);
      }, PEEK_HIDE_MS);
    };
    const stay = () => {
      window.clearTimeout(hideAt.current);
      hideAt.current = undefined;
    };
    const within = (box: HTMLDivElement | null, t: EventTarget | null) =>
      t instanceof Node && Boolean(box?.contains(t));
    const move = (e: PointerEvent) => {
      if (within(railBox.current, e.target)) {
        /* On the rail: the rail is the only drawer — unless an item was
           just clicked and the pointer has not moved off yet. */
        stay();
        if (!picked.current) setExpanded(false);
        return;
      }
      picked.current = false;
      if (within(drawerBox.current, e.target)) {
        stay();
      } else {
        arm();
      }
    };
    /* The pointer can also leave by leaving the WINDOW, which produces no
       further moves to ask. A `mouseout` with nothing on the other side of it
       is that, and only that. */
    const out = (e: MouseEvent) => {
      if (!e.relatedTarget) arm();
    };
    /* A CLICK OUTSIDE IS A DECISION, AND IT DOES NOT WAIT.
       The clock is for a pointer that has wandered off and may come back —
       one second of grace on the way past. Pressing on the work behind the
       panels is not wandering: it says the reader is done with the nav and is
       somewhere else now, and holding two panels over what they just pressed
       for another second is the shell arguing with them. Outside both boxes,
       it goes straight away. */
    const dismiss = (e: PointerEvent) => {
      if (within(drawerBox.current, e.target)) return;
      if (within(railBox.current, e.target)) {
        /* A MENU ITEM PRESSED — the second drawer's cue. The module switcher
           is not a menu item and leaves it alone. */
        const t = e.target as Element;
        if (t.closest("nav li button")) {
          stay();
          picked.current = true;
          setExpanded(true);
        }
        return;
      }
      stay();
      setExpanded(false);
    };
    document.addEventListener("pointermove", move, true);
    document.addEventListener("mouseout", out, true);
    document.addEventListener("pointerdown", dismiss, true);
    return () => {
      document.removeEventListener("pointermove", move, true);
      document.removeEventListener("mouseout", out, true);
      document.removeEventListener("pointerdown", dismiss, true);
    };
  }, [peeking]);

  React.useEffect(() => () => window.clearTimeout(hideAt.current), []);

  /* THE RAIL IS WRAPPED ONLY TO BE LISTENED TO — the wrapper is a flex box
     round a fixed-width child and changes no geometry. */
  const railEl =
    peeking && rail ? (
      <div ref={railBox} className="flex shrink-0">
        {rail}
      </div>
    ) : (
      rail
    );

  return (
    <div
      className={cn(
        "flex h-(--fp-vh) flex-col overflow-hidden bg-background text-foreground",
        className
      )}
    >
      {/* Global top bar: full-width chrome band above the rail + content. */}
      {topBar}

      <div className="flex min-h-0 flex-1 overflow-hidden">
        {/* Tier-1 rail: flush left, full height (outside the padded region). */}
        {railEl}

        {/* Padded region: p-2 = 8px outer margin (top/right/bottom) + 8px gap from
            the rail; gap-2 = 8px between the sidebar and the content layer. */}
        {/* `overflow-hidden` ONLY WHEN THE DRAWER PEEKS, and it is what the
            hiding IS: the drawer sits to the left of this box while it is away
            and the box clips it, so it reads as coming out from behind the
            rail rather than as fading in on top of the table. Overlays are
            portalled, so nothing that needs to escape this box is inside it. */}
        <div
          className={cn(
            "relative flex min-w-0 flex-1 gap-2 p-2",
            peeking && "overflow-hidden"
          )}
        >
          {peeking ? (
            /* z-20, one BELOW the rail's z-30 — that one digit is the whole of
               the parent-over-child stacking. `pointer-events-none` while away
               so a drawer nobody can see cannot eat a click on the column it
               is sitting over; focus still reaches it, and tabbing in brings
               it out, which is the keyboard's version of moving left. */
            <div
              ref={drawerBox}
              className={cn(
                "absolute inset-y-2 left-2 z-20 rounded-lg transition-transform duration-200 ease-out",
                expanded
                  ? "translate-x-0 shadow-xl"
                  : "pointer-events-none -translate-x-[calc(100%+0.75rem)]"
              )}
              /* Tabbing in brings it out — the keyboard's version of moving
                 left. Staying out is the pointer test above, not an event. */
              onFocusCapture={open}
            >
              {sidebar}
            </div>
          ) : (
            sidebar
          )}
        {/* Content Layer: FP/Surface 1b, rounded-md, no outer border and NO
            SHADOW. The shadow existed to lift it off a ground it was the same
            colour as; now that the app ground is the tinted surface-base, the
            step in value does that job on its own — and a shadow on top of a
            real value step is a second answer to a question already answered.
            (28679:1109 drew it when light's ground was #ffffff.) */}
        {/* `isolate` — THE CONTENT LAYER STACKS INSIDE ITSELF.
            Without it the layer is `relative` at `z-auto`, which makes no
            stacking context of its own, so every z-index inside it competes
            directly with the shell's: the data table's sticky header is `z-20`,
            the drawer is `z-20`, the table comes later in the document, and a
            column header painted over a navigation drawer. Neither number was
            wrong — they were never meant to be in the same conversation. A
            stacking context puts the whole layer at one depth and settles it
            for everything that will ever be built inside it. Overlays that must
            escape are portalled to the body and are not affected. */}
        <section className="relative isolate flex min-w-0 flex-1 flex-col overflow-hidden rounded-md bg-fp-surface-1b">
          {/* Page header. Title row (48px when alone); the optional breadcrumb
              sits directly beneath the title text, inside the header unit, above
              the divider. */}
          {hasHeader && (
            <header className={cn("flex shrink-0 flex-col gap-1 px-4", compactHeader ? "py-1" : "py-3", !compactHeader && headerDivider && "border-b border-fp-outline-1")}>
              <div className="flex items-center gap-6">
                {titleEl}
                {headerAction != null && (
                  <div className="ml-auto flex items-center gap-2">
                    {headerAction}
                  </div>
                )}
              </div>
              {breadcrumb != null && (
                <div className="flex items-center">{breadcrumb}</div>
              )}
            </header>
          )}
          {/* Body: 16px inset (hard rule). Children manage their own scroll. */}
          <div
            className={cn(
              "relative flex min-h-0 flex-1 flex-col overflow-hidden",
              inset && "p-4"
            )}
          >
            {children}
          </div>
        </section>
        </div>
      </div>
    </div>
  );
}

import * as React from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

export interface BulkEditDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Attribute being edited, e.g. "Driver". Becomes the step-1 title. */
  title: string;
  /**
   * Verb phrase for the scope line, WITHOUT a trailing "selected" — the line is
   * composed as `{scopeVerb} selected {N items}`, so "Assign driver to" reads
   * "Assign driver to selected 25 orders".
   */
  scopeVerb: string;
  count: number;
  /** Noun for the count, pluralised automatically. */
  itemNoun?: string;
  /** Step 1 is only completable once the picker has a value. */
  canProceed: boolean;
  /** Step 1 body — the picker. */
  children: React.ReactNode;
  /** Step 2 body — what already exists, and what changes. */
  summary: React.ReactNode;
  /** One line under the "View Summary" title describing the commit. */
  summaryDescription: string;
  /** Commit. The dialog closes itself afterwards. */
  onConfirm: () => void;
  /**
   * Confirmation toast. A string overrides the default wording; `false`
   * suppresses it. Fired by the dialog rather than left to callers so the
   * "apply → toast" rule cannot be forgotten one call site at a time.
   */
  toastMessage?: string | false;
  /**
   * Mark the commit destructive. Adds a second confirmation press before the
   * mutation runs, for replaces that discard standing values.
   */
  destructive?: boolean;
}

/**
 * Two-step bulk-attribute editor.
 *
 * The shape is the DS's prescribed one: bulk-attribute editors come in three
 * tiers by cardinality (scalar → single input; one-value-per-row → searchable
 * select; a collection per row → richer picker), each opening a **dialog**, and
 * each taking a two-step shape — (1) input dialog whose header leads with
 * **scope + count**, (2) per-row **before/after preview** with `Go back` /
 * `Confirm`, (3) commit. This shell is tier-agnostic: the tier only changes what
 * you pass as `children`.
 *
 * WHY BOTH STEPS EARN THEIR KEEP — the reason the pattern exists, and the thing
 * to preserve if it is ever "simplified": the operator needs to see the state
 * that **already exists** on the target before piling onto it. A target is
 * typically mid-flight with values already on it. Step 1 surfaces that standing
 * state (see `StandingItems`); step 2 shows the delta it is about to become (see
 * `BeforeAfterTable`). Collapsing to one step removes the only chance to notice
 * you are about to replace something.
 *
 * The dialog ALWAYS reopens on step 1. Reopening mid-flow would present a
 * `Confirm` for a value the operator can no longer see.
 */
export function BulkEditDialog({
  open,
  onOpenChange,
  title,
  scopeVerb,
  count,
  itemNoun = "item",
  canProceed,
  children,
  summary,
  summaryDescription,
  onConfirm,
  toastMessage,
  destructive = false,
}: BulkEditDialogProps) {
  const [step, setStep] = React.useState<"pick" | "summary">("pick");
  const [armed, setArmed] = React.useState(false);

  React.useEffect(() => {
    if (!open) {
      setStep("pick");
      setArmed(false);
    }
  }, [open]);

  const items = `${count} ${count === 1 ? itemNoun : `${itemNoun}s`}`;

  const commit = () => {
    // A destructive replace discards standing values, so it takes a second
    // deliberate press rather than committing on the first.
    if (destructive && !armed) {
      setArmed(true);
      return;
    }
    onConfirm();
    if (toastMessage !== false) {
      toast.success(toastMessage ?? `Updated ${items}`);
    }
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        size={step === "summary" ? "lg" : "default"}
        aria-describedby={undefined}
      >
        <DialogHeader>
          <DialogTitle>{step === "pick" ? title : "View Summary"}</DialogTitle>
          <DialogDescription>
            {step === "pick" ? (
              <>
                {scopeVerb} selected{" "}
                <span className="font-medium text-foreground">{items}</span>
              </>
            ) : (
              summaryDescription
            )}
          </DialogDescription>
        </DialogHeader>

        {/* Body scrolls; the header and footer stay put however many rows the
            selection carries. */}
        <div className="-mx-1 max-h-[55vh] overflow-y-auto px-1">
          {step === "pick" ? children : summary}
        </div>

        {step === "pick" ? (
          <DialogFooter>
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button disabled={!canProceed} onClick={() => setStep("summary")}>
              Proceed and Confirm
            </Button>
          </DialogFooter>
        ) : (
          // `between`: Go back navigates, it does not dismiss — grouping it
          // against Confirm would read as a cancel.
          <DialogFooter align="between">
            <Button
              variant="outline"
              onClick={() => {
                setArmed(false);
                setStep("pick");
              }}
            >
              Go back
            </Button>
            <Button
              variant={destructive ? "destructive" : "default"}
              onClick={commit}
            >
              {destructive && armed ? `Yes, replace ${items}` : "Confirm"}
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
}

export { BulkEditDialog, type BulkEditDialogProps } from "./BulkEditDialog";
export {
  RecordMiniTable,
  BeforeAfterTable,
  StandingItems,
  type RecordRef,
  type BeforeAfterRow,
} from "./parts";

import * as React from "react";
import { ChevronDown } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

/** One record as the summary tables render it: an identity plus its cells. */
export interface RecordRef {
  /** Stable identity, rendered in the first column. */
  id: string;
  /** Remaining cells, in column order. */
  cells?: string[];
}

/**
 * Plain identity table — the records being acted on. Deliberately unstyled
 * beyond the DS table: its job is to let the operator confirm *which* rows the
 * mutation lands on, not to re-present their data.
 */
export function RecordMiniTable({
  records,
  headers,
}: {
  records: RecordRef[];
  /** Column headers; `headers[0]` labels the identity column. */
  headers: string[];
}) {
  return (
    <div className="overflow-hidden rounded-md border border-border">
      <Table>
        <TableHeader>
          <TableRow className="hover:bg-transparent">
            {headers.map((h) => (
              <TableHead key={h}>{h}</TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {records.map((r) => (
            <TableRow key={r.id}>
              <TableCell className="font-medium tabular-nums">{r.id}</TableCell>
              {(r.cells ?? []).map((c, i) => (
                <TableCell
                  key={i}
                  className={i === (r.cells ?? []).length - 1 ? "text-muted-foreground" : undefined}
                >
                  {c}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

export interface BeforeAfterRow {
  id: string;
  before: string;
  after: string;
}

/**
 * Per-row before/after — the step-2 preview.
 *
 * `before` renders muted with a line through it so the row reads as a
 * **replacement** rather than an addition. An empty `before` falls back to an
 * em-dash, so "had nothing" and "had something" stay visually distinct — without
 * it, a blank cell reads as a rendering failure rather than as a fact.
 */
export function BeforeAfterTable({
  rows,
  valueHeader,
  idHeader = "ID",
}: {
  rows: BeforeAfterRow[];
  /** Name of the attribute changing; used for both value columns. */
  valueHeader: string;
  idHeader?: string;
}) {
  return (
    <div className="overflow-hidden rounded-md border border-border">
      <Table>
        <TableHeader>
          <TableRow className="hover:bg-transparent">
            <TableHead>{idHeader}</TableHead>
            <TableHead>Current {valueHeader}</TableHead>
            <TableHead>New {valueHeader}</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((r) => (
            <TableRow key={r.id}>
              <TableCell className="font-medium tabular-nums">{r.id}</TableCell>
              <TableCell className="text-muted-foreground line-through">
                {r.before || "—"}
              </TableCell>
              <TableCell className="font-medium">{r.after || "—"}</TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}

/**
 * What the target already holds, collapsed by default.
 *
 * This is the "surface what already exists" half of the flow — the reason the
 * pattern is two steps at all. The count stays visible; the records behind it
 * are one click away.
 *
 * Inner surface is `bg-fp-surface-1b`, NOT `bg-fp-card-1`: measured against the
 * dialog's own `bg-background`, card-1 is only [6,3,10] away in light (#e9ecf1
 * on #efefeb — near-invisible), while surface-1b is [16,16,20] light and
 * [19,24,32] dark. Same collision family as the bulk bar's fill.
 */
export function StandingItems({
  label,
  records,
  headers,
  itemNoun = "item",
  summary,
  className,
}: {
  label: string;
  records: RecordRef[];
  headers: string[];
  /** Noun used by the default count phrasing. */
  itemNoun?: string;
  /** Override the count phrasing entirely. */
  summary?: React.ReactNode;
  className?: string;
}) {
  const [open, setOpen] = React.useState(false);
  const n = records.length;
  const plural = n === 1 ? itemNoun : `${itemNoun}s`;

  return (
    <Collapsible
      open={open}
      onOpenChange={setOpen}
      className={cn("rounded-md border border-border bg-fp-surface-1b", className)}
    >
      <CollapsibleTrigger
        disabled={n === 0}
        className="flex w-full items-center justify-between gap-2 p-3 text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/50 disabled:cursor-default"
      >
        <span className="text-sm font-medium">{label}</span>
        <span className="flex items-center gap-2 text-sm text-muted-foreground">
          {summary ?? (n === 0 ? `No ${itemNoun}s yet` : `${n} existing ${plural}`)}
          {n > 0 && (
            <ChevronDown
              className={cn("size-4 transition-transform", open && "rotate-180")}
            />
          )}
        </span>
      </CollapsibleTrigger>
      {n > 0 && (
        <CollapsibleContent className="px-3 pb-3">
          {/* Bounded on purpose. A heavily loaded target can hold 20+ records,
              and letting that list run full height pushes the section the
              operator is actually deciding on several screens down the dialog's
              own scroll. It scrolls within itself instead. */}
          <div className="max-h-56 overflow-y-auto">
            <RecordMiniTable records={records} headers={headers} />
          </div>
        </CollapsibleContent>
      )}
    </Collapsible>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";

/*
  Single-select "Options" pills (Figma 27593:15012) — Low / Medium / High /
  Critical. The active pill fills; the rest are quiet surface chips.
*/
const OPTIONS = ["Low", "Medium", "High", "Critical"];

export function ChoicePills({ defaultValue = "Low" }: { defaultValue?: string }) {
  const [value, setValue] = React.useState(defaultValue);
  return (
    <div className="flex flex-wrap gap-2">
      {OPTIONS.map((opt) => {
        const active = value === opt;
        return (
          <button
            key={opt}
            type="button"
            onClick={() => setValue(opt)}
            aria-pressed={active}
            className={cn(
              "h-8 rounded-md px-3 text-sm font-medium outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
              active
                ? "bg-foreground text-background"
                : "border border-border bg-fp-surface-1a text-foreground hover:border-fp-outline-2"
            )}
          >
            {opt}
          </button>
        );
      })}
    </div>
  );
}

import * as React from "react";
import { ChevronDown, Plus, Trash2, X, Check } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

/*
  Editable "Input / Dropdown Tables Layout" + "Add more and hover and delete"
  (Figma 27593:15012 / 27592:33634). Fully editable cells: dropdown cells (two
  lines, open a combobox list) and free-text cells, with required-column markers
  (*), a row-hover delete control, and a "+ Add more" row affordance.
*/

interface TableCellValue {
  title: string;
  description: string;
}

interface EditableRow {
  id: string;
  peripheral: TableCellValue;
  serial: string;
  condition: TableCellValue;
  ownership: TableCellValue;
}

const PERIPHERAL_OPTIONS = ["Scanner", "Printer", "Sensor", "Router"];
const CONDITION_OPTIONS = ["New", "Refurbished", "Used", "Damaged"];
const OWNERSHIP_OPTIONS = ["Owned", "Leased", "Rented", "Third-party"];

const emptyCell = (): TableCellValue => ({
  title: "Table Cell Text",
  description: "Description Text",
});

const makeRow = (id: string): EditableRow => ({
  id,
  peripheral: emptyCell(),
  serial: "",
  condition: emptyCell(),
  ownership: emptyCell(),
});

/** A two-line cell that opens a combobox list and writes the choice back. */
function CellSelect({
  value,
  options,
  onChange,
}: {
  value: TableCellValue;
  options: string[];
  onChange: (v: TableCellValue) => void;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <button
          type="button"
          className={cn(
            // Fills the whole cell (no inset, no outline) — the hover/open
            // background covers the entire td, per the design. The cell sits on
            // Surface-1b, so the hover lift uses --accent to stay visible.
            "flex h-full w-full items-center justify-between gap-2 px-3 py-2.5 text-left outline-none transition-colors",
            "hover:bg-accent",
            "focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
            "data-[state=open]:bg-accent"
          )}
        >
          <span className="flex min-w-0 flex-col">
            <span className="truncate text-sm text-foreground">{value.title}</span>
            <span className="truncate text-xs text-muted-foreground">
              {value.description}
            </span>
          </span>
          <ChevronDown className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="w-44">
        {options.map((opt) => (
          <DropdownMenuItem
            key={opt}
            onSelect={() => onChange({ title: opt, description: value.description })}
          >
            {opt}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * A free-text cell that fills the whole td (no inner input box). Mirrors
 * CellSelect: borderless, full-cell hover lift, and inset focus ring while
 * typing. Carries the full set of input states:
 *  - default / filled → text-foreground (placeholder muted when empty)
 *  - hover            → bg-accent (same lift as the dropdown cells)
 *  - typing / focus   → inset ring + Surface-1a wash
 *  - disabled         → muted + not-allowed cursor
 */
function CellInput({
  value,
  onChange,
  placeholder,
  disabled,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  disabled?: boolean;
}) {
  return (
    // Absolutely fills the cell (the parent td is `relative`). A table cell
    // gives no definite height for `h-full` to resolve against, so `inset-0`
    // is what makes the hover/focus surface span the entire td.
    <label
      className={cn(
        "absolute inset-0 flex cursor-text items-stretch transition-colors",
        "hover:bg-accent",
        "focus-within:bg-fp-surface-1a focus-within:ring-2 focus-within:ring-inset focus-within:ring-ring/50",
        disabled && "cursor-not-allowed opacity-50 hover:bg-transparent"
      )}
    >
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
        className={cn(
          "h-full w-full min-w-0 bg-transparent px-3 text-sm text-foreground outline-none",
          "placeholder:text-muted-foreground disabled:cursor-not-allowed"
        )}
      />
    </label>
  );
}

function RequiredLabel({ children, required }: { children: React.ReactNode; required?: boolean }) {
  return (
    <span className="text-sm font-medium text-foreground">
      {children}
      {required && <span className="text-destructive"> *</span>}
    </span>
  );
}

export function EditableTable() {
  const idRef = React.useRef(2);
  const [rows, setRows] = React.useState<EditableRow[]>([
    makeRow("er-1"),
    makeRow("er-2"),
  ]);
  // Row id whose delete is awaiting inline confirmation (✕ / red ✓).
  const [confirmId, setConfirmId] = React.useState<string | null>(null);
  // Add chip: icon-only until hovered/focused, then the label slides out.
  const [addExpanded, setAddExpanded] = React.useState(false);

  const update = (id: string, patch: Partial<EditableRow>) =>
    setRows((prev) => prev.map((r) => (r.id === id ? { ...r, ...patch } : r)));

  const addRow = () =>
    setRows((prev) => [...prev, makeRow(`er-${++idRef.current}`)]);

  const removeRow = (id: string) =>
    setRows((prev) => prev.filter((r) => r.id !== id));

  return (
    <div>
      {/* Bottom-left corner squared so the Add chip connects as an extension.
          T2 — the component IS the unit, ruled correct 2026-09-22 (7-variants
          §3); the attribute is how the boxed-tables check remembers that. */}
      <div
        data-table-variant="T2"
        className="overflow-hidden rounded-md rounded-bl-none border border-border"
      >
        <table className="w-full table-fixed border-collapse">
          {/* Last column is pinned to exactly 52px (the delete/confirm control).
              The four data columns keep their 26/22/26/26 proportions; in a
              fixed layout the browser reserves the 52px and scales the
              percentages to the remaining width. */}
          <colgroup>
            <col className="w-[26%]" />
            <col className="w-[22%]" />
            <col className="w-[26%]" />
            <col className="w-[26%]" />
            <col className="w-[52px]" />
          </colgroup>
          <thead>
            <tr className="border-b border-border bg-fp-table-header">
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel required>Peripheral</RequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel>Input/Text</RequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel>Condition</RequiredLabel>
              </th>
              <th className="px-3 py-2.5 text-left">
                <RequiredLabel required>Ownership Status</RequiredLabel>
              </th>
              <th aria-hidden />
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr
                key={row.id}
                className="group/row border-b border-border last:border-b-0"
              >
                <td className="p-0 align-middle">
                  <CellSelect
                    value={row.peripheral}
                    options={PERIPHERAL_OPTIONS}
                    onChange={(v) => update(row.id, { peripheral: v })}
                  />
                </td>
                <td className="relative p-0 align-middle">
                  <CellInput
                    value={row.serial}
                    onChange={(v) => update(row.id, { serial: v })}
                    placeholder="Enter Serial No."
                  />
                </td>
                <td className="p-0 align-middle">
                  <CellSelect
                    value={row.condition}
                    options={CONDITION_OPTIONS}
                    onChange={(v) => update(row.id, { condition: v })}
                  />
                </td>
                <td className="p-0 align-middle">
                  <CellSelect
                    value={row.ownership}
                    options={OWNERSHIP_OPTIONS}
                    onChange={(v) => update(row.id, { ownership: v })}
                  />
                </td>
                {/* Last column — delete with inline confirm (Figma 28133:1526):
                    default → hover reveals trash → click swaps the same cell
                    space for a 52×52 vertical split: ✕ cancel (top, dark) over
                    ✓ confirm (bottom, red). */}
                <td className="p-0 align-middle">
                  {confirmId === row.id ? (
                    <div className="flex size-[52px] flex-col overflow-hidden rounded-md">
                      <button
                        type="button"
                        onClick={() => setConfirmId(null)}
                        aria-label="Cancel delete"
                        className="flex flex-1 items-center justify-center bg-fp-card-1 text-foreground outline-none transition-colors hover:bg-accent focus-visible:relative focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
                      >
                        <X className="size-4" />
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          removeRow(row.id);
                          setConfirmId(null);
                        }}
                        aria-label="Confirm delete"
                        className="flex flex-1 items-center justify-center bg-destructive text-white outline-none transition-colors hover:bg-destructive/90 focus-visible:relative focus-visible:z-10 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50"
                      >
                        <Check className="size-4" />
                      </button>
                    </div>
                  ) : (
                    <button
                      type="button"
                      onClick={() => setConfirmId(row.id)}
                      aria-label="Delete row"
                      className="mx-auto flex size-7 items-center justify-center rounded-sm text-muted-foreground opacity-0 outline-none transition-[color,opacity,background-color] group-hover/row:opacity-100 hover:bg-destructive/15 hover:text-destructive focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                    >
                      <Trash2 className="size-4" />
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Add a full row — a Surface-Base chip that connects to the table's
          bottom-left as an extension (squared top corners), sitting 1px below
          the table stroke. Icon-only until hover/focus, then "Add row" slides
          out. Hover is JS-driven so it's reliable inside the flex button. */}
      <Button
        variant="ghost"
        size="sm"
        onClick={addRow}
        onMouseEnter={() => setAddExpanded(true)}
        onMouseLeave={() => setAddExpanded(false)}
        onFocus={() => setAddExpanded(true)}
        onBlur={() => setAddExpanded(false)}
        className="mt-px h-7 gap-0 rounded-t-none rounded-b-md bg-background px-2 text-foreground hover:bg-background/80"
      >
        <Plus className="size-4 shrink-0" />
        <span
          className={cn(
            "overflow-hidden whitespace-nowrap transition-[max-width,opacity,padding] duration-200",
            addExpanded ? "max-w-[90px] pl-1.5 opacity-100" : "max-w-0 opacity-0"
          )}
        >
          Add row
        </span>
      </Button>
    </div>
  );
}

import * as React from "react";
import { FileText, Trash2, UploadCloud } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  "Upload documents" (Figma 27593:15012). Three states from the design: an empty
  dropzone, an in-progress upload (circular progress + "Uploading N of M"), and
  uploaded file chips (type icon + name + size + preview/delete). Seeded to match
  the frame; the dropzone accepts new files and removal is live.
*/

export interface UploadedFile {
  id: string;
  name: string;
  size: string;
  kind: "PDF" | "DOC" | "PNG";
}

/* File-kind chips are categorical, not semantic — the hues come from the DS
   status/verified tokens so both themes track the token layer (never Tailwind's
   stock palette, whose -400 steps are tuned for dark grounds only). */
const KIND_STYLE: Record<UploadedFile["kind"], string> = {
  PDF: "bg-status-failed/15 text-status-failed",
  DOC: "bg-verified/15 text-verified",
  PNG: "bg-status-processing/15 text-status-processing",
};

const INITIAL_FILES: UploadedFile[] = [
  { id: "f1", name: "Signature format.pdf", size: "2.4mb", kind: "PDF" },
  { id: "f2", name: "Fees.doc", size: "2.4mb", kind: "DOC" },
  { id: "f3", name: "Conditions.png", size: "2.4mb", kind: "PNG" },
];

const NOTE =
  "Note: Upload files in .JPG, .PNG, .PDF, or .DOC format. Files must be under 5 MB in total.";

/** Determinate circular progress ring. */
function CircularProgress({ value }: { value: number }) {
  const r = 18;
  const c = 2 * Math.PI * r;
  return (
    <span className="relative inline-flex size-11 items-center justify-center">
      <svg className="size-11 -rotate-90" viewBox="0 0 44 44">
        <circle
          cx="22"
          cy="22"
          r={r}
          fill="none"
          strokeWidth="3"
          className="stroke-muted"
        />
        <circle
          cx="22"
          cy="22"
          r={r}
          fill="none"
          strokeWidth="3"
          strokeLinecap="round"
          className="stroke-primary"
          strokeDasharray={c}
          strokeDashoffset={c * (1 - value / 100)}
        />
      </svg>
      <span className="absolute text-[11px] font-medium tabular-nums">
        {value}%
      </span>
    </span>
  );
}

export interface FileUploadProps {
  /**
   * `showcase` renders all three states at once — empty dropzone, an
   * in-progress example, and seeded chips — which is what the gallery needs and
   * what every existing caller gets by default.
   *
   * `field` renders the control a real form needs: dropzone, note, and only the
   * files actually added. No seeded files, no fake progress.
   */
  variant?: "showcase" | "field";
  /** Dropzone label. */
  label?: string;
  /** The format/size note under the dropzone. */
  note?: string;
  /** The files picked so far, whenever the list changes — for a caller that
   *  has to act on them (attach, send). Optional; the control works alone. */
  onFilesChange?: (files: UploadedFile[]) => void;
  /** Passed to the file input — e.g. `"image/*"`. */
  accept?: string;
}

export function FileUpload({
  variant = "showcase",
  label = "Upload Documents",
  note = NOTE,
  onFilesChange,
  accept,
}: FileUploadProps = {}) {
  const showcase = variant === "showcase";
  const [files, setFiles] = React.useState<UploadedFile[]>(
    showcase ? INITIAL_FILES : [],
  );
  const idRef = React.useRef(INITIAL_FILES.length);
  const reported = React.useRef(onFilesChange);
  React.useEffect(() => {
    reported.current = onFilesChange;
  });
  React.useEffect(() => {
    if (!showcase) reported.current?.(files);
  }, [files, showcase]);
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [dragOver, setDragOver] = React.useState(false);

  const inferKind = (name: string): UploadedFile["kind"] => {
    const ext = name.split(".").pop()?.toLowerCase();
    if (ext === "doc" || ext === "docx") return "DOC";
    if (ext === "png" || ext === "jpg" || ext === "jpeg") return "PNG";
    return "PDF";
  };

  const addFiles = (list: FileList | null) => {
    if (!list) return;
    const next = Array.from(list).map((f) => ({
      id: `f${++idRef.current}`,
      name: f.name,
      size: `${(f.size / 1_000_000).toFixed(1)}mb`,
      kind: inferKind(f.name),
    }));
    setFiles((prev) => [...prev, ...next]);
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Dropzone + its note are ONE unit, 4px apart — the note describes the
          control above it, not the list below. */}
      <div className="flex flex-col gap-1">
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          onDragOver={(e) => {
            e.preventDefault();
            setDragOver(true);
          }}
          onDragLeave={() => setDragOver(false)}
          onDrop={(e) => {
            e.preventDefault();
            setDragOver(false);
            addFiles(e.dataTransfer.files);
          }}
          className={cn(
            /* TRANSPARENT AT REST — an empty dropzone is a 96px hole in the
               form, and a filled one made it the largest painted shape on the
               page for the field least often used. The dashed rim is the whole
               affordance; the fill was only saying "something goes here" a
               second time, louder. Transparent also means the zone inherits
               whatever it is dropped into — the white content layer, a card, a
               tinted panel — instead of pinning one surface value that is
               right in exactly one of those places.

               A FILL ON DRAG, though: while a file is over it the zone has to
               say it will catch it, and that is the one moment the extra
               weight is information rather than decoration. */
            "flex h-24 w-full items-center justify-center gap-2 rounded-md border bg-transparent text-sm outline-none transition-colors",
            dragOver
              ? "border-ring bg-accent"
              : "border-border hover:border-fp-outline-2",
            "focus-visible:ring-2 focus-visible:ring-ring/50",
          )}
        >
          <UploadCloud className="size-5 text-muted-foreground" />
          <span className="font-medium">{label}</span>
          <input
            ref={inputRef}
            type="file"
            multiple
            accept={accept}
            className="hidden"
            onChange={(e) => addFiles(e.target.files)}
          />
        </button>
        <p className="text-xs text-muted-foreground">{note}</p>
      </div>

      {/* The in-progress state is a STATE, not a permanent block — it belongs in
          the showcase, never on a form where nothing is uploading. */}
      {showcase && (
        <div className="flex flex-col gap-1">
          <div className="flex h-24 w-full items-center justify-center gap-3 rounded-md border border-border bg-fp-surface-1a">
            <CircularProgress value={75} />
            <span className="text-sm">Uploading 2 of 3</span>
          </div>
          <p className="text-xs text-muted-foreground">{note}</p>
        </div>
      )}

      {/* Uploaded chips. A CHIP IS SIZED BY ITS CONTENT, not by the container:
          a filename and a file size need about 240px, and a three-column grid
          across a wide sheet stretched each one to twice that for no reader's
          benefit. They wrap, so more files fill the row rather than the row
          growing to fit. */}
      <div className="flex flex-wrap gap-3">
        {files.map((file) => (
          <div
            key={file.id}
            className="flex w-60 items-center gap-3 rounded-md border border-border bg-fp-surface-1a px-3 py-2.5"
          >
            <span
              className={cn(
                "flex size-9 shrink-0 items-center justify-center rounded-md text-[10px] font-semibold",
                KIND_STYLE[file.kind],
              )}
            >
              <FileText className="size-4" />
            </span>
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="truncate text-sm font-medium">{file.name}</span>
              <span className="text-xs text-muted-foreground">{file.size}</span>
            </span>
            <button
              type="button"
              aria-label={`Delete ${file.name}`}
              onClick={() =>
                setFiles((prev) => prev.filter((f) => f.id !== file.id))
              }
              className="flex size-7 items-center justify-center rounded-sm text-muted-foreground outline-none transition-colors hover:bg-destructive/15 hover:text-destructive focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <Trash2 className="size-4" />
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

