import * as React from "react";
import { Minus, Moon, Plus, RotateCcw, Sun } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Slider } from "@/components/ui/slider";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { DISPLAY_STEPS, RESET_SHORTCUT, TEXT_STEPS, textOfStep, textStepOf, isDefaultA11y, resetA11y, setA11y, setTheme, useA11y, useTheme, type A11y } from "./a11y";

/*
  THE ACCESSIBILITY PANEL (Pavan, 2026-10-21; DS ui §10n) — opened from the
  main navigation. Everything changes the page as it moves, is saved, and
  applies across every module. In this order (Pavan, 2026-10-21):

    Theme                 Light | Dark, on top
    Text size             six steps, 100% – 130%; only the text grows
    Stroke contrast       rims, dividers, field borders — Default → Maximum
    Contrast              grays go darker, whites stay white, text follows
                          — Default → Maximum
                          (renamed and Text color removed, Pavan, 2026-10-24)
    ── divider ──
    Display size          50% – 150% in five steps, 100% in the middle —
                          scales every component and view

  THE TWO SIZES ARE STEPS, LIKE ANDROID'S "Display size and text" (Pavan,
  2026-10-23): − and + either side of a track with a dot on every step.

  Reset is the icon in the header (⌘⌥0 too). Text on colour fills picks white
  or dark by itself.
*/

function Row({
  label,
  value,
  shown,
  onChange,
  ends,
  min = 0,
  max = 100,
  step = 5,
  disabled,
  aside,
}: {
  label: string;
  value: number;
  shown: string;
  onChange: (v: number) => void;
  ends: string[];
  min?: number;
  max?: number;
  step?: number;
  disabled?: boolean;
  aside?: React.ReactNode;
}) {
  const id = React.useId();
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between gap-3">
        <span id={id} className="text-sm font-medium text-foreground">
          {label}
        </span>
        <span className="flex items-center gap-3">
          {aside}
          <span className="text-sm tabular-nums text-foreground">{shown}</span>
        </span>
      </div>
      <Slider
        aria-labelledby={id}
        min={min}
        max={max}
        step={step}
        value={[value]}
        disabled={disabled}
        onValueChange={([v]) => onChange(v)}
      />
      <div className="flex justify-between text-xs text-muted-foreground">
        {ends.map((e) => (
          <span key={e}>{e}</span>
        ))}
      </div>
    </div>
  );
}

/** A STEPPED SIZE — − · a track with a dot per step · +. */
function StepRow({
  label,
  step,
  steps,
  shown,
  onChange,
  disabled,
}: {
  label: string;
  step: number;
  /** The last step's index (steps + 1 dots). */
  steps: number;
  shown: string;
  onChange: (step: number) => void;
  disabled?: boolean;
}) {
  const id = React.useId();
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center justify-between gap-3">
        <span id={id} className="text-sm font-medium text-foreground">
          {label}
        </span>
        <span className="text-sm tabular-nums text-foreground">{shown}</span>
      </div>
      <div className="flex items-center gap-2">
        <Button variant="ghost" size="icon-sm" aria-label={`Smaller ${label.toLowerCase()}`} disabled={disabled || step <= 0} onClick={() => onChange(step - 1)}>
          <Minus />
        </Button>
        <div className="relative flex-1">
          <Slider aria-labelledby={id} min={0} max={steps} step={1} value={[step]} disabled={disabled} onValueChange={([v]) => onChange(v)} />
          {/* A DOT ON EVERY STEP, under the thumb's travel. */}
          <div aria-hidden className="pointer-events-none absolute inset-x-0 top-1/2 flex -translate-y-1/2 justify-between px-1">
            {Array.from({ length: steps + 1 }, (_, i) => (
              <span key={i} className={i <= step ? "size-1 rounded-full bg-primary-foreground" : "size-1 rounded-full bg-muted-foreground"} />
            ))}
          </div>
        </div>
        <Button variant="ghost" size="icon-sm" aria-label={`Larger ${label.toLowerCase()}`} disabled={disabled || step >= steps} onClick={() => onChange(step + 1)}>
          <Plus />
        </Button>
      </div>
    </div>
  );
}

export function AccessibilityPanel() {
  const theme = useTheme();
  const a = useA11y();
  const set = (k: keyof A11y) => (v: number) => setA11y({ [k]: v });
  const pct = (v: number) => (v === 0 ? "Default" : v === 100 ? "Maximum" : `${v}%`);
  return (
    /* ALWAYS FITS THE WINDOW, at any Display size — it scrolls inside. */
    <div className="flex max-h-[calc(var(--fp-vh)*0.85)] w-80 max-w-full flex-col">
      <div className="flex shrink-0 items-center justify-between gap-3 border-b border-border px-4 py-3">
        <h2 className="text-base font-semibold text-foreground">Accessibility</h2>
        {/* RESET — THE ICON ALONE (Pavan, 2026-10-21). */}
        <TooltipProvider>
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={`Reset to default (${RESET_SHORTCUT})`}
                disabled={isDefaultA11y(a)}
                onClick={resetA11y}
              >
                <RotateCcw />
              </Button>
            </TooltipTrigger>
            <TooltipContent>Reset to default · {RESET_SHORTCUT}</TooltipContent>
          </Tooltip>
        </TooltipProvider>
      </div>

      <div className="flex min-h-0 flex-col gap-6 overflow-y-auto p-4">
        <ToggleGroup
          type="single"
          variant="outline"
          size="sm"
          value={theme}
          onValueChange={(v) => v && setTheme(v as "light" | "dark")}
          aria-label="Theme"
          className="w-full"
        >
          <ToggleGroupItem value="light" className="flex-1 gap-1.5 font-normal data-[state=on]:font-medium">
            <Sun className="size-4" />
            Light
          </ToggleGroupItem>
          <ToggleGroupItem value="dark" className="flex-1 gap-1.5 font-normal data-[state=on]:font-medium">
            <Moon className="size-4" />
            Dark
          </ToggleGroupItem>
        </ToggleGroup>

        <StepRow
          label="Text size"
          step={textStepOf(a.text)}
          steps={TEXT_STEPS}
          shown={`${Math.round(100 + a.text * 0.3)}%`}
          onChange={(v) => setA11y({ text: textOfStep(v) })}
        />

        {/* NO TEXT COLOR SLIDER (Pavan, 2026-10-24) — text contrast follows
            Contrast (a11y.ts), so the two never pull apart. */}
        <div className="flex flex-col gap-4">
          <Row label="Stroke contrast" value={a.stroke} shown={pct(a.stroke)} onChange={set("stroke")} ends={["Default", "Maximum"]} />
          <Row label="Contrast" value={a.background} shown={pct(a.background)} onChange={set("background")} ends={["Default", "Maximum"]} />
        </div>

        <Separator />

        {/* DISPLAY SIZE — 50% to 150%, 100% in the middle (Pavan, 2026-10-23). */}
        <StepRow
          label="Display size"
          step={DISPLAY_STEPS.indexOf(a.display)}
          steps={DISPLAY_STEPS.length - 1}
          shown={`${Math.round(a.display * 100)}%`}
          onChange={(v) => setA11y({ display: DISPLAY_STEPS[v] })}
        />
      </div>
    </div>
  );
}

import { Sun, Moon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { setTheme, useTheme } from "./a11y";

/*
  Light/dark theme toggle. LIGHT BY DEFAULT (Pavan, 2026-10-07). The theme
  lives in the shared settings store (`a11y.ts`), so this and the
  Accessibility panel's Light | Dark are one switch (Pavan, 2026-10-21 — the
  WCAG modes moved into that panel as sliders).
*/
export function ThemeToggle() {
  const dark = useTheme() === "dark";
  return (
    <Button
      variant="ghost"
      size="icon-sm"
      aria-label={dark ? "Switch to light mode" : "Switch to dark mode"}
      aria-pressed={dark}
      onClick={() => setTheme(dark ? "light" : "dark")}
    >
      {dark ? <Moon /> : <Sun />}
    </Button>
  );
}

import * as React from "react";

/*
  THEME + ACCESSIBILITY SETTINGS (Pavan, 2026-10-21; DS ui §10n) — one store
  for the theme (light / dark) and the Accessibility panel's three sliders:

    text     0–100 → type 100%–130% in six steps, a little heavier as it
             grows — `--fp-text-scale`. ONLY THE TEXT GROWS (Pavan,
             2026-10-23): no box widens; the text wraps and cards grow taller
    stroke   0–100 → every rim, divider, field border, lane and chart colour:
             the theme's own value at 0, its WCAG value (3:1+) at 50, the
             MAXIMUM (5:1+) at 100
    background 0–100 → the page, panels, cards and their steps, hover and
             selected fills — theme · WCAG · maximum
    ink      0–100 → secondary and coloured text (muted, status, brand,
             violet, trend, pills) — theme · WCAG (text AAA 7:1) · maximum
             (Pavan, 2026-10-21: Layers split into Background and Text)
    TEXT ON A COLOUR FILL is automatic while either is on: white or dark,
             whichever reads better on the fill as it now is
    display  DISPLAY SIZE — 50% to 150% in five steps, 100% in the middle
             (Pavan, 2026-10-23: not tied to monitors, it scales down too,
             no Auto). It scales EVERYTHING — every component and view — by
             one zoom

  THE WCAG AND MAXIMUM POINTS ARE THE CSS's `.wcag` and `.a11y-max` blocks —
  the values `npm run eval` checks. To mix, all three are read off the page
  in one synchronous pass (the classes are on only while reading, so nothing
  paints), then each token is set inline as a color-mix between the two
  points either side of the slider.
*/

export type Theme = "light" | "dark";
export interface A11y {
  text: number;
  stroke: number;
  background: number;
  ink: number;
  /** Display size — the page zoom, one of DISPLAY_STEPS. */
  display: number;
}
export const A11Y_DEFAULT: A11y = { text: 0, stroke: 0, background: 0, ink: 0, display: 1 };

/** THE TEXT SIZE STEPS — 100% to 130%, 5% apart (stored as 0–100). */
export const TEXT_STEPS = 6;
export const textStepOf = (text: number) => Math.round((text / 100) * TEXT_STEPS);
export const textOfStep = (step: number) => Math.round((step / TEXT_STEPS) * 100);

/** THE DISPLAY SIZE STEPS — the page zoom; 100% is the middle one. */
export const DISPLAY_STEPS = [0.5, 0.75, 1, 1.25, 1.5];
const nearestDisplay = (z: number) => DISPLAY_STEPS.reduce((a, b) => (Math.abs(b - z) < Math.abs(a - z) ? b : a));

const THEME_KEY = "fp-theme-choice";
const A11Y_KEY = "fp-a11y";

/** Rims, dividers, field borders, lanes, chart series — the Stroke slider. */
const STROKE = [
  "--fp-stroke-field",
  "--fp-outline-1",
  "--fp-outline-2",
  "--fp-stroke-hairline",
  "--fp-shell-rim",
  "--fp-shell-guide",
  "--fp-selected-border",
  "--fp-shell-marker",
  "--sidebar-border",
  "--ring",
  ...["grey", "blue", "yellow", "green", "cyan", "purple", "pink", "orange", "red"].map((l) => `--fp-lane-${l}`),
  ...[1, 2, 3, 4, 5, 6, 7, 8].map((n) => `--fp-viz-${n}`),
];
/** Secondary and coloured text — the Text slider. */
const INK = [
  "--fp-ink-3",
  "--fp-danger",
  "--destructive",
  "--status-success",
  "--status-processing",
  "--status-pink",
  "--verified",
  "--fp-selected-strong",
  "--fp-trend-up",
  "--fp-trend-down",
  "--fp-banner-accent-info",
  "--fp-banner-accent-caution",
  "--fp-banner-accent-warning",
  "--fp-banner-accent-success",
  "--accent-violet",
  /* ORANGE TEXT — not --brand, which is the logo's and the brand buttons' fill. */
  "--fp-brand-ink",
  /* MAIN TEXT — pure black (white in dark) at the far end. */
  "--fp-ink-1",
  "--fp-ink-2",
];
/** The page, panels, cards, their steps, hover and selected fills — the Background slider. */
const BACKGROUND = [
  "--fp-surface-base",
  "--fp-surface-1a",
  "--fp-card-1",
  "--fp-card-2",
  "--fp-card-3",
  "--fp-shell-ground",
  "--fp-shell-selected",
  "--fp-emphasis",
  "--fp-emphasis-hover",
  "--fp-emphasis-quiet",
  "--fp-table-header",
  "--fp-board-lane",
  "--fp-row-hover",
  "--fp-banner-caution",
];
/** TEXT ON A FILL — chosen, never blended: white or dark, whichever reads
    better on the fill as the sliders left it. [text token, its fill]. */
const ON_FILL: [string, string][] = [
  ["--primary-foreground", "--primary"],
  ["--brand-foreground", "--brand"],
  ["--accent-violet-foreground", "--accent-violet"],
  ["--verified-foreground", "--verified"],
  ["--status-success-foreground", "--status-success"],
  ["--status-foreground", "--status-success"],
  ["--destructive-foreground", "--destructive"],
];
const LIGHT_INK = "white";
const DARK_INK = "black";

function read<T>(key: string, fallback: T, parse: (v: string) => T | null): T {
  try {
    const v = localStorage.getItem(key);
    return (v ? parse(v) : null) ?? fallback;
  } catch {
    return fallback;
  }
}

/* THE OLD WCAG MODES BECOME THE PANEL AT FULL (2026-10-21). */
const legacy = read<string | null>(THEME_KEY, null, (v) => v);
let theme: Theme = legacy === "dark" || legacy === "wcag-dark" ? "dark" : "light";
let a11y: A11y =
  legacy === "wcag-light" || legacy === "wcag-dark"
    ? { ...A11Y_DEFAULT, text: 30, stroke: 50, background: 50, ink: 50 }
    : read<A11y>(A11Y_KEY, A11Y_DEFAULT, (v) => {
        const o = JSON.parse(v) as Partial<A11y>;
        const n = (x: unknown, d: number) => (Number.isFinite(Number(x)) && x !== null && x !== undefined ? Number(x) : d);
        return {
          text: n(o.text, 0),
          stroke: n(o.stroke, 0),
          /* THE OLD Layers SLIDER BECOMES BOTH. */
          background: n(o.background, n((o as { layers?: number }).layers, 0)),
          /* NO TEXT COLOR SLIDER (2026-10-24) — text follows Contrast. */
          ink: 0,
          /* THE OLD SCREEN SIZES land on the nearest step; Auto on 100%. */
          display: nearestDisplay(
            n(o.display, ({ monitor: 1.1, large: 1.25, tv: 1.5 } as Record<string, number>)[(o as { screen?: string }).screen ?? ""] ?? 1)
          ),
        };
      });

const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());
const save = () => {
  try {
    localStorage.setItem(THEME_KEY, theme);
    localStorage.setItem(A11Y_KEY, JSON.stringify(a11y));
  } catch {
    // Storage blocked — the settings still hold for this visit.
  }
};

/** Puts the settings on <html>. */
export function applySettings() {
  if (typeof document === "undefined") return;
  const root = document.documentElement;
  const style = root.style;
  root.classList.toggle("dark", theme === "dark");
  root.classList.remove("wcag", "a11y-max");
  root.classList.remove("a11y-ink", "a11y-frame");

  /* TYPE — 100%–130%; the units around it are fitted after. */
  const scale = 1 + (a11y.text / 100) * 0.3;
  style.setProperty("--fp-text-scale", String(scale));
  root.classList.toggle("a11y-text", a11y.text > 0);
  fitUnits();

  /* DISPLAY SIZE — one zoom for the whole page. */
  const zoom = a11y.display;
  if (zoom === 1) style.removeProperty("zoom");
  else style.setProperty("zoom", String(zoom));
  root.classList.toggle("a11y-zoom", zoom !== 1);
  style.setProperty("--fp-zoom", String(zoom));

  style.removeProperty("filter");

  /* COLOURS — read both ends in one pass, then mix. */
  const all = [...STROKE, ...INK, ...BACKGROUND, ...ON_FILL.map(([t]) => t)];
  all.forEach((t) => style.removeProperty(t));
  if (a11y.stroke !== 0 || a11y.background !== 0 || a11y.ink !== 0) mixContrast(root, all);
  if (a11y.background !== 0 || a11y.ink !== 0) textOnFills(root);
  /* THE DARK FRAME — Contrast 80%+ in the light theme: the shell
     ground and the selected nav item jump to near black, white text on them
     (Pavan, 2026-10-21 — no grey between ~#5a and #95 reads at 7:1 either
     way, so it jumps rather than fades). */
  const frame = theme === "light" && a11y.background >= 80;
  root.classList.toggle("a11y-frame", frame);
  if (frame) {
    style.setProperty("--fp-shell-ground", "var(--fp-frame-ground)");
    style.setProperty("--fp-shell-selected", "var(--fp-frame-selected)");
  }
}

function mixContrast(root: HTMLElement, all: string[]) {
  const style = root.style;
  const cs = getComputedStyle(root);
  const from = Object.fromEntries(all.map((t) => [t, cs.getPropertyValue(t).trim()]));
  root.classList.add("wcag");
  const cs2 = getComputedStyle(root);
  const to = Object.fromEntries(all.map((t) => [t, cs2.getPropertyValue(t).trim()]));
  root.classList.add("a11y-max");
  const cs3 = getComputedStyle(root);
  const max = Object.fromEntries(all.map((t) => [t, cs3.getPropertyValue(t).trim()]));
  root.classList.remove("wcag", "a11y-max");
  /* 0 → the theme · 50 → WCAG · 100 → maximum. */
  const blend = (a: string, b: string, pct: number) =>
    pct <= 0 || a === b ? a : pct >= 100 ? b : `color-mix(in oklab, ${b} ${pct}%, ${a})`;
  const mix = (t: string, v: number) => {
    if (!from[t] || !to[t] || v === 0) return;
    const value = v <= 50 ? blend(from[t], to[t], v * 2) : blend(to[t], max[t] || to[t], (v - 50) * 2);
    if (value !== from[t]) style.setProperty(t, value);
  };
  STROKE.forEach((t) => mix(t, a11y.stroke));
  /* TEXT NEVER SITS BELOW ITS GROUND — past the middle, Contrast
     darkens the greys, so Text colour rises with it (it can go further, not
     less). */
  const ink = Math.max(a11y.ink, a11y.background);
  INK.forEach((t) => mix(t, ink));
  /* Faded labels come up to full past the middle (CSS `.a11y-ink`). */
  root.classList.toggle("a11y-ink", ink >= 50);
  BACKGROUND.forEach((t) => mix(t, a11y.background));
}

/* A COLOUR AS IT NOW RENDERS — a probe swatch read back as rgb(). */
function rgbOf(value: string): [number, number, number] | null {
  const el = document.createElement("span");
  el.style.color = value;
  el.style.display = "none";
  document.body.appendChild(el);
  const c = getComputedStyle(el).color;
  el.remove();
  /* A color-mix comes back in the space it was mixed in — oklab here. */
  const ok = /oklab\((-?[\d.]+) (-?[\d.]+) (-?[\d.]+)/.exec(c);
  if (ok) {
    const [L, A, B] = [Number(ok[1]), Number(ok[2]), Number(ok[3])];
    const l = (L + 0.3963377774 * A + 0.2158037573 * B) ** 3;
    const m = (L - 0.1055613458 * A - 0.0638541728 * B) ** 3;
    const s = (L - 0.0894841775 * A - 1.291485548 * B) ** 3;
    const lin = [
      4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
      -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
      -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
    ];
    const enc = (x: number) => {
      const v = Math.min(1, Math.max(0, x));
      return v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055;
    };
    return [enc(lin[0]), enc(lin[1]), enc(lin[2])];
  }
  /* …or as color(srgb r g b) in 0–1; plain colours as rgb(). */
  const srgb = /color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)/.exec(c);
  if (srgb) return [Number(srgb[1]), Number(srgb[2]), Number(srgb[3])];
  const m = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)/.exec(c);
  return m ? [Number(m[1]) / 255, Number(m[2]) / 255, Number(m[3]) / 255] : null;
}
const luminance = ([r, g, b]: [number, number, number]) => {
  const l = (c: number) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
  return 0.2126 * l(r) + 0.7152 * l(g) + 0.0722 * l(b);
};
const contrast = (a: number, b: number) => (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);

/** WHITE OR DARK on each fill, whichever reads better (Pavan, 2026-10-21). */
function textOnFills(root: HTMLElement) {
  const cs = getComputedStyle(root);
  const white = 1;
  const dark = luminance(rgbOf(DARK_INK)!);
  for (const [fg, fill] of ON_FILL) {
    const v = cs.getPropertyValue(fill).trim();
    const c = v && rgbOf(v);
    if (!c) continue;
    const l = luminance(c);
    root.style.setProperty(fg, contrast(white, l) >= contrast(dark, l) ? LIGHT_INK : DARK_INK);
  }
}

export function setTheme(t: Theme) {
  theme = t;
  save();
  applySettings();
  emit();
}
/** BACK TO DEFAULT — every accessibility setting; the theme stays. */
export function resetA11y() {
  a11y = { ...A11Y_DEFAULT };
  save();
  applySettings();
  emit();
}
export const isDefaultA11y = (a: A11y) =>
  (Object.keys(A11Y_DEFAULT) as (keyof A11y)[]).every((k) => a[k] === A11Y_DEFAULT[k]);
/** The way back when the panel can't be reached: ⌘⌥0 (Ctrl+Alt+0). */
export const RESET_SHORTCUT = typeof navigator !== "undefined" && /Mac/.test(navigator.platform) ? "⌘⌥0" : "Ctrl+Alt+0";

export function setA11y(patch: Partial<A11y>) {
  a11y = { ...a11y, ...patch };
  save();
  applySettings();
  emit();
}

const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};
export const useTheme = () => React.useSyncExternalStore(subscribe, () => theme, () => theme);
export const useA11y = () => React.useSyncExternalStore(subscribe, () => a11y, () => a11y);

/*
  TEXT GROWS, BOXES DON'T (Pavan, 2026-10-23) — no unit widens for bigger
  text any more: the nav, a board lane, a sheet keep their width, the text
  wraps onto the next line inside them and the card grows taller (CSS
  `.a11y-text`). Making the boxes bigger is the Display size slider's job.
  The width multipliers stay at 1 so anything still reading them holds.
*/
function fitUnits() {
  if (typeof document === "undefined") return;
  ["--fp-nav-k", "--fp-lane-k", "--fp-scale"].forEach((k) => document.documentElement.style.setProperty(k, "1"));
}

/* ON LOAD — once the stylesheet is in, so both ends can be read. */
if (typeof window !== "undefined") {
  if (document.readyState === "complete") applySettings();
  else window.addEventListener("load", applySettings, { once: true });
  applySettings();
  /* THE ESCAPE HATCHES (Pavan, 2026-10-21) — a shortcut, and `?a11y=reset`
     in the address, put every accessibility setting back to default. */
  window.addEventListener("keydown", (e) => {
    if ((e.metaKey || e.ctrlKey) && e.altKey && e.code === "Digit0") {
      e.preventDefault();
      resetA11y();
    }
  });
  if (new URLSearchParams(window.location.search).get("a11y") === "reset") resetA11y();
}

export { ThemeToggle } from "./ThemeToggle";
export { AccessibilityPanel } from "./AccessibilityPanel";
export { applySettings, setA11y, setTheme, useA11y, useTheme } from "./a11y";
export { AccessibilityIcon } from "./AccessibilityIcon";

import * as React from "react";
import { Search, Bell, ChevronDown, UserRound, Settings, LogOut, Boxes, Keyboard } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Kbd } from "@/components/ui/kbd";
import { cn } from "@/lib/utils";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { SideSheet } from "@/components/side-sheet";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";

export interface TopBarUser {
  name: string;
  email: string;
  /** Avatar fallback initials, e.g. "PS". */
  fallback: string;
  avatarSrc?: string;
}

export interface TopBarProps {
  user: TopBarUser;
  /** Unread notification count — shows a dot when > 0. */
  unread?: number;
  /**
   * Turn the search field into a trigger for a command palette. When supplied,
   * the field stops accepting inline typing and instead opens on click, focus or
   * ⌘K/Ctrl-K — the palette owns the query from there. Left out, the field stays
   * a plain input, so existing callers are unaffected.
   */
  onSearchActivate?: () => void;
  /** Placeholder for the search field. */
  searchPlaceholder?: string;
  /**
   * Account-menu destinations. The menu items render regardless; supplying a
   * handler is what makes one navigate. Left out, the item stays inert — which
   * is what every caller before these props got, so behaviour is unchanged.
   */
  onProfile?: () => void;
  onSettings?: () => void;
  onLogout?: () => void;
}

/**
 * Global application top bar — a full-width chrome band above the rail + content.
 * Centre: global search + the keyboard-shortcuts CTA. Right: notifications +
 * profile menu.
 */
export function TopBar({
  user,
  unread = 0,
  onSearchActivate,
  searchPlaceholder = "Search",
  onProfile,
  onSettings,
  onLogout,
}: TopBarProps) {
  const [shortcutsOpen, setShortcutsOpen] = React.useState(false);

  // ⌘K / Ctrl-K opens the palette from anywhere, which is what the field's own
  // hint promises. Only bound when there is a palette to open.
  React.useEffect(() => {
    if (!onSearchActivate) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key.toLowerCase() === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        onSearchActivate();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onSearchActivate]);
  return (
    /* NO FILL OF ITS OWN — it sits on the shell's ground, so an app that tints
       its ground (Unified View, 2026-10-06) tints the bar with it. */
    /* `data-fp-frame` / `data-fp-on-frame` — at the far end of the
       Accessibility panel's Component background the shell ground goes near
       black, and what sits straight on it turns white (DS ui §10n). */
    <header data-fp-frame className="flex h-12 shrink-0 items-center gap-3 border-b border-border bg-transparent px-3">
      {/* Left — brand logo */}
      <div className="flex flex-1 items-center gap-2">
        <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-brand text-brand-foreground [&_svg]:size-5">
          <Boxes />
        </span>
        <span data-fp-on-frame className="truncate text-base font-semibold text-foreground">FleetPanda</span>
      </div>

      {/* Center — global search + keyboard shortcuts */}
      <div className="flex flex-1 justify-center">
        <div className="flex w-full max-w-md items-center gap-2">
          <div className="relative flex-1">
            <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              type="search"
              placeholder={searchPlaceholder}
              aria-label="Search"
              // As a palette trigger the field must not swallow the query: it is
              // read-only so typing goes to the palette's own input instead of
              // being lost here, and the caret is hidden to match.
              readOnly={Boolean(onSearchActivate)}
              onClick={onSearchActivate}
              onFocus={onSearchActivate}
              className={cn(
                /* NO RIM (Pavan, 2026-10-06) — the white field on the
                   shell ground is edge enough; the focus ring still shows. */
                "h-9 rounded-md border-transparent pl-8 shadow-none",
                onSearchActivate && "cursor-pointer caret-transparent"
              )}
            />
            {onSearchActivate && (
              <span className="pointer-events-none absolute top-1/2 right-2 -translate-y-1/2">
                <Kbd>⌘K</Kbd>
              </span>
            )}
          </div>
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  aria-label="Keyboard shortcuts"
                  data-fp-on-frame
                  onClick={() => setShortcutsOpen(true)}
                  className="shrink-0 text-muted-foreground hover:text-foreground"
                >
                  <Keyboard />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Keyboard shortcuts</TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>
      </div>

      {/* Right — notifications + profile */}
      <div className="flex flex-1 items-center justify-end gap-1">
        <Button variant="ghost" size="icon" aria-label="Notifications" data-fp-on-frame className="relative">
          <Bell />
          {unread > 0 && (
            <span
              className="absolute top-1.5 right-1.5 size-2 rounded-full bg-brand ring-2 ring-background"
              aria-label={`${unread} unread`}
            />
          )}
        </Button>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              aria-label="Account menu"
              data-fp-on-frame
              className="flex items-center gap-1.5 rounded-md p-1 outline-none transition-colors hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <Avatar className="size-8">
                {user.avatarSrc && <AvatarImage src={user.avatarSrc} alt={user.name} />}
                <AvatarFallback>{user.fallback}</AvatarFallback>
              </Avatar>
              <ChevronDown className="size-4 text-muted-foreground" />
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-56">
            <DropdownMenuLabel className="flex flex-col gap-0.5">
              <span className="text-sm font-medium text-foreground">{user.name}</span>
              <span className="text-xs font-normal text-muted-foreground">{user.email}</span>
            </DropdownMenuLabel>
            <DropdownMenuSeparator />
            <DropdownMenuItem onSelect={onProfile}><UserRound /> Profile</DropdownMenuItem>
            <DropdownMenuItem onSelect={onSettings}><Settings /> Settings</DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem variant="destructive" onSelect={onLogout}><LogOut /> Log out</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      <SideSheet
        variant="shortcuts"
        open={shortcutsOpen}
        onOpenChange={setShortcutsOpen}
      />
    </header>
  );
}

